const ROWS = 1;
const COLS = 5;
const DEFAULT_DYNAMIC_COLS = 3;
// ---------------------------------------------------------------------------
// Where the data lives
//
// Every search file (case) is stored ONLY in the database behind the sync
// server (Railway). The browser keeps the case it is working on in memory for
// as long as the page is open - never in localStorage, IndexedDB or any other
// on-device store - so nothing is ever left on the computer and every page load
// reads the current copy from the server. The only things a device remembers
// between page loads are the login (cookies + sessionStorage) and the address
// of the sync server to talk to.
// ---------------------------------------------------------------------------
const BUNDLE_STORAGE_KEY = 'pill-table-bundle-v1';
// Older builds kept a copy of every case under this key; the Saved Cases table
// is now read from the server and nothing is cached on the device any more.
const FILE_LIST_STORAGE_KEY = 'sar-saved-files-v1';
// Stand-in shown while no CASE # is selected. A search file is never created
// under this name: its name always follows the CASE # it was created for.
const DEFAULT_FILE_NAME = '';
const NO_CASE_LABEL = 'No case selected';
// Which sync server this device talks to. Two cookies, in order of precedence:
//   * SYNC_URL_LOCAL_STORAGE_KEY - the address typed into the login popup's
//     "Set Server" (the ONLY place a person can change the data server; it is
//     reached by logging out first);
//   * SYNC_URL_CONFIG_STORAGE_KEY - the address the server itself publishes
//     from the Railway variable CALTOPO_SYNC (GET /api/config), refreshed on
//     every page load and used whenever nothing was set by hand.
// The CalTopo proxy is not configurable any more: it is always the sync
// server's own /api/proxy (see getCalTopoProxy).
const SYNC_URL_LOCAL_STORAGE_KEY = 'sar-sync-url-local-v1';
const SYNC_URL_CONFIG_STORAGE_KEY = 'sar-sync-url-config-v1';
const SYNC_BUCKET_STORAGE_KEY = 'sar-sync-bucket-v1';
const USER_NAME_STORAGE_KEY = 'sar-user-name-v1';
const USER_PASSWORD_STORAGE_KEY = 'sar-user-password-v1';
const CALTOPO_CREDS_STORAGE_KEY = 'sar-caltopo-creds-v1';
const DEVICE_ID_STORAGE_KEY = 'sar-device-id-v1';
// The background photo every page shows unless the login uploaded its own.
const DEFAULT_BACKGROUND_IMAGE = 'assets/us-night.jpg';
// Row changes this device has made but not yet delivered to the server. Every
// save is diffed against the copy that was on this device just before it, and
// only those rows are queued here and uploaded. The queue lives in memory for
// the lifetime of the page and is retried until the server confirms it.
const SYNC_OUTBOX_STORAGE_KEY = 'sar-sync-outbox-v1';
// Which CASE # (sync bucket) the in-memory search file belongs to, so a copy
// of another case is never mistaken for this one's.
const BUNDLE_BUCKET_STORAGE_KEY = 'sar-bundle-bucket-v1';
// Older builds kept a second full copy of the search file under this key.
const LEGACY_SYNC_SNAPSHOT_STORAGE_KEY = 'sar-sync-snapshot-v1';
// Everything an older build may have left in the browser's localStorage. It is
// removed once on start-up so no case data stays on the computer.
const LEGACY_LOCAL_STORAGE_KEYS = [
    BUNDLE_STORAGE_KEY,
    FILE_LIST_STORAGE_KEY,
    SYNC_OUTBOX_STORAGE_KEY,
    BUNDLE_BUCKET_STORAGE_KEY,
    LEGACY_SYNC_SNAPSHOT_STORAGE_KEY,
    'sar-server-settings-cache-v1',
    'sar-map-unaccounted-last-check-v1',
    'sar-sync-url-v1',
    'sar-sync-bucket-v1',
    'sar-caltopo-proxy-v1',
    'sar-caltopo-creds-v1',
    'sar-device-id-v1',
    'sar-map-psrc-overlay-v1',
    'sar-caltopo-assignment-overlay-v1',
    'sar-segments-psrc-sort-v1',
    'sar-chart-range-v1',
    'sar-theme-cache',
    'sar-accent-cache',
    'sar-geek-mode-cache'
];
// How often a page asks the database whether the other devices changed
// anything. The answer is tiny when nothing changed.
const SYNC_POLL_INTERVAL_MS = 4000;
// const DEFAULT_BUCKET = 'MNSAR14';
const SAVE_BUTTON_MIN_LOADING_MS = 1000;
const SAVE_BUTTON_SUCCESS_MS = 3000;
const MAP_PSRC_OVERLAY_STORAGE_KEY = 'sar-map-psrc-overlay-v1';
const CALTOPO_ASSIGNMENT_OVERLAY_STORAGE_KEY = 'sar-caltopo-assignment-overlay-v1';
// Segments page "Sort by PSRc" toggle. Stored in the per-user server settings
// as a map keyed by sync bucket (CASE # + username), so each user keeps a
// separate toggle state for each case.
const SEGMENTS_PSRC_SORT_STORAGE_KEY = 'sar-segments-psrc-sort-v1';
// Start/End of the PSRc and POS cumulative charts (Home and Search Log pages).
// Only values the user typed are stored, in the per-user server settings as a
// map keyed by sync bucket; a field that was never edited keeps following its
// default (one hour before the earliest task assignment -> now) and the tiny
// reset button clears the stored values again.
const CHART_RANGE_STORAGE_KEY = 'sar-chart-range-v1';
// How often the app re-fetches the CalTopo map to look for shapes that are
// neither imported as segments nor marked unwanted ("unaccounted" features).
const MAP_UNACCOUNTED_CHECK_INTERVAL_MS = 5 * 60 * 1000;
// When the last automatic check ran. Kept in the per-user server settings
// (keyed by sync bucket) so navigating between pages - or devices - does not
// restart the 5-minute clock, without anything being stored on the device.
const MAP_UNACCOUNTED_LAST_CHECK_STORAGE_KEY = 'sar-map-unaccounted-last-check-v1';
const UNACCOUNTED_FEATURES_NOTIFICATION_TITLE = 'Unaccounted Map Features';
const UNACCOUNTED_FEATURES_NOTIFICATION_CLASS = 'map-features-unaccounted';
// CalTopo color sync: the PSRc segment-color push is coalesced so CalTopo is
// never asked more often than the cooldown ("maximum refresh", seconds) and is
// re-asserted at least once per heartbeat ("minimum refresh", minutes). These
// defaults apply until the login changes them on the Settings page.
const CALTOPO_COLOR_SYNC_DEFAULT_COOLDOWN_SECONDS = 10;
const CALTOPO_COLOR_SYNC_DEFAULT_HEARTBEAT_MINUTES = 1;
// How often the countdown / heartbeat ticker wakes up.
const CALTOPO_COLOR_SYNC_TICK_INTERVAL_MS = 1000;
// When THIS tab last pushed (or tried to push) the colors. sessionStorage is
// used on purpose: it survives page navigation inside the tab (every page is a
// full reload) and is forgotten when the tab closes. It is a clock, never a
// piece of case data - the case's own hint is maps[0].caltopoAssignmentOverlayState.updatedAt.
const CALTOPO_COLOR_SYNC_LAST_PUSH_STORAGE_KEY = 'sar-caltopo-color-sync-last-v1';
// One notification per CalTopo Assignment that is on the map but not imported
// yet, with its own Import / Decline buttons.
const NEW_ASSIGNMENT_NOTIFICATION_TITLE = 'New Assignment';
const NEW_ASSIGNMENT_NOTIFICATION_CLASS = 'map-assignment-new';
// Maps page "Proxy Status" dot. The page is rebuilt on every change another
// device makes, so the last answer is kept this long and painted straight away;
// the server is only asked again once it is older than that (or when the dot
// is clicked). One probe waits at most this long for an answer.
const MAPS_PROXY_STATUS_RECHECK_INTERVAL_MS = 30000;
const MAPS_PROXY_STATUS_TIMEOUT_MS = 8000;
// At most this many "New Assignment" toasts pop up per refresh; the rest are
// still listed in the notification sidebar.
const NEW_ASSIGNMENT_TOAST_LIMIT = 5;
// The feature-type toggles below the map (markers / shapes / assignments /
// routes / other). Mirrors SARMapSegmentUtils.FEATURE_CATEGORIES for pages
// that load app.js without map-segment-utils.js.
const MAP_FEATURE_CATEGORIES_FALLBACK = [
    {key: 'marker', label: 'Markers', singular: 'Marker'},
    {key: 'shape', label: 'Shapes', singular: 'Shape'},
    {key: 'assignment', label: 'Assignments', singular: 'Assignment'},
    {key: 'route', label: 'Routes', singular: 'Route'},
    {key: 'other', label: 'Other', singular: 'Other'}
];

function getMapSegmentUtils() {
    return (typeof window !== 'undefined' && window.SARMapSegmentUtils) ? window.SARMapSegmentUtils : {};
}

function ensureSegmentsPageRows(bundle) {
    const utils = getMapSegmentUtils();
    if (typeof utils.ensureSegmentsPageRows === 'function') {
        return utils.ensureSegmentsPageRows(bundle, defaultSegmentsData);
    }
    if (!bundle.pages) bundle.pages = {};
    if (Array.isArray(bundle.pages.page2)) return bundle.pages.page2;
    bundle.pages.page2 = defaultSegmentsData();
    return bundle.pages.page2;
}

function getCalTopoFeatureTypeKey(feature) {
    const utils = getMapSegmentUtils();
    return typeof utils.getFeatureTypeKey === 'function' ? utils.getFeatureTypeKey(feature) : 'other';
}

function getCalTopoFeatureTypeLabel(feature) {
    const utils = getMapSegmentUtils();
    return typeof utils.getFeatureTypeLabel === 'function' ? utils.getFeatureTypeLabel(feature) : 'Graphic';
}

// ---------------------------------------------------------------------------
// Feature categories (marker / shape / assignment / route / other) and the
// per-case toggles that decide which of them the team wants to hear about.
// ---------------------------------------------------------------------------

function getMapFeatureCategories() {
    const utils = getMapSegmentUtils();
    return Array.isArray(utils.FEATURE_CATEGORIES) ? utils.FEATURE_CATEGORIES : MAP_FEATURE_CATEGORIES_FALLBACK;
}

function getMapFeatureCategoryKey(feature) {
    const utils = getMapSegmentUtils();
    if (typeof utils.getFeatureCategoryKey === 'function') return utils.getFeatureCategoryKey(feature);
    const attrs = feature?.attributes || feature?.properties || {};
    const rawClass = String(attrs.class || '').trim().toLowerCase();
    const rawType = String(attrs.type || '').trim().toLowerCase();
    const geomType = String((feature?.geometry && feature.geometry.type) || '').trim().toLowerCase();
    const classOrType = rawClass || (rawType !== 'feature' ? rawType : '');
    if (classOrType === 'assignment' || attrs.assignment) return 'assignment';
    if (classOrType === 'marker' || geomType === 'point' || geomType === 'multipoint') return 'marker';
    if (['route', 'track', 'line', 'polyline'].includes(classOrType) || ['linestring', 'multilinestring', 'polyline', 'line'].includes(geomType)) return 'route';
    if (['shape', 'polygon', 'area'].includes(classOrType) || ['polygon', 'multipolygon', 'geometrycollection'].includes(geomType)) return 'shape';
    return 'other';
}

function getMapFeatureCategoryLabel(feature) {
    const utils = getMapSegmentUtils();
    if (typeof utils.getFeatureCategoryLabel === 'function') return utils.getFeatureCategoryLabel(feature);
    const key = getMapFeatureCategoryKey(feature);
    const category = getMapFeatureCategories().find(entry => entry.key === key);
    return category ? category.singular : 'Other';
}

function getMapFeatureCategoryPluralLabel(typeKey) {
    const category = getMapFeatureCategories().find(entry => entry.key === typeKey);
    return category ? category.label : 'Other';
}

// {marker: true, shape: true, assignment: true, route: true, other: true};
// a type that was never toggled is ON.
function getMapFeatureTypeFilters(bundle) {
    const b = bundle || loadBundle();
    const utils = getMapSegmentUtils();
    if (typeof utils.normalizeFeatureTypeFilters === 'function') return utils.normalizeFeatureTypeFilters(b.mapFeatureTypeFilters);
    const source = (b.mapFeatureTypeFilters && typeof b.mapFeatureTypeFilters === 'object' && !Array.isArray(b.mapFeatureTypeFilters)) ? b.mapFeatureTypeFilters : {};
    const result = {};
    getMapFeatureCategories().forEach(category => {
        result[category.key] = source[category.key] !== false;
    });
    return result;
}

function isMapFeatureTypeEnabled(feature, bundle) {
    return getMapFeatureTypeFilters(bundle)[getMapFeatureCategoryKey(feature)] !== false;
}

function getFilteredSegmentImports(items, typeKey) {
    const utils = getMapSegmentUtils();
    if (typeof utils.filterSegmentImportsByType === 'function') {
        return utils.filterSegmentImportsByType(items, typeKey);
    }
    if (!typeKey || typeKey === 'all') return items.slice();
    return items.filter(item => item.typeKey === typeKey);
}

function buildSegmentPsrcLookup(rows, options = {}) {
    const utils = getMapSegmentUtils();
    return typeof utils.buildSegmentPsrcLookup === 'function'
        ? utils.buildSegmentPsrcLookup(rows, options)
        : {values: new Map(), maxValue: 0};
}

function getFeaturePsrcColor(feature, lookup, options = {}) {
    const utils = getMapSegmentUtils();
    return typeof utils.getFeaturePsrcColor === 'function' ? utils.getFeaturePsrcColor(feature, lookup, options) : null;
}

function getFeaturePsrcAssignmentStyle(feature, lookup, options = {}) {
    const utils = getMapSegmentUtils();
    if (typeof utils.getFeaturePsrcAssignmentStyle === 'function') {
        return utils.getFeaturePsrcAssignmentStyle(feature, lookup, options);
    }
    const color = getFeaturePsrcColor(feature, lookup, options);
    return color ? {stroke: color.css, fill: color.css, color} : null;
}

function normalizeSegmentNameForMatch(value) {
    const utils = getMapSegmentUtils();
    return typeof utils.normalizeSegmentName === 'function'
        ? utils.normalizeSegmentName(value)
        : String(value || '').trim().toLowerCase();
}

// ---------------------------------------------------------------------------
// Lost Person Behavior (LPB).
//
// The Incident page's "Lost Person Behavior" section switches on any number of
// lost-person categories (listed under their group titles: External Forces,
// Water, Wheel/Motorized, Mental State, Child, Outdoor Activity, Snow
// Activity), picks a terrain for each and imports the IPP marker from the
// CalTopo map. The maths (segment centre, distance to the IPP, which
// 25/50/75/95 % bracket it falls into, that bracket's percentage per mile and
// the sum over the categories that becomes the PSR factor) lives in
// map-segment-utils.js so the server and the tests share it; these wrappers
// only fall back to "not active" on a page that loads app.js without it.
//
// What the case stores (bundle.lostPersonBehavior, mirrored to the
// lost_person_behavior table and - for the IPP - lpb_ipp on the server):
//   psrAdjustmentEnabled  the Segments page switch; off keeps every setting
//                         but leaves the PSR values alone
//   ipp                   {featureId, featureName, lat, lng, importedAt, importedBy}
//   categories.<key>      {enabled, terrain, distances: {p25, p50, p75, p95}}
// The four distances of a category are copied INTO the case (from the login's
// values on the server, see loadLpbDistances) when the category is switched on
// or its terrain changes, and edited in place afterwards. Every device
// therefore computes the PSR from the same numbers; a login's own edits live
// on the server (lpb_user_distances) and only seed the next case / terrain.
// ---------------------------------------------------------------------------
const LPB_CATEGORIES_FALLBACK = [{key: 'mentalIllness', label: 'Mental Illness', group: 'mentalState'}];
const LPB_CATEGORY_GROUPS_FALLBACK = [{key: 'mentalState', title: 'Mental State', categories: LPB_CATEGORIES_FALLBACK}];
const LPB_TERRAINS_FALLBACK = ['Mtn Temperate', 'Flat Temperate', 'Dry', 'Urban'];
const LPB_BRACKETS_FALLBACK = [
    {key: 'p25', percent: 25},
    {key: 'p50', percent: 50},
    {key: 'p75', percent: 75},
    {key: 'p95', percent: 95}
];
const LPB_SEED_DISTANCES_FALLBACK = {p25: 0.5, p50: 1.0, p75: 1.5, p95: 2.0};

function getLpbCategories() {
    const utils = getMapSegmentUtils();
    return Array.isArray(utils.LPB_CATEGORIES) ? utils.LPB_CATEGORIES : LPB_CATEGORIES_FALLBACK;
}

// The categories in page order, grouped under their titles
// ([{key, title, categories: [{key, label}]}]).
function getLpbCategoryGroups() {
    const utils = getMapSegmentUtils();
    return Array.isArray(utils.LPB_CATEGORY_GROUPS) ? utils.LPB_CATEGORY_GROUPS : LPB_CATEGORY_GROUPS_FALLBACK;
}

function getLpbTerrains() {
    const utils = getMapSegmentUtils();
    return Array.isArray(utils.LPB_TERRAINS) ? utils.LPB_TERRAINS : LPB_TERRAINS_FALLBACK;
}

function getLpbBrackets() {
    const utils = getMapSegmentUtils();
    return Array.isArray(utils.LPB_BRACKETS) ? utils.LPB_BRACKETS : LPB_BRACKETS_FALLBACK;
}

function normalizeLpbDistanceMiles(value) {
    const utils = getMapSegmentUtils();
    if (typeof utils.normalizeLpbDistanceMiles === 'function') return utils.normalizeLpbDistanceMiles(value);
    const miles = parseFloat(String(value === undefined || value === null ? '' : value).replace(/[^0-9.\-]/g, ''));
    return Number.isFinite(miles) && miles > 0 ? Math.round(miles * 10) / 10 : null;
}

function formatLpbMiles(value) {
    const utils = getMapSegmentUtils();
    if (typeof utils.formatLpbMiles === 'function') return utils.formatLpbMiles(value);
    const miles = normalizeLpbDistanceMiles(value);
    return miles === null ? '' : `${miles.toFixed(1)} mi`;
}

// "13.2%" / "50%" - how a percentage (a bracket's rate, a segment's gain) is shown.
function formatLpbPercent(value) {
    const utils = getMapSegmentUtils();
    if (typeof utils.formatLpbPercent === 'function') return utils.formatLpbPercent(value);
    const num = typeof value === 'number' ? value : parseFloat(value);
    if (!Number.isFinite(num)) return '';
    const rounded = Math.round(num * 10) / 10;
    return `${Number.isInteger(rounded) ? rounded.toFixed(0) : rounded.toFixed(1)}%`;
}

// One entry per bracket with its percentage per mile (see
// computeLpbBracketRates in map-segment-utils.js); without the shared module
// no bracket has a rate.
function computeLpbBracketRates(distances) {
    const utils = getMapSegmentUtils();
    if (typeof utils.computeLpbBracketRates === 'function') return utils.computeLpbBracketRates(distances);
    return getLpbBrackets().map(bracket => ({key: bracket.key, percent: bracket.percent, distance: null, previousPercent: 0, previousDistance: 0, ratePercentPerMile: null}));
}

// The section in canonical form (see the block comment above). Without the
// shared module the object is kept as it is, so nothing a fuller page saved is
// thrown away by a page that cannot interpret it.
function normalizeLostPersonBehavior(value) {
    const utils = getMapSegmentUtils();
    if (typeof utils.normalizeLostPersonBehavior === 'function') return utils.normalizeLostPersonBehavior(value);
    if (value && typeof value === 'object' && !Array.isArray(value)) return value;
    return {psrAdjustmentEnabled: true, ipp: null, categories: {}};
}

function getLostPersonBehavior(bundle) {
    return normalizeLostPersonBehavior((bundle || loadBundle()).lostPersonBehavior);
}

// Everything the PSR maths needs, worked out once per recalculation: the
// categories that are on with complete distances (`categories`), the ones
// still missing a distance (`incomplete`) and the IPP. `active` is false when
// the Segments switch is off, no category is on, none has complete distances
// or no IPP was imported (see buildLpbContext in map-segment-utils.js for
// `reason`).
function buildLpbContext(bundle) {
    const utils = getMapSegmentUtils();
    if (typeof utils.buildLpbContext === 'function') return utils.buildLpbContext(bundle);
    return {active: false, reason: 'unavailable', lpb: normalizeLostPersonBehavior(bundle && bundle.lostPersonBehavior), features: [], ipp: null, categories: [], incomplete: [], category: null, terrain: '', distances: null};
}

// null when the adjustment is not active; otherwise {matched, distanceMiles,
// contributions, addedPercent, factor} for one Segments row: one contribution
// per applied category (its bracket and the percentage of the PSRi it adds),
// their sum, and factor = 1 + sum / 100 (1 for a segment without a shape on
// the map or beyond every category's 95 % distance).
function getLpbSegmentAdjustment(row, context) {
    const utils = getMapSegmentUtils();
    return typeof utils.getLpbSegmentAdjustment === 'function' ? utils.getLpbSegmentAdjustment(row, context) : null;
}

// The PSR factor of one Segments row under the current settings (1 when the
// adjustment is not active or does not reach this segment).
function getLpbPsrFactor(row, context) {
    const adjustment = getLpbSegmentAdjustment(row, context);
    return adjustment && Number.isFinite(adjustment.factor) && adjustment.factor > 0 ? adjustment.factor : 1;
}

// The login's distance tables from the server (GET /api/lpb/distances):
//   defaults   what the database holds for every category x terrain
//   overrides  the brackets this login edited (lpb_user_distances)
// Read once per page load by the Incident and Maps pages (both show the
// section); `effective` merges the two.
let _lpbDistances = null;
let _lpbDistancesPromise = null;

function getLpbDistancesApiUrl() {
    const serverUrl = getSyncServerUrl();
    if (!serverUrl || !getUserCredentials()) return '';
    return `${serverUrl.replace(/\/$/, '')}/api/lpb/distances`;
}

function normalizeLpbDistanceTable(raw) {
    const out = {};
    if (!raw || typeof raw !== 'object') return out;
    Object.keys(raw).forEach(category => {
        const terrains = raw[category];
        if (!terrains || typeof terrains !== 'object') return;
        out[category] = {};
        Object.keys(terrains).forEach(terrain => {
            const values = terrains[terrain];
            if (!values || typeof values !== 'object') return;
            const entry = {};
            getLpbBrackets().forEach(bracket => {
                const miles = normalizeLpbDistanceMiles(values[bracket.key]);
                if (miles !== null) entry[bracket.key] = miles;
            });
            out[category][terrain] = entry;
        });
    });
    return out;
}

async function loadLpbDistances(options = {}) {
    if (_lpbDistances && !options.force) return _lpbDistances;
    if (_lpbDistancesPromise) return _lpbDistancesPromise;
    const url = getLpbDistancesApiUrl();
    if (!url) return null;
    _lpbDistancesPromise = (async () => {
        try {
            const resp = await apiFetch(`${url}?_=${Date.now()}`, {headers: getAuthHeaders()});
            if (!resp.ok) {
                console.warn(`Could not read the Lost Person Behavior distances from the server (HTTP ${resp.status}).`);
                return _lpbDistances;
            }
            const body = await resp.json();
            _lpbDistances = {
                defaults: normalizeLpbDistanceTable(body && body.defaults),
                overrides: normalizeLpbDistanceTable(body && body.overrides)
            };
            return _lpbDistances;
        } catch (err) {
            console.warn('Could not read the Lost Person Behavior distances from the server:', err);
            return _lpbDistances;
        } finally {
            _lpbDistancesPromise = null;
        }
    })();
    return _lpbDistancesPromise;
}

// The database default for one bracket of a category x terrain; the seed
// value when the server has not answered (yet).
function getLpbDefaultDistance(categoryLabel, terrain, bracketKey) {
    const table = _lpbDistances && _lpbDistances.defaults && _lpbDistances.defaults[categoryLabel];
    const entry = table && table[terrain];
    if (entry && typeof entry[bracketKey] === 'number') return entry[bracketKey];
    const utils = getMapSegmentUtils();
    const seed = utils.LPB_SEED_DISTANCES || LPB_SEED_DISTANCES_FALLBACK;
    return typeof seed[bracketKey] === 'number' ? seed[bracketKey] : null;
}

function getLpbDefaultDistances(categoryLabel, terrain) {
    const out = {};
    getLpbBrackets().forEach(bracket => {
        const miles = getLpbDefaultDistance(categoryLabel, terrain, bracket.key);
        if (miles !== null) out[bracket.key] = miles;
    });
    return out;
}

// The login's own value for a bracket (or null when it never edited it).
function getLpbOverrideDistance(categoryLabel, terrain, bracketKey) {
    const table = _lpbDistances && _lpbDistances.overrides && _lpbDistances.overrides[categoryLabel];
    const entry = table && table[terrain];
    return entry && typeof entry[bracketKey] === 'number' ? entry[bracketKey] : null;
}

// What a case starts from when a category is switched on or its terrain
// changes: the login's edited value where there is one, else the default.
function getLpbEffectiveDistances(categoryLabel, terrain) {
    const out = {};
    getLpbBrackets().forEach(bracket => {
        const override = getLpbOverrideDistance(categoryLabel, terrain, bracket.key);
        const miles = override !== null ? override : getLpbDefaultDistance(categoryLabel, terrain, bracket.key);
        if (miles !== null) out[bracket.key] = miles;
    });
    return out;
}

// Store one edited bracket (miles, or null to go back to the default) in the
// login's table on the server and in the page's copy. Resolves to true when
// the server confirmed it.
async function saveLpbOverrideDistance(categoryLabel, terrain, bracketKey, miles) {
    const url = getLpbDistancesApiUrl();
    if (!_lpbDistances) _lpbDistances = {defaults: {}, overrides: {}};
    const overrides = _lpbDistances.overrides;
    if (!overrides[categoryLabel]) overrides[categoryLabel] = {};
    if (!overrides[categoryLabel][terrain]) overrides[categoryLabel][terrain] = {};
    if (miles === null) {
        delete overrides[categoryLabel][terrain][bracketKey];
    } else {
        overrides[categoryLabel][terrain][bracketKey] = miles;
    }
    if (!url) return false;
    const values = {};
    getLpbBrackets().forEach(bracket => {
        const value = overrides[categoryLabel][terrain][bracket.key];
        values[bracket.key] = typeof value === 'number' ? value : null;
    });
    try {
        const resp = await apiFetch(url, {
            method: 'PUT',
            headers: getAuthHeaders(),
            body: JSON.stringify({category: categoryLabel, terrain, values})
        });
        if (!resp.ok) {
            console.warn(`The server did not store the Lost Person Behavior distance (HTTP ${resp.status}).`);
            return false;
        }
        return true;
    } catch (err) {
        console.warn('The server did not store the Lost Person Behavior distance:', err);
        return false;
    }
}

function getSegmentDisplaySettings(bundle) {
    const utils = getMapSegmentUtils();
    if (typeof utils.normalizeSegmentDisplaySettings === 'function') {
        return utils.normalizeSegmentDisplaySettings(bundle || {});
    }

    const normalizeColor = (value, fallback) => {
        const raw = String(value || '').trim();
        const stripped = raw.replace(/^#/, '').toLowerCase();
        if (!/^[0-9a-f]{3}([0-9a-f]{3})?$/i.test(stripped)) {
            return fallback;
        }
        const expanded = stripped.length === 3
            ? stripped.split('').map(char => char + char).join('')
            : stripped;
        return `#${expanded}`;
    };
    // Defaults for segments that are actively being searched: a light blue fill so the
    // underlying map stays readable, and a fully opaque blue border that outlines it.
    const ACTIVE_SEARCH_DEFAULTS = {
        fillOpacityPercent: 10,
        fillColor: '#228be6',
        borderOpacityPercent: 100,
        borderColor: '#228be6',
        borderWidth: 3
    };
    const normalizeOpacity = (value, fallback) => {
        const parsed = parseFloat(value);
        return Number.isFinite(parsed) ? Math.min(100, Math.max(0, parsed)) : fallback;
    };
    // Border thickness is expressed in pixels/points and is clamped to a range that
    // stays usable on both the in-app map symbols and the CalTopo stroke-width.
    const normalizeBorderWidth = (value, fallback) => {
        const parsed = parseFloat(value);
        if (!Number.isFinite(parsed)) return fallback;
        return Math.min(20, Math.max(0, Math.round(parsed * 10) / 10));
    };
    const toRgbTriple = hex => {
        const stripped = String(hex || '').replace(/^#/, '');
        const full = stripped.length === 3
            ? stripped.split('').map(char => char + char).join('')
            : stripped;
        return [
            parseInt(full.slice(0, 2), 16) || 0,
            parseInt(full.slice(2, 4), 16) || 0,
            parseInt(full.slice(4, 6), 16) || 0
        ];
    };

    const activeSearchOpacityPercent = normalizeOpacity(bundle?.segmentActiveSearchOpacityPercent, ACTIVE_SEARCH_DEFAULTS.fillOpacityPercent);
    const activeSearchBorderOpacityPercent = normalizeOpacity(bundle?.segmentActiveSearchBorderOpacityPercent, ACTIVE_SEARCH_DEFAULTS.borderOpacityPercent);
    const activeSearchFillColor = normalizeColor(bundle?.segmentActiveSearchFillColor, ACTIVE_SEARCH_DEFAULTS.fillColor);
    const activeSearchBorderColor = normalizeColor(bundle?.segmentActiveSearchBorderColor, ACTIVE_SEARCH_DEFAULTS.borderColor);
    const activeSearchBorderWidth = normalizeBorderWidth(bundle?.segmentActiveSearchBorderWidth, ACTIVE_SEARCH_DEFAULTS.borderWidth);

    return {
        usePsriMax: bundle?.segmentColorScaleUsePsriMax === true,
        lowColor: normalizeColor(bundle?.segmentColorScaleLowColor, '#40c057'),
        midColor: normalizeColor(bundle?.segmentColorScaleMidColor, '#ffd43b'),
        highColor: normalizeColor(bundle?.segmentColorScaleHighColor, '#fa5252'),
        activeSearchOpacityPercent,
        activeSearchOpacity: activeSearchOpacityPercent / 100,
        activeSearchFillColor,
        activeSearchFillRgb: toRgbTriple(activeSearchFillColor),
        activeSearchBorderColor,
        activeSearchBorderRgb: toRgbTriple(activeSearchBorderColor),
        activeSearchBorderOpacityPercent,
        activeSearchBorderOpacity: activeSearchBorderOpacityPercent / 100,
        activeSearchBorderWidth
    };
}

// A color-sync interval is a whole number of units (minutes or seconds) of at
// least 1; anything else falls back to the given default. Shared by the
// sanitizer, the scheduler and the Settings page so they can never disagree.
function normalizeCalTopoColorSyncInterval(value, fallback) {
    if (value === null || value === undefined || value === '') return fallback;
    const parsed = typeof value === 'number' ? value : parseFloat(String(value).trim());
    if (!Number.isFinite(parsed)) return fallback;
    const rounded = Math.round(parsed);
    return rounded >= 1 ? rounded : fallback;
}

// Returns {heartbeatMinutes, cooldownSeconds, heartbeatMs, cooldownMs} for the
// CalTopo color push. The cooldown ("never more often than") can never exceed
// the heartbeat ("at least every"), so it is clamped to heartbeat * 60 seconds
// here rather than only in the Settings UI - a stale preference record must not
// be able to produce a cooldown longer than the heartbeat.
function getCalTopoColorSyncSettings(bundle) {
    const source = (bundle && typeof bundle === 'object') ? bundle : {};
    const heartbeatMinutes = normalizeCalTopoColorSyncInterval(source.caltopoColorSyncHeartbeatMinutes, CALTOPO_COLOR_SYNC_DEFAULT_HEARTBEAT_MINUTES);
    const rawCooldown = normalizeCalTopoColorSyncInterval(source.caltopoColorSyncCooldownSeconds, CALTOPO_COLOR_SYNC_DEFAULT_COOLDOWN_SECONDS);
    const cooldownSeconds = Math.min(rawCooldown, heartbeatMinutes * 60);
    return {
        heartbeatMinutes,
        cooldownSeconds,
        heartbeatMs: heartbeatMinutes * 60 * 1000,
        cooldownMs: cooldownSeconds * 1000
    };
}

// Returns the normalized display settings for either an already-normalized settings
// object or a raw bundle, so callers can accept both shapes.
function normalizeSegmentDisplaySettingsInput(settings) {
    return (settings && typeof settings.activeSearchOpacity === 'number')
        ? settings
        : getSegmentDisplaySettings(settings);
}

function formatSegmentAssignmentLabel(region, segment) {
    const utils = getMapSegmentUtils();
    if (typeof utils.formatSegmentAssignmentLabel === 'function') {
        return utils.formatSegmentAssignmentLabel(region, segment);
    }

    const trimmedSegment = String(segment || '').trim();
    const trimmedRegion = String(region || '').trim();
    if (!trimmedSegment) return '';
    return trimmedRegion ? `${trimmedRegion} - ${trimmedSegment}` : trimmedSegment;
}

function buildActiveSearchSegmentNameSet(bundle, rows) {
    const utils = getMapSegmentUtils();
    if (typeof utils.buildActiveSearchSegmentNameSet === 'function') {
        const utilNames = utils.buildActiveSearchSegmentNameSet(
            rows || ensureSegmentsPageRows(bundle),
            bundle?.currentAssignments || {},
            bundle?.teamStatuses || {}
        );
        // Custom (manually entered) searches have no team status; they stay
        // "active" until their Task Assignment form is marked completed.
        return addCustomSearchActiveSegmentNames(bundle, utilNames);
    }

    const names = new Set();
    const currentAssignments = bundle?.currentAssignments || {};
    const teamStatuses = bundle?.teamStatuses || {};
    (rows || ensureSegmentsPageRows(bundle)).forEach(row => {
        const fullName = formatSegmentAssignmentLabel(row?.[0], row?.[1]);
        if (!fullName) return;
        const isSearching = Object.entries(currentAssignments).some(([teamName, assignment]) => {
            const status = String(teamStatuses[teamName] || '').trim().toLowerCase();
            return String(assignment || '').includes(fullName) && status && !status.includes('finished segment') && !status.startsWith('at base');
        });
        if (!isSearching) return;
        names.add(normalizeSegmentNameForMatch(row?.[1]));
        names.add(normalizeSegmentNameForMatch(fullName));
    });
    return addCustomSearchActiveSegmentNames(bundle, names);
}

function isFeatureActivelyBeingSearched(feature, activeSearchNames) {
    const utils = getMapSegmentUtils();
    if (typeof utils.isFeatureActivelyBeingSearched === 'function') {
        return utils.isFeatureActivelyBeingSearched(feature, activeSearchNames);
    }

    const attributes = feature?.attributes || feature?.properties || {};
    const keys = [attributes.name, feature?.name, attributes.label, attributes.title]
        .map(normalizeSegmentNameForMatch)
        .filter(Boolean);
    return keys.some(key => activeSearchNames instanceof Set && activeSearchNames.has(key));
}

function resolveDisplayedSegmentOpacity(isActiveSearch, settings, baseOpacity = 0.2) {
    const utils = getMapSegmentUtils();
    if (typeof utils.resolveDisplayedSegmentOpacity === 'function') {
        return utils.resolveDisplayedSegmentOpacity(isActiveSearch, settings, baseOpacity);
    }

    const safeBaseOpacity = Number.isFinite(baseOpacity) ? Math.min(1, Math.max(0, baseOpacity)) : 0.2;
    if (!isActiveSearch) {
        return safeBaseOpacity;
    }
    // `settings` may already be a normalized display-settings object (with a numeric
    // activeSearchOpacity) or a raw bundle; use the normalized value directly when
    // present so the user's configured active-search opacity is honored.
    const normalizedSettings = normalizeSegmentDisplaySettingsInput(settings);
    // The active-search opacity setting is an ABSOLUTE reset: actively-searched
    // segments are drawn at exactly the configured opacity, regardless of the
    // segment's existing/base opacity.
    const activeSearchOpacity = Number.isFinite(normalizedSettings.activeSearchOpacity)
        ? normalizedSettings.activeSearchOpacity
        : 0.1;
    return Math.min(1, Math.max(0, activeSearchOpacity));
}

// Like resolveDisplayedSegmentOpacity, the active-search border opacity is an
// ABSOLUTE reset applied only to segments that are actively being searched.
function resolveDisplayedSegmentBorderOpacity(isActiveSearch, settings, baseOpacity = 1) {
    const safeBaseOpacity = Number.isFinite(baseOpacity) ? Math.min(1, Math.max(0, baseOpacity)) : 1;
    if (!isActiveSearch) {
        return safeBaseOpacity;
    }
    const normalizedSettings = normalizeSegmentDisplaySettingsInput(settings);
    const borderOpacity = Number.isFinite(normalizedSettings.activeSearchBorderOpacity)
        ? normalizedSettings.activeSearchBorderOpacity
        : 1;
    return Math.min(1, Math.max(0, borderOpacity));
}

// Actively-searched segments override their computed (PSRc gradient) fill color with
// the color configured in Settings; every other segment keeps `baseColor`.
function resolveDisplayedSegmentFillColor(isActiveSearch, settings, baseColor) {
    if (!isActiveSearch) {
        return baseColor;
    }
    const normalizedSettings = normalizeSegmentDisplaySettingsInput(settings);
    return normalizedSettings.activeSearchFillColor || baseColor;
}

function resolveDisplayedSegmentBorderColor(isActiveSearch, settings, baseColor) {
    if (!isActiveSearch) {
        return baseColor;
    }
    const normalizedSettings = normalizeSegmentDisplaySettingsInput(settings);
    return normalizedSettings.activeSearchBorderColor || baseColor;
}

function resolveDisplayedSegmentBorderWidth(isActiveSearch, settings, baseWidth) {
    if (!isActiveSearch) {
        return baseWidth;
    }
    const normalizedSettings = normalizeSegmentDisplaySettingsInput(settings);
    return Number.isFinite(normalizedSettings.activeSearchBorderWidth)
        ? normalizedSettings.activeSearchBorderWidth
        : baseWidth;
}

// Returns the [r, g, b] triple an actively-searched segment should use, falling back
// to `baseRgb` for segments that are not actively being searched.
function resolveDisplayedSegmentRgb(isActiveSearch, settings, baseRgb, kind) {
    if (!isActiveSearch) {
        return baseRgb;
    }
    const normalizedSettings = normalizeSegmentDisplaySettingsInput(settings);
    const override = kind === 'border'
        ? normalizedSettings.activeSearchBorderRgb
        : normalizedSettings.activeSearchFillRgb;
    return Array.isArray(override) && override.length === 3 ? override : baseRgb;
}

function buildSegmentNameSet(rows) {
    const utils = getMapSegmentUtils();
    if (typeof utils.buildSegmentNameSet === 'function') {
        return utils.buildSegmentNameSet(rows);
    }
    const names = new Set();
    (rows || []).forEach(row => {
        const nameKey = normalizeSegmentNameForMatch(row?.[1]);
        if (nameKey) names.add(nameKey);
    });
    return names;
}

// ---------------------------------------------------------------------------
// Fetched CalTopo features: A-Z ordering, name search, and the hidden
// "unwanted" list that keeps shapes nobody wants imported out of the way.
// ---------------------------------------------------------------------------

function getMapFeatureDisplayName(feature) {
    const utils = getMapSegmentUtils();
    if (typeof utils.getFeatureDisplayName === 'function') return utils.getFeatureDisplayName(feature);
    const attrs = feature?.attributes || feature?.properties || {};
    return String(attrs.name || attrs.label || attrs.title || '').trim() || 'Unnamed Graphic';
}

function sortMapFeaturesByName(features) {
    const utils = getMapSegmentUtils();
    if (typeof utils.sortFeaturesByName === 'function') return utils.sortFeaturesByName(features);
    return (Array.isArray(features) ? features.slice() : []).sort((a, b) =>
        getMapFeatureDisplayName(a).localeCompare(getMapFeatureDisplayName(b), undefined, {numeric: true, sensitivity: 'base'}));
}

function filterMapFeaturesByName(features, query) {
    const utils = getMapSegmentUtils();
    if (typeof utils.filterFeaturesByName === 'function') return utils.filterFeaturesByName(features, query);
    const needle = normalizeSegmentNameForMatch(query);
    const list = Array.isArray(features) ? features : [];
    if (!needle) return list.slice();
    return list.filter(feature => normalizeSegmentNameForMatch(getMapFeatureDisplayName(feature)).includes(needle));
}

function getMapFeatureIdentityKey(feature) {
    const utils = getMapSegmentUtils();
    if (typeof utils.getFeatureIdentityKey === 'function') return utils.getFeatureIdentityKey(feature);
    const attrs = feature?.attributes || feature?.properties || {};
    const id = String(attrs.id || '').trim();
    return id && !isSyntheticCalTopoFeatureId(id) ? `id:${id}` : `name:${normalizeSegmentNameForMatch(getMapFeatureDisplayName(feature))}`;
}

// {id, name} of a fetched feature: the real CalTopo id (never a made-up gfx-N
// one) and the lower-cased display name.
function getMapFeatureIdentity(feature) {
    const utils = getMapSegmentUtils();
    if (typeof utils.getFeatureIdentity === 'function') return utils.getFeatureIdentity(feature);
    const attrs = feature?.attributes || feature?.properties || {};
    const rawId = attrs.id !== undefined && attrs.id !== null ? attrs.id : feature?.id;
    const id = String(rawId === undefined || rawId === null ? '' : rawId).trim();
    return {
        id: id && !isSyntheticCalTopoFeatureId(id) ? id : '',
        name: normalizeSegmentNameForMatch(getMapFeatureDisplayName(feature))
    };
}

function unwantedEntryMatchesIdentity(entry, identity) {
    if (identity.id && entry.id) return identity.id === entry.id;
    return !!identity.name && identity.name === entry.name;
}

function getUnwantedMapFeatures(bundle) {
    const utils = getMapSegmentUtils();
    const list = bundle?.unwantedMapFeatures;
    if (typeof utils.normalizeUnwantedFeatureList === 'function') return utils.normalizeUnwantedFeatureList(list);
    return (Array.isArray(list) ? list : []).map(entry => {
        if (!entry || typeof entry !== 'object') return null;
        const id = String(entry.id || '').trim();
        const name = normalizeSegmentNameForMatch(entry.name);
        if (!id && !name) return null;
        const normalized = {id: isSyntheticCalTopoFeatureId(id) ? '' : id, name};
        if (entry.markedAt) normalized.markedAt = entry.markedAt;
        if (typeof entry.filteredType === 'string' && entry.filteredType) normalized.filteredType = entry.filteredType;
        return normalized;
    }).filter(Boolean);
}

function isMapFeatureUnwanted(feature, bundle) {
    const utils = getMapSegmentUtils();
    const unwanted = getUnwantedMapFeatures(bundle);
    if (typeof utils.isFeatureUnwanted === 'function') return utils.isFeatureUnwanted(feature, unwanted);
    const identity = getMapFeatureIdentity(feature);
    return unwanted.some(entry => unwantedEntryMatchesIdentity(entry, identity));
}

// Imported as a Segments row (by CalTopo id, else by name).
function isMapFeatureImportedAsSegment(feature, bundle) {
    const utils = getMapSegmentUtils();
    const rows = ensureSegmentsPageRows(bundle);
    if (typeof utils.isFeatureImportedAsSegment === 'function') return utils.isFeatureImportedAsSegment(feature, rows);
    const identity = getMapFeatureIdentity(feature);
    return (Array.isArray(rows) ? rows : []).some(row => {
        if (!Array.isArray(row)) return false;
        const rowId = String(row[9] || '').trim();
        if (identity.id && rowId && identity.id === rowId) return true;
        const rowName = normalizeSegmentNameForMatch(row[1]);
        return !!rowName && rowName === identity.name;
    });
}

// Imported into the Search Log page's Searchers Tracks table.
function isMapFeatureImportedAsTrack(feature, bundle) {
    const utils = getMapSegmentUtils();
    const tracks = (bundle || loadBundle()).searcherTracks;
    return typeof utils.isFeatureImportedAsTrack === 'function' ? utils.isFeatureImportedAsTrack(feature, tracks) : false;
}

// Accounted for = imported somewhere: as a segment or as a searcher track.
function isMapFeatureAccountedFor(feature, bundle) {
    const b = bundle || loadBundle();
    return isMapFeatureImportedAsSegment(feature, b) || isMapFeatureImportedAsTrack(feature, b);
}

// Where a fetched feature goes when it is imported: 'segment' (a CalTopo
// Assignment -> Segments page), 'track' (a line -> Searchers Tracks on the
// Search Log page) or '' (markers, plain shapes, other: not importable).
function getMapFeatureImportTarget(feature) {
    const utils = getMapSegmentUtils();
    if (typeof utils.getFeatureImportTarget === 'function') return utils.getFeatureImportTarget(feature);
    const category = getMapFeatureCategoryKey(feature);
    return category === 'assignment' ? 'segment' : (category === 'route' ? 'track' : '');
}

// {segment: [...], track: [...], other: [...]} - features by import target.
function groupMapFeaturesByImportTarget(features) {
    const groups = {segment: [], track: [], other: []};
    (Array.isArray(features) ? features : []).forEach(feature => {
        const target = getMapFeatureImportTarget(feature);
        groups[target === 'segment' || target === 'track' ? target : 'other'].push(feature);
    });
    return groups;
}

// Fetched features that are neither imported (as a segment or a searcher
// track) nor marked unwanted, A-Z. Pass {ignoreTypeFilters: true} to also
// include the feature types the team switched off below the map (normally
// those are hidden from every list).
function getUnaccountedMapFeatures(bundle, options = {}) {
    const b = bundle || loadBundle();
    const map = Array.isArray(b.maps) && b.maps[0] ? b.maps[0] : null;
    const features = map && Array.isArray(map.features) ? map.features : [];
    const utils = getMapSegmentUtils();
    let unaccounted;
    if (typeof utils.getUnaccountedFeatures === 'function') {
        unaccounted = utils.getUnaccountedFeatures(features, ensureSegmentsPageRows(b), getUnwantedMapFeatures(b), b.searcherTracks);
    } else {
        unaccounted = sortMapFeaturesByName(features.filter(feature => !isMapFeatureAccountedFor(feature, b) && !isMapFeatureUnwanted(feature, b)));
    }
    if (options && options.ignoreTypeFilters) return unaccounted;
    const filters = getMapFeatureTypeFilters(b);
    return unaccounted.filter(feature => filters[getMapFeatureCategoryKey(feature)] !== false);
}

// Unaccounted features whose CalTopo type is Assignment: each gets its own
// "New Assignment" notification with Import / Decline buttons.
function getUnaccountedAssignmentMapFeatures(bundle) {
    return getUnaccountedMapFeatures(bundle).filter(feature => getMapFeatureCategoryKey(feature) === 'assignment');
}

// "A, B, C" for the activity log; long lists are cut off with "... (+N more)"
// so one entry never balloons because a whole map was imported at once.
function summarizeNamesForLog(names, max = 15) {
    const list = (Array.isArray(names) ? names : []).map(n => String(n || '').trim()).filter(Boolean);
    if (list.length <= max) return list.join(', ');
    return `${list.slice(0, max).join(', ')} (+${list.length - max} more)`;
}

// Adds `features` to the hidden unwanted list (features that are already
// segments are skipped: they are accounted for anyway) and records the shapes
// that were newly marked in the activity log. Returns how many entries were
// newly added. `options.filteredType` tags the entries as hidden by that
// feature-type toggle (so turning the type back on restores them) and
// `options.reason` replaces the default "(not imported)" in the log entry.
function markMapFeaturesUnwanted(features, bundle = null, options = {}) {
    const utils = getMapSegmentUtils();
    const b = bundle || loadBundle();
    const filteredType = (options && typeof options.filteredType === 'string' && options.filteredType) ? options.filteredType : '';
    const reason = (options && options.reason) ? String(options.reason) : 'not imported';
    const candidates = (Array.isArray(features) ? features : []).filter(feature => !isMapFeatureAccountedFor(feature, b));
    const before = getUnwantedMapFeatures(b);
    const wasUnwanted = feature => {
        const identity = getMapFeatureIdentity(feature);
        return before.some(entry => unwantedEntryMatchesIdentity(entry, identity));
    };
    const newlyMarkedNames = candidates.filter(feature => !wasUnwanted(feature)).map(getMapFeatureDisplayName);
    let after;
    if (typeof utils.markFeaturesUnwanted === 'function') {
        after = utils.markFeaturesUnwanted(before, candidates, undefined, filteredType || undefined);
    } else {
        after = before.slice();
        const markedAt = new Date().toISOString();
        candidates.forEach(feature => {
            const identity = getMapFeatureIdentity(feature);
            if (after.some(entry => unwantedEntryMatchesIdentity(entry, identity))) return;
            const entry = {id: identity.id, name: identity.name, markedAt};
            if (filteredType) entry.filteredType = filteredType;
            after.push(entry);
        });
    }
    const added = after.length - before.length;
    if (added > 0) {
        b.unwantedMapFeatures = after;
        addActivityLogEntry('System', `Marked ${added} CalTopo shape${added === 1 ? '' : 's'} as unwanted (${reason}): ${summarizeNamesForLog(newlyMarkedNames)}`, b);
        if (!bundle) saveBundle(b);
    }
    return added;
}

// Marks every not-yet-imported feature whose type is switched off below the
// map as unwanted (tagged with the type, so switching it back on restores
// them). Runs after each fetch and whenever a toggle is turned off. Returns
// how many entries were newly added.
function applyMapFeatureTypeFilters(bundle = null) {
    const b = bundle || loadBundle();
    const filters = getMapFeatureTypeFilters(b);
    const disabledKeys = Object.keys(filters).filter(key => filters[key] === false);
    if (!disabledKeys.length) return 0;
    const candidates = getUnaccountedMapFeatures(b, {ignoreTypeFilters: true});
    let added = 0;
    disabledKeys.forEach(typeKey => {
        const ofType = candidates.filter(feature => getMapFeatureCategoryKey(feature) === typeKey);
        if (!ofType.length) return;
        added += markMapFeaturesUnwanted(ofType, b, {
            filteredType: typeKey,
            reason: `${getMapFeatureCategoryPluralLabel(typeKey)} are switched off on the Maps page`
        });
    });
    if (added > 0 && !bundle) saveBundle(b);
    return added;
}

// Takes the entries a feature-type toggle added for `typeKey` off the
// unwanted list again (entries a person marked stay). Returns how many were
// restored.
function restoreMapFeaturesFilteredByType(typeKey, bundle = null) {
    const utils = getMapSegmentUtils();
    const b = bundle || loadBundle();
    const before = getUnwantedMapFeatures(b);
    const after = typeof utils.unmarkFeaturesUnwantedByFilteredType === 'function'
        ? utils.unmarkFeaturesUnwantedByFilteredType(before, typeKey)
        : before.filter(entry => entry.filteredType !== typeKey);
    const removed = before.length - after.length;
    if (removed > 0) {
        const restoredNames = before.filter(entry => entry.filteredType === typeKey).map(entry => entry.name);
        b.unwantedMapFeatures = after;
        addActivityLogEntry('System', `Restored ${removed} CalTopo shape${removed === 1 ? '' : 's'} hidden by the ${getMapFeatureCategoryPluralLabel(typeKey)} toggle: ${summarizeNamesForLog(restoredNames)}`, b);
        if (!bundle) saveBundle(b);
    }
    return removed;
}

// The toggle switches in the table below the map. Turning a type OFF marks
// every not-yet-imported feature of that type unwanted (and does the same
// for whatever later fetches bring in); turning it back ON restores the
// features that toggle hid, so they show up as new again.
function setMapFeatureTypeFilterEnabled(typeKey, enabled) {
    const categories = getMapFeatureCategories();
    if (!categories.some(category => category.key === typeKey)) return;
    const bundle = loadBundle();
    const filters = getMapFeatureTypeFilters(bundle);
    const wasEnabled = filters[typeKey] !== false;
    const nextEnabled = enabled !== false;
    filters[typeKey] = nextEnabled;
    bundle.mapFeatureTypeFilters = filters;
    const label = getMapFeatureCategoryPluralLabel(typeKey);
    if (wasEnabled !== nextEnabled) {
        logSettingChange(`Maps page: show new ${label}`, wasEnabled ? 'ON' : 'OFF', nextEnabled ? 'ON' : 'OFF', bundle);
    }
    let marked = 0;
    let restored = 0;
    if (nextEnabled) {
        restored = restoreMapFeaturesFilteredByType(typeKey, bundle);
    } else {
        marked = applyMapFeatureTypeFilters(bundle);
    }
    saveBundle(bundle);

    if (marked > 0) {
        showToast(`${label} are switched off: ${marked} shape${marked === 1 ? ' was' : 's were'} marked unwanted.`, 'Map Feature Types');
    } else if (restored > 0) {
        showToast(`${label} are switched on again: ${restored} shape${restored === 1 ? ' was' : 's were'} restored.`, 'Map Feature Types');
    }
    if (isMapsPage()) {
        renderUnaccountedFeaturesPanel();
        if (typeof renderFeaturesList === 'function') renderFeaturesList();
    }
    refreshUnaccountedMapFeatureNotifications();
    return {marked, restored};
}

// Takes `features` off the unwanted list again (the "Restore" button) and
// records the restored shapes in the activity log. Returns how many entries
// were removed.
function unmarkMapFeaturesUnwanted(features, bundle = null) {
    const utils = getMapSegmentUtils();
    const b = bundle || loadBundle();
    const before = getUnwantedMapFeatures(b);
    const list = Array.isArray(features) ? features : [];
    const restoredNames = list.filter(feature => {
        const identity = getMapFeatureIdentity(feature);
        return before.some(entry => unwantedEntryMatchesIdentity(entry, identity));
    }).map(getMapFeatureDisplayName);
    let after;
    if (typeof utils.unmarkFeaturesUnwanted === 'function') {
        after = utils.unmarkFeaturesUnwanted(before, list);
    } else {
        const identities = list.map(getMapFeatureIdentity);
        after = before.filter(entry => !identities.some(identity => unwantedEntryMatchesIdentity(entry, identity)));
    }
    const removed = before.length - after.length;
    if (removed > 0) {
        b.unwantedMapFeatures = after;
        addActivityLogEntry('System', `Restored ${removed} CalTopo shape${removed === 1 ? '' : 's'} from the unwanted list: ${summarizeNamesForLog(restoredNames)}`, b);
        if (!bundle) saveBundle(b);
    }
    return removed;
}

function isMapUnaccountedAutoCheckEnabled(bundle) {
    const b = bundle || loadBundle();
    return b.mapUnaccountedAutoCheck !== false;
}

function isMapPsrcOverlayEnabled() {
    return _serverSettings && _serverSettings[MAP_PSRC_OVERLAY_STORAGE_KEY] === 'true';
}

function setMapPsrcOverlayEnabled(enabled) {
    if (_serverSettings) {
        _serverSettings[MAP_PSRC_OVERLAY_STORAGE_KEY] = enabled ? 'true' : 'false';
        saveServerSettings(_serverSettings);
    }
}

function isSegmentsPsrcSortEnabled() {
    if (!_serverSettings) return false;
    const states = _serverSettings[SEGMENTS_PSRC_SORT_STORAGE_KEY];
    if (!states || typeof states !== 'object') return false;
    const bucket = getSyncBucket();
    if (!bucket) return false;
    return states[bucket] === 'true';
}

function setSegmentsPsrcSortEnabled(enabled) {
    if (!_serverSettings) { _serverSettings = {}; }
    const bucket = getSyncBucket();
    if (!bucket) return;
    const existing = _serverSettings[SEGMENTS_PSRC_SORT_STORAGE_KEY];
    const states = (existing && typeof existing === 'object') ? existing : {};
    states[bucket] = enabled ? 'true' : 'false';
    _serverSettings[SEGMENTS_PSRC_SORT_STORAGE_KEY] = states;
    saveServerSettings(_serverSettings);
}

function isCalTopoAssignmentOverlayEnabled() {
    return _serverSettings && _serverSettings[CALTOPO_ASSIGNMENT_OVERLAY_STORAGE_KEY] === 'true';
}

function setCalTopoAssignmentOverlayEnabled(enabled) {
    if (_serverSettings) {
        _serverSettings[CALTOPO_ASSIGNMENT_OVERLAY_STORAGE_KEY] = enabled ? 'true' : 'false';
        saveServerSettings(_serverSettings);
    }
}

function getCalTopoApiObjectType(feature) {
    const utils = getMapSegmentUtils();
    return typeof utils.getCalTopoApiObjectType === 'function' ? utils.getCalTopoApiObjectType(feature) : 'Assignment';
}

function getCalTopoApiObjectTypeCandidates(feature) {
    const primaryType = getCalTopoApiObjectType(feature);
    const candidates = [primaryType, 'Assignment', 'Shape'];

    const attrs = feature?.attributes || feature?.properties || {};
    const rawClass = attrs.class || attrs.type || feature?.geometry?.class || feature?.geometry?.type || '';
    if (typeof rawClass === 'string' && rawClass.trim()) {
        const normalized = rawClass.trim().toLowerCase();
        if (normalized === 'marker') {
            candidates.push('Marker');
        } else if (normalized === 'folder') {
            candidates.push('Folder');
        }
    }

    return candidates.filter((type, index, all) => !!type && all.indexOf(type) === index);
}

function captureCalTopoFeatureStyle(attributes = {}) {
    const utils = getMapSegmentUtils();
    if (typeof utils.captureCalTopoFeatureStyle === 'function') {
        return utils.captureCalTopoFeatureStyle(attributes);
    }
    return {
        color: Object.prototype.hasOwnProperty.call(attributes, 'color') ? attributes.color : null,
        stroke: Object.prototype.hasOwnProperty.call(attributes, 'stroke') ? attributes.stroke : null,
        fill: Object.prototype.hasOwnProperty.call(attributes, 'fill') ? attributes.fill : null,
        'fill-opacity': Object.prototype.hasOwnProperty.call(attributes, 'fill-opacity') ? attributes['fill-opacity'] : null,
        opacity: Object.prototype.hasOwnProperty.call(attributes, 'opacity') ? attributes.opacity : null,
        'stroke-opacity': Object.prototype.hasOwnProperty.call(attributes, 'stroke-opacity') ? attributes['stroke-opacity'] : null,
        'stroke-width': Object.prototype.hasOwnProperty.call(attributes, 'stroke-width') ? attributes['stroke-width'] : null
    };
}

function resolveOverlayOpacity(value, fallback = 1) {
    const parsed = parseFloat(value);
    return Number.isFinite(parsed) ? Math.max(0, Math.min(1, parsed)) : fallback;
}

function applyCapturedCalTopoFeatureStyle(attributes, style = {}) {
    const utils = getMapSegmentUtils();
    if (typeof utils.applyCapturedCalTopoFeatureStyle === 'function') {
        return utils.applyCapturedCalTopoFeatureStyle(attributes, style);
    }
    ['color', 'stroke', 'fill', 'fill-opacity', 'opacity', 'stroke-opacity', 'stroke-width'].forEach(key => {
        if (!Object.prototype.hasOwnProperty.call(style, key)) {
            return;
        }
        const value = style[key];
        if (value === null || value === undefined || value === '') {
            delete attributes[key];
        } else {
            attributes[key] = value;
        }
    });
}

function cloneIfValidGeoJsonGeometry(geometry) {
    if (!geometry || typeof geometry !== 'object' || Array.isArray(geometry)) {
        return null;
    }

    const type = typeof geometry.type === 'string' ? geometry.type.trim() : '';
    if (!type) {
        return null;
    }

    const hasCoordinates = Object.prototype.hasOwnProperty.call(geometry, 'coordinates');
    const hasGeometries = type === 'GeometryCollection' && Array.isArray(geometry.geometries);
    if (!hasCoordinates && !hasGeometries) {
        return null;
    }

    try {
        return JSON.parse(JSON.stringify(geometry));
    } catch (error) {
        return null;
    }
}

function resolveCalTopoFeatureId(feature, attributes = {}, fallbackId = '') {
    const candidates = [
        feature?.id,
        attributes?.id,
        attributes?.uuid,
        attributes?.objectId,
        attributes?.objectID,
        attributes?.featureId,
        attributes?.assignmentId,
        attributes?.sid,
        attributes?.gid,
        feature?.uuid,
        feature?.objectId,
        feature?.objectID,
        feature?.featureId,
        feature?.assignmentId,
        feature?.sid,
        feature?.gid
    ];

    for (const candidate of candidates) {
        if (candidate === null || candidate === undefined) {
            continue;
        }
        if (typeof candidate === 'number' && Number.isFinite(candidate)) {
            return String(candidate);
        }
        const normalized = String(candidate).trim();
        if (normalized && normalized !== '[object Object]') {
            return normalized;
        }
    }

    return typeof fallbackId === 'string' ? fallbackId : '';
}

function isSyntheticCalTopoFeatureId(featureId) {
    const normalizedId = typeof featureId === 'string' ? featureId.trim() : String(featureId || '').trim();
    return /^gfx-\d+$/i.test(normalizedId);
}

function getCalTopoWritableFeatureId(feature) {
    const attrs = feature?.attributes || feature?.properties || {};
    const resolvedId = resolveCalTopoFeatureId(feature, attrs, '');
    if (!resolvedId || isSyntheticCalTopoFeatureId(resolvedId)) {
        return '';
    }
    return resolvedId;
}

function getCalTopoOverlayOriginalStyleKey(feature) {
    const writableId = getCalTopoWritableFeatureId(feature);
    if (writableId) {
        return writableId;
    }
    const attrs = feature?.attributes || feature?.properties || {};
    const fallbackId = resolveCalTopoFeatureId(feature, attrs, '');
    return fallbackId || '';
}

function buildCalTopoFeatureUpdatePayload(feature, styleOverrides = {}) {
    const utils = getMapSegmentUtils();
    if (typeof utils.buildCalTopoFeatureUpdatePayload === 'function') {
        return utils.buildCalTopoFeatureUpdatePayload(feature, styleOverrides);
    }
    const attributes = {...(feature?.attributes || feature?.properties || {})};
    const geometry = cloneIfValidGeoJsonGeometry(feature?.geometry);

    delete attributes.ObjectID;
    delete attributes.id;

    applyCapturedCalTopoFeatureStyle(attributes, styleOverrides);

    const payload = {
        id: resolveCalTopoFeatureId(feature, feature?.attributes || feature?.properties || {}, null),
        type: 'Feature',
        properties: attributes
    };

    if (geometry) {
        payload.geometry = geometry;
    }

    return payload;
}

// Border thickness CalTopo draws a shape with when the object carries no
// stroke-width of its own.
const CALTOPO_DEFAULT_STROKE_WIDTH = 2;

// The border thickness a segment goes back to once it is no longer actively
// searched: the stroke-width it had in CalTopo before the overlay first touched
// it, or CalTopo's standard thickness when it never had one.
function resolveCalTopoRestingStrokeWidth(originalStyle) {
    const parsed = parseFloat(originalStyle ? originalStyle['stroke-width'] : NaN);
    return Number.isFinite(parsed) && parsed > 0 ? parsed : CALTOPO_DEFAULT_STROKE_WIDTH;
}

// Builds the CalTopo style overlay for an assignment shape.
// Segments that are NOT actively being searched keep the PSRc gradient color, a base
// fill opacity, and a fully opaque border. Actively-searched segments override the
// fill color/opacity, border color/opacity, and border thickness with the values
// configured on the Settings page.
//
// `restingBorderWidth` is the thickness a resting segment must be drawn with (see
// resolveCalTopoRestingStrokeWidth). It is what puts the border back to standard
// after a search finishes: the active-search thickness was written into the
// CalTopo object, so leaving stroke-width out would keep the thick border. When
// the caller does not know the resting width (null) no stroke-width is sent.
function buildCalTopoOverlayStyle(overlayColor, isActiveSearch, segmentDisplaySettings, restingBorderWidth = null) {
    const STROKE_OVERLAY_OPACITY = 1;
    const fillOpacity = Number(resolveDisplayedSegmentOpacity(isActiveSearch, segmentDisplaySettings, 0.42).toFixed(4));
    const strokeOpacity = Number(resolveDisplayedSegmentBorderOpacity(isActiveSearch, segmentDisplaySettings, STROKE_OVERLAY_OPACITY).toFixed(4));
    const fillColor = resolveDisplayedSegmentFillColor(isActiveSearch, segmentDisplaySettings, overlayColor);
    const borderColor = resolveDisplayedSegmentBorderColor(isActiveSearch, segmentDisplaySettings, overlayColor);
    const baseBorderWidth = Number.isFinite(restingBorderWidth) ? restingBorderWidth : null;
    const borderWidth = resolveDisplayedSegmentBorderWidth(isActiveSearch, segmentDisplaySettings, baseBorderWidth);
    const style = {
        color: borderColor,
        stroke: borderColor,
        fill: fillColor,
        'fill-opacity': fillOpacity,
        opacity: strokeOpacity,
        'stroke-opacity': strokeOpacity
    };
    if (Number.isFinite(borderWidth)) {
        style['stroke-width'] = borderWidth;
    }
    return style;
}

// The line color of a searcher track that has been imported into the search
// file (Search Log page, Searchers Tracks) while the PSRc Assignment Colors
// are on: a darker red, so the map tells the tracks the file counts from the
// ones it does not know yet. Pushed by updateCalTopoAssignmentOverlay along
// with the segment colors; the track's own style is kept in the overlay
// state's `originals` and put back when the colors go off or the track is
// dropped from the table.
const CALTOPO_IMPORTED_TRACK_COLOR = '#8b0000';

// The style pushed for an imported track: the dark red line at full opacity,
// its thickness left as it is (a line has no fill).
function buildCalTopoImportedTrackStyle() {
    return {
        color: CALTOPO_IMPORTED_TRACK_COLOR,
        stroke: CALTOPO_IMPORTED_TRACK_COLOR,
        opacity: 1,
        'stroke-opacity': 1
    };
}

// ---------------------------------------------------------------------------
// Finished-task summaries in CalTopo assignment descriptions.
//
// Once a search of a segment is finished, a one-line summary of that task is
// appended to the CalTopo description of the matching assignment shape:
//
//   [Task #3] Finished 09-04-2026 14:05 - Team Alpha: Jane Doe (lead), John Roe - Tracks: 4 - Sweep width: 40 ft
//
// The line is keyed by its "[Task #N]" prefix, so when the task's data changes
// later (the sweep count is logged, the form's personnel is edited) the line is
// replaced in place instead of being appended a second time. Whatever the
// description already contained is kept in front of the summaries.
// ---------------------------------------------------------------------------

function normalizeSearchTaskTag(taskNum) {
    const num = String(taskNum === undefined || taskNum === null ? '' : taskNum).trim().replace(/^#/, '');
    return num ? `#${num}` : '';
}

function isPreFinishTeamStatus(status) {
    const s = String(status || '').trim().toLowerCase();
    if (!s) return false;
    return !s.includes('finished segment') && !s.startsWith('returning') && !s.startsWith('at base');
}

// A task is finished when the team on it has reported "Finished Assignment" (or
// is already returning / back at base), when no team is on it any more, or -
// for a custom search - when its Task Assignment form is marked completed.
function isSearchTaskFinished(bundle, taskNum) {
    const tag = normalizeSearchTaskTag(taskNum);
    if (!tag) return false;
    const form = getCustomSearchTaskForm(bundle, tag);
    if (form) return !!form.completed;
    const assignments = bundle?.currentAssignments || {};
    const statuses = bundle?.teamStatuses || {};
    return !Object.keys(assignments).some(team => {
        const match = String(assignments[team] || '').match(/#(\d+)/);
        return !!match && `#${match[1]}` === tag && isPreFinishTeamStatus(statuses[team]);
    });
}

function findFinishedAssignmentLogEntry(bundle, taskNum) {
    const tag = normalizeSearchTaskTag(taskNum);
    if (!tag) return null;
    // The activity log is newest-first, so the first hit is the latest report.
    return (bundle?.activityLog || []).find(entry => {
        const entryTag = String(entry?.tag || '');
        if (entryTag !== tag && !entryTag.startsWith(`${tag} - `)) return false;
        return String(entry?.action || '').toLowerCase().includes('finished assignment');
    }) || null;
}

// "MM-DD-YYYY HH:mm" the task was finished at: the team's "Finished assignment"
// report, else the search-complete time typed into the Task Assignment form.
function getSearchTaskFinishStamp(bundle, taskNum, logRow) {
    const entry = findFinishedAssignmentLogEntry(bundle, taskNum);
    if (entry) {
        return [entry.date, entry.time].filter(Boolean).join(' ').trim();
    }
    const form = bundle?.forms?.[String(normalizeSearchTaskTag(taskNum)).replace('#', '')];
    const completeTime = String(form?.completeSearch || '').trim();
    if (completeTime) {
        const date = String(form?.dateTime || logRow?.[1] || '').trim();
        return [date, completeTime].filter(Boolean).join(' ').trim();
    }
    return '';
}

// Team name and members ({name, leader}) that searched the task. The Task
// Assignment form is authoritative when it exists (its personnel list is what
// the user sees and edits); otherwise the members recorded with the team's
// "Finished assignment" report, then the current roster of the team.
function getSearchTaskTeamSummary(bundle, taskNum, logRow) {
    const tag = normalizeSearchTaskTag(taskNum);
    const form = bundle?.forms?.[tag.replace('#', '')];
    const teamCell = String(logRow?.[7] || '').trim();
    const cellTeamName = teamCell.replace(/\s*\(\d+\)\s*$/, '').trim();
    const teamName = String(form?.teamName || '').trim() || cellTeamName;

    let members = (Array.isArray(form?.teamMembers) ? form.teamMembers : [])
        .filter(m => m && String(m.name || '').trim())
        .map(m => ({name: String(m.name).trim(), leader: m.leader === true}));

    if (!members.length) {
        const entry = findFinishedAssignmentLogEntry(bundle, tag);
        members = String(entry?.members || '')
            .split(',')
            .map(part => part.trim())
            .filter(Boolean)
            .map(part => ({name: part.replace(/\*$/, '').trim(), leader: part.endsWith('*')}));
    }

    if (!members.length && teamName) {
        members = (bundle?.pages?.page3 || [])
            .filter(row => Array.isArray(row) && row[1] === teamName && String(row[0] || '').trim())
            .map(row => ({name: String(row[0]).trim(), leader: row[2] === row[0]}));
    }

    return {teamName, members};
}

function formatSearchTaskSweepWidth(value) {
    const raw = String(value === undefined || value === null ? '' : value).trim();
    if (!raw) return 'n/a';
    return /^[\d.]+$/.test(raw) ? `${raw} ft` : raw;
}

function formatSearchTaskTrackCount(value) {
    const raw = String(value === undefined || value === null ? '' : value).trim();
    return raw || 'not logged';
}

// The description line for one Search Log row (see the section comment above).
function buildSearchTaskSummaryLine(bundle, logRow) {
    const tag = normalizeSearchTaskTag(logRow?.[0]);
    if (!tag) return '';
    const parts = [];
    const finishedAt = getSearchTaskFinishStamp(bundle, tag, logRow);
    parts.push(finishedAt ? `Finished ${finishedAt}` : 'Finished');

    const {teamName, members} = getSearchTaskTeamSummary(bundle, tag, logRow);
    const memberText = members.map(m => (m.leader ? `${m.name} (lead)` : m.name)).join(', ');
    if (teamName && memberText) {
        parts.push(`Team ${teamName}: ${memberText}`);
    } else if (teamName) {
        parts.push(`Team ${teamName}`);
    } else if (memberText) {
        parts.push(memberText);
    }

    parts.push(`Tracks: ${formatSearchTaskTrackCount(logRow?.[9])}`);
    parts.push(`Sweep width: ${formatSearchTaskSweepWidth(logRow?.[8])}`);
    return `[Task ${tag}] ${parts.join(' - ')}`;
}

// Appends `line` to `description`, replacing any earlier summary of the same task.
function appendSearchTaskSummaryToDescription(description, taskNum, line) {
    const tag = normalizeSearchTaskTag(taskNum);
    const existing = String(description === undefined || description === null ? '' : description);
    if (!tag || !line) return existing;
    const escaped = `[Task ${tag}]`.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const withoutOld = existing
        .split('\n')
        .filter(part => !new RegExp(`^\\s*${escaped}`).test(part))
        .join('\n')
        .replace(/\s+$/, '');
    return withoutOld ? `${withoutOld}\n${line}` : line;
}

// Map of segment lookup key ("id:<caltopo id>", "region - segment", "segment")
// -> summary lines of every finished task on that segment, in task order.
function buildFinishedTaskSummaryLookup(bundle) {
    const lookup = new Map();
    const rows = ensureSegmentsPageRows(bundle);
    const searchLog = (bundle?.pages?.page4 || []).filter(row => Array.isArray(row) && normalizeSearchTaskTag(row[0]));
    searchLog.sort((a, b) => parseInt(String(a[0]).replace('#', ''), 10) - parseInt(String(b[0]).replace('#', ''), 10));

    searchLog.forEach(row => {
        const tag = normalizeSearchTaskTag(row[0]);
        if (!isSearchTaskFinished(bundle, tag)) return;
        const line = buildSearchTaskSummaryLine(bundle, row);
        if (!line) return;
        const region = row[3];
        const segment = row[4];
        const segmentRow = rows.find(r => Array.isArray(r) && r[0] === region && r[1] === segment)
            || rows.find(r => Array.isArray(r) && normalizeSegmentNameForMatch(r[1]) === normalizeSegmentNameForMatch(segment));
        const keys = new Set();
        const caltopoId = String(segmentRow?.[9] || '').trim();
        if (caltopoId && !isSyntheticCalTopoFeatureId(caltopoId)) keys.add(`id:${caltopoId}`);
        const fullName = normalizeSegmentNameForMatch(formatSegmentAssignmentLabel(region, segment));
        const shortName = normalizeSegmentNameForMatch(segment);
        if (fullName) keys.add(fullName);
        if (shortName) keys.add(shortName);
        keys.forEach(key => {
            if (!lookup.has(key)) lookup.set(key, []);
            lookup.get(key).push({tag, line});
        });
    });
    return lookup;
}

function getFinishedTaskSummariesForFeature(feature, lookup) {
    if (!(lookup instanceof Map) || !lookup.size) return [];
    const attrs = feature?.attributes || feature?.properties || {};
    const id = getCalTopoWritableFeatureId(feature);
    if (id && lookup.has(`id:${id}`)) return lookup.get(`id:${id}`);
    const nameKeys = [attrs.name, attrs.label, attrs.title].map(normalizeSegmentNameForMatch).filter(Boolean);
    for (const key of nameKeys) {
        if (lookup.has(key)) return lookup.get(key);
    }
    return [];
}

// The description an assignment shape should carry once the summaries of its
// finished tasks are appended, or null when nothing needs to change.
function buildCalTopoAssignmentDescription(feature, lookup) {
    const summaries = getFinishedTaskSummariesForFeature(feature, lookup);
    if (!summaries.length) return null;
    const attrs = feature?.attributes || feature?.properties || {};
    const current = String(attrs.description === undefined || attrs.description === null ? '' : attrs.description);
    let next = current;
    summaries.forEach(({tag, line}) => {
        next = appendSearchTaskSummaryToDescription(next, tag, line);
    });
    return next === current ? null : next;
}

async function updateCalTopoAssignmentOverlay(enabled, options = {}) {
    const {ensureFeaturesLoaded = false} = options;
    let bundle = loadBundle();
    let map = bundle.maps && bundle.maps[0] ? bundle.maps[0] : null;

    if (!map || !map.id) {
        throw new Error('Please add a CalTopo map first.');
    }

    if ((!Array.isArray(map.features) || map.features.length === 0) && ensureFeaturesLoaded) {
        await caltopo_request(null, {silent: true});
        bundle = loadBundle();
        map = bundle.maps && bundle.maps[0] ? bundle.maps[0] : null;
    }

    const features = Array.isArray(map?.features) ? map.features : [];
    if (!features.length) {
        throw new Error('Fetch Shapes first so the app knows which CalTopo assignments to update.');
    }

    if (!map.caltopoAssignmentOverlayState || typeof map.caltopoAssignmentOverlayState !== 'object') {
        map.caltopoAssignmentOverlayState = {originals: {}};
    }
    if (!map.caltopoAssignmentOverlayState.originals || typeof map.caltopoAssignmentOverlayState.originals !== 'object') {
        map.caltopoAssignmentOverlayState.originals = {};
    }

    const originals = map.caltopoAssignmentOverlayState.originals;
    const segmentRows = ensureSegmentsPageRows(bundle);
    const segmentDisplaySettings = getSegmentDisplaySettings(bundle);
    const psrcLookup = buildSegmentPsrcLookup(segmentRows, segmentDisplaySettings);
    const activeSearchNames = buildActiveSearchSegmentNameSet(bundle, segmentRows);
    // Summaries of finished tasks, appended to the description of each segment's
    // assignment shape along with the style push (the same POST carries both).
    const finishedTaskSummaries = enabled ? buildFinishedTaskSummaryLookup(bundle) : new Map();
    const matchingAssignments = features.filter(feature => {
        const styleKey = getCalTopoOverlayOriginalStyleKey(feature);
        if (!styleKey || getCalTopoFeatureTypeKey(feature) !== 'assignment') {
            return false;
        }
        if (!enabled) {
            return !!originals[styleKey];
        }
        return !!getFeaturePsrcAssignmentStyle(feature, psrcLookup, segmentDisplaySettings);
    });

    // The searcher tracks imported on the Search Log page: drawn in dark red
    // while the colors are on (their own style captured first, like the
    // assignments'); a track-like shape whose original style is on record but
    // that is no longer imported - or every one of them when the colors go off
    // - gets its original style back.
    const importedTracks = [];
    const trackKeys = new Set();
    if (enabled) {
        getSearcherTracks(bundle).forEach(track => {
            const feature = findFeatureForSearcherTrack(track, features);
            const styleKey = feature ? getCalTopoOverlayOriginalStyleKey(feature) : '';
            if (!feature || !styleKey || trackKeys.has(styleKey) || !getCalTopoWritableFeatureId(feature)) {
                return;
            }
            trackKeys.add(styleKey);
            importedTracks.push({feature, styleKey, style: buildCalTopoImportedTrackStyle(), restore: false});
        });
    }
    features.forEach(feature => {
        const styleKey = getCalTopoOverlayOriginalStyleKey(feature);
        if (!styleKey || trackKeys.has(styleKey) || !originals[styleKey] || !isTrackLikeMapFeature(feature) || !getCalTopoWritableFeatureId(feature)) {
            return;
        }
        trackKeys.add(styleKey);
        importedTracks.push({feature, styleKey, style: originals[styleKey], restore: true});
    });

    if (!matchingAssignments.length && !importedTracks.length) {
        if (!enabled) {
            delete map.caltopoAssignmentOverlayState;
            saveBundle(bundle);
            return {updatedCount: 0};
        }
        throw new Error('No matching assignment shapes were found for your current segments.');
    }

    let updatedCount = 0;
    const errors = [];
    // Whether this push changed anything in the case's own copy of the shapes
    // (a first-time capture of a shape's original style, a new fill/border, a
    // corrected object class, an appended task summary). Only then is the case
    // saved: the heartbeat re-pushes identical colors every minute, and saving
    // the heavy `maps` section each time would make every device download it
    // again for nothing.
    let changedLocally = false;

    // A push is an attempt on this tab's cooldown clock, whether it is the
    // scheduler's or the Maps page toggle's, and whether or not it succeeds.
    if (enabled) {
        markCalTopoColorSyncAttempt();
    }

    for (const feature of matchingAssignments) {
        const styleKey = getCalTopoOverlayOriginalStyleKey(feature);
        const featureId = getCalTopoWritableFeatureId(feature);
        const featureName = feature.attributes.name || styleKey || 'Unnamed Assignment';
        const originalStyle = originals[styleKey] || captureCalTopoFeatureStyle(feature.attributes);
        const style = enabled
            ? getFeaturePsrcAssignmentStyle(feature, psrcLookup, segmentDisplaySettings)
            : originals[styleKey];

        if (!style) {
            continue;
        }

        if (enabled && !Object.prototype.hasOwnProperty.call(originals, styleKey)) {
            originals[styleKey] = originalStyle;
            changedLocally = true;
        }

        const isActiveSearch = enabled && isFeatureActivelyBeingSearched(feature, activeSearchNames);
        const overlayColor = style.stroke || style.fill || (style.color ? style.color.css : null) || '#40c057';
        // Resting segments are pushed with the border thickness they had before the
        // overlay (or CalTopo's standard one), so a segment whose search just
        // finished loses the thick active-search border again.
        const overlayStyle = enabled
            ? buildCalTopoOverlayStyle(overlayColor, isActiveSearch, segmentDisplaySettings, resolveCalTopoRestingStrokeWidth(originals[styleKey]))
            : style;
        const nextDescription = enabled ? buildCalTopoAssignmentDescription(feature, finishedTaskSummaries) : null;

        const payload = buildCalTopoFeatureUpdatePayload(feature, overlayStyle);
        if (nextDescription !== null) {
            payload.properties.description = nextDescription;
        }
        if (featureId) {
            payload.id = featureId;
        }

        if (!featureId) {
            errors.push(`CalTopo could not update assignment "${featureName}" because it has no valid CalTopo object ID.`);
            continue;
        }

        const typeCandidates = getCalTopoApiObjectTypeCandidates(feature);
        let result = null;
        let successfulType = null;

        for (const objectType of typeCandidates) {
            const endpoint = `/api/v1/map/${encodeURIComponent(map.id)}/${encodeURIComponent(objectType)}/${encodeURIComponent(featureId)}`;
            result = await caltopo_api_call('POST', endpoint, payload, map.domain || 'caltopo.com', {silent: true});
            if (result) {
                successfulType = objectType;
                break;
            }
        }

        if (result && successfulType && feature.attributes.class !== successfulType) {
            feature.attributes.class = successfulType;
            changedLocally = true;
        }

        if (!result) {
            errors.push(`CalTopo could not update assignment "${featureName}".`);
            continue;
        }

        // Compare the captured style before and after so a re-push of the same
        // colors is recognised as "nothing changed".
        const styleBefore = JSON.stringify(captureCalTopoFeatureStyle(feature.attributes));
        applyCapturedCalTopoFeatureStyle(feature.attributes, overlayStyle);
        if (JSON.stringify(captureCalTopoFeatureStyle(feature.attributes)) !== styleBefore) {
            changedLocally = true;
        }
        if (nextDescription !== null) {
            feature.attributes.description = nextDescription;
            changedLocally = true;
        }
        updatedCount++;
    }

    for (const {feature, styleKey, style, restore} of importedTracks) {
        const featureId = getCalTopoWritableFeatureId(feature);
        const featureName = getMapFeatureDisplayName(feature) || styleKey;
        if (!restore && !Object.prototype.hasOwnProperty.call(originals, styleKey)) {
            originals[styleKey] = captureCalTopoFeatureStyle(feature.attributes);
            changedLocally = true;
        }

        // The whole shape travels with the style (geometry and all) so nothing
        // else about the track changes on CalTopo.
        const payload = buildCalTopoFeatureUpdatePayload(feature, style);
        payload.id = featureId;
        let successfulType = null;
        for (const objectType of getSearcherTrackApiObjectTypeCandidates(feature)) {
            const endpoint = `/api/v1/map/${encodeURIComponent(map.id)}/${encodeURIComponent(objectType)}/${encodeURIComponent(featureId)}`;
            const result = await caltopo_api_call('POST', endpoint, payload, map.domain || 'caltopo.com', {silent: true});
            if (result) {
                successfulType = objectType;
                break;
            }
        }
        if (!successfulType) {
            errors.push(`CalTopo could not update track "${featureName}".`);
            continue;
        }
        if (feature.attributes.class !== successfulType) {
            feature.attributes.class = successfulType;
            changedLocally = true;
        }

        const styleBefore = JSON.stringify(captureCalTopoFeatureStyle(feature.attributes));
        applyCapturedCalTopoFeatureStyle(feature.attributes, style);
        if (JSON.stringify(captureCalTopoFeatureStyle(feature.attributes)) !== styleBefore) {
            changedLocally = true;
        }
        if (restore) {
            // Back to its own style: nothing left to put back later.
            delete originals[styleKey];
            changedLocally = true;
        }
        updatedCount++;
    }

    if (errors.length > 0 && updatedCount === 0) {
        throw new Error(errors.join('\n'));
    }

    if (enabled) {
        // `updatedAt` is the case's record of the last push that CHANGED a shape;
        // other devices read it as a lower bound for their own cooldown.
        if (changedLocally) {
            map.caltopoAssignmentOverlayState.updatedAt = Date.now();
            saveBundle(bundle);
        }
    } else {
        delete map.caltopoAssignmentOverlayState;
        saveBundle(bundle);
    }

    return {updatedCount, errors, changed: changedLocally};
}

// Re-push the CalTopo/SARTopo assignment overlay (PSRc colors, active-search
// style incl. border thickness, finished-task description summaries) whenever
// the underlying data changes - e.g. a search log edit that recomputes a
// segment's PSRc, a team finishing its assignment (which flips the segment
// from actively searched back to resting), or a sweep count being logged.
//
// This is a best-effort, SILENT refresh: it does nothing unless the assignment
// overlay is currently enabled and a CalTopo map with already fetched shapes
// exists. That way ordinary edits on devices that never turned the overlay on
// (or never fetched shapes) pay no cost and trigger no network requests.
//
// It is also RATE LIMITED ("CalTopo color sync", Settings page):
//   * cooldown  - CalTopo is never asked more often than every N seconds. A
//                 request inside the cooldown is not dropped: ONE push is
//                 scheduled for the end of the cooldown and every request until
//                 then folds into it (refreshCalTopoAssignmentOverlayIfEnabled);
//   * heartbeat - the colors are re-asserted at least every N minutes even when
//                 nothing changed, so a hand edit in CalTopo or a push that was
//                 lost never leaves the map stale (caltopoColorSyncTick, driven
//                 by a 1 s ticker started from DOMContentLoaded);
//   * page load - every page is a full reload, so the ticker's start asks for a
//                 push too: it runs at once when the cooldown is over, otherwise
//                 at the end of the cooldown.
// The last push time lives in sessionStorage (this tab's clock, survives page
// navigation) and the case carries a hint of the last push that changed a shape
// (maps[0].caltopoAssignmentOverlayState.updatedAt, written by any device); the
// later of the two counts, so a device never re-pushes right after another one.
let _caltopoOverlayRefreshInFlight = false;
let _caltopoOverlayRefreshPending = false;
// The one pending push and when it is due (drives the Maps page countdown).
let _caltopoColorSyncTimer = null;
let _caltopoColorSyncDueAt = 0;
// The 1 s ticker behind the heartbeat and the countdown.
let _caltopoColorSyncTicker = null;

// loadBundle() for the scheduler: null instead of an exception, so a broken
// store can never break the ticker.
function loadBundleForCalTopoColorSync() {
    try {
        return loadBundle();
    } catch (e) {
        return null;
    }
}

// When the colors were last pushed (or a push was last attempted) - epoch ms,
// 0 when never. The later of this tab's own record and the case's hint.
function getLastCalTopoColorSyncAt(bundle) {
    let own = 0;
    try {
        own = parseInt(sessionStorage.getItem(CALTOPO_COLOR_SYNC_LAST_PUSH_STORAGE_KEY) || '0', 10) || 0;
    } catch (e) {
        own = 0;
    }
    const state = bundle && bundle.maps && bundle.maps[0] ? bundle.maps[0].caltopoAssignmentOverlayState : null;
    const hint = state && Number.isFinite(Number(state.updatedAt)) ? Number(state.updatedAt) : 0;
    return Math.max(own, hint, 0);
}

// Remember that this tab pushed (or tried to push) the colors now. Recorded
// BEFORE the push so a failing CalTopo is retried no sooner than the cooldown.
function markCalTopoColorSyncAttempt(at = Date.now()) {
    try {
        sessionStorage.setItem(CALTOPO_COLOR_SYNC_LAST_PUSH_STORAGE_KEY, String(at));
    } catch (e) { /* sessionStorage unavailable: the case hint still applies */ }
}

// The overlay is switched on and a CalTopo map with already-fetched shapes
// exists; otherwise there is nothing to recolor and we must not surprise the
// user with a background fetch.
function canRunCalTopoColorSync(bundle) {
    if (typeof isCalTopoAssignmentOverlayEnabled !== 'function' || !isCalTopoAssignmentOverlayEnabled()) {
        return false;
    }
    const map = bundle && bundle.maps && bundle.maps[0] ? bundle.maps[0] : null;
    return !!(map && map.id && Array.isArray(map.features) && map.features.length > 0);
}

function clearPendingCalTopoColorSync() {
    if (_caltopoColorSyncTimer) {
        clearTimeout(_caltopoColorSyncTimer);
    }
    _caltopoColorSyncTimer = null;
    _caltopoColorSyncDueAt = 0;
}

// Ask for a color push. `delay` only coalesces a burst of edits into one push;
// the push never runs before the cooldown since the last one has passed. At
// most one push is pending at any time: a request that would run no sooner than
// the pending one simply folds into it.
function refreshCalTopoAssignmentOverlayIfEnabled(options = {}) {
    const {delay = 300} = options;
    const bundle = loadBundleForCalTopoColorSync();
    if (!canRunCalTopoColorSync(bundle)) {
        return;
    }
    const {cooldownMs} = getCalTopoColorSyncSettings(bundle);
    const now = Date.now();
    const runAt = Math.max(now + Math.max(0, Number(delay) || 0), getLastCalTopoColorSyncAt(bundle) + cooldownMs);
    if (_caltopoColorSyncTimer && _caltopoColorSyncDueAt <= runAt) {
        return;
    }
    clearPendingCalTopoColorSync();
    _caltopoColorSyncDueAt = runAt;
    _caltopoColorSyncTimer = setTimeout(runCalTopoAssignmentOverlayRefresh, Math.max(0, runAt - now));
}

// When the next push is due: the pending one if any, else the heartbeat.
function getNextCalTopoColorSyncAt(bundle = loadBundleForCalTopoColorSync()) {
    if (_caltopoColorSyncTimer) {
        return _caltopoColorSyncDueAt;
    }
    const {heartbeatMs} = getCalTopoColorSyncSettings(bundle);
    return getLastCalTopoColorSyncAt(bundle) + heartbeatMs;
}

// "m:ss" for a remaining time; never below 0:00.
function formatCountdown(ms) {
    const totalSeconds = Math.max(0, Math.ceil((Number(ms) || 0) / 1000));
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${minutes}:${String(seconds).padStart(2, '0')}`;
}

// The Maps page pill next to the map title: "Color sync in m:ss" (time to the
// pending push or the heartbeat), "Syncing..." while a push runs, hidden when
// the PSRc Assignment Colors toggle is off or no shapes were fetched. A no-op
// on every other page (no element).
function renderCalTopoColorSyncCountdown() {
    if (typeof document === 'undefined') return;
    const pill = document.getElementById('caltopo-color-sync-countdown');
    if (!pill) return;
    const bundle = loadBundleForCalTopoColorSync();
    if (!canRunCalTopoColorSync(bundle)) {
        pill.style.display = 'none';
        pill.textContent = '';
        return;
    }
    pill.style.display = '';
    if (_caltopoOverlayRefreshInFlight) {
        pill.textContent = 'Syncing\u2026';
        return;
    }
    pill.textContent = `Color sync in ${formatCountdown(getNextCalTopoColorSyncAt(bundle) - Date.now())}`;
}

async function runCalTopoAssignmentOverlayRefresh() {
    clearPendingCalTopoColorSync();
    // Collapse overlapping requests: if a push is already running, remember that
    // another refresh was requested and run it once the current one settles so
    // the map always ends on the latest colors/opacity.
    if (_caltopoOverlayRefreshInFlight) {
        _caltopoOverlayRefreshPending = true;
        return;
    }
    if (!canRunCalTopoColorSync(loadBundleForCalTopoColorSync())) {
        return;
    }
    _caltopoOverlayRefreshInFlight = true;
    markCalTopoColorSyncAttempt();
    renderCalTopoColorSyncCountdown();
    try {
        await updateCalTopoAssignmentOverlay(true);
    } catch (err) {
        // Silent by design: an auto-refresh must never interrupt data entry with
        // an error dialog. The manual toggle still surfaces problems to the user.
        console.warn('CalTopo assignment overlay auto-refresh failed:', err);
    } finally {
        _caltopoOverlayRefreshInFlight = false;
        renderCalTopoColorSyncCountdown();
        if (_caltopoOverlayRefreshPending) {
            _caltopoOverlayRefreshPending = false;
            // Through the gate, so the re-run respects the cooldown too.
            refreshCalTopoAssignmentOverlayIfEnabled({delay: 0});
        }
    }
}

// One tick of the 1 s ticker: redraw the countdown, then the heartbeat. The
// heartbeat is skipped while the tab is hidden (like the unaccounted-feature
// check), while a push is running or one is already pending.
function caltopoColorSyncTick() {
    renderCalTopoColorSyncCountdown();
    if (typeof document !== 'undefined' && document.hidden) {
        return;
    }
    if (_caltopoOverlayRefreshInFlight || _caltopoColorSyncTimer) {
        return;
    }
    const bundle = loadBundleForCalTopoColorSync();
    if (!canRunCalTopoColorSync(bundle)) {
        return;
    }
    const {heartbeatMs} = getCalTopoColorSyncSettings(bundle);
    if (Date.now() - getLastCalTopoColorSyncAt(bundle) >= heartbeatMs) {
        refreshCalTopoAssignmentOverlayIfEnabled({delay: 0});
    }
}

// Started once per page from the DOMContentLoaded handler, after the case is
// in memory.
function startCalTopoColorSyncTicker() {
    if (_caltopoColorSyncTicker) {
        return;
    }
    _caltopoColorSyncTicker = setInterval(caltopoColorSyncTick, CALTOPO_COLOR_SYNC_TICK_INTERVAL_MS);
    // Page just loaded / switched: push now when the cooldown is over, else at
    // the end of the cooldown.
    refreshCalTopoAssignmentOverlayIfEnabled({delay: 500});
    caltopoColorSyncTick();
}

function wait(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

async function withSaveButtonFeedback(button, saveAction, options = {}) {
    if (!button || button.dataset.saveFeedbackBusy === 'true') {
        return;
    }

    const loadingLabel = options.loadingLabel || 'Saving';
    const originalHtml = button.dataset.saveFeedbackOriginalHtml || button.innerHTML;
    const originallyDisabled = button.disabled;
    button.dataset.saveFeedbackOriginalHtml = originalHtml;
    button.dataset.saveFeedbackBusy = 'true';
    button.disabled = true;
    button.classList.remove('save-feedback-success');
    button.classList.add('save-feedback-loading');
    button.innerHTML = `<span class="save-feedback-spinner" aria-hidden="true"></span><span>${loadingLabel}</span>`;

    const startedAt = Date.now();

    try {
        const result = await Promise.resolve(saveAction());
        const remainingLoadingTime = SAVE_BUTTON_MIN_LOADING_MS - (Date.now() - startedAt);
        if (remainingLoadingTime > 0) {
            await wait(remainingLoadingTime);
        }

        button.classList.remove('save-feedback-loading');
        button.classList.add('save-feedback-success');
        await wait(SAVE_BUTTON_SUCCESS_MS);
        return result;
    } catch (error) {
        const remainingLoadingTime = SAVE_BUTTON_MIN_LOADING_MS - (Date.now() - startedAt);
        if (remainingLoadingTime > 0) {
            await wait(remainingLoadingTime);
        }
        throw error;
    } finally {
        button.classList.remove('save-feedback-loading', 'save-feedback-success');
        button.innerHTML = originalHtml;
        button.disabled = originallyDisabled;
        delete button.dataset.saveFeedbackBusy;
    }
}

// Public backend (Railway) that runs the SAR sync API (register/login + per-user
// data buckets). The GitHub-hosted static site cannot execute data.php locally,
// so all API requests must be sent to this absolute URL instead of a relative path.
// It is only the bootstrap address: the server it names publishes the address
// the website is actually to use (Railway variable CALTOPO_SYNC, GET /api/config),
// which then takes over as the default - see loadSyncServerConfig().
const DEFAULT_SYNC_SERVER_URL = 'https://sarwebtheory2-production.up.railway.app';

// Absolute http(s) address with no trailing slash, or '' when the value is not one.
function normalizeSyncServerUrl(url) {
    const trimmed = typeof url === 'string' ? url.trim().replace(/\/+$/, '') : '';
    return /^https?:\/\/[^\s/]+/i.test(trimmed) ? trimmed : '';
}

// A locally-stored (cookie) sync server URL, set from the login popup BEFORE
// authentication. This is the source against which all data flows in and out.
// It must be readable before login, so it lives in a cookie rather than the
// server-side settings (which are only loaded after a successful login).
function getLocalSyncServerUrl() {
    const url = getCookie(SYNC_URL_LOCAL_STORAGE_KEY);
    return (url && /^https?:\/\//i.test(url)) ? url : '';
}

function setLocalSyncServerUrl(url) {
    const trimmed = typeof url === 'string' ? url.trim() : '';
    if (trimmed) {
        setCookie(SYNC_URL_LOCAL_STORAGE_KEY, trimmed);
    } else {
        eraseCookie(SYNC_URL_LOCAL_STORAGE_KEY);
    }
}

// The sync server address the server publishes from its CALTOPO_SYNC variable,
// as last read by this device (cookie, so it is known before the first request
// of the next page load). '' until a server has answered /api/config.
function getPublishedSyncServerUrl() {
    return normalizeSyncServerUrl(getCookie(SYNC_URL_CONFIG_STORAGE_KEY));
}

function setPublishedSyncServerUrl(url) {
    const normalized = normalizeSyncServerUrl(url);
    if (normalized) {
        setCookie(SYNC_URL_CONFIG_STORAGE_KEY, normalized);
    } else {
        eraseCookie(SYNC_URL_CONFIG_STORAGE_KEY);
    }
}

// The address the website uses when nobody typed one into "Set Server": the
// one CALTOPO_SYNC publishes, else the built-in bootstrap address.
function getDefaultSyncServerUrl() {
    return getPublishedSyncServerUrl() || DEFAULT_SYNC_SERVER_URL;
}

function getSyncServerUrl() {
    // A URL explicitly set from the login popup wins over everything else so the
    // user can point the app at their own server before (and after) logging in.
    const localUrl = getLocalSyncServerUrl();
    if (localUrl) {
        return localUrl;
    }
    // Next, the address the server publishes from CALTOPO_SYNC (once read).
    const publishedUrl = getPublishedSyncServerUrl();
    if (publishedUrl) {
        return publishedUrl;
    }
    // When running the backend locally, talk to the local sync server.
    if (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1') {
        return `${window.location.protocol}//${window.location.hostname}:3000`;
    }
    // In production the static frontend (GitHub Pages) must reach the remote
    // backend over an absolute URL; a relative "data.php" would hit the static
    // host and return a 405 HTML page instead of JSON.
    return DEFAULT_SYNC_SERVER_URL;
}

// Which servers loadSyncServerConfig() asks for the published address, in
// order: the one this device uses now, then the bootstrap address (not from a
// localhost page, which must never silently talk to production).
function getSyncConfigServerCandidates() {
    const isLocalPage = typeof window !== 'undefined' && !!window.location
        && (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1');
    const candidates = [normalizeSyncServerUrl(getSyncServerUrl())];
    if (!isLocalPage) candidates.push(DEFAULT_SYNC_SERVER_URL);
    return candidates.filter((url, index) => !!url && candidates.indexOf(url) === index);
}

// Ask the server which sync server the website is to use (its CALTOPO_SYNC
// variable, GET /api/config) and remember the answer for getSyncServerUrl().
// Runs once per page load, before anything else talks to the server, and is
// bounded by a timeout so a sleeping or unreachable server cannot hold the
// page. Nothing is changed when no server answers: the last published address
// stays in force. A server that answers with no address (variable unset)
// clears the remembered one, so the built-in bootstrap address is used again.
// Resolves with the address in force afterwards.
async function loadSyncServerConfig(timeoutMs = 4000) {
    for (const base of getSyncConfigServerCandidates()) {
        if (isBlockedMixedContentUrl(base)) continue;
        try {
            const resp = await fetchWithTimeout(`${base}/api/config?_=${Date.now()}`, {
                method: 'GET',
                cache: 'no-store'
            }, timeoutMs);
            if (!resp || !resp.ok) continue;
            const data = await resp.json().catch(() => null);
            if (!data || typeof data !== 'object' || !('syncServerUrl' in data)) continue;
            const published = normalizeSyncServerUrl(data.syncServerUrl);
            if (published && isBlockedMixedContentUrl(published)) {
                console.warn(`[SYNC] CALTOPO_SYNC names an http:// server (${published}) that this https:// page cannot call; ignoring it.`);
                continue;
            }
            setPublishedSyncServerUrl(published);
            return getSyncServerUrl();
        } catch (e) {
            // Unreachable / timed out: try the next candidate.
        }
    }
    return getSyncServerUrl();
}

// The working copy of the open case, the rows still queued for the server and
// the copy of the per-user settings all live here, in memory, for as long as
// the page is open. Nothing below ever touches localStorage: closing or
// reloading the page forgets everything and the next load reads the database.
// (A test harness may hand in the object to use as window.SAR_MEMORY_STORAGE so
// it can seed and inspect a page's memory; a browser never sets it.)
const _memoryStorage = (typeof window !== 'undefined' && window.SAR_MEMORY_STORAGE && typeof window.SAR_MEMORY_STORAGE === 'object')
    ? window.SAR_MEMORY_STORAGE
    : {};

function getStorageItem(key) {
  return Object.prototype.hasOwnProperty.call(_memoryStorage, key) ? _memoryStorage[key] : null;
}

function setStorageItem(key, value) {
  _memoryStorage[key] = String(value);
}

function removeStorageItem(key) {
  delete _memoryStorage[key];
}

// Remove whatever an older build of this site left in the browser's
// localStorage (whole search files, the saved-cases list, queued rows, cached
// settings). Runs once per page load; harmless when there is nothing to remove.
function purgeLegacyLocalData() {
  try {
    if (typeof localStorage === 'undefined' || localStorage === null) return;
    LEGACY_LOCAL_STORAGE_KEYS.forEach((key) => {
      try { localStorage.removeItem(key); } catch (e) {}
    });
  } catch (e) {}
}

purgeLegacyLocalData();

const SERVER_SETTINGS_CACHE_KEY = 'sar-server-settings-cache-v1';

// URL-safe suffix that namespaces every synced bucket to the logged-in user.
// Data is scoped per login (not per shared PIN), so two accounts that share a
// PIN never land in the same bucket. encodeURIComponent keeps the suffix valid
// inside an API path even when the username contains spaces or other reserved
// characters. This is the single place the suffix is built, so getSyncBucket(),
// caseNumberToBucket() and bucketToCaseNumber() stay in lockstep.
function getUserBucketSuffix() {
    const creds = getUserCredentials();
    if (!creds || !creds.name) return '';
    return encodeURIComponent(creds.name);
}

// Names the website uses for its own bookkeeping on the server ("bundle",
// "all-files", "user-<pin>"). They are never a CASE #: a stored case number
// that reads like one is ignored, so a mis-saved setting can never make the
// site work inside - or list - a case called "bundle".
function isInternalCaseName(name) {
    const value = String(name || '').trim().replace(/\.json$/i, '');
    if (!value) return true;
    if (value === 'bundle' || value === 'all-files') return true;
    return /^user-/i.test(value);
}

function getSyncBucket() {
    let bucket = _serverSettings && _serverSettings[SYNC_BUCKET_STORAGE_KEY] ? _serverSettings[SYNC_BUCKET_STORAGE_KEY] : '';
    if (!bucket) {
        try {
            const cached = getStorageItem(SERVER_SETTINGS_CACHE_KEY);
            if (cached) {
                const parsed = JSON.parse(cached);
                if (parsed && parsed[SYNC_BUCKET_STORAGE_KEY]) {
                    bucket = parsed[SYNC_BUCKET_STORAGE_KEY];
                }
            }
        } catch (e) {}
    }
    if (isInternalCaseName(bucket)) return '';
    const suffix = getUserBucketSuffix();
    if (bucket && suffix) {
        return `${bucket}_${suffix}`;
    }
    return bucket;
}

function setSyncBucket(bucket) {
    // Persist the chosen CASE # server-side. Return the save promise so callers
    // that reload the page (e.g. the case-number popup) can await it first;
    // otherwise the reload aborts the in-flight PUT and the case number is lost.
    if (!_serverSettings) { _serverSettings = {}; }
    _serverSettings[SYNC_BUCKET_STORAGE_KEY] = bucket;
    return saveServerSettings(_serverSettings);
}

// Convert an internal sync-bucket id back to the clean CASE # to show the user.
// getSyncBucket() appends "_<username>" so each login's data is namespaced in
// the shared store; that suffix is an internal detail and must never be shown
// or fed back into setSyncBucket() (doing so would double the suffix). The list
// returned by /api/auth/history stores those suffixed ids, so anything shown to
// the user or used for duplicate detection must pass through here first.
//
// The server persists the URL-decoded bucket, so a username that was
// percent-encoded on the way out (e.g. one containing spaces) comes back
// decoded; strip whichever form is present so the round-trip is exact.
function bucketToCaseNumber(bucket) {
    if (!bucket) return '';
    const creds = getUserCredentials();
    if (!creds || !creds.name) return bucket;
    const encodedSuffix = `_${encodeURIComponent(creds.name)}`;
    const rawSuffix = `_${creds.name}`;
    if (bucket.endsWith(encodedSuffix)) {
        return bucket.slice(0, -encodedSuffix.length);
    }
    if (bucket.endsWith(rawSuffix)) {
        return bucket.slice(0, -rawSuffix.length);
    }
    return bucket;
}

// Inverse of bucketToCaseNumber(): build the internal, per-login bucket id for a
// clean CASE #. Load/Delete callers only know the case number, so they use this
// to reach the same bucket getSyncBucket() would produce for the active case.
function caseNumberToBucket(caseNumber) {
    if (!caseNumber) return '';
    const suffix = getUserBucketSuffix();
    return suffix ? `${caseNumber}_${suffix}` : caseNumber;
}

// The clean CASE # this device is working in ('' while none is selected). A
// search file's own name always follows it, so a file is never created under a
// stand-in name and the structured tables on the server are always keyed by
// the real CASE #.
function getActiveCaseNumber() {
    const bucket = getSyncBucket();
    return bucket ? String(bucketToCaseNumber(bucket) || '').replace(/\.json$/i, '') : '';
}

// The CASE # to show for a search file: its own name, else the active CASE #,
// else the "no case" stand-in.
function getCaseDisplayName(bundle) {
    const own = bundle && typeof bundle.fileName === 'string' ? bundle.fileName.trim() : '';
    return own || getActiveCaseNumber() || NO_CASE_LABEL;
}

// True when a bucket id returned by /api/auth/history belongs to the current
// login. Pre-existing "_<pin>" buckets from before per-user namespacing stay in
// the database but must not be surfaced, so history-derived lists filter on this
// ("start fresh", no migration). Matches either the encoded suffix or the
// decoded form the server stores.
function bucketBelongsToCurrentUser(bucket) {
    if (!bucket) return false;
    const creds = getUserCredentials();
    if (!creds || !creds.name) return false;
    const encodedSuffix = `_${encodeURIComponent(creds.name)}`;
    const rawSuffix = `_${creds.name}`;
    return bucket.endsWith(encodedSuffix) || bucket.endsWith(rawSuffix);
}

function setCookie(name, value, days = 365) {
    let expires = "";
    if (days) {
        const date = new Date();
        date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
        expires = "; expires=" + date.toUTCString();
    }
    document.cookie = name + "=" + (value || "")  + expires + "; path=/";
}

function getCookie(name) {
    const nameEQ = name + "=";
    const ca = document.cookie.split(';');
    for(let i = 0; i < ca.length; i++) {
        let c = ca[i];
        while (c.charAt(0) === ' ') c = c.substring(1, c.length);
        if (c.indexOf(nameEQ) === 0) return c.substring(nameEQ.length, c.length);
    }
    return null;
}

function eraseCookie(name) {
    document.cookie = name + '=; Path=/; Expires=Thu, 01 Jan 1970 00:00:01 GMT;';
}

function getUserCredentials() {
    const name = getCookie(USER_NAME_STORAGE_KEY);
    const password = getCookie(USER_PASSWORD_STORAGE_KEY);
    if (!name || !password) return null;
    return { name, password };
}

// Per-user settings, stored on the server (/api/auth/settings) and mirrored in
// memory for the lifetime of the page. Loaded once on start-up, right after login.
let _serverSettings = null;
let _serverSettingsLoading = false;
// True once the server's copy was actually read during this page load. Writes
// that happen on their own (not from a user action) wait for this, so a slow or
// unreachable server can never make the page overwrite the stored settings
// with an empty record.
let _serverSettingsLoaded = false;

async function loadServerSettings() {
    const creds = getUserCredentials();
    if (!creds) return {};
    if (_serverSettings !== null) return _serverSettings;
    if (_serverSettingsLoading) return _serverSettings || {};

    try {
        const cached = getStorageItem(SERVER_SETTINGS_CACHE_KEY);
        if (cached && _serverSettings === null) {
            _serverSettings = JSON.parse(cached);
        }
    } catch (e) {}

    _serverSettingsLoading = true;
    try {
        const serverUrl = getSyncServerUrl();
        const resp = await apiFetch(`${serverUrl.replace(/\/$/, '')}/api/auth/settings`, {
            headers: {
                'X-User-Name': creds.name,
                'X-User-Password': creds.password
            }
        });
        if (resp.ok) {
            _serverSettings = await resp.json();
            _serverSettingsLoaded = true;
            setStorageItem(SERVER_SETTINGS_CACHE_KEY, JSON.stringify(_serverSettings));
        } else if (_serverSettings === null) {
            _serverSettings = {};
        }
    } catch (e) {
        console.warn('Failed to load server settings:', e);
        if (_serverSettings === null) {
            _serverSettings = {};
        }
    } finally {
        _serverSettingsLoading = false;
    }
    return _serverSettings;
}

async function saveServerSettings(settings) {
    const creds = getUserCredentials();
    if (!creds) return;
    _serverSettings = settings;
    try {
        setStorageItem(SERVER_SETTINGS_CACHE_KEY, JSON.stringify(settings));
    } catch (e) {}
    try {
        const serverUrl = getSyncServerUrl();
        await apiFetch(`${serverUrl.replace(/\/$/, '')}/api/auth/settings`, {
            method: 'PUT',
            headers: {
                'Content-Type': 'application/json',
                'X-User-Name': creds.name,
                'X-User-Password': creds.password
            },
            body: JSON.stringify(settings)
        });
    } catch (e) {
        console.warn('Failed to save server settings:', e);
    }
}

async function getServerSetting(key) {
    const settings = await loadServerSettings();
    return settings[key] !== undefined ? settings[key] : null;
}

async function setServerSetting(key, value) {
    const settings = await loadServerSettings();
    settings[key] = value;
    await saveServerSettings(settings);
}

// ---------------------------------------------------------------------------
// Login preferences.
//
// The Settings page used to keep every preference only inside the open search
// file, so a new CASE # (or another device) came up with the defaults again.
// The preferences below now also live in the database under the LOGIN username
// (the user_settings row read by loadServerSettings), and on every page load
// they are copied onto the open case before anything is drawn - so a login sees
// its own settings every time it signs in, on every device and in every case.
//
// Two groups of settings are shown on the Settings page (each panel carries a
// pill naming who it is saved for, see renderSettingScopePills):
//   * per USER ACCOUNT (the person selected from the accounts list): the theme
//     and "Use My Highlight Color" - stored on that account - and Geek Mode,
//     stored here per account name (geekModeByUser, see getGeekModeRecord);
//   * per LOGIN: everything else - stored here.
// ---------------------------------------------------------------------------
const USER_PREFERENCES_KEY = 'sar-user-preferences-v1';

// Bundle keys that are login preferences. Each is mirrored 1:1 between the
// open case and the login's preference record.
const LOGIN_PREFERENCE_KEYS = [
    'deleteMode',
    'showTips',
    'parCheckFrequency',
    'mapUnaccountedAutoCheck',
    'segmentColorScaleUsePsriMax',
    'segmentColorScaleLowColor',
    'segmentColorScaleMidColor',
    'segmentColorScaleHighColor',
    'segmentActiveSearchOpacityPercent',
    'segmentActiveSearchFillColor',
    'segmentActiveSearchBorderOpacityPercent',
    'segmentActiveSearchBorderColor',
    'segmentActiveSearchBorderWidth',
    'caltopoColorSyncHeartbeatMinutes',
    'caltopoColorSyncCooldownSeconds'
];

// The login's preference record (never null). Geek Mode (`geekModeByUser` plus
// the login-level `geekMode` / `geekPaddingPercent` fallback) and the last
// applied `theme` live here as well; they are not bundle keys.
function getUserPreferences() {
    const prefs = _serverSettings && _serverSettings[USER_PREFERENCES_KEY];
    return prefs && typeof prefs === 'object' && !Array.isArray(prefs) ? prefs : {};
}

// Store one or more preferences for this login. Returns the save promise (or
// null when nothing changed / nobody is logged in) so callers may await it.
function saveUserPreferences(patch) {
    if (!getUserCredentials() || !patch || typeof patch !== 'object') return null;
    // Never write before the server's record was read: the PUT replaces the
    // whole record, so saving onto an empty stand-in would wipe the login's
    // case number, preferences and every other setting.
    if (!_serverSettingsLoaded) {
        console.warn('Preferences not saved: the server settings have not been read yet.');
        return null;
    }
    if (!_serverSettings) { _serverSettings = {}; }
    const current = getUserPreferences();
    const next = Object.assign({}, current);
    let changed = false;
    Object.keys(patch).forEach((key) => {
        if (patch[key] === undefined) return;
        if (JSON.stringify(current[key]) !== JSON.stringify(patch[key])) {
            next[key] = patch[key];
            changed = true;
        }
    });
    if (!changed) return null;
    _serverSettings[USER_PREFERENCES_KEY] = next;
    return saveServerSettings(_serverSettings);
}

// Settings page helper: a login preference was changed on the open case; keep
// the login's record in step.
function persistLoginPreference(key, value) {
    if (!LOGIN_PREFERENCE_KEYS.includes(key)) return null;
    return saveUserPreferences({[key]: value});
}

// Copy the login's stored preferences onto a case. Returns true when the case
// was changed (the caller then saves it so the case mirrors the login).
function applyLoginPreferencesToBundle(bundle) {
    if (!bundle || typeof bundle !== 'object') return false;
    const prefs = getUserPreferences();
    let changed = false;
    LOGIN_PREFERENCE_KEYS.forEach((key) => {
        if (prefs[key] === undefined) return;
        if (JSON.stringify(bundle[key]) !== JSON.stringify(prefs[key])) {
            bundle[key] = JSON.parse(JSON.stringify(prefs[key]));
            changed = true;
        }
    });
    return changed;
}

// ---------------------------------------------------------------------------
// Geek Mode.
//
// Kept in the database under the login username (user_settings) - never in the
// case - and, inside that record, per USER ACCOUNT: several people share one
// login username, and not all of them want the dense layout. `geekModeByUser`
// maps the account name (getAccountName of the person picked from the accounts
// list) to {enabled, paddingPercent}; the login-level `geekMode` /
// `geekPaddingPercent` keys are what an account without its own entry (and a
// page with no account picked yet) falls back to, and what older records hold.
// Applied to <html> as the `geek-mode` class. While it is on:
//   * every padding / margin written as calc(Npx * var(--space-scale)) shrinks
//     by the percentage the login entered on the Settings page (the
//     `--geek-space-scale` custom property set inline below; styles.css falls
//     back to one third, the reduction Geek Mode had before the percentage);
//   * the toggle panels marked data-geek-compact (Segments page Sorting / Lost
//     Person Behavior / Actions, the Settings page panels) collapse to their
//     short data-geek-title plus the control itself, and labels marked
//     .geek-full give way to their .geek-abbr sibling - see styles.css.
// ---------------------------------------------------------------------------
const GEEK_MODE_DEFAULT_PADDING_PERCENT = 67;

// The Geek Mode settings that apply to `user` (default: the account picked on
// this device): {enabled, paddingPercent}.
function getGeekModeRecord(user = getCurrentUser()) {
    const prefs = getUserPreferences();
    const byUser = prefs.geekModeByUser && typeof prefs.geekModeByUser === 'object' && !Array.isArray(prefs.geekModeByUser)
        ? prefs.geekModeByUser : {};
    const name = getAccountName(user);
    const own = name && byUser[name] && typeof byUser[name] === 'object' ? byUser[name] : null;
    return {
        enabled: own && own.enabled !== undefined ? own.enabled === true : prefs.geekMode === true,
        paddingPercent: normalizeGeekPaddingPercent(own && own.paddingPercent !== undefined ? own.paddingPercent : prefs.geekPaddingPercent)
    };
}

// Store Geek Mode settings for `user`. With no account picked the login-level
// fallback is written instead. Returns the save promise (or null).
function saveGeekModePreference(patch, user = getCurrentUser()) {
    if (!patch || typeof patch !== 'object') return null;
    const current = getGeekModeRecord(user);
    const next = {
        enabled: patch.enabled !== undefined ? patch.enabled === true : current.enabled,
        paddingPercent: normalizeGeekPaddingPercent(patch.paddingPercent !== undefined ? patch.paddingPercent : current.paddingPercent, current.paddingPercent)
    };
    const name = getAccountName(user);
    if (!name) return saveUserPreferences({geekMode: next.enabled, geekPaddingPercent: next.paddingPercent});
    const prefs = getUserPreferences();
    const byUser = Object.assign({}, prefs.geekModeByUser && typeof prefs.geekModeByUser === 'object' && !Array.isArray(prefs.geekModeByUser) ? prefs.geekModeByUser : {});
    byUser[name] = next;
    return saveUserPreferences({geekModeByUser: byUser});
}

function isGeekModeEnabled() {
    return getGeekModeRecord().enabled;
}

// The percentage (0-100, whole number) taken away from every padding. Anything
// unusable falls back to `fallback`.
function normalizeGeekPaddingPercent(value, fallback = GEEK_MODE_DEFAULT_PADDING_PERCENT) {
    const number = typeof value === 'string' ? Number(value.trim()) : Number(value);
    if (value === '' || value === null || value === undefined || !Number.isFinite(number)) return fallback;
    return Math.min(100, Math.max(0, Math.round(number)));
}

function getGeekPaddingPercent() {
    return getGeekModeRecord().paddingPercent;
}

// The --space-scale factor a reduction percentage stands for (67 % -> 0.33).
function geekPaddingPercentToScale(percent) {
    return String(Math.round((100 - normalizeGeekPaddingPercent(percent)) * 10) / 1000);
}

function applyGeekMode(enabled = isGeekModeEnabled(), paddingPercent = getGeekPaddingPercent()) {
    const root = document.documentElement;
    if (!root || !root.classList) return;
    const percent = normalizeGeekPaddingPercent(paddingPercent);
    if (enabled) {
        root.classList.add('geek-mode');
        if (root.style && root.style.setProperty) root.style.setProperty('--geek-space-scale', geekPaddingPercentToScale(percent));
    } else {
        root.classList.remove('geek-mode');
        if (root.style && root.style.removeProperty) root.style.removeProperty('--geek-space-scale');
    }
    rememberUiHint(getAppliedTheme(), enabled, percent);
}

// The theme currently applied to the page ('light' | 'dark').
function getAppliedTheme() {
    const root = document.documentElement;
    return root && root.classList && root.classList.contains('light-mode') ? 'light' : 'dark';
}

// ---------------------------------------------------------------------------
// Boot hint + boot overlay (see theme-boot.js).
//
// The theme is only known after the server has been read, so the page used to
// paint dark and then switch to light. theme-boot.js runs in <head>, reads a
// tiny hint cookie with the theme (and Geek Mode) last applied for this login
// and puts the page in that theme before the first paint; it also covers the
// page with an 80% dark/light overlay and a spinner until finishPageBoot()
// says the preferences from the server have been applied.
// ---------------------------------------------------------------------------
const UI_HINT_COOKIE = 'sar-ui-hint';

// The hint is a comma-separated flag list: "light" | "dark", then "geek" and
// "pad<percent>" (the Geek Mode padding reduction) while Geek Mode is on.
function rememberUiHint(theme = getAppliedTheme(), geek = isGeekModeEnabled(), paddingPercent = getGeekPaddingPercent()) {
    const flags = [theme === 'light' ? 'light' : 'dark'];
    if (geek) flags.push('geek', `pad${normalizeGeekPaddingPercent(paddingPercent)}`);
    try { setCookie(UI_HINT_COOKIE, flags.join(','), 365); } catch (e) { /* ignore */ }
}

// Write the hint from the preferences just read for a login (used right after
// logging in, before the reload, so the very first page already paints right).
function rememberUiHintFromPreferences() {
    const prefs = getUserPreferences();
    const geek = getGeekModeRecord();
    rememberUiHint(prefs.theme === 'light' ? 'light' : 'dark', geek.enabled, geek.paddingPercent);
}

let _pageBootFinished = false;
function finishPageBoot() {
    if (_pageBootFinished) return;
    _pageBootFinished = true;
    const root = document.documentElement;
    if (!root || !root.classList || !root.classList.contains('sar-booting')) return;
    root.classList.add('sar-boot-done');
    setTimeout(() => {
        root.classList.remove('sar-booting');
        root.classList.remove('sar-boot-done');
    }, 320);
}

// ---------------------------------------------------------------------------
// Per-login images (header logo, background photo).
//
// The images chosen on the Settings page are stored in the database under the
// login username (/api/auth/assets) and read back on every page load, so they
// are the same on every device and in every case and only go away through the
// "Remove Logo" / "Use Default" buttons. They used to be kept inside the case
// file only - and the logo was not even re-applied on load - so a refresh lost
// them.
// ---------------------------------------------------------------------------
const USER_ASSET_KINDS = ['logo', 'background'];
let _userAssets = null;

function getUserAsset(kind) {
    const asset = _userAssets && _userAssets[kind];
    return asset && typeof asset.data === 'string' && asset.data ? asset : null;
}

function getUserAssetsUrl(kind) {
    const base = getSyncServerUrl().replace(/\/$/, '');
    return kind ? `${base}/api/auth/assets/${kind}` : `${base}/api/auth/assets`;
}

async function loadUserAssets() {
    if (!getUserCredentials() || !getSyncServerUrl()) return _userAssets || {};
    try {
        const resp = await apiFetch(`${getUserAssetsUrl()}?_=${Date.now()}`, {headers: getAuthHeaders()});
        if (resp.ok) {
            const data = await resp.json();
            _userAssets = data && typeof data === 'object' ? data : {};
        } else if (_userAssets === null) {
            _userAssets = {};
        }
    } catch (e) {
        console.warn('Failed to load user images:', e);
        if (_userAssets === null) _userAssets = {};
    }
    return _userAssets;
}

// Store an image for this login. `dataUrl` is the data: URL the browser read.
// Resolves to true when the server confirmed the write.
async function saveUserAsset(kind, dataUrl, fileName) {
    if (!USER_ASSET_KINDS.includes(kind) || !getUserCredentials()) return false;
    if (!_userAssets) _userAssets = {};
    _userAssets[kind] = {data: dataUrl, fileName: fileName || '', updatedAt: new Date().toISOString()};
    try {
        const resp = await apiFetch(getUserAssetsUrl(kind), {
            method: 'PUT',
            headers: getAuthHeaders({'Content-Type': 'application/json'}),
            body: JSON.stringify({data: dataUrl, fileName: fileName || ''})
        });
        return resp.ok;
    } catch (e) {
        console.warn(`Failed to store the ${kind} image:`, e);
        return false;
    }
}

async function deleteUserAsset(kind) {
    if (!USER_ASSET_KINDS.includes(kind)) return false;
    if (_userAssets) _userAssets[kind] = null;
    if (!getUserCredentials()) return false;
    try {
        const resp = await apiFetch(getUserAssetsUrl(kind), {
            method: 'DELETE',
            headers: getAuthHeaders()
        });
        return resp.ok;
    } catch (e) {
        console.warn(`Failed to remove the ${kind} image:`, e);
        return false;
    }
}

// This login's cases as the server lists them (see GET /api/auth/history).
// The request must carry the full credentials: the server authenticates every
// read, and a name-only request was answered with 401, which left the Saved
// Cases table showing whatever happened to be cached on the device instead.
async function fetchUserHistory() {
    const creds = getUserCredentials();
    if (!creds) return [];
    const serverUrl = getSyncServerUrl();
    if (!serverUrl) return [];

    try {
        const resp = await apiFetch(`${serverUrl.replace(/\/$/, '')}/api/auth/history?_=${Date.now()}`, {
            headers: getAuthHeaders()
        });
        if (resp.ok) {
            const list = await resp.json();
            return Array.isArray(list) ? list : [];
        }
    } catch (e) {
        console.warn("Failed to fetch history:", e);
    }
    return [];
}

// Read a fetch Response as JSON without crashing when the server answers with
// something that is not JSON. An outdated or misconfigured sync server returns
// an HTML page (for example "<!DOCTYPE html> ... Cannot POST /api/auth/login"),
// which otherwise makes resp.json() throw the cryptic
// "Unexpected token '<', "<!DOCTYPE "... is not valid JSON".
async function readJsonResponse(resp) {
    const raw = await resp.text();
    const contentType = (resp.headers.get('content-type') || '').toLowerCase();
    if (contentType.includes('application/json') || /^\s*[[{]/.test(raw)) {
        try {
            return JSON.parse(raw);
        } catch (e) {
            // Content was not valid JSON; fall through to the descriptive error.
        }
    }
    const looksLikeHtml = /^\s*</.test(raw);
    const snippet = raw.trim().replace(/\s+/g, ' ').slice(0, 120);
    const detail = looksLikeHtml
        ? 'the server returned an HTML page instead of JSON'
        : (snippet ? `the server returned: "${snippet}"` : 'the server returned an empty response');
    throw new Error(`Unexpected server response (HTTP ${resp.status}): ${detail}. Make sure the Sync Server URL points to the SAR sync server that provides /api/auth/login.`);
}

// A fetch() that never reached a server rejects with a bare TypeError whose
// message is the famously unhelpful "Failed to fetch" ("Load failed" on iOS
// Safari). It always means the request was blocked or the address is
// unreachable, never that the username/PIN were wrong, so it has to be handled
// separately from an HTTP error response.
function isNetworkFetchError(error) {
    if (!error) return false;
    const message = String(error.message || error).toLowerCase();
    return message.includes('failed to fetch')
        || message.includes('load failed')
        || message.includes('networkerror')
        || message.includes('network request failed')
        || message.includes('fetch failed');
}

// A browser refuses to call an http:// address from a page served over https://
// (mixed content) and reports that refusal as a generic "Failed to fetch".
// Loopback is exempt because browsers treat it as a secure context.
function isBlockedMixedContentUrl(url) {
    const target = String(url || '');
    if (!/^http:\/\//i.test(target)) return false;
    if (/^http:\/\/(localhost|127\.0\.0\.1|\[::1\])(:|\/|$)/i.test(target)) return false;
    return typeof window !== 'undefined' && !!window.location && window.location.protocol === 'https:';
}

// Base URLs to try for the pre-login auth calls, in priority order. The address
// this device is configured to use comes first, then the address CALTOPO_SYNC
// publishes, then the built-in public backend as a last fallback, so a device
// holding a stale or unreachable "Set Server" address (or an http:// one that
// gets blocked as mixed content) can still log in instead of dead-ending on
// "Failed to fetch". Local development is left alone: a page opened from
// localhost must never silently talk to production.
function getAuthServerUrlCandidates() {
    const stripTrailingSlash = url => String(url || '').trim().replace(/\/$/, '');
    const isLocalPage = typeof window !== 'undefined' && !!window.location
        && (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1');
    const candidates = [stripTrailingSlash(getSyncServerUrl())];
    if (!isLocalPage) {
        candidates.push(stripTrailingSlash(getPublishedSyncServerUrl()));
        candidates.push(stripTrailingSlash(DEFAULT_SYNC_SERVER_URL));
    }
    return candidates.filter((url, index) => !!url && candidates.indexOf(url) === index);
}

// The public backend is hosted on a platform that idles the container when it
// is not in use. The first request from a cold device has to wait for that
// container to boot, which can take longer than a mobile browser is willing to
// hold an idle connection open, so the very first login attempt on a new device
// is the one most likely to fail. Every auth request is therefore given a
// generous timeout and is retried a couple of times before the address is
// declared unreachable.
const AUTH_REQUEST_TIMEOUT_MS = 20000;
const AUTH_REQUEST_ATTEMPTS = 3;
const AUTH_RETRY_DELAY_MS = 1500;

function delayMs(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

// fetch() with an explicit timeout. Without one a request aimed at a host that
// silently drops packets (a captive portal, a firewalled network, a sleeping
// backend) can hang for minutes and simply look like "nothing happens".
async function fetchWithTimeout(url, options = {}, timeoutMs = AUTH_REQUEST_TIMEOUT_MS) {
    if (typeof AbortController === 'undefined') {
        return fetch(url, options);
    }
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
        return await fetch(url, {...options, signal: controller.signal});
    } catch (e) {
        if (e && (e.name === 'AbortError' || /aborted/i.test(String(e.message || '')))) {
            const timeoutError = new Error(`timed out after ${Math.round(timeoutMs / 1000)}s`);
            timeoutError.isTimeout = true;
            throw timeoutError;
        }
        throw e;
    } finally {
        clearTimeout(timer);
    }
}

// True for the failures that justify trying again / trying the next address:
// the request never produced an HTTP response.
function isRetriableConnectionError(error) {
    return !!(error && (error.isTimeout || isNetworkFetchError(error)));
}

// Human-readable reason for a connection failure, so the login popup can say
// what actually went wrong instead of the browser's opaque "Failed to fetch".
function describeConnectionError(error) {
    if (!error) return 'unreachable';
    if (error.isTimeout) return `no answer (${error.message})`;
    if (isNetworkFetchError(error)) return 'could not connect (blocked, offline, or the address is wrong)';
    return error.message || 'unreachable';
}

// A cross-origin POST that carries "Content-Type: application/json" (or any
// custom X-... header) is NOT a CORS "simple request": before it is sent the
// browser must first get an OPTIONS preflight answered. Plenty of Windows
// security suites with HTTPS/web scanning, along with older corporate proxies,
// silently swallow that OPTIONS request - the page itself loads fine, yet every
// API call dies with the same opaque "Failed to fetch". The workaround is to
// re-send the identical JSON body as a preflight-free simple request
// ("text/plain" content type, no custom headers); the server parses it exactly
// the same way. Once that has been shown to be necessary the choice is
// remembered for this device so the authenticated data calls use it too.
const SYNC_NO_PREFLIGHT_STORAGE_KEY = 'sar-sync-no-preflight-v1';
const SIMPLE_REQUEST_CONTENT_TYPE = 'text/plain;charset=UTF-8';

function isPreflightFallbackEnabled() {
    return getCookie(SYNC_NO_PREFLIGHT_STORAGE_KEY) === '1';
}

function setPreflightFallbackEnabled(enabled) {
    setCookie(SYNC_NO_PREFLIGHT_STORAGE_KEY, enabled ? '1' : '');
}

// XMLHttpRequest, wrapped in the small part of the fetch Response surface this
// code uses. It is the last resort for a device where fetch() itself is broken
// (an injected extension/AV script, or a browser old enough that its fetch does
// not handle the request) but the underlying network is fine.
function postViaXhr(url, body, timeoutMs = AUTH_REQUEST_TIMEOUT_MS, headers = {}) {
    return new Promise((resolve, reject) => {
        if (typeof XMLHttpRequest === 'undefined') {
            const error = new Error('XMLHttpRequest is not available');
            error.isUnsupported = true;
            return reject(error);
        }
        const xhr = new XMLHttpRequest();
        xhr.open('POST', url, true);
        xhr.timeout = timeoutMs;
        // Only simple-request headers here: a custom header would re-introduce
        // the preflight this transport exists to avoid.
        xhr.setRequestHeader('Content-Type', headers['Content-Type'] || SIMPLE_REQUEST_CONTENT_TYPE);
        xhr.onload = () => resolve({
            ok: xhr.status >= 200 && xhr.status < 300,
            status: xhr.status,
            url,
            headers: {
                get: name => xhr.getResponseHeader(name)
            },
            text: () => Promise.resolve(xhr.responseText || ''),
            json: () => Promise.resolve(JSON.parse(xhr.responseText || 'null'))
        });
        xhr.onerror = () => reject(new TypeError('Failed to fetch'));
        xhr.ontimeout = () => {
            const error = new Error(`timed out after ${Math.round(timeoutMs / 1000)}s`);
            error.isTimeout = true;
            reject(error);
        };
        xhr.send(body);
    });
}

// The ordered list of ways to deliver one auth POST. The plain JSON request is
// tried (and retried, for a backend waking up from idle) first because it is
// the normal path; the preflight-free variants only come into play on a device
// whose browser or security software blocks the preflight.
function buildAuthTransportPlan(attempts, options = {}) {
    const jsonTransport = {
        name: 'json',
        label: 'standard request',
        send: (url, body, timeoutMs) => fetchWithTimeout(url, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body,
            cache: 'no-store'
        }, timeoutMs)
    };
    const simpleTransport = {
        name: 'simple',
        label: 'compatibility mode (no CORS preflight)',
        send: (url, body, timeoutMs) => fetchWithTimeout(url, {
            method: 'POST',
            headers: {'Content-Type': SIMPLE_REQUEST_CONTENT_TYPE},
            body,
            cache: 'no-store'
        }, timeoutMs)
    };
    const xhrTransport = {
        name: 'xhr',
        label: 'compatibility mode (XMLHttpRequest)',
        send: (url, body, timeoutMs) => postViaXhr(url, body, timeoutMs)
    };

    // A device already known to need the preflight-free path leads with it, so
    // it does not have to sit through the failing standard request every time.
    const available = isPreflightFallbackEnabled()
        ? [simpleTransport, xhrTransport, jsonTransport]
        : [jsonTransport, simpleTransport, xhrTransport];

    const allowed = Array.isArray(options.transports) && options.transports.length
        ? available.filter(transport => options.transports.includes(transport.name))
        : available;

    const plan = [];
    allowed.forEach(transport => {
        // Only the primary transport is worth repeating: the retries exist for a
        // cold backend, and if a transport is blocked outright, repeating it
        // just makes the user wait.
        const repeats = transport === allowed[0] ? attempts : 1;
        for (let i = 0; i < repeats; i++) {
            plan.push(transport);
        }
    });
    return plan;
}

// GET /api/health on a candidate server. Used by the "Test" button on the Set
// Server popup so a device can be diagnosed without guessing at a login.
// A plain GET is already a CORS simple request, so when it fails the follow-up
// opaque ("no-cors") probe tells the two very different causes apart: nothing
// reached the server at all, or the server answered but the browser refused to
// hand the response to the page.
async function checkSyncServerReachable(serverUrl, timeoutMs = AUTH_REQUEST_TIMEOUT_MS) {
    const base = String(serverUrl || '').trim().replace(/\/$/, '');
    if (!base) return {ok: false, url: '', detail: 'no server address set'};
    if (isBlockedMixedContentUrl(base)) {
        return {ok: false, url: base, detail: 'blocked: this page is served over HTTPS and cannot call an http:// server'};
    }
    try {
        const resp = await fetchWithTimeout(`${base}/api/health`, {method: 'GET', cache: 'no-store'}, timeoutMs);
        return {ok: resp.ok, url: base, status: resp.status, detail: `answered HTTP ${resp.status}`};
    } catch (e) {
        const detail = describeConnectionError(e);
        const opaque = await probeServerOpaquely(base, timeoutMs);
        if (opaque.reached) {
            return {
                ok: false,
                url: base,
                corsBlocked: true,
                detail: `${detail}, but the server DID answer a plain browser request \u2014 something on this device (antivirus/web-shield HTTPS scanning, a browser extension, or a proxy) is blocking the app\u2019s cross-origin requests`
            };
        }
        return {ok: false, url: base, detail};
    }
}

// POST /api/auth/login with a deliberately empty body, in the shape whose
// delivery is being tested. The server answers 400 ("Username and PIN are
// required") without touching any account, so ANY HTTP status proves this
// device can reach the server that way.
async function probeAuthEndpoint(serverUrl, {simple = false, timeoutMs = AUTH_REQUEST_TIMEOUT_MS} = {}) {
    const base = String(serverUrl || '').trim().replace(/\/$/, '');
    if (!base) return {ok: false, detail: 'no server address set'};
    try {
        const resp = await fetchWithTimeout(`${base}/api/auth/login`, {
            method: 'POST',
            headers: {'Content-Type': simple ? SIMPLE_REQUEST_CONTENT_TYPE : 'application/json'},
            body: '{}',
            cache: 'no-store'
        }, timeoutMs);
        return {ok: true, status: resp.status, detail: `answered HTTP ${resp.status}`};
    } catch (e) {
        return {ok: false, detail: describeConnectionError(e)};
    }
}

// Full diagnosis of one server address, written for the "Test" button.
//
// It matters WHICH request fails. A plain GET /api/health carries no custom
// headers and no JSON content type, so the browser sends it without asking
// permission first; the login POST does need that CORS preflight. When the
// health check succeeds but the JSON POST does not, the preflight is what is
// being blocked - and the preflight-free POST proving it can still get through
// is exactly what the app falls back to.
async function diagnoseSyncServerConnection(serverUrl, timeoutMs = AUTH_REQUEST_TIMEOUT_MS) {
    const base = String(serverUrl || '').trim().replace(/\/$/, '');
    const lines = [];
    const health = await checkSyncServerReachable(base, timeoutMs);
    lines.push(health.ok
        ? `\u2713 the server is up and answering (${health.detail})`
        : `\u2717 basic check failed: ${health.detail}`);

    const standard = await probeAuthEndpoint(base, {timeoutMs});
    lines.push(standard.ok
        ? '\u2713 the app\u2019s normal login request gets through'
        : `\u2717 the app\u2019s normal login request fails: ${standard.detail}`);

    if (standard.ok) {
        return {ok: true, preflightBlocked: false, serverReachable: true, lines};
    }

    const simple = await probeAuthEndpoint(base, {simple: true, timeoutMs});
    if (simple.ok && simple.status >= 500) {
        // The request itself arrived, but this server build cannot read a
        // text/plain body yet.
        lines.push(`\u2717 compatibility mode reaches the server but it answered HTTP ${simple.status} \u2014 the sync server needs to be updated/redeployed to accept it.`);
        return {ok: false, preflightBlocked: false, serverReachable: true, lines};
    }
    if (simple.ok) {
        lines.push('\u2713 compatibility mode (no CORS preflight) DOES get through \u2014 the app will use it on this device from now on.');
        lines.push('Cause: something on this device (antivirus/internet-security HTTPS or "web shield" scanning, a browser extension, or a proxy) is blocking the browser\u2019s permission check for cross-site requests.');
        return {ok: true, preflightBlocked: true, serverReachable: true, lines};
    }

    lines.push(`\u2717 compatibility mode also fails: ${simple.detail}`);
    return {
        ok: false,
        preflightBlocked: false,
        serverReachable: health.ok,
        lines
    };
}

// Fires a request the browser cannot read the response of ("no-cors"). It still
// resolves when the server was actually contacted, which is why it can prove
// that a failure was the browser's CORS/preflight check rather than the network.
async function probeServerOpaquely(serverUrl, timeoutMs = AUTH_REQUEST_TIMEOUT_MS) {
    const base = String(serverUrl || '').trim().replace(/\/$/, '');
    if (!base) return {reached: false};
    try {
        await fetchWithTimeout(`${base}/api/health?_=${Date.now()}`, {
            method: 'GET',
            mode: 'no-cors',
            cache: 'no-store'
        }, timeoutMs);
        return {reached: true};
    } catch (e) {
        return {reached: false, error: e};
    }
}

// POST to a pre-login auth endpoint (/api/auth/login, /api/auth/register),
// retrying each address (a cold backend often misses the first attempt), then
// falling back to the preflight-free transports (for a device whose security
// software blocks the CORS preflight), and only then moving on to the next
// candidate address. Resolves with the first response received, whatever its
// HTTP status, and remembers both the server that answered and the transport
// that got through so every later data request goes the same way. When no
// candidate can be reached it throws an error naming the addresses tried and
// what to do about it, instead of the opaque "Failed to fetch" the browser
// produces.
async function postAuthRequest(endpointPath, payload, options = {}) {
    const candidates = getAuthServerUrlCandidates();
    const attempts = Math.max(1, options.attempts || AUTH_REQUEST_ATTEMPTS);
    const timeoutMs = options.timeoutMs || AUTH_REQUEST_TIMEOUT_MS;
    const onProgress = typeof options.onProgress === 'function' ? options.onProgress : null;
    const plan = buildAuthTransportPlan(attempts, options);
    const body = JSON.stringify(payload);
    const failures = [];

    for (const serverUrl of candidates) {
        if (isBlockedMixedContentUrl(serverUrl)) {
            failures.push(`${serverUrl} (blocked: this page is served over HTTPS and cannot call an http:// server)`);
            continue;
        }
        let lastError = null;
        const blockedLabels = [];
        for (let step = 0; step < plan.length; step++) {
            const transport = plan[step];
            if (onProgress) {
                onProgress({
                    serverUrl,
                    attempt: step + 1,
                    attempts: plan.length,
                    transport: transport.name,
                    label: transport.label
                });
            }
            try {
                const resp = await transport.send(`${serverUrl}${endpointPath}`, body, timeoutMs);
                // A backend that has not been updated with the compatibility
                // middleware yet cannot read a text/plain body and answers 5xx.
                // Treat that as "this transport does not work here" rather than
                // as a login result, and above all do not remember it.
                if (transport.name !== 'json' && resp.status >= 500) {
                    lastError = new Error(`answered HTTP ${resp.status} (server does not support compatibility mode)`);
                    if (!blockedLabels.includes(transport.label)) {
                        blockedLabels.push(transport.label);
                    }
                    continue;
                }
                if (serverUrl !== getLocalSyncServerUrl().replace(/\/$/, '')) {
                    setLocalSyncServerUrl(serverUrl);
                }
                // Remember whether this device needs the preflight-free path, so
                // the authenticated sync calls made after login use it as well.
                setPreflightFallbackEnabled(transport.name !== 'json');
                return {resp, serverUrl, transport: transport.name};
            } catch (e) {
                if (e && e.isUnsupported) continue;
                if (!isRetriableConnectionError(e)) throw e;
                lastError = e;
                if (!blockedLabels.includes(transport.label)) {
                    blockedLabels.push(transport.label);
                }
                const nextTransport = plan[step + 1];
                if (nextTransport && nextTransport === transport) {
                    await delayMs(AUTH_RETRY_DELAY_MS * (step + 1));
                }
            }
        }
        failures.push(`${serverUrl} (${describeConnectionError(lastError)}; ${plan.length} attempts, incl. ${blockedLabels.join(' + ')})`);
    }

    const isOffline = typeof navigator !== 'undefined' && navigator && navigator.onLine === false;
    throw new Error([
        'Cannot reach the sync server.',
        failures.length ? `Tried: ${failures.join('; ')}.` : '',
        isOffline
            ? 'This device reports that it is offline \u2014 connect it to Wi\u2011Fi or mobile data and try again.'
            : [
                'This device can load the app but no request of any kind reaches the server.',
                'On a Windows laptop this is almost always software on the device itself:',
                'antivirus / internet-security "web shield" or HTTPS scanning (ESET, Avast/AVG, Kaspersky, Bitdefender, McAfee, Norton),',
                'a browser extension (ad/script blocker, privacy shield),',
                'a VPN or corporate proxy, or Windows/browser certificate trust being out of date.',
                'Try: an incognito/private window with extensions off, then temporarily disable the antivirus web/HTTPS scanning, then a different network (mobile hotspot).',
                `To confirm the server is up, open ${getDefaultSyncServerUrl()}/api/health directly in this browser \u2014 if that shows "status":"ok" while the app still cannot connect, the block is on this device.`,
                'The "Set Server" popup also has a "Test" button that reports exactly what is failing.'
            ].join(' ')
    ].filter(Boolean).join(' '));
}

function showLoginPopup() {
    if (document.querySelector('.popup-overlay.login-popup')) return;
    const onCancel = () => {
        if (!getUserCredentials()) {
            setTimeout(() => {
                if (!getUserCredentials()) {
                    alert('Login is required to synchronize data.');
                    showLoginPopup();
                }
            }, 300);
        }
    };
    const popup = createPopup('Login', null, onCancel);
    popup.classList.add('login-popup');
    const content = popup.querySelector('.popup-content');
    const btnContainer = popup.querySelector('.popup-buttons');

    const inputs = document.createElement('div');
    inputs.className = 'popup-input-container';
    inputs.style.display = 'flex';
    inputs.style.flexDirection = 'column';
    inputs.style.gap = '15px';

    const usernameInput = document.createElement('input');
    usernameInput.type = 'text';
    usernameInput.placeholder = 'Username';
    usernameInput.className = 'pill-input';
    usernameInput.style.textAlign = 'center';
    usernameInput.style.width = '100%';
    usernameInput.style.padding = '12px';
    inputs.appendChild(usernameInput);

    const pinInput = document.createElement('input');
    pinInput.type = 'password';
    pinInput.placeholder = 'User PIN';
    pinInput.className = 'pill-input';
    pinInput.style.textAlign = 'center';
    pinInput.style.width = '100%';
    pinInput.style.padding = '12px';
    inputs.appendChild(pinInput);

    content.insertBefore(inputs, btnContainer);

    const loginBtn = document.createElement('button');
    loginBtn.className = 'popup-btn primary';
    loginBtn.textContent = 'Login';
    loginBtn.onclick = async () => {
        const username = usernameInput.value.trim();
        const pin = pinInput.value.trim();
        if (!username || !pin) return alert('Username and PIN required');

        // The first attempt from a new device may have to wait for the backend
        // to wake up, so the button reports what it is doing instead of looking
        // frozen while the retries run.
        const originalLabel = loginBtn.textContent;
        loginBtn.disabled = true;
        loginBtn.textContent = 'Connecting\u2026';
        try {
            const {resp} = await postAuthRequest('/api/auth/login', { username, pin }, {
                onProgress: ({attempt, attempts, transport}) => {
                    if (attempt === 1) {
                        loginBtn.textContent = 'Connecting\u2026';
                        return;
                    }
                    loginBtn.textContent = transport === 'json'
                        ? `Connecting\u2026 (try ${attempt} of ${attempts})`
                        : `Retrying\u2026 (${attempt} of ${attempts}, compatibility mode)`;
                }
            });
            const data = await readJsonResponse(resp);
            if (resp.ok && data.success) {
                setCookie(USER_NAME_STORAGE_KEY, data.user.username);
                setCookie(USER_PASSWORD_STORAGE_KEY, data.user.pin);
                // The login is the team's, not a person's: nobody is the current
                // user until they pick themselves in the profile popup below.
                sessionStorage.removeItem('sar-current-user');
                // Read this login's stored preferences now (they also name the
                // open case, whose team members the picker lists) and leave the
                // theme hint for the reload, so the first page after logging in
                // already paints in the login's theme (see theme-boot.js).
                loginBtn.textContent = 'Loading your settings\u2026';
                _serverSettings = null;
                await withTimeout(loadServerSettings(), 6000);
                rememberUiHintFromPreferences();
                loginBtn.textContent = 'Loading team members\u2026';
                const choices = await withTimeout(fetchLoginProfileChoices(), 8000);
                closePopup(popup);
                showLoginProfilePopup(choices, (user) => {
                    setCurrentUser(user);
                    window.location.reload();
                });
                return;
            }
            alert(data.error || 'no matching login found');
        } catch (e) {
            console.error("Login connection error:", e);
            alert(`Login failed. ${e.message || 'Unable to reach the sync server.'}`);
        } finally {
            loginBtn.disabled = false;
            loginBtn.textContent = originalLabel;
        }
    };
    btnContainer.appendChild(loginBtn);

    // Registration is gated behind a Super-Admin password. This button turns the
    // username/PIN already typed above into a new account, but only after the
    // themed Super-Admin popup verifies the admin password server-side.
    const registerBtn = document.createElement('button');
    registerBtn.className = 'popup-btn';
    registerBtn.id = 'login-register-btn';
    registerBtn.textContent = 'Register';
    registerBtn.onclick = () => {
        const username = usernameInput.value.trim();
        const pin = pinInput.value.trim();
        if (!username || !pin) return alert('Enter a username and PIN to register.');
        if (typeof showAdminVerifyPopup !== 'function') {
            alert('Registration is temporarily unavailable.');
            return;
        }
        showAdminVerifyPopup(username, pin, popup);
    };
    btnContainer.appendChild(registerBtn);

    // Opens a second popup where the user can type/paste the address of the
    // server against which all data flows in and out.
    const setServerBtn = document.createElement('button');
    setServerBtn.className = 'popup-btn';
    setServerBtn.textContent = 'Set Server';
    setServerBtn.onclick = () => {
        showSetServerPopup();
    };
    btnContainer.appendChild(setServerBtn);

    const cancelBtn = document.createElement('button');
    cancelBtn.className = 'popup-btn';
    cancelBtn.textContent = 'Cancel';
    cancelBtn.onclick = () => {
        onCancel();
        closePopup(popup);
    };
    btnContainer.appendChild(cancelBtn);

    setTimeout(() => usernameInput.focus(), 100);
}

// Themed Super-Admin verification popup (opened from the login popup's
// "Register" button). It collects ONLY the Super-Admin password and sends it,
// together with the username/PIN typed on the login popup, to the gated
// /api/auth/register endpoint. On success the new account is created and the
// user is logged in immediately (the same path as a normal login). The gate
// itself lives on the server, so this popup cannot bypass it.
function showAdminVerifyPopup(username, pin, loginPopup) {
    if (document.querySelector('.popup-overlay.admin-verify-popup')) return;
    const popup = createPopup('Super-Admin Verification', null, null);
    popup.classList.add('admin-verify-popup');
    const content = popup.querySelector('.popup-content');
    const btnContainer = popup.querySelector('.popup-buttons');

    const inputs = document.createElement('div');
    inputs.className = 'popup-input-container';
    inputs.style.display = 'flex';
    inputs.style.flexDirection = 'column';
    inputs.style.gap = '10px';

    const label = document.createElement('div');
    label.textContent = `Enter the Super-Admin password to create the account "${username}".`;
    label.style.textAlign = 'center';
    label.style.fontSize = '0.9em';
    label.style.opacity = '0.85';
    inputs.appendChild(label);

    const adminInput = document.createElement('input');
    adminInput.type = 'password';
    adminInput.placeholder = 'Super-Admin password';
    adminInput.className = 'pill-input';
    adminInput.style.textAlign = 'center';
    adminInput.style.width = '100%';
    adminInput.style.padding = '12px';
    inputs.appendChild(adminInput);

    content.insertBefore(inputs, btnContainer);

    const registerBtn = document.createElement('button');
    registerBtn.className = 'popup-btn primary';
    registerBtn.textContent = 'Register';
    registerBtn.onclick = async () => {
        const adminPassword = adminInput.value.trim();
        if (!adminPassword) return alert('Enter the Super-Admin password.');

        registerBtn.disabled = true;
        registerBtn.textContent = 'Registering\u2026';
        try {
            const {resp} = await postAuthRequest('/api/auth/register', { username, pin, adminPassword });
            const data = await readJsonResponse(resp);
            if (resp.ok && data.success) {
                // Auto-login the new account: identical to the login-success path,
                // including the "who is using this device?" pick (a brand-new
                // login has no team members yet, so that offers Anonymous and
                // the Super Admin).
                setCookie(USER_NAME_STORAGE_KEY, data.user.username);
                setCookie(USER_PASSWORD_STORAGE_KEY, data.user.pin);
                sessionStorage.removeItem('sar-current-user');
                _serverSettings = null;
                closePopup(popup);
                if (loginPopup) closePopup(loginPopup);
                showLoginProfilePopup(buildLoginProfileChoices([]), (user) => {
                    setCurrentUser(user);
                    window.location.reload();
                });
            } else {
                alert(data.error || 'Registration failed');
                registerBtn.disabled = false;
                registerBtn.textContent = 'Register';
            }
        } catch (e) {
            // Never log the admin password itself; only the error is reported.
            console.error("Registration connection error:", e);
            alert(`Registration failed. ${e.message || 'Unable to reach the sync server.'}`);
            registerBtn.disabled = false;
            registerBtn.textContent = 'Register';
        }
    };
    btnContainer.appendChild(registerBtn);

    const cancelBtn = document.createElement('button');
    cancelBtn.className = 'popup-btn';
    cancelBtn.textContent = 'Cancel';
    cancelBtn.onclick = () => {
        closePopup(popup);
    };
    btnContainer.appendChild(cancelBtn);

    setTimeout(() => adminInput.focus(), 100);
}

// ---------------------------------------------------------------------------
// Who is at the device: the profile picked right after logging in.
//
// A login (username + PIN) belongs to a whole team; the person at the device
// says WHO they are the moment the login is verified, and that choice (kept in
// sessionStorage as 'sar-current-user') is what tags activity-log entries,
// completed forms and the per-account look-and-feel. Nobody is presumed: the
// pick starts on a stand-in called "Anonymous" - never on the Super-Admin -
// and lists every team member stored under the login (the personnel table on
// the server, for the login's open case when it has one), plus the Super
// Admin for whoever really is one. Anonymous is not an account of the case: it
// is virtual, has no profile to edit and belongs to no personnel row, so the
// Users page simply offers "Switch User" for it.
// ---------------------------------------------------------------------------
const ANONYMOUS_USER_NAME = 'Anonymous';
const ANONYMOUS_USER_PIN = 'anonymous';
// Set (sessionStorage, this tab only) by "Switch User" so the next page load
// opens the team-member picker instead of quietly continuing as Anonymous.
const OPEN_USER_POPUP_SESSION_KEY = 'sar-open-user-popup';

function createAnonymousUser() {
    return {
        username: ANONYMOUS_USER_NAME,
        pin: ANONYMOUS_USER_PIN,
        handle: ANONYMOUS_USER_NAME,
        color: 'none',
        theme: 'dark',
        isFileManager: false,
        isAnonymous: true
    };
}

function isAnonymousUser(user) {
    return !!user && (user.isAnonymous === true || user.pin === ANONYMOUS_USER_PIN);
}

// "Switch User": forget who is at this device and open the team-member picker
// on the Home page (the flag survives the navigation; the login itself stays).
function requestUserSwitch() {
    try { sessionStorage.setItem(OPEN_USER_POPUP_SESSION_KEY, '1'); } catch (e) { /* ignore */ }
    sessionStorage.removeItem('sar-current-user');
    window.location.href = 'home.html';
}

// The one Super Admin account every case carries (see defaultBundle).
function createSuperAdminAccount() {
    const fromDefault = (defaultBundle().accounts || []).find(a => a.pin === '1976');
    return fromDefault ? {...fromDefault, visiblePages: [...(fromDefault.visiblePages || [])]} : {
        username: 'Super Admin', pin: '1976', color: 'none', handle: 'Super-Admin', isFileManager: true, theme: 'dark'
    };
}

// ---------------------------------------------------------------------------
// The login's users (its team).
//
// The people a login can pick from - name, PIN, handle, highlight colour, theme
// and the other account preferences - belong to the LOGIN username, not to a
// CASE #: they live in the database table `login_users` (GET/PUT
// /api/auth/users, read only with the verified username + password) and are
// the same in every case. What a person does in a case (their Personnel row:
// team, status, incident times) stays per case. The website keeps one copy of
// the list in memory for the page lifetime (`_loginUsers`, read right after
// the login's settings) and:
//   * lays it over the open case before anything is drawn
//     (applyLoginUsersToBundle): the case's `accounts` become Super Admin +
//     the login's users, everyone gets a Personnel row when the case has none
//     for them yet (team "Off Duty", not on scene), and a user this case knows
//     but the login does not yet is adopted into the list (how the cases from
//     before this list existed fill it);
//   * learns from every save (syncLoginUsersFromBundle): a name typed into
//     the Personnel page, an account edited on the Users page, a colour or
//     theme changed in Settings, is written back to the login's list at once.
// A user is removed with removeLoginUser (Users page, or deleting their
// Personnel row): the list keeps a record flagged `removed`, the open case
// drops their account and rows, and every other case drops them when it is
// next opened - a stale row there can never bring them back. Typing the name
// again on the Personnel page revives the record.
// ---------------------------------------------------------------------------
let _loginUsers = null;
// True once the server's list was read during this page load; nothing is
// written to it - and no case is changed from it - before that.
let _loginUsersLoaded = false;
// True once applyLoginUsersToBundle ran on the open case during this page
// load; the save hook only learns from a case that was laid over first.
let _loginUsersApplied = false;
let _loginUsersSavePromise = null;
const LOGIN_USER_FIRST_PIN = 1400;
const LOGIN_USER_DEFAULT_PAGES = ['index', 'page2', 'page3', 'page4', 'page5', 'page6', 'page7', 'settings', 'home', 'page8', 'page10'];

// The identity of a login user: the trimmed, lower-cased name.
function loginUserKey(name) {
    return String(name == null ? '' : name).trim().toLowerCase();
}

// Whether an account record is (or could become) a login user: it has a name
// and is neither the Super Admin nor the Anonymous stand-in.
function isLoginUserCandidate(account) {
    if (!account || typeof account !== 'object' || isAnonymousUser(account)) return false;
    const key = loginUserKey(account.username);
    if (!key || key === ANONYMOUS_USER_NAME.toLowerCase() || key === 'super admin' || key === 'super-admin') return false;
    return String(account.pin == null ? '' : account.pin).trim() !== '1976';
}

// Canonical copy of one login user, or null when the input is not one.
function normalizeLoginUser(input) {
    if (!isLoginUserCandidate(input)) return null;
    const name = String(input.username).trim();
    const record = JSON.parse(JSON.stringify(input));
    delete record.isAnonymous;
    record.username = name;
    record.pin = String(input.pin == null ? '' : input.pin).trim();
    record.handle = String(input.handle == null || input.handle === '' ? name : input.handle).trim() || name;
    record.color = typeof input.color === 'string' && input.color ? input.color : 'none';
    record.theme = input.theme === 'light' ? 'light' : 'dark';
    record.isFileManager = input.isFileManager === true;
    record.visiblePages = Array.isArray(input.visiblePages) ? input.visiblePages.slice() : LOGIN_USER_DEFAULT_PAGES.slice();
    record.removed = input.removed === true;
    return record;
}

// The account object a case carries for a login user (the list's record
// without its bookkeeping flag).
function loginUserAsAccount(record) {
    const account = JSON.parse(JSON.stringify(record));
    delete account.removed;
    delete account.updatedAt;
    return account;
}

// The login's users: the ones still on the team unless `includeRemoved`.
function getLoginUsers({includeRemoved = false} = {}) {
    if (!Array.isArray(_loginUsers)) return [];
    return _loginUsers.filter(u => includeRemoved || !u.removed).map(u => JSON.parse(JSON.stringify(u)));
}

function findLoginUserRecord(name) {
    const key = loginUserKey(name);
    if (!key || !Array.isArray(_loginUsers)) return null;
    return _loginUsers.find(u => loginUserKey(u.username) === key) || null;
}

// The next PIN no present login user (and nothing in `alsoTaken`) has,
// counting up from 1400 like the Personnel page always did.
function nextFreeLoginUserPin(alsoTaken = []) {
    const taken = new Set([...(Array.isArray(_loginUsers) ? _loginUsers : []).filter(u => !u.removed).map(u => u.pin), ...alsoTaken.map(String), '1976']);
    let next = LOGIN_USER_FIRST_PIN;
    while (taken.has(String(next))) next++;
    return String(next);
}

// Read the login's users from the server. Resolves to the list (removed ones
// included); [] without credentials. The in-memory copy is only replaced by a
// good answer, so an unreachable server leaves the page working as before.
async function loadLoginUsers({force = false} = {}) {
    const creds = getUserCredentials();
    if (!creds) return [];
    if (_loginUsersLoaded && !force) return getLoginUsers({includeRemoved: true});
    const serverUrl = normalizeSyncServerUrl(getSyncServerUrl());
    if (!serverUrl) return getLoginUsers({includeRemoved: true});
    try {
        const resp = await apiFetch(`${serverUrl}/api/auth/users?_=${Date.now()}`, {headers: getAuthHeaders()});
        if (resp && resp.ok) {
            const body = await resp.json().catch(() => null);
            const list = body && Array.isArray(body.users) ? body.users : (Array.isArray(body) ? body : null);
            if (list) {
                _loginUsers = list.map(normalizeLoginUser).filter(Boolean);
                _loginUsersLoaded = true;
            }
        }
    } catch (e) {
        console.warn('[USERS] Could not read the login\'s users:', e);
    }
    return getLoginUsers({includeRemoved: true});
}

// Write the given user records to the server (upsert by name; the server never
// deletes). Writes are queued one after another; nothing is written before the
// server's list was read. Returns the save promise, or null when nothing went.
function saveLoginUsers(records) {
    const creds = getUserCredentials();
    if (!creds || !_loginUsersLoaded) return null;
    const users = (Array.isArray(records) ? records : []).map(normalizeLoginUser).filter(Boolean);
    if (!users.length) return null;
    const serverUrl = normalizeSyncServerUrl(getSyncServerUrl());
    if (!serverUrl) return null;
    const run = async () => {
        try {
            const resp = await apiFetch(`${serverUrl}/api/auth/users`, {
                method: 'PUT',
                headers: getAuthHeaders(),
                body: JSON.stringify({users})
            });
            if (!resp || !resp.ok) {
                console.warn('[USERS] The login\'s users were not saved:', resp ? resp.status : 'no response');
            }
        } catch (e) {
            console.warn('[USERS] The login\'s users were not saved:', e);
        }
    };
    _loginUsersSavePromise = (_loginUsersSavePromise || Promise.resolve()).then(run, run);
    return _loginUsersSavePromise;
}

// Put `record` into the in-memory list (new, or replacing the record with the
// same name). Returns the stored record.
function upsertLoginUserRecord(record) {
    if (!Array.isArray(_loginUsers)) _loginUsers = [];
    const existing = findLoginUserRecord(record.username);
    if (existing) {
        Object.keys(existing).forEach((k) => { delete existing[k]; });
        Object.assign(existing, record);
        return existing;
    }
    _loginUsers.push(record);
    return record;
}

// Take a case's own account into the login's list. Its PIN must be unique
// among the login's users: when another (still present) user has it, the
// newcomer gets the next free one and the case's Personnel rows are re-linked
// to it. A removed record's PIN is free again - that is how a renamed user
// keeps theirs.
function adoptAccountIntoLoginUsers(account, personnelRows) {
    const record = normalizeLoginUser(account);
    if (!record) return null;
    record.removed = false;
    const owner = (_loginUsers || []).find(u => !u.removed && u.pin && u.pin === record.pin && loginUserKey(u.username) !== loginUserKey(record.username));
    if (owner || !record.pin) {
        const oldPin = record.pin;
        record.pin = nextFreeLoginUserPin();
        account.pin = record.pin;
        (Array.isArray(personnelRows) ? personnelRows : []).forEach((row) => {
            if (!Array.isArray(row)) return;
            if (loginUserKey(row[0]) === loginUserKey(record.username) || (oldPin && String(row[8] || '').trim() === oldPin && !row[0])) {
                row[8] = record.pin;
            }
        });
    }
    return upsertLoginUserRecord(record);
}

// A blank Personnel row for a login user who has none in this case yet: team
// "Off Duty", not on scene, linked to the user by PIN; the GPS / Radio / Medic
// toggles the case already remembers for the name are kept.
function personnelRowForLoginUser(record, bundle) {
    const row = Array.from({length: 14}, () => '');
    row[0] = record.username;
    row[1] = 'Off Duty';
    row[6] = 'false';
    row[8] = record.pin;
    const roles = bundle && bundle.permanentPersonnel && bundle.permanentPersonnel[record.username];
    if (roles && typeof roles === 'object') {
        row[3] = roles.gps || '';
        row[4] = roles.radio || '';
        row[5] = roles.medic || '';
    }
    return row;
}

// Whether a Personnel row still is the blank one personnelRowForLoginUser
// made: nothing but the name, the "Off Duty" team, the not-on-scene flag,
// the PIN and the remembered role toggles.
function isBlankLoginUserRow(row) {
    if (!Array.isArray(row)) return false;
    return row.every((cell, index) => {
        const value = String(cell == null ? '' : cell).trim();
        if (index === 0 || index === 8 || index === 3 || index === 4 || index === 5) return true;
        if (index === 1) return value === '' || value === 'Off Duty';
        if (index === 6) return value === '' || value === 'false';
        return value === '';
    });
}

// Lay the login's users over a case (once per page load, before it is drawn):
//   1. accounts this case has that the login does not know are adopted;
//   2. the case's accounts become Super Admin + the login's users;
//   3. every user has a Personnel row (a missing one is added), rows are linked
//      to the user's PIN, and rows of removed users go.
// Returns true when the case changed (the caller saves it). Nothing happens
// before the server's list was read.
function applyLoginUsersToBundle(bundle) {
    if (!bundle || typeof bundle !== 'object' || !_loginUsersLoaded || !Array.isArray(_loginUsers)) return false;
    let changed = false;
    const toSave = [];
    const accounts = Array.isArray(bundle.accounts) ? bundle.accounts : [];
    if (!bundle.pages || typeof bundle.pages !== 'object') bundle.pages = {};
    const personnel = Array.isArray(bundle.pages.page3) ? bundle.pages.page3 : [];

    accounts.filter(isLoginUserCandidate).forEach((account) => {
        if (findLoginUserRecord(account.username)) return;
        const record = adoptAccountIntoLoginUsers(account, personnel);
        if (record) { toSave.push(record); changed = true; }
    });

    const superAdmin = accounts.find(a => a && a.pin === '1976') || createSuperAdminAccount();
    const active = _loginUsers.filter(u => !u.removed);
    const nextAccounts = [superAdmin, ...active.map(loginUserAsAccount)];
    if (JSON.stringify(nextAccounts) !== JSON.stringify(accounts)) {
        bundle.accounts = nextAccounts;
        changed = true;
    }

    // Rows are claimed by PIN first (a user renamed on another device keeps
    // their team and status here) - unless the row is named after another
    // present user, whose row it is (a case from before the list handed out
    // its own PINs) - then by name; only then do the rows of removed users
    // go, together with the roles the case remembered for them, or
    // syncPersonnelData would put a row back on the Personnel page.
    const activeKeys = new Set(active.map(u => loginUserKey(u.username)));
    let rows = personnel.slice();
    active.forEach((user) => {
        const key = loginUserKey(user.username);
        let row = (user.pin && rows.find(r => Array.isArray(r) && String(r[8] || '').trim() === user.pin && String(r[0] || '').trim()
                && (loginUserKey(r[0]) === key || !activeKeys.has(loginUserKey(r[0])))))
            || rows.find(r => Array.isArray(r) && loginUserKey(r[0]) === key);
        if (!row) {
            rows.push(personnelRowForLoginUser(user, bundle));
            changed = true;
            return;
        }
        while (row.length < 14) { row.push(''); changed = true; }
        if (String(row[0] || '').trim() !== user.username) { row[0] = user.username; changed = true; }
        if (String(row[8] || '').trim() !== user.pin) { row[8] = user.pin; changed = true; }
    });
    // Two devices opening a case at the same moment may both have appended
    // the blank row of the same person (row batches append, they do not
    // dedupe): the second blank copy goes; a row somebody worked on stays.
    const seenKeys = new Set();
    const removedKeys = new Set(_loginUsers.filter(u => u.removed).map(u => loginUserKey(u.username)));
    const kept = rows.filter((row) => {
        if (!Array.isArray(row)) return true;
        const key = loginUserKey(row[0]);
        if (!key) return true;
        if (removedKeys.has(key)) return false;
        if (activeKeys.has(key) && seenKeys.has(key) && isBlankLoginUserRow(row)) return false;
        seenKeys.add(key);
        return true;
    });
    if (kept.length !== rows.length) { rows = kept; changed = true; }
    if (bundle.permanentPersonnel && typeof bundle.permanentPersonnel === 'object') {
        Object.keys(bundle.permanentPersonnel).forEach((name) => {
            if (removedKeys.has(loginUserKey(name))) { delete bundle.permanentPersonnel[name]; changed = true; }
        });
    }
    if (changed) bundle.pages.page3 = rows;

    if (toSave.length) saveLoginUsers(toSave);
    _loginUsersApplied = true;
    return changed;
}

// The save hook: whatever the case now says about its users - a new name on
// the Personnel page (the sanitizer made it an account), an edited account, a
// changed colour or theme - goes into the login's list. A name the list has
// as removed is revived (it was typed anew: the case dropped stale rows when
// it was opened). Runs only on a case that was laid over this page load.
function syncLoginUsersFromBundle(bundle) {
    if (!_loginUsersApplied || !_loginUsersLoaded || !bundle || typeof bundle !== 'object') return false;
    const accounts = Array.isArray(bundle.accounts) ? bundle.accounts : [];
    const personnel = bundle.pages && Array.isArray(bundle.pages.page3) ? bundle.pages.page3 : [];
    const toSave = [];
    accounts.filter(isLoginUserCandidate).forEach((account) => {
        const known = findLoginUserRecord(account.username);
        if (!known) {
            const record = adoptAccountIntoLoginUsers(account, personnel);
            if (record) toSave.push(record);
            return;
        }
        const next = normalizeLoginUser({...known, ...account, removed: false});
        if (!next) return;
        delete next.updatedAt;
        const current = {...known};
        delete current.updatedAt;
        if (JSON.stringify(next) !== JSON.stringify(current)) {
            toSave.push(upsertLoginUserRecord(next));
        }
    });
    if (toSave.length) saveLoginUsers(toSave);
    return toSave.length > 0;
}

// A user was renamed (Users page): the list keeps the old name as removed so
// no case revives it, and the new name is adopted from the case on save.
function noteLoginUserRename(oldName, newName) {
    if (loginUserKey(oldName) === loginUserKey(newName)) return;
    const known = findLoginUserRecord(oldName);
    if (!known || known.removed) return;
    known.removed = true;
    saveLoginUsers([known]);
}

// Remove a person from the login: flagged as removed in the list, and taken
// out of the case (account and Personnel rows). With a bundle passed in the
// caller saves it; without one the open case is loaded and saved here.
function removeLoginUser(name, bundle) {
    const key = loginUserKey(name);
    if (!key) return false;
    const known = findLoginUserRecord(name);
    if (known && !known.removed) {
        known.removed = true;
        saveLoginUsers([known]);
    }
    const own = !bundle;
    const target = own ? loadBundle() : bundle;
    let changed = false;
    if (Array.isArray(target.accounts)) {
        const kept = target.accounts.filter(a => !(isLoginUserCandidate(a) && loginUserKey(a.username) === key));
        if (kept.length !== target.accounts.length) { target.accounts = kept; changed = true; }
    }
    if (target.pages && Array.isArray(target.pages.page3)) {
        const kept = target.pages.page3.filter(row => !(Array.isArray(row) && loginUserKey(row[0]) === key));
        if (kept.length !== target.pages.page3.length) {
            target.pages.page3 = kept.length ? kept : [Array.from({length: 14}, () => '')];
            changed = true;
        }
    }
    if (target.permanentPersonnel && typeof target.permanentPersonnel === 'object') {
        Object.keys(target.permanentPersonnel).forEach((n) => {
            if (loginUserKey(n) === key) { delete target.permanentPersonnel[n]; changed = true; }
        });
    }
    if (own && changed) saveBundle(target);
    return changed;
}

// The choices the picker shows: the login's users (their stored PIN, colour
// and theme) plus, for a login whose list is still empty, the names of the
// personnel rows the server holds for it in any case - either the structured
// `personnel` table rows ({label, data: [name, team, lead, ..., pin at 8]}) or
// bare Personnel page rows. Anonymous first and marked as the default, then
// every distinct person A-Z, then the Super Admin (offered, but never the
// default). Removed users and rows that would duplicate those two are dropped.
function buildLoginProfileChoices(personnelRows, loginUsers) {
    const reserved = new Set([ANONYMOUS_USER_NAME.toLowerCase(), 'super admin', 'super-admin']);
    const seen = new Set();
    const removed = new Set();
    const people = [];
    (Array.isArray(loginUsers) ? loginUsers : []).forEach((user) => {
        const record = normalizeLoginUser(user);
        if (!record) return;
        const key = loginUserKey(record.username);
        if (reserved.has(key) || seen.has(key)) return;
        if (record.removed) { removed.add(key); return; }
        seen.add(key);
        people.push({user: loginUserAsAccount(record), isDefault: false, isSuperAdmin: false});
    });
    (Array.isArray(personnelRows) ? personnelRows : []).forEach((row) => {
        const data = row && Array.isArray(row.data) ? row.data : (Array.isArray(row) ? row : null);
        const name = String((data && data[0]) || (row && !Array.isArray(row) && row.label) || '').trim();
        if (!name) return;
        const key = name.toLowerCase();
        if (reserved.has(key) || seen.has(key) || removed.has(key)) return;
        seen.add(key);
        people.push({
            user: {
                username: name,
                pin: String((data && data[8]) || '').trim(),
                color: 'none',
                handle: name,
                isFileManager: false,
                theme: 'dark'
            },
            isDefault: false,
            isSuperAdmin: false
        });
    });
    people.sort((a, b) => a.user.username.localeCompare(b.user.username, undefined, {sensitivity: 'base'}));
    return [
        {user: createAnonymousUser(), isDefault: true, isSuperAdmin: false},
        ...people,
        {user: createSuperAdminAccount(), isDefault: false, isSuperAdmin: true}
    ];
}

// Every personnel row the login has in ANY case, read from the server right
// after the login is verified (the case itself is not in memory yet). Not
// restricted to the open case - the users belong to the login, not to a
// CASE # - and only there to fill the picker for a login whose user list is
// still empty. [] when nothing is reachable.
async function fetchLoginProfilePersonnel() {
    const serverUrl = normalizeSyncServerUrl(getSyncServerUrl());
    if (!serverUrl || !getUserCredentials()) return [];
    try {
        const resp = await apiFetch(`${serverUrl}/api/v1/tables/personnel?_=${Date.now()}`, {headers: getAuthHeaders()});
        if (!resp || !resp.ok) return [];
        const rows = await resp.json().catch(() => []);
        return Array.isArray(rows) ? rows : [];
    } catch (e) {
        console.warn('[LOGIN] Could not read the team members for the profile picker:', e);
        return [];
    }
}

// The login's users from /api/auth/users - read afresh, the credentials were
// just verified - together with the names of the login's personnel rows in
// every case, so a person from a case that was not opened since the list
// exists is offered too (and adopted into the list once that case is opened).
async function fetchLoginProfileChoices() {
    const [users, personnel] = await Promise.all([loadLoginUsers({force: true}), fetchLoginProfilePersonnel()]);
    return buildLoginProfileChoices(personnel, users);
}

// The picker itself (opened by the login popup once the login is verified).
// Clicking a name picks it at once; "Continue as Anonymous", the ✕ and a click
// outside all pick the default. `onPick(user)` is called exactly once.
function showLoginProfilePopup(choices, onPick) {
    if (document.querySelector('.popup-overlay.login-profile-popup')) return null;
    const list = Array.isArray(choices) && choices.length ? choices : buildLoginProfileChoices([]);
    const defaultChoice = list.find(c => c.isDefault) || list[0];
    let picked = false;
    let popup = null;
    const pick = (user) => {
        if (picked) return;
        picked = true;
        if (popup) closePopup(popup);
        if (typeof onPick === 'function') onPick(user);
    };
    popup = createPopup('Who is using this device?', null, () => pick(defaultChoice.user));
    popup.classList.add('login-profile-popup');
    const content = popup.querySelector('.popup-content');
    const btnContainer = popup.querySelector('.popup-buttons');

    const inputs = document.createElement('div');
    inputs.className = 'popup-input-container';
    inputs.style.display = 'flex';
    inputs.style.flexDirection = 'column';
    inputs.style.gap = '12px';

    const creds = getUserCredentials();
    const label = document.createElement('div');
    label.textContent = `Logged in as "${creds ? creds.name : ''}". Pick the team member working on this device - everything done here is recorded under that name. "${ANONYMOUS_USER_NAME}" is used unless you pick someone.`;
    label.style.textAlign = 'center';
    label.style.fontSize = '0.9em';
    label.style.opacity = '0.85';
    inputs.appendChild(label);

    const searchInput = document.createElement('input');
    searchInput.type = 'text';
    searchInput.placeholder = 'Type to search...';
    searchInput.className = 'pill-input';
    searchInput.style.textAlign = 'center';
    searchInput.style.width = '100%';
    inputs.appendChild(searchInput);

    const pillsContainer = document.createElement('div');
    pillsContainer.className = 'login-profile-pills';
    pillsContainer.style.display = 'flex';
    pillsContainer.style.flexWrap = 'wrap';
    pillsContainer.style.justifyContent = 'center';
    pillsContainer.style.gap = '5px';
    pillsContainer.style.maxHeight = '40vh';
    pillsContainer.style.overflowY = 'auto';
    inputs.appendChild(pillsContainer);

    const renderPills = () => {
        pillsContainer.innerHTML = '';
        const query = searchInput.value.trim().toLowerCase();
        list.filter(choice => !query || choice.user.username.toLowerCase().includes(query)).forEach((choice) => {
            const pill = document.createElement('button');
            pill.type = 'button';
            pill.className = 'mini-pill login-profile-pill';
            pill.textContent = choice.user.username;
            pill.dataset.pin = choice.user.pin || '';
            if (choice.isDefault) {
                pill.classList.add('active');
                pill.style.background = 'var(--pill-bg-hover)';
                pill.style.borderColor = 'var(--accent)';
                pill.title = 'Default';
            }
            if (choice.isSuperAdmin) {
                pill.style.opacity = '0.8';
                pill.title = 'Only for the Super-Admin';
            }
            pill.onclick = () => pick(choice.user);
            pillsContainer.appendChild(pill);
        });
    };
    searchInput.oninput = renderPills;
    renderPills();

    content.insertBefore(inputs, btnContainer);

    const continueBtn = document.createElement('button');
    continueBtn.className = 'popup-btn primary';
    continueBtn.id = 'login-profile-continue-btn';
    continueBtn.textContent = `Continue as ${defaultChoice.user.username}`;
    continueBtn.onclick = () => pick(defaultChoice.user);
    btnContainer.appendChild(continueBtn);

    setTimeout(() => searchInput.focus(), 100);
    return popup;
}

// Second popup (opened from the login popup's "Set Server" button) that lets the
// user type or paste the address of the server against which all data flows in
// and out. On "Set" the URL is validated and persisted locally so it takes
// effect immediately for every request, including the login that follows.
// This is the ONLY place the data server can be changed: the Settings page no
// longer has a sync-server (or CalTopo proxy) section, so switching servers
// means logging out and using this popup from the login popup. "Use Default"
// returns to the address the server publishes from CALTOPO_SYNC.
function showSetServerPopup() {
    if (document.querySelector('.popup-overlay.set-server-popup')) return;
    const popup = createPopup('Set Server', null, null);
    popup.classList.add('set-server-popup');
    const content = popup.querySelector('.popup-content');
    const btnContainer = popup.querySelector('.popup-buttons');

    const inputs = document.createElement('div');
    inputs.className = 'popup-input-container';
    inputs.style.display = 'flex';
    inputs.style.flexDirection = 'column';
    inputs.style.gap = '10px';

    const label = document.createElement('div');
    label.textContent = 'Server address (e.g. https://your-server.example.com)';
    label.style.textAlign = 'center';
    label.style.fontSize = '0.9em';
    label.style.opacity = '0.85';
    inputs.appendChild(label);

    const serverInput = document.createElement('input');
    serverInput.type = 'text';
    serverInput.placeholder = 'https://your-server.example.com';
    serverInput.className = 'pill-input';
    serverInput.style.textAlign = 'center';
    serverInput.style.width = '100%';
    serverInput.style.padding = '12px';
    serverInput.value = getLocalSyncServerUrl() || getSyncServerUrl() || '';
    inputs.appendChild(serverInput);

    content.insertBefore(inputs, btnContainer);

    // Live result of the "Test" button, so a device that cannot log in can be
    // diagnosed here rather than through the login error alert.
    const statusLine = document.createElement('div');
    statusLine.style.textAlign = 'center';
    statusLine.style.fontSize = '0.85em';
    statusLine.style.opacity = '0.85';
    statusLine.style.minHeight = '1.2em';
    statusLine.style.whiteSpace = 'pre-wrap';
    inputs.appendChild(statusLine);

    // Normalizes what the user typed into a usable base URL, or returns '' and
    // explains why it cannot be used.
    const readServerInput = () => {
        let url = serverInput.value.trim();
        if (!url) {
            alert('Please enter a server address.');
            return '';
        }
        // Be forgiving about a missing scheme so pasting a bare host still works.
        if (!/^https?:\/\//i.test(url)) {
            url = 'https://' + url;
        }
        try {
            // Validate the address before using it.
            // eslint-disable-next-line no-new
            new URL(url);
        } catch (e) {
            alert('That does not look like a valid server address.');
            return '';
        }
        return url.replace(/\/$/, '');
    };

    // Checks the typed address (and, when it fails, the built-in public backend)
    // so the user learns whether the problem is the address or the network.
    const testBtn = document.createElement('button');
    testBtn.className = 'popup-btn';
    testBtn.textContent = 'Test';
    testBtn.onclick = async () => {
        const url = readServerInput();
        if (!url) return;
        testBtn.disabled = true;
        const originalLabel = testBtn.textContent;
        testBtn.textContent = 'Testing\u2026';
        statusLine.textContent = `Testing ${url}\u2026`;
        try {
            const result = await diagnoseSyncServerConnection(url);
            // A device that only gets through without the CORS preflight is
            // switched over here, so the very next login uses the path the test
            // just proved works.
            if (result.preflightBlocked) {
                setPreflightFallbackEnabled(true);
            }
            let message = `${url}\n${result.lines.join('\n')}`;
            if (result.ok) {
                statusLine.textContent = message;
                return;
            }

            const fallback = getDefaultSyncServerUrl().replace(/\/$/, '');
            if (url !== fallback) {
                statusLine.textContent = `${message}\nTesting the built-in server ${fallback}\u2026`;
                const fallbackResult = await diagnoseSyncServerConnection(fallback);
                if (fallbackResult.preflightBlocked) {
                    setPreflightFallbackEnabled(true);
                }
                message += fallbackResult.ok
                    ? `\n\nThe built-in server ${fallback} DOES work \u2014 press "Use Default", then "Set".`
                    : `\n\nThe built-in server ${fallback} also failed:\n${fallbackResult.lines.join('\n')}`;
                if (fallbackResult.ok) {
                    statusLine.textContent = message;
                    return;
                }
            }

            message += result.serverReachable
                ? '\n\nThe server itself answers, so the block is on this device: turn off the antivirus web/HTTPS scanning, or open the app in a private window with extensions disabled.'
                : '\n\nNothing reaches the server from this device. Try a different network (mobile hotspot), turn off any VPN, and check that antivirus HTTPS scanning is not intercepting the connection.';
            statusLine.textContent = message;
        } finally {
            testBtn.disabled = false;
            testBtn.textContent = originalLabel;
        }
    };
    btnContainer.appendChild(testBtn);

    // Restores the default backend (the address CALTOPO_SYNC publishes, else
    // the built-in one), undoing a wrong/stale address saved on this device.
    const resetBtn = document.createElement('button');
    resetBtn.className = 'popup-btn';
    resetBtn.textContent = 'Use Default';
    resetBtn.onclick = () => {
        const fallback = getDefaultSyncServerUrl();
        serverInput.value = fallback;
        setLocalSyncServerUrl('');
        statusLine.textContent = `Reset to the default server ${fallback}. Press "Test" to check it.`;
    };
    btnContainer.appendChild(resetBtn);

    const setBtn = document.createElement('button');
    setBtn.className = 'popup-btn primary';
    setBtn.textContent = 'Set';
    setBtn.onclick = () => {
        const url = readServerInput();
        if (!url) return;
        // Refuse an address the browser would silently block anyway: an http://
        // server cannot be called from a page served over https:// (mixed
        // content), and every request would fail with "Failed to fetch".
        if (isBlockedMixedContentUrl(url)) {
            return alert(`This page is served over HTTPS, so it cannot talk to an http:// server.\n\nUse https:// for:\n${url}`);
        }
        // The choice is this device's alone (a cookie); it is deliberately not
        // written into the login's server-side settings, so no other device -
        // and no page other than this popup - can switch the data server.
        setLocalSyncServerUrl(url);
        alert(`Server set to:\n${url}`);
        closePopup(popup);
    };
    btnContainer.appendChild(setBtn);

    const cancelBtn = document.createElement('button');
    cancelBtn.className = 'popup-btn';
    cancelBtn.textContent = 'Cancel';
    cancelBtn.onclick = () => {
        closePopup(popup);
    };
    btnContainer.appendChild(cancelBtn);

    setTimeout(() => serverInput.focus(), 100);
}

