// ---------------------------------------------------------------------------
// IC Report
//
// Every CASE # carries exactly one IC Report: a free-text report written by
// the Incident Commander plus a "form completed" checkbox. The name typed into
// the small field next to the checkbox is tagged onto the completion (with the
// date/time) the moment the checkbox is ticked; when nobody typed a name the
// signed-in user is tagged instead. It is edited under the "IC Report" button
// of the Forms page (next to Incident Times), printed on its own from there,
// and also included in the Case # Printout.
// ---------------------------------------------------------------------------

function defaultIcReport() {
  return {
    text: '',
    completedName: '',
    completed: false,
    completedBy: '',
    completedAt: ''
  };
}

function sanitizeIcReport(raw) {
  const report = defaultIcReport();
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return report;
  const str = value => (value === undefined || value === null) ? '' : String(value);
  report.text = str(raw.text);
  report.completedName = str(raw.completedName).trim();
  report.completed = raw.completed === true;
  report.completedBy = str(raw.completedBy).trim();
  report.completedAt = str(raw.completedAt).trim();
  if (!report.completed) {
    report.completedBy = '';
    report.completedAt = '';
  }
  return report;
}

// The report of `bundle`, created in place when the file predates IC Reports.
function ensureIcReport(bundle) {
  const b = bundle || loadBundle();
  b.icReport = sanitizeIcReport(b.icReport);
  return b.icReport;
}

// "MM-DD-YYYY HH:mm" the way the Search Log and activity log stamp times.
function formatIcReportStamp(date) {
  const d = (date && typeof date.getTime === 'function' && !isNaN(date.getTime())) ? date : new Date();
  const pad = n => String(n).padStart(2, '0');
  return `${pad(d.getMonth() + 1)}-${pad(d.getDate())}-${d.getFullYear()} ${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function getIcReportSignerName(report) {
  const typed = String(report?.completedName || '').trim();
  if (typed) return typed;
  const user = getCurrentUser();
  return user ? getAccountName(user) : 'Unknown User';
}

// Ticks the checkbox: whoever is named in the small text field (else the
// signed-in user) is tagged with the completion date/time. Returns the report.
function markIcReportCompleted(bundle, now = new Date()) {
  const report = ensureIcReport(bundle);
  report.completed = true;
  report.completedBy = getIcReportSignerName(report);
  report.completedAt = formatIcReportStamp(now);
  return report;
}

// Unticks the checkbox; the typed name stays so it can be re-signed quickly.
function reopenIcReport(bundle) {
  const report = ensureIcReport(bundle);
  report.completed = false;
  report.completedBy = '';
  report.completedAt = '';
  return report;
}

function getIcReportCompletionLabel(report) {
  const r = sanitizeIcReport(report);
  if (!r.completed) return 'Mark IC Report as Completed';
  const by = r.completedBy || 'Unknown User';
  return r.completedAt ? `Completed by ${by} at ${r.completedAt}` : `Completed by ${by}`;
}

// The CASE # shown under the "IC Report" title (the file name without .json).
function getIcReportCaseLabel(bundle) {
  return getCaseDisplayName(bundle).replace(/\.json$/i, '');
}

function escapeIcReportHtml(value) {
  return String(value === undefined || value === null ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// Print styles of the report block; shared by the stand-alone "Print Report"
// of the Forms page and the Case # Printout.
const IC_REPORT_PRINT_STYLES = `
        .ic-report { border: 2px solid #000; padding: 12px 15px; margin-bottom: 20px; page-break-inside: avoid; }
        .ic-report-title { font-size: 16pt; border-bottom: 2px solid #000; margin: 0 0 4px 0; padding-bottom: 3px; }
        .ic-report .print-title-row { margin: 0 0 4px 0; padding-bottom: 3px; }
        .ic-report-case { font-size: 11pt; font-weight: bold; color: #444; margin-bottom: 10px; }
        .ic-report-text { min-height: 1.5in; border: 1px solid #999; padding: 8px; font-size: 11pt; white-space: pre-wrap; word-wrap: break-word; margin-bottom: 10px; }
        .ic-report-empty { font-style: italic; color: #888; }
        .ic-report-completion { font-size: 10pt; font-weight: bold; display: flex; align-items: center; gap: 6px; }
        .ic-report-check { font-size: 14pt; line-height: 1; }
`;

// Static markup of the report for the printouts. `options.logo` puts the
// login's logo in the title row (the stand-alone printout; the Case #
// Printout already carries it in the top row of the page).
function getIcReportPrintHTML(bundle, options = {}) {
  const report = sanitizeIcReport(bundle && bundle.icReport);
  const caseLabel = escapeIcReportHtml(getIcReportCaseLabel(bundle));
  const title = options.logo === true
    ? getPrintTitleRowHTML(bundle, 'IC Report', {tag: 'h2', className: 'ic-report-title'})
    : '<h2 class="ic-report-title">IC Report</h2>';
  const text = report.text.trim()
    ? escapeIcReportHtml(report.text)
    : '<span class="ic-report-empty">No IC report has been written for this case.</span>';
  const completion = report.completed
    ? `<span class="ic-report-check">&#9745;</span> ${escapeIcReportHtml(getIcReportCompletionLabel(report))}`
    : '<span class="ic-report-check">&#9744;</span> Form not yet completed';
  return `
            <div class="ic-report">
                ${title}
                <div class="ic-report-case">Case # ${caseLabel}</div>
                <div class="ic-report-text">${text}</div>
                <div class="ic-report-completion">${completion}</div>
            </div>`;
}

// Prints only the IC Report (the "Print Report" button of the IC Report form).
function printIcReport() {
    const bundle = loadBundle();
    const caseLabel = getIcReportCaseLabel(bundle);

    const printWindow = window.open('', '_blank');
    if (!printWindow) {
        alert("Please allow popups to view the printout.");
        return;
    }

    printWindow.document.write(`
<!DOCTYPE html>
<html lang="en">
<head>
    <title>IC Report - ${escapeIcReportHtml(caseLabel)}</title>
    <style>
        ${TASK_FORM_PRINT_STYLES}
        ${IC_REPORT_PRINT_STYLES}
    </style>
</head>
<body>
    <div class="no-print">
        <button onclick="window.print()" style="padding: 10px 20px; font-size: 16px; cursor: pointer; background: #007bff; color: white; border: none; border-radius: 999px;">Print PDF</button>
        <p style="font-size: 12px; color: #666;">Note: Use "Save as PDF" in the print dialog for a digital copy.</p>
    </div>
    <div class="print-container">
        <div class="print-section">
            ${getIcReportPrintHTML(bundle, {logo: true})}
        </div>
    </div>
    <script>
        setTimeout(() => { window.print(); }, 500);
    </script>
</body>
</html>
    `);
    printWindow.document.close();
}

// Creates the (empty) IC Report form markup inside `container` unless it is
// already there, and returns the panel element.
function ensureIcReportPanel(container) {
  const existing = document.getElementById('ic-report-panel');
  if (existing && existing.parentElement === container) return existing;
  container.innerHTML = '';

  const panel = document.createElement('div');
  panel.className = 'ic-report-panel';
  panel.id = 'ic-report-panel';

  const heading = document.createElement('h2');
  heading.className = 'ic-report-heading';
  heading.textContent = 'IC Report';
  panel.appendChild(heading);

  const subtitle = document.createElement('div');
  subtitle.className = 'ic-report-subtitle';
  subtitle.id = 'ic-report-case';
  subtitle.textContent = 'Case #';
  panel.appendChild(subtitle);

  const label = document.createElement('label');
  label.className = 'ic-report-label';
  label.htmlFor = 'ic-report-text';
  label.textContent = 'Report';
  panel.appendChild(label);

  const textArea = document.createElement('textarea');
  textArea.id = 'ic-report-text';
  textArea.className = 'form-input ic-report-textarea';
  textArea.placeholder = 'Incident Commander report for this case...';
  panel.appendChild(textArea);

  const row = document.createElement('div');
  row.className = 'ic-report-completion-row';

  const check = document.createElement('input');
  check.type = 'checkbox';
  check.id = 'ic-report-completed';
  check.className = 'pill-checkbox';
  check.setAttribute('aria-label', 'Mark IC Report as completed');
  row.appendChild(check);

  const nameInput = document.createElement('input');
  nameInput.type = 'text';
  nameInput.id = 'ic-report-name';
  nameInput.className = 'form-input ic-report-name';
  nameInput.placeholder = 'Completed by (name)';
  nameInput.setAttribute('aria-label', 'Name to tag with the completion');
  row.appendChild(nameInput);

  const status = document.createElement('span');
  status.className = 'ic-report-status';
  status.id = 'ic-report-status';
  status.textContent = 'Mark IC Report as Completed';
  row.appendChild(status);

  panel.appendChild(row);
  container.appendChild(panel);
  return panel;
}

// The editable form shown under the "IC Report" button of the Forms page
// (page5.html, inside the interactive form container). Re-run on every page
// rebuild, including the ones triggered by another device's edits, so a field
// the user is typing in right now is left alone.
function buildIcReportForm() {
  const container = document.getElementById('interactive-form-container');
  if (!container) return;
  ensureIcReportPanel(container);
  renderIcReportForm();
}

function renderIcReportForm() {
  const panel = document.getElementById('ic-report-panel');
  if (!panel) return;
  const caseEl = document.getElementById('ic-report-case');
  const textArea = document.getElementById('ic-report-text');
  const check = document.getElementById('ic-report-completed');
  const nameInput = document.getElementById('ic-report-name');
  const statusEl = document.getElementById('ic-report-status');
  if (!textArea || !check || !nameInput) return;

  const bundle = loadBundle();
  const report = ensureIcReport(bundle);
  const active = document.activeElement;

  if (caseEl) caseEl.textContent = `Case # ${getIcReportCaseLabel(bundle)}`;
  if (active !== textArea && textArea.value !== report.text) textArea.value = report.text;
  if (active !== nameInput && nameInput.value !== report.completedName) nameInput.value = report.completedName;
  check.checked = report.completed;
  nameInput.readOnly = report.completed;
  if (report.completed) {
    if (nameInput.value !== report.completedBy) nameInput.value = report.completedBy;
    panel.classList.add('is-completed');
  } else {
    panel.classList.remove('is-completed');
  }
  if (statusEl) {
    statusEl.textContent = getIcReportCompletionLabel(report);
    statusEl.classList.toggle('is-completed', report.completed);
  }

  textArea.oninput = () => {
    const b = loadBundle();
    ensureIcReport(b).text = textArea.value;
    saveBundle(b);
  };

  nameInput.oninput = () => {
    const b = loadBundle();
    const r = ensureIcReport(b);
    if (r.completed) return;
    r.completedName = nameInput.value.trim();
    saveBundle(b);
  };

  check.onchange = () => {
    const b = loadBundle();
    const r = ensureIcReport(b);
    const user = getCurrentUser();
    const userName = user ? getAccountName(user) : 'Unknown User';
    if (check.checked) {
      r.completedName = nameInput.value.trim();
      const signed = markIcReportCompleted(b);
      saveBundle(b);
      addActivityLogEntry('System', `IC Report for Case # ${getIcReportCaseLabel(b)} marked as completed by ${signed.completedBy}${signed.completedBy !== userName ? ` (entered by ${userName})` : ''}`);
    } else {
      const previouslyBy = r.completedBy;
      reopenIcReport(b);
      saveBundle(b);
      addActivityLogEntry('System', `IC Report for Case # ${getIcReportCaseLabel(b)} reopened (marked not completed) by ${userName}${previouslyBy ? ` - was completed by ${previouslyBy}` : ''}`);
    }
    renderIcReportForm();
  };
}

// ---------------------------------------------------------------------------
// Incident Times Report
//
// Records, per DAY of the incident, when every roster member went Enroute,
// arrived On Scene, started Returning and Arrived Home, plus the hours spent
// on scene (On Scene -> Returning). It is edited under the "Incident Times"
// button of the Forms page, on the mobile status page (one member at a time)
// and on the Personnel page's Member Reports, printed on its own from the
// Forms page and included, compactly, in the Case # Printout.
//
// The case stores
//   bundle.incidentDays = [ { "<member name>": {enroute, onScene, returning, arrived} }, ... ]
// one object per day, keyed by member name, so two phones marking different
// people at the same moment merge key by key in row-level sync (one change per
// day). A stamp is "MM-DD-YYYY HH:MM". A day has no date of its own: its button
// shows the earliest Enroute date of anyone that day and "Day N" until someone
// is enroute. Files from before this existed kept the times in personnel
// columns 9-12 (one extra roster row per extra "incident set"); those seed
// Day 1, Day 2, ... as bare "HH:MM" stamps when a file has no incidentDays yet.
// ---------------------------------------------------------------------------

const INCIDENT_TIME_FIELDS = [
  {key: 'enroute', label: 'Enroute', legacyIndex: 9},
  {key: 'onScene', label: 'On Scene', legacyIndex: 10},
  {key: 'returning', label: 'Returning', legacyIndex: 11},
  {key: 'arrived', label: 'Arrived Home', legacyIndex: 12}
];

function blankIncidentTimes() {
  return {enroute: '', onScene: '', returning: '', arrived: ''};
}

function normalizeIncidentStamp(value) {
  return (value === undefined || value === null) ? '' : String(value).trim();
}

// One member's four stamps in canonical form; null when all four are blank.
function normalizeIncidentTimesEntry(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null;
  const entry = blankIncidentTimes();
  let any = false;
  INCIDENT_TIME_FIELDS.forEach(field => {
    entry[field.key] = normalizeIncidentStamp(raw[field.key]);
    if (entry[field.key]) any = true;
  });
  return any ? entry : null;
}

// One day: member name -> entry. Blank members and unsafe keys are dropped.
function normalizeIncidentDay(raw) {
  const day = {};
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return day;
  Object.keys(raw).forEach(name => {
    const key = String(name).trim();
    if (!key || key === '__proto__' || key === 'constructor' || key === 'prototype') return;
    const entry = normalizeIncidentTimesEntry(raw[name]);
    if (entry) day[key] = entry;
  });
  return day;
}

// Days seeded from the pre-incidentDays layout: a member's n-th roster row
// carrying times in columns 9-12 becomes that member's entry of day n.
function legacyIncidentDaysFromPersonnel(rows) {
  const days = [];
  const rowsSeen = {};
  (Array.isArray(rows) ? rows : []).forEach(row => {
    if (!Array.isArray(row)) return;
    const name = normalizeIncidentStamp(row[0]);
    if (!name) return;
    const entry = blankIncidentTimes();
    let any = false;
    INCIDENT_TIME_FIELDS.forEach(field => {
      entry[field.key] = normalizeIncidentStamp(row[field.legacyIndex]);
      if (entry[field.key]) any = true;
    });
    if (!any) return;
    const dayIndex = rowsSeen[name] || 0;
    rowsSeen[name] = dayIndex + 1;
    while (days.length <= dayIndex) days.push({});
    days[dayIndex][name] = entry;
  });
  return days;
}

// The canonical incidentDays of a file: always at least one day.
function normalizeIncidentDays(raw, personnelRows) {
  const days = Array.isArray(raw) ? raw.map(normalizeIncidentDay) : legacyIncidentDaysFromPersonnel(personnelRows);
  if (!days.length) days.push({});
  return days;
}

function getIncidentDays(bundle) {
  const b = bundle || loadBundle();
  b.incidentDays = normalizeIncidentDays(b.incidentDays, b.pages && b.pages.page3);
  return b.incidentDays;
}

// "MM-DD-YYYY HH:MM" -> {date, time, ms, minutes}; a bare "HH:MM" has no date
// (ms null) and anything else is kept as typed (time only). null when blank.
function parseIncidentStamp(stamp) {
  const text = normalizeIncidentStamp(stamp);
  if (!text) return null;
  const match = text.match(/^(?:(\d{1,2})-(\d{1,2})-(\d{4})\s+)?(\d{1,2}):(\d{2})$/);
  if (!match) return {date: '', time: text, ms: null, minutes: null};
  const hours = Number(match[4]);
  const mins = Number(match[5]);
  const time = `${String(hours).padStart(2, '0')}:${match[5]}`;
  if (!match[1]) return {date: '', time, ms: null, minutes: hours * 60 + mins};
  const date = `${match[1].padStart(2, '0')}-${match[2].padStart(2, '0')}-${match[3]}`;
  const ms = new Date(Number(match[3]), Number(match[1]) - 1, Number(match[2]), hours, mins).getTime();
  return {date, time, ms: Number.isFinite(ms) ? ms : null, minutes: hours * 60 + mins};
}

function formatIncidentStamp(date, time) {
  return `${normalizeIncidentStamp(date)} ${normalizeIncidentStamp(time)}`.trim();
}

// The earliest Enroute stamp of anyone that day (null when nobody is enroute
// with a date yet).
function getIncidentDayEarliestEnroute(day) {
  let best = null;
  Object.keys(day || {}).forEach(name => {
    const parsed = parseIncidentStamp(day[name] && day[name].enroute);
    if (parsed && parsed.ms !== null && (best === null || parsed.ms < best.ms)) best = parsed;
  });
  return best;
}

// What the day's button says: the earliest Enroute date, else "Day N".
function getIncidentDayLabel(day, index) {
  const earliest = getIncidentDayEarliestEnroute(day);
  return earliest ? earliest.date : `Day ${index + 1}`;
}

// hh:mm from On Scene until Returning; '' while either is missing. Stamps
// without a date are taken to be on the same day (crossing midnight adds 24h).
function getIncidentHoursOnScene(entry) {
  const start = parseIncidentStamp(entry && entry.onScene);
  const end = parseIncidentStamp(entry && entry.returning);
  if (!start || !end) return '';
  let diffMinutes;
  if (start.ms !== null && end.ms !== null) {
    diffMinutes = Math.round((end.ms - start.ms) / 60000);
  } else if (start.minutes !== null && end.minutes !== null) {
    diffMinutes = end.minutes - start.minutes;
    if (diffMinutes < 0) diffMinutes += 24 * 60;
  } else {
    return '';
  }
  if (diffMinutes < 0) return '';
  return `${String(Math.floor(diffMinutes / 60)).padStart(2, '0')}:${String(diffMinutes % 60).padStart(2, '0')}`;
}

// Everyone shown on a day's table: the roster (unique names) plus anyone the
// day already has times for (a member since removed from the roster).
function getIncidentReportNames(bundle, day) {
  const names = new Set();
  ((bundle && bundle.pages && bundle.pages.page3) || []).forEach(row => {
    const name = Array.isArray(row) ? normalizeIncidentStamp(row[0]) : '';
    if (name) names.add(name);
  });
  Object.keys(day || {}).forEach(name => names.add(name));
  return Array.from(names).sort((a, b) => a.localeCompare(b));
}

// The team a member is on per the roster (for the activity log entry).
function getIncidentMemberTeam(bundle, memberName) {
  const row = ((bundle && bundle.pages && bundle.pages.page3) || []).find(r => Array.isArray(r) && normalizeIncidentStamp(r[0]) === memberName);
  const team = row ? normalizeIncidentStamp(row[1]) : '';
  return team || 'System';
}

// Sets (or, with a blank stamp, clears) one time of one member on one day and
// logs it. Returns true when the case changed.
function setIncidentTime(memberName, dayIndex, fieldKey, stamp) {
  const field = INCIDENT_TIME_FIELDS.find(f => f.key === fieldKey);
  const name = normalizeIncidentStamp(memberName);
  if (!field || !name || !Number.isInteger(dayIndex) || dayIndex < 0) return false;
  const b = loadBundle();
  const days = getIncidentDays(b);
  while (days.length <= dayIndex) days.push({});
  const day = days[dayIndex];
  const entry = day[name] ? Object.assign(blankIncidentTimes(), day[name]) : blankIncidentTimes();
  const previous = entry[field.key];
  const next = normalizeIncidentStamp(stamp);
  if (previous === next) return false;
  entry[field.key] = next;
  if (normalizeIncidentTimesEntry(entry)) day[name] = entry; else delete day[name];
  const dayLabel = getIncidentDayLabel(day, dayIndex);
  const dayNote = dayLabel === `Day ${dayIndex + 1}` ? dayLabel : `Day ${dayIndex + 1}, ${dayLabel}`;
  const action = next
    ? `Incident Times: ${name} ${field.label} time set to ${next}${previous ? ` (was ${previous})` : ''} - ${dayNote}`
    : `Incident Times: ${name} ${field.label} time cleared (was ${previous}) - ${dayNote}`;
  addActivityLogEntry(getIncidentMemberTeam(b, name), action, b, name);
  saveBundle(b);
  return true;
}

// Adds the next day and returns its index.
function addIncidentDay() {
  const b = loadBundle();
  const days = getIncidentDays(b);
  days.push({});
  addActivityLogEntry('System', `Incident Times: Day ${days.length} added`, b);
  saveBundle(b);
  return days.length - 1;
}

// The status shown in the All Members table, derived from the incident times:
// the furthest step reached on the member's OLDEST day that has times but no
// Arrived Home yet (a day started while an older one is still open keeps the
// older one driving the status). null when every day of theirs is finished,
// so callers fall back to the raw status field.
function getMemberIncidentStatus(memberName, incidentDays) {
  const name = normalizeIncidentStamp(memberName);
  if (!name || !Array.isArray(incidentDays)) return null;
  for (const day of incidentDays) {
    const entry = day && day[name];
    if (!entry) continue;
    const hasActivity = INCIDENT_TIME_FIELDS.some(field => entry[field.key]);
    if (!hasActivity || entry.arrived) continue;
    if (entry.returning) return 'Returning Home';
    if (entry.onScene) return 'On-Scene';
    if (entry.enroute) return 'Enroute';
    return null;
  }
  return null;
}

// The rows of one member across the days (Member Reports printout).
function getMemberIncidentTimecardRows(bundle, memberName) {
  const name = normalizeIncidentStamp(memberName);
  const rows = [];
  getIncidentDays(bundle).forEach((day, index) => {
    const entry = day[name];
    if (!entry) return;
    rows.push({dayLabel: getIncidentDayLabel(day, index), dayNumber: index + 1, entry, hours: getIncidentHoursOnScene(entry)});
  });
  return rows;
}

// Which day the report is showing (per page load).
let currentIncidentDayIndex = 0;

// The day buttons next to the report title: one per day (its date, or
// "Day N" until someone is enroute) and a "+" that starts the next day.
function renderIncidentDayButtons(container, days, onSelect) {
  container.innerHTML = '';
  container.className = 'incident-day-tabs';
  days.forEach((day, index) => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'mini-pill incident-day-btn' + (index === currentIncidentDayIndex ? ' active' : '');
    btn.textContent = getIncidentDayLabel(day, index);
    btn.title = `Day ${index + 1}`;
    btn.onclick = () => {
      currentIncidentDayIndex = index;
      onSelect();
    };
    container.appendChild(btn);
  });
  const addBtn = document.createElement('button');
  addBtn.type = 'button';
  addBtn.className = 'mini-pill incident-day-add no-print';
  addBtn.textContent = '+';
  addBtn.title = `Add Day ${days.length + 1}`;
  addBtn.setAttribute('aria-label', `Add Day ${days.length + 1}`);
  addBtn.onclick = () => {
    currentIncidentDayIndex = addIncidentDay();
    onSelect();
  };
  container.appendChild(addBtn);
}

// The day buttons live inside the title element when the page has one (Forms
// page "Incident Times Report", mobile "Incident Times"); the element is reused
// across rebuilds and recreated when the title was rewritten.
function ensureIncidentDayTabs(titleEl) {
  let tabs = document.getElementById('incident-day-tabs');
  if (tabs && tabs.parentElement !== titleEl) {
    if (typeof tabs.remove === 'function') tabs.remove();
    tabs = null;
  }
  if (!tabs) {
    tabs = document.createElement('div');
    tabs.id = 'incident-day-tabs';
    titleEl.appendChild(tabs);
  }
  return tabs;
}

// One time cell: the stamp's time (and its date when it is not the day's
// date) or a "+" to enter it. Clicking opens the date/time prompt with a
// "Clear Info" button, exactly as before.
function createIncidentTimeButton(memberName, dayIndex, field, entry, dayDate, rerender) {
  const stamp = entry ? entry[field.key] : '';
  const parsed = parseIncidentStamp(stamp);
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'incident-time-btn' + (parsed ? '' : ' incident-time-empty');
  btn.title = parsed ? `${field.label}: ${stamp}` : `Set ${field.label}`;
  if (parsed) {
    const time = document.createElement('span');
    time.className = 'incident-time-value';
    time.textContent = parsed.time;
    btn.appendChild(time);
    if (parsed.date && parsed.date !== dayDate) {
      const date = document.createElement('span');
      date.className = 'incident-time-date';
      date.textContent = parsed.date;
      btn.appendChild(date);
    }
  } else {
    btn.textContent = '+';
  }
  btn.onclick = () => {
    showTimePrompt(`Set ${field.label} - ${memberName}`, (d, t) => {
      const date = normalizeIncidentStamp(d);
      const time = normalizeIncidentStamp(t);
      if (!time) {
        if (typeof showToast === 'function') showToast('Enter a time (hh:mm) to set it.');
        return;
      }
      setIncidentTime(memberName, dayIndex, field.key, formatIncidentStamp(date, time));
      rerender();
    }, null, parsed ? parsed.time : null, (popup) => {
      if (!parsed) return;
      const btnContainer = popup.querySelector('.popup-buttons');
      const clearBtn = document.createElement('button');
      clearBtn.className = 'popup-btn';
      clearBtn.style.marginRight = 'auto';
      clearBtn.style.color = '#eb5757';
      clearBtn.textContent = 'Clear Info';
      clearBtn.onclick = () => {
        setIncidentTime(memberName, dayIndex, field.key, '');
        popup.remove();
        rerender();
      };
      btnContainer.insertBefore(clearBtn, btnContainer.firstChild);
    }, (parsed && parsed.date) || dayDate || null);
  };
  return btn;
}

// The table of one day: Name | Enroute | On Scene | Returning | Arrived Home |
// Hours On Scene. With `memberName` only that member's row is shown (mobile
// status page, Member Reports) and the Name column is left out.
function renderIncidentDayTable(container, bundle, dayIndex, memberName, rerender) {
  const days = getIncidentDays(bundle);
  const day = days[dayIndex] || {};
  const earliest = getIncidentDayEarliestEnroute(day);
  const dayDate = earliest ? earliest.date : '';
  const names = memberName ? [memberName] : getIncidentReportNames(bundle, day);

  if (!names.length) {
    const empty = document.createElement('div');
    empty.className = 'incident-times-empty';
    empty.textContent = 'No members found in the roster.';
    container.appendChild(empty);
    return;
  }

  const scroll = document.createElement('div');
  scroll.className = 'incident-times-scroll';
  const table = document.createElement('table');
  table.className = 'incident-times-table';
  table.setAttribute('aria-label', `Incident times for Day ${dayIndex + 1}`);

  const thead = document.createElement('thead');
  const headRow = document.createElement('tr');
  const headers = (memberName ? [] : ['Name']).concat(INCIDENT_TIME_FIELDS.map(f => f.label), ['Hours On Scene']);
  headers.forEach(label => {
    const th = document.createElement('th');
    th.textContent = label;
    headRow.appendChild(th);
  });
  thead.appendChild(headRow);
  table.appendChild(thead);

  const tbody = document.createElement('tbody');
  names.forEach(name => {
    const entry = day[name] || null;
    const tr = document.createElement('tr');
    tr.className = 'incident-times-row';
    tr.dataset.member = name;
    if (!memberName) {
      const tdName = document.createElement('td');
      tdName.className = 'incident-times-name';
      tdName.dataset.label = 'Name';
      tdName.textContent = name;
      tr.appendChild(tdName);
    }
    INCIDENT_TIME_FIELDS.forEach(field => {
      const td = document.createElement('td');
      td.dataset.label = field.label;
      td.appendChild(createIncidentTimeButton(name, dayIndex, field, entry, dayDate, rerender));
      tr.appendChild(td);
    });
    const tdHours = document.createElement('td');
    tdHours.className = 'incident-times-hours';
    tdHours.dataset.label = 'Hours On Scene';
    tdHours.textContent = getIncidentHoursOnScene(entry) || '—';
    tr.appendChild(tdHours);
    tbody.appendChild(tr);
  });
  table.appendChild(tbody);
  scroll.appendChild(table);
  container.appendChild(scroll);
}

// Draws the whole report into `container`: the day buttons (inside
// `options.titleEl` when given, else at the top of the container) and the
// open day's table. `options.memberName` limits the table to one member.
function renderIncidentTimesReport(container, options = {}) {
  if (!container) return;
  const memberName = normalizeIncidentStamp(options.memberName) || null;
  const titleEl = options.titleEl || null;
  const bundle = loadBundle();
  const days = getIncidentDays(bundle);
  if (currentIncidentDayIndex >= days.length) currentIncidentDayIndex = days.length - 1;
  if (currentIncidentDayIndex < 0) currentIncidentDayIndex = 0;

  const rerender = () => renderIncidentTimesReport(container, options);
  container.innerHTML = '';
  container.classList.add('incident-times-report');

  const tabs = titleEl ? ensureIncidentDayTabs(titleEl) : document.createElement('div');
  renderIncidentDayButtons(tabs, days, rerender);
  if (!titleEl) container.appendChild(tabs);

  renderIncidentDayTable(container, bundle, currentIncidentDayIndex, memberName, rerender);
}

// One member's view of the report (mobile status page, Member Reports).
function renderMemberIncidentCards(memberName, container, titleEl = null) {
  renderIncidentTimesReport(container, {memberName, titleEl});
}

// Print styles of the report; shared by the Forms page "Print Report" and the
// (compact) block of the Case # Printout.
const INCIDENT_TIMES_PRINT_STYLES = `
        .incident-times-print { margin-bottom: 20px; }
        .incident-times-print-title { font-size: 14pt; border-bottom: 1px solid #333; margin: 20px 0 10px 0; padding-bottom: 2px; }
        .incident-day-print { margin-bottom: 14px; page-break-inside: avoid; }
        .incident-day-print-title { font-size: 11pt; font-weight: 700; margin: 0 0 6px 0; color: #000; }
        .incident-times-print-table { width: 100%; border-collapse: collapse; font-size: 10pt; }
        .incident-times-print-table th, .incident-times-print-table td { border: 1px solid #000; padding: 4px 6px; text-align: center; }
        .incident-times-print-table th { background: #eee !important; -webkit-print-color-adjust: exact; font-size: 8pt; text-transform: uppercase; letter-spacing: 0.5px; }
        .incident-times-print-table td.incident-times-print-name { text-align: left; font-weight: 600; }
        .incident-times-print-table td.incident-times-print-hours { font-weight: 700; }
        .incident-times-print.compact .incident-times-print-table { font-size: 8pt; }
        .incident-times-print.compact .incident-times-print-table th, .incident-times-print.compact .incident-times-print-table td { padding: 2px 4px; }
        .incident-times-print.compact .incident-day-print-title { font-size: 9pt; margin-bottom: 3px; }
        .incident-times-print.compact .incident-day-print { margin-bottom: 8px; }
        .incident-times-print-empty { font-style: italic; color: #888; font-size: 10pt; }
`;

// Static markup of the report for the printouts: one table per day, in the
// new layout. `compact` (Case # Printout) lists only the members with a time
// that day and skips days nobody has times on; the full report lists the
// whole roster so blanks can be filled in by hand.
function getIncidentTimesPrintHTML(bundle, options = {}) {
  const compact = options.compact === true;
  const esc = escapeIcReportHtml;
  const days = getIncidentDays(bundle);
  const blocks = [];
  days.forEach((day, index) => {
    const earliest = getIncidentDayEarliestEnroute(day);
    const dayDate = earliest ? earliest.date : '';
    const names = compact ? Object.keys(day).sort((a, b) => a.localeCompare(b)) : getIncidentReportNames(bundle, day);
    if (!names.length) return;
    const label = getIncidentDayLabel(day, index);
    const title = label === `Day ${index + 1}` ? label : `Day ${index + 1} - ${label}`;
    const rows = names.map(name => {
      const entry = day[name] || blankIncidentTimes();
      const cells = INCIDENT_TIME_FIELDS.map(field => {
        const parsed = parseIncidentStamp(entry[field.key]);
        if (!parsed) return '<td></td>';
        const text = (parsed.date && parsed.date !== dayDate) ? `${parsed.time} (${parsed.date})` : parsed.time;
        return `<td>${esc(text)}</td>`;
      }).join('');
      return `<tr><td class="incident-times-print-name">${esc(name)}</td>${cells}<td class="incident-times-print-hours">${esc(getIncidentHoursOnScene(entry))}</td></tr>`;
    }).join('');
    blocks.push(`
                <div class="incident-day-print">
                    <div class="incident-day-print-title">${esc(title)}</div>
                    <table class="incident-times-print-table">
                        <thead><tr><th>Name</th>${INCIDENT_TIME_FIELDS.map(f => `<th>${esc(f.label)}</th>`).join('')}<th>Hours On Scene</th></tr></thead>
                        <tbody>${rows}</tbody>
                    </table>
                </div>`);
  });
  const body = blocks.length ? blocks.join('') : '<div class="incident-times-print-empty">No incident times have been recorded for this case.</div>';
  return `
            <div class="incident-times-print${compact ? ' compact' : ''}">
                ${compact ? '<h2 class="incident-times-print-title">Incident Times</h2>' : ''}
                ${body}
            </div>`;
}

function defaultBundle() {
  return {
    // A new search file is named after the CASE # it is created for.
    fileName: getActiveCaseNumber() || DEFAULT_FILE_NAME,
    lastModified: new Date(0).toISOString(),
    deleteMode: false,
    theme: 'dark',
    showTips: true,
      segmentColorScaleUsePsriMax: false,
      segmentColorScaleLowColor: '#40c057',
      segmentColorScaleMidColor: '#ffd43b',
      segmentColorScaleHighColor: '#fa5252',
      segmentActiveSearchOpacityPercent: 10,
      segmentActiveSearchFillColor: '#228be6',
      segmentActiveSearchBorderOpacityPercent: 100,
      segmentActiveSearchBorderColor: '#228be6',
      segmentActiveSearchBorderWidth: 3,
    background: 'assets/us-night.jpg',
    activityLog: [],
    currentAssignments: {},
    teamStatuses: {},
    parChecks: {},
    teamLeaveTimes: {},
    teamAssignmentTimes: {},
    parCheckFrequency: 20,
    // CalTopo color push limits: at least every N minutes, never more often
    // than every N seconds (Settings page "CalTopo Color Sync").
    caltopoColorSyncHeartbeatMinutes: CALTOPO_COLOR_SYNC_DEFAULT_HEARTBEAT_MINUTES,
    caltopoColorSyncCooldownSeconds: CALTOPO_COLOR_SYNC_DEFAULT_COOLDOWN_SECONDS,
    dismissedNotifications: [],
    arrivedTeams: [],
    forms: {},
    uploads: [],
    maps: [],
    // CalTopo shapes the team decided not to import (hidden from the "only new"
    // and unaccounted views) and whether the 5-minute unaccounted check runs.
    unwantedMapFeatures: [],
    mapUnaccountedAutoCheck: true,
    // Which feature types (markers / shapes / assignments / routes / other)
    // the team wants to hear about; a type switched off is marked unwanted
    // automatically. Missing = on.
    mapFeatureTypeFilters: {marker: true, shape: true, assignment: true, route: true, other: true},
    // Search Log page "Map Tracking": off until switched on, no searcher tracks
    // imported from the map yet (see the Searchers Tracks section).
    mapTrackingEnabled: false,
    searcherTracks: [],
    permanentPersonnel: {},
    // The one IC Report of this CASE # (Forms page, "IC Report" button).
    icReport: defaultIcReport(),
    // Incident Times Report: one (empty) day to start with.
    incidentDays: [{}],
    // Incident page "Lost Person Behavior": no category on, no IPP yet, and the
    // PSR adjustment applied as soon as both exist.
    lostPersonBehavior: normalizeLostPersonBehavior(null),
    accounts: [
      { username: 'Super Admin', pin: '1976', color: 'none', handle: 'Super-Admin', isFileManager: true, theme: 'dark', visiblePages: ['index', 'page2', 'page3', 'page4', 'page5', 'page6', 'page7', 'settings', 'home', 'page8', 'page9', 'page10'] }
    ],
    profile: {
      incidentNumber: '',
      lostPersonName: '',
      lostPersonAge: '',
      lostPersonGender: '',
      lostPersonDescription: '',
      lostPersonClothing: '',
      lostPersonPhysical: ''
    },
    pages: {
      index: defaultRegionsData(),
      page2: defaultSegmentsData(),
      page3: defaultPersonnelData(),
      page4: defaultSearchLogData(),
      page5: defaultData(),
      page6: defaultData(),
      page7: defaultData()
    }
  };
}

function sanitizeStandardData(parsed) {
  if (!Array.isArray(parsed) || parsed.length === 0) return defaultData();
  return parsed.map(row =>
    Array.from({ length: COLS }, (_, c) => (row?.[c] ?? '').toString())
  );
}

function sanitizeRegionsData(parsed) {
  const fallback = defaultRegionsData();
  if (!parsed || typeof parsed !== 'object') return fallback;

  const headers = Array.isArray(parsed.headers) ? parsed.headers.slice() : fallback.headers.slice();
  const rawRows = Array.isArray(parsed.rows) ? parsed.rows : fallback.rows;
  const rowCount = Math.max(1, rawRows.length);
  const dynamicCount = Math.max(1, headers.length - 2 || (typeof DEFAULT_DYNAMIC_COLS !== 'undefined' ? DEFAULT_DYNAMIC_COLS : 3));

  const safeHeaders = ['Region'];
  for (let i = 0; i < dynamicCount; i++) {
    safeHeaders.push((headers[i + 1] ?? `Voter ${i + 1}`).toString());
  }
  safeHeaders.push('Consensus');

  const safeRows = Array.from({ length: rowCount }, (_, rowIndex) => {
    const sourceRow = Array.isArray(rawRows[rowIndex]) ? rawRows[rowIndex] : [];
    // Ensure row has enough columns (Region + dynamicCount + Consensus)
    return Array.from({ length: dynamicCount + 2 }, (_, colIndex) => (sourceRow[colIndex] ?? '').toString());
  });

  const voterVisibility = Array.isArray(parsed.voterVisibility) 
    ? parsed.voterVisibility.slice(0, dynamicCount) 
    : Array.from({ length: dynamicCount }, () => false);
  
  while (voterVisibility.length < dynamicCount) {
    voterVisibility.push(false);
  }

  return { headers: safeHeaders, rows: safeRows, voterVisibility };
}

function sanitizeSegmentsData(parsed) {
  if (!Array.isArray(parsed) || parsed.length === 0) return defaultSegmentsData();
  return parsed.map(row => {
    const sourceLen = row.length;
    const targetRow = Array.from({ length: 10 }, (_, c) => (row?.[c] ?? '').toString());
    if (sourceLen === 7) {
       // Old index 6 was PSR. Now it's PSRi and we initialize PSRc with it.
       targetRow[7] = targetRow[6];
    }
    return targetRow;
  });
}

function sanitizePersonnelData(parsed) {
  if (!Array.isArray(parsed) || parsed.length === 0) return defaultPersonnelData();
  return parsed.map(row => {
    // Ensure we have at least 14 columns to include incident times (9, 10, 11, 12) and JSON history (13)
    const r = Array.from({ length: Math.max(14, row?.length || 0) }, (_, c) => (row?.[c] ?? '').toString());
    return r;
  });
}

function sanitizeSearchLogData(parsed) {
  if (!Array.isArray(parsed) || parsed.length === 0) return defaultSearchLogData();
  return parsed.map(row =>
    Array.from({ length: 10 }, (_, c) => (row?.[c] ?? '').toString())
  );
}

function sanitizeBundle(bundle) {
  const fallback = defaultBundle();
  if (!bundle || typeof bundle !== 'object') return fallback;

  const fileName = typeof bundle.fileName === 'string' && bundle.fileName.trim()
    ? bundle.fileName.trim()
    : (getActiveCaseNumber() || DEFAULT_FILE_NAME);

  const deleteMode = typeof bundle.deleteMode === 'boolean' ? bundle.deleteMode : false;
  const background = typeof bundle.background === 'string' && bundle.background.trim()
    ? bundle.background.trim()
    : 'assets/us-night.jpg';
  const logo = typeof bundle.logo === 'string' ? bundle.logo.trim() : '';

  const activityLog = Array.isArray(bundle.activityLog) ? bundle.activityLog : [];
  const currentAssignments = (bundle.currentAssignments && typeof bundle.currentAssignments === 'object')
    ? bundle.currentAssignments
    : {};

  const teamStatuses = (bundle.teamStatuses && typeof bundle.teamStatuses === 'object')
    ? bundle.teamStatuses
    : {};

  const parChecks = (bundle.parChecks && typeof bundle.parChecks === 'object')
    ? bundle.parChecks
    : {};

  const teamLeaveTimes = (bundle.teamLeaveTimes && typeof bundle.teamLeaveTimes === 'object')
    ? bundle.teamLeaveTimes
    : {};

  const teamAssignmentTimes = (bundle.teamAssignmentTimes && typeof bundle.teamAssignmentTimes === 'object')
    ? bundle.teamAssignmentTimes
    : {};

  const arrivedTeams = Array.isArray(bundle.arrivedTeams) ? bundle.arrivedTeams : [];
  const dismissedNotifications = Array.isArray(bundle.dismissedNotifications) ? bundle.dismissedNotifications : [];

  // The GPS / Radio / Medic flags of every member live here (see
  // splitPersonnelData). This key used to be dropped by the sanitizer, which
  // silently threw those three toggles away on every save, so it must be kept.
  const permanentPersonnel = (bundle.permanentPersonnel && typeof bundle.permanentPersonnel === 'object' && !Array.isArray(bundle.permanentPersonnel))
    ? bundle.permanentPersonnel
    : {};

  const pages = {};
  for (const page of PAGE_DEFS) {
    const rawPage = bundle.pages?.[page.key];
    if (page.key === 'index') {
      pages[page.key] = sanitizeRegionsData(rawPage);
    } else if (page.key === 'page2') {
      pages[page.key] = sanitizeSegmentsData(rawPage);
    } else if (page.key === 'page3') {
      pages[page.key] = sanitizePersonnelData(rawPage);
    } else if (page.key === 'page4') {
      pages[page.key] = sanitizeSearchLogData(rawPage);
    } else {
      pages[page.key] = sanitizeStandardData(rawPage);
    }
  }

  // Ensure all teams in Personnel (page3) have a status of "at base" if not already set
  const personnelData = pages.page3 || [];
  personnelData.forEach(row => {
    const team = (row[1] || '').trim();
    const onScene = isActiveMemberStatus(row[6]);
    if (team && onScene && !teamStatuses[team]) {
        const now = new Date();
        const timeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
        teamStatuses[team] = `at base (${timeStr})`;
    }
  });

  const parCheckFrequency = (bundle.parCheckFrequency !== undefined) ? bundle.parCheckFrequency : 20;
  const showTips = (bundle.showTips !== undefined) ? bundle.showTips : true;

  // Preserve the segment color-scale / active-search opacity display settings.
  // Normalize them through the shared helper so saved values stay valid.
  const segmentDisplaySettings = getSegmentDisplaySettings(bundle);
  const segmentColorScaleUsePsriMax = segmentDisplaySettings.usePsriMax;
  const segmentColorScaleLowColor = segmentDisplaySettings.lowColor;
  const segmentColorScaleMidColor = segmentDisplaySettings.midColor;
  const segmentColorScaleHighColor = segmentDisplaySettings.highColor;
  const segmentActiveSearchOpacityPercent = segmentDisplaySettings.activeSearchOpacityPercent;
  const segmentActiveSearchFillColor = segmentDisplaySettings.activeSearchFillColor;
  const segmentActiveSearchBorderOpacityPercent = segmentDisplaySettings.activeSearchBorderOpacityPercent;
  const segmentActiveSearchBorderColor = segmentDisplaySettings.activeSearchBorderColor;
  const segmentActiveSearchBorderWidth = segmentDisplaySettings.activeSearchBorderWidth;
  // CalTopo color push limits, normalised (>= 1, cooldown never above the
  // heartbeat) so every device schedules the same way.
  const caltopoColorSyncSettings = getCalTopoColorSyncSettings(bundle);
  const caltopoColorSyncHeartbeatMinutes = caltopoColorSyncSettings.heartbeatMinutes;
  const caltopoColorSyncCooldownSeconds = caltopoColorSyncSettings.cooldownSeconds;
  const theme = bundle.theme || 'dark';
  const lastModified = bundle.lastModified || new Date().toISOString();
  const forms = bundle.forms || {};
  const profile = bundle.profile || fallback.profile;
  const uploads = Array.isArray(bundle.uploads) ? bundle.uploads : [];
  const maps = Array.isArray(bundle.maps) ? bundle.maps : [];
  const unwantedMapFeatures = getUnwantedMapFeatures(bundle);
  const mapUnaccountedAutoCheck = bundle.mapUnaccountedAutoCheck !== false;
  const mapFeatureTypeFilters = getMapFeatureTypeFilters(bundle);
  const icReport = sanitizeIcReport(bundle.icReport);
  // The Incident Times Report's days; a file that predates it is seeded from
  // the times its personnel rows carried in columns 9-12.
  const incidentDays = normalizeIncidentDays(bundle.incidentDays, pages.page3);
  // The Incident page's Lost Person Behavior settings (category switches,
  // terrain, the case's four distances per category, the imported IPP and the
  // Segments page's apply switch). Kept in canonical form so two devices never
  // disagree about the shape they diff.
  const lostPersonBehavior = normalizeLostPersonBehavior(bundle.lostPersonBehavior);
  // The Search Log page's Map Tracking switch and the searcher tracks imported
  // from the CalTopo map with their measured miles per segment (canonical, so
  // every device allocates the same miles to the same tasks).
  const mapTrackingEnabled = bundle.mapTrackingEnabled === true;
  const searcherTracks = normalizeSearcherTracks(bundle.searcherTracks);

  let accounts = Array.isArray(bundle.accounts) ? bundle.accounts : fallback.accounts;

  // 1. Ensure only one Super Admin exists
  const superAdmin = accounts.find(a => a.pin === '1976') || fallback.accounts[0];
  superAdmin.username = 'Super Admin';
  superAdmin.handle = 'Super-Admin';
  superAdmin.pin = '1976';
  
  if (superAdmin.visiblePages && !superAdmin.visiblePages.includes('page10')) {
    superAdmin.visiblePages.push('page10');
  }

  // 2. Filter out any other accounts that might be pretending to be super admin
  accounts = accounts.filter(a => a.pin !== '1976');
  
  // 3. Sync with Personnel (page3)
  const personnel = pages.page3 || [];

  const syncedAccounts = [];
  syncedAccounts.push(superAdmin);

  // Helper to find next available PIN starting from 1400
  const getNextPin = (currentSynced) => {
    let next = 1400;
    while (currentSynced.some(a => a.pin === next.toString())) {
      next++;
    }
    return next.toString();
  };

  personnel.forEach(row => {
    const name = (row[0] || '').trim();
    if (!name) return;

    // Try to find by PIN link first (column 8)
    const rowPin = (row[8] || '').trim();
    let existing = null;
    
    if (rowPin) {
        existing = accounts.find(a => a.pin === rowPin);
    }

    // Fallback to name match
    if (!existing) {
        existing = accounts.find(a => a.handle === name || (a.username || '').trim() === name);
    }

    if (existing) {
      // Update account name from Personnel list (Personnel is source of truth for name unless changed via User Account page which also updates Personnel)
      existing.username = name;
      existing.handle = name;
      
      // Ensure PIN link is established in Personnel list
      row[8] = existing.pin;
      
      syncedAccounts.push(existing);
      // Remove from accounts to avoid double-processing
      accounts = accounts.filter(a => a !== existing);
    } else {
      // Create new account
      const newPin = rowPin || getNextPin(syncedAccounts);
      const newAcc = {
        username: name,
        pin: newPin,
        color: 'none',
        handle: name,
        isFileManager: false,
        theme: 'dark',
        visiblePages: ['index', 'page2', 'page3', 'page4', 'page5', 'page6', 'page7', 'settings', 'home', 'page8', 'page10']
      };
      syncedAccounts.push(newAcc);
      row[8] = newPin; // Establish link
    }
  });

  // Also keep any other accounts that are Admins or were not matched (to prevent accidental loss)
  // This prevents accidental loss of the currently logged-in user or admins not yet in Personnel list
  const currentU = getCurrentUser();
  accounts.forEach(a => {
      const isAlreadySynced = syncedAccounts.some(sa => sa.pin === a.pin);
      const isCurrUser = currentU && a.pin === currentU.pin;
      const isAdmin = isUserAdmin(a) || a.isFileManager;

      if (!isAlreadySynced && (isAdmin || isCurrUser)) {
          syncedAccounts.push(a);
      }
  });

  return { 
    fileName, 
    lastModified,
    deleteMode, 
    theme, 
    background, 
    logo, 
    activityLog, 
    currentAssignments, 
    teamStatuses, 
    parChecks, 
    teamLeaveTimes, 
    teamAssignmentTimes, 
    arrivedTeams, 
    dismissedNotifications,
    parCheckFrequency, 
    showTips, 
    segmentColorScaleUsePsriMax,
    segmentColorScaleLowColor,
    segmentColorScaleMidColor,
    segmentColorScaleHighColor,
    segmentActiveSearchOpacityPercent,
    segmentActiveSearchFillColor,
    segmentActiveSearchBorderOpacityPercent,
    segmentActiveSearchBorderColor,
    segmentActiveSearchBorderWidth,
    caltopoColorSyncHeartbeatMinutes,
    caltopoColorSyncCooldownSeconds,
    pages, 
    forms, 
    profile, 
    uploads, 
    maps,
    unwantedMapFeatures,
    mapUnaccountedAutoCheck,
    mapFeatureTypeFilters,
    permanentPersonnel,
    icReport,
    incidentDays,
    lostPersonBehavior,
    mapTrackingEnabled,
    searcherTracks,
    accounts: syncedAccounts 
  };
}

function loadBundle() {
  try {
    const raw = getStorageItem(BUNDLE_STORAGE_KEY);
    if (!raw) return defaultBundle();
    const bundle = sanitizeBundle(JSON.parse(raw));
    rememberActivityLogVersion(bundle);
    return bundle;
  } catch {
    return defaultBundle();
  }
}

// ----------------------------------------------------------------------------
// Activity log entries must never be lost by a stale save.
//
// Many handlers load the search file, change it and save it a moment later.
// If something else is saved in between - addActivityLogEntry() writing an
// entry on its own, another handler, a server poll bringing another device's
// entries - the handler's copy no longer has those entries, and saving it
// would erase them again: locally, and (as a "deleted" row) on the server, so
// they never reached the database. promoteToTeamLead() did exactly that with
// its own "reassigned" entry.
//
// loadBundle() therefore remembers, per stored version (lastModified), which
// entry ids that version held. When a save comes from an older version than
// the one in storage, every entry the stored copy has that the saved copy
// lacks is put back - unless the caller's version already had it, in which
// case the caller removed it on purpose (deleting a task, a timecard, ...).
// ----------------------------------------------------------------------------
// version (lastModified) -> Set of entry keys. Created on first use so that
// loadBundle() may run before this part of the file has been evaluated.
function getActivityLogVersionRegistry() {
  if (!getActivityLogVersionRegistry.map) getActivityLogVersionRegistry.map = new Map();
  return getActivityLogVersionRegistry.map;
}

function activityLogEntryKey(entry) {
  if (!entry || typeof entry !== 'object') return '';
  if (entry.id !== undefined && entry.id !== null && String(entry.id).trim()) return String(entry.id).trim();
  return `${entry.timestamp || ''}|${entry.date || ''}|${entry.time || ''}|${entry.team || ''}|${entry.action || ''}`;
}

function rememberActivityLogVersion(bundle) {
  const version = bundle && typeof bundle.lastModified === 'string' ? bundle.lastModified : '';
  const registry = getActivityLogVersionRegistry();
  if (!version || registry.has(version)) return;
  registry.set(version, new Set((bundle.activityLog || []).map(activityLogEntryKey).filter(Boolean)));
  // Only the most recent versions matter: a handler saves within moments of loading.
  while (registry.size > 16) {
    registry.delete(registry.keys().next().value);
  }
}

// The version stamp (lastModified) for the copy about to be stored: now, but
// always later than the copy it replaces, so two saves never share a stamp and
// a handler can always tell whether the stored copy moved on since it loaded.
function nextLocalVersionStamp(previous) {
  const stamp = new Date().toISOString();
  const previousStamp = previous && typeof previous.lastModified === 'string' ? previous.lastModified : '';
  if (!previousStamp || stamp > previousStamp) return stamp;
  const previousMs = new Date(previousStamp).getTime();
  return Number.isFinite(previousMs) ? new Date(previousMs + 1).toISOString() : stamp;
}

// What saveBundle does to a copy before storing it: put back the activity-log
// entries that were logged since the copy was loaded (see above), then give it
// the next version stamp. `previous` is the copy in storage right now.
function stampBundleForSave(bundle, previous) {
  restoreActivityLogEntriesAddedMeanwhile(bundle, previous, bundle.lastModified);
  bundle.lastModified = nextLocalVersionStamp(previous);
}

// Puts the entries that were added to the stored copy after `bundle` was loaded
// back into `bundle` (see above). `loadedVersion` is the lastModified `bundle`
// carried when it was loaded, `stored` the copy in storage right now. Returns
// how many entries were restored.
function restoreActivityLogEntriesAddedMeanwhile(bundle, stored, loadedVersion) {
  if (!bundle || !stored || !Array.isArray(stored.activityLog) || !stored.activityLog.length) return 0;
  if (typeof loadedVersion !== 'string' || !loadedVersion || stored.lastModified === loadedVersion) return 0;
  const base = getActivityLogVersionRegistry().get(loadedVersion);
  if (!base) return 0;
  if (!Array.isArray(bundle.activityLog)) bundle.activityLog = [];
  const present = new Set(bundle.activityLog.map(activityLogEntryKey));
  let restored = 0;
  stored.activityLog.forEach((entry, index) => {
    const key = activityLogEntryKey(entry);
    if (!key || present.has(key) || base.has(key)) return;
    // Keep the entry where the stored copy had it (the log is newest-first).
    bundle.activityLog.splice(Math.min(index, bundle.activityLog.length), 0, JSON.parse(JSON.stringify(entry)));
    present.add(key);
    restored++;
  });
  return restored;
}

// ----------------------------------------------------------------------------
// Sync outbox
//
// Every save is diffed against the copy that was on this device just before it
// (SARSyncDelta.computeBundleChanges) and only the rows that differ are queued
// here, under "<CASE #>::<file name>", until the server confirms them. The
// queue lives in memory for as long as the page is open (nothing is stored on
// the device); a dropped connection is retried by the next save or poll, and a
// batch keeps its id across retries so the server can recognise one it already
// applied.
// ----------------------------------------------------------------------------

function getSyncDeltaUtils() {
    return (typeof window !== 'undefined' && window.SARSyncDelta) ? window.SARSyncDelta : null;
}

function outboxKeyFor(bundle) {
    return `${getSyncBucket()}::${(bundle && bundle.fileName) || ''}`;
}

function readOutboxStore() {
    try {
        const raw = getStorageItem(SYNC_OUTBOX_STORAGE_KEY);
        const parsed = raw ? JSON.parse(raw) : null;
        return (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) ? parsed : {};
    } catch (e) {
        return {};
    }
}

function writeOutboxStore(store) {
    try {
        setStorageItem(SYNC_OUTBOX_STORAGE_KEY, JSON.stringify(store));
    } catch (e) {}
}

function normalizeOutboxRecord(record) {
    const raw = (record && typeof record === 'object') ? record : {};
    const inFlight = (raw.inFlight && typeof raw.inFlight.batchId === 'string' && raw.inFlight.batchId)
        ? {batchId: raw.inFlight.batchId, count: Math.max(0, Number(raw.inFlight.count) || 0)}
        : null;
    return {
        // Server lastModified this device has caught up to (advanced by /state only).
        cursor: typeof raw.cursor === 'string' ? raw.cursor : '',
        // Row changes waiting for the server, oldest first.
        changes: Array.isArray(raw.changes) ? raw.changes : [],
        // The batch currently being sent (or sent without an answer): the first
        // `count` changes travel again under the same id until confirmed.
        inFlight,
        // The next upload must be the whole file (nothing to diff against).
        needsFullUpload: raw.needsFullUpload === true
    };
}

function readOutboxRecord(bundle) {
    return normalizeOutboxRecord(readOutboxStore()[outboxKeyFor(bundle)]);
}

function writeOutboxRecord(bundle, record) {
    const store = readOutboxStore();
    store[outboxKeyFor(bundle)] = normalizeOutboxRecord(record);
    writeOutboxStore(store);
}

// Forget every queued row of a CASE # (used when the case itself is deleted).
function removeOutboxRecordsForBucket(bucket) {
    if (!bucket) return;
    const store = readOutboxStore();
    const prefix = `${bucket}::`;
    let changed = false;
    Object.keys(store).forEach((key) => {
        if (key.indexOf(prefix) === 0) {
            delete store[key];
            changed = true;
        }
    });
    if (changed) writeOutboxStore(store);
}

// Queue the rows that differ between the copy this device had and the copy it
// just saved. Without a previous copy of the same file (first save on this
// device, or a switch to another file) there is nothing to diff against, so
// the next upload sends the whole file instead.
function queueBundleChanges(previousBundle, nextBundle) {
    const record = readOutboxRecord(nextBundle);
    const utils = getSyncDeltaUtils();
    if (!utils || !previousBundle || previousBundle.fileName !== nextBundle.fileName) {
        record.needsFullUpload = true;
        record.changes = [];
        record.inFlight = null;
        writeOutboxRecord(nextBundle, record);
        return record;
    }
    if (record.needsFullUpload) {
        // The pending whole-file upload will carry this save as well.
        return record;
    }
    const changes = utils.computeBundleChanges(previousBundle, nextBundle);
    if (!changes.length) return record;

    // Changes that belong to a batch already sent must not be touched (a
    // retry has to repeat that batch exactly), so only the ones behind it
    // are coalesced with the new edits.
    const locked = record.inFlight ? record.inFlight.count : 0;
    let open = record.changes.slice(locked);
    changes.forEach((change) => {
        open = utils.coalesceChange(open, change);
    });
    record.changes = record.changes.slice(0, locked).concat(open);
    writeOutboxRecord(nextBundle, record);
    return record;
}

// The server answered a row batch: those changes are delivered.
function confirmOutboxBatch(bundle, batchId) {
    const record = readOutboxRecord(bundle);
    if (!record.inFlight || record.inFlight.batchId !== batchId) return;
    record.changes = record.changes.slice(record.inFlight.count);
    record.inFlight = null;
    writeOutboxRecord(bundle, record);
}

// A whole-file upload landed: everything queued before it started is covered
// by it. Rows queued while it was travelling stay for the next row batch.
function settleOutboxAfterFullUpload(bundle, queuedAtStart) {
    const record = readOutboxRecord(bundle);
    record.needsFullUpload = false;
    record.inFlight = null;
    record.changes = record.changes.slice(Math.min(queuedAtStart, record.changes.length));
    writeOutboxRecord(bundle, record);
}

function createBatchId() {
    if (typeof crypto !== 'undefined' && crypto && typeof crypto.randomUUID === 'function') {
        return crypto.randomUUID();
    }
    return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 12)}`;
}

// Remember which CASE # the in-memory search file belongs to.
function tagLocalBundleBucket() {
    const bucket = getSyncBucket();
    if (bucket) {
        setStorageItem(BUNDLE_BUCKET_STORAGE_KEY, bucket);
    } else {
        removeStorageItem(BUNDLE_BUCKET_STORAGE_KEY);
    }
}

// A search file in memory that belongs to another CASE # must never be shown
// here, let alone uploaded into this case: drop it so the case is read from
// the database instead. Returns true when dropped.
function discardForeignLocalCopy() {
    const bucket = getSyncBucket();
    const tag = getStorageItem(BUNDLE_BUCKET_STORAGE_KEY);
    if (!bucket || !getStorageItem(BUNDLE_STORAGE_KEY) || tag === bucket) return false;
    removeStorageItem(BUNDLE_STORAGE_KEY);
    removeStorageItem(BUNDLE_BUCKET_STORAGE_KEY);
    return true;
}

// Browsers refuse a keepalive request whose body is over 64 KiB - the upload
// then fails with "Failed to fetch" and nothing reaches the server. Only a
// body safely under that limit may ask to outlive the page.
const KEEPALIVE_MAX_BODY_BYTES = 60000;

function utf8ByteLength(text) {
    let bytes = 0;
    for (let i = 0; i < text.length; i++) {
        const code = text.charCodeAt(i);
        if (code < 0x80) bytes += 1;
        else if (code < 0x800) bytes += 2;
        else if (code >= 0xd800 && code <= 0xdbff) { bytes += 4; i++; }
        else bytes += 3;
    }
    return bytes;
}

function fetchInitWithKeepalive(body, init = {}) {
    const out = {...init, body};
    if (typeof body === 'string' && body.length < KEEPALIVE_MAX_BODY_BYTES
        && utf8ByteLength(body) < KEEPALIVE_MAX_BODY_BYTES) {
        out.keepalive = true;
    }
    return out;
}


// The parts of the search file that decide how the CalTopo assignment overlay
// draws a segment (active-search vs resting style) and what the finished-task
// summary in its description says: team statuses/assignments, the Task
// Assignment forms' completion, team name and personnel, and the activity-log
// "Finished assignment" reports that stamp the finish time.
function buildSearchActivitySignature(bundle) {
  const forms = bundle?.forms || {};
  return JSON.stringify({
    statuses: bundle?.teamStatuses || {},
    assignments: bundle?.currentAssignments || {},
    forms: Object.keys(forms).map(num => {
      const form = forms[num] || {};
      const members = Array.isArray(form.teamMembers) ? form.teamMembers : [];
      return [num, !!form.completed, form.teamName || '', form.completeSearch || '',
        members.map(m => `${m?.name || ''}${m?.leader ? '*' : ''}`).join('|')];
    }),
    finished: (bundle?.activityLog || [])
      .filter(entry => String(entry?.action || '').toLowerCase().includes('finished assignment'))
      .map(entry => `${entry.tag}|${entry.date}|${entry.time}`)
  });
}

function didSearchActivityChange(previous, next) {
  if (!previous || !next) return false;
  try {
    return buildSearchActivitySignature(previous) !== buildSearchActivitySignature(next);
  } catch (e) {
    return false;
  }
}

// Keep the search file in memory, queue the rows that changed and (unless the
// caller flushes later itself) send them to the database. Returns the flush
// promise so callers that reload or wait can await the write.
//
// A team reporting "Finished Assignment" (or any other status / assignment /
// task-form change, see buildSearchActivitySignature) must reach CalTopo too:
// the segment goes back to its resting style and border thickness and its
// description gets the task's summary. That refresh is debounced and silent,
// and a no-op unless the assignment overlay is enabled.
//
// The users belong to the login: what this save says about the case's accounts
// goes to the login's list too (syncLoginUsersFromBundle, on the sanitized copy
// so a PIN the list has to re-link is what gets stored).
function saveBundle(bundle, deferFlush = false) {
  const previous = getStorageItem(BUNDLE_STORAGE_KEY) ? loadBundle() : null;
  stampBundleForSave(bundle, previous);
  const sanitized = sanitizeBundle(bundle);
  try { syncLoginUsersFromBundle(sanitized); } catch (e) { console.warn('[USERS]', e); }
  queueBundleChanges(previous, sanitized);
  setStorageItem(BUNDLE_STORAGE_KEY, JSON.stringify(sanitized));
  tagLocalBundleBucket();
  updateFileNameDisplay();
  const flush = deferFlush ? Promise.resolve(false) : pushBundleDelta(sanitized);
  if (didSearchActivityChange(previous, sanitized)) refreshCalTopoAssignmentOverlayIfEnabled();
  return flush;
}

// The Saved Cases table is the server's list of this login's cases
// (/api/auth/history); no copy of any case is kept on the device. These stay
// as the (empty) local view of that list for the callers that still ask.
function getSavedFiles() {
    return {};
}

function saveFileToList() {}

function deleteFileFromList(fileName) {
    logDeletion('File', fileName);
}

// Import a case (.json) file exported from the Saved Cases table.
//
// The whole file goes to the server in ONE request (PUT .../bundle?import=1) as
// this login's copy of the CASE #: the bucket is "<CASE #>_<username>" (see
// getSyncBucket / caseNumberToBucket) and the server rewrites the structured
// tables for (username, CASE #) from it before answering. Nothing is diffed or
// merged with the case that happens to be open, and the file is authoritative
// over any copy the server already holds, so a re-import restores every row of
// a backup. Only once the server confirmed the import does this device switch
// to the case: the local copy is then exactly the server's, so nothing is
// queued and the poll cursor is current. Resolves to the clean CASE #; throws
// with a user-facing message when nothing was imported (nothing changes then).
async function importCaseFromJson(text) {
    let imported;
    try {
        imported = JSON.parse(text);
    } catch (e) {
        throw new Error('This file is not a valid JSON case file.');
    }
    if (!imported || typeof imported !== 'object' || Array.isArray(imported)
        || !imported.pages || typeof imported.pages !== 'object'
        || typeof imported.fileName !== 'string' || !imported.fileName.trim()) {
        throw new Error('Invalid case file format. Missing pages or case number.');
    }

    // The CASE # is the file name carried inside the case, minus any ".json"
    // suffix; the bucket id is that CASE # in URL-safe form (same rule as the
    // case-number popup), and the login is appended by caseNumberToBucket().
    const caseNumber = imported.fileName.trim().replace(/\.json$/i, '');
    const bucketId = caseNumber.replace(/[^a-zA-Z0-9_-]/g, '_');
    if (!bucketId) throw new Error('The case file has no usable case number.');
    const bucket = caseNumberToBucket(bucketId);

    const serverUrl = getSyncServerUrl();
    if (!serverUrl || !getUserCredentials()) {
        throw new Error('Log in and connect to the sync server before importing a case.');
    }

    const bundle = sanitizeBundle({...imported, fileName: caseNumber});
    // Bookkeeping of the server the file came from; ours stamps it afresh.
    delete bundle._sectionUpdatedAt;
    logCreation('Imported Case #', caseNumber, bundle);
    bundle.lastModified = new Date().toISOString();

    let resp;
    try {
        resp = await apiFetch(`${serverUrl.replace(/\/$/, '')}/api/v1/${bucket}/bundle?import=1`, {
            method: 'PUT',
            headers: getAuthHeaders(),
            body: JSON.stringify(bundle)
        });
    } catch (e) {
        throw new Error('Could not reach the server to import this case. Please try again when online.');
    }
    if (!resp.ok) {
        let message = `The server refused the import (HTTP ${resp.status}).`;
        try {
            const body = await resp.json();
            if (body && (body.message || body.error)) message = body.message || body.error;
        } catch (e) {}
        throw new Error(message);
    }
    const result = await resp.json().catch(() => ({}));
    if (result && typeof result.lastModified === 'string' && result.lastModified) {
        bundle.lastModified = result.lastModified;
    }

    // The server holds the whole case: make it the active case on this device.
    await setSyncBucket(bucketId);
    removeOutboxRecordsForBucket(getSyncBucket());
    setStorageItem(BUNDLE_STORAGE_KEY, JSON.stringify(bundle));
    tagLocalBundleBucket();
    writeOutboxRecord(bundle, {cursor: bundle.lastModified, changes: [], inFlight: null, needsFullUpload: false});
    updateFileNameDisplay();
    return caseNumber;
}

// Read another case's search file straight from the database (the Saved Cases
// table's Export and Edit work on cases that are not open). Resolves to the
// sanitized file, or null when the server has none for this login and CASE #.
// Throws with a user-facing message when the server cannot be reached.
async function fetchCaseFromServer(caseNumber) {
    const clean = String(caseNumber || '').replace(/\.json$/i, '');
    const serverUrl = getSyncServerUrl();
    if (!clean || !serverUrl || !getUserCredentials()) {
        throw new Error('Log in and connect to the sync server first.');
    }
    const bucket = caseNumberToBucket(clean);
    let resp;
    try {
        resp = await apiFetch(`${serverUrl.replace(/\/$/, '')}/api/v1/${bucket}/bundle?_=${Date.now()}`, {
            headers: getAuthHeaders()
        });
    } catch (e) {
        throw new Error('Could not reach the server. Please try again when online.');
    }
    if (resp.status === 404) return null;
    if (!resp.ok) throw new Error(`The server refused the request (HTTP ${resp.status}).`);
    const body = await resp.json().catch(() => null);
    if (!body || typeof body !== 'object' || Array.isArray(body) || !body.pages) return null;
    return sanitizeBundle({...body, fileName: clean});
}

// Rename a case on the server: its search file is stored again under the new
// CASE # (the server rewrites the structured tables from it), then every row
// of the old CASE # is deleted. If the renamed case is the open one, this
// device switches to the new CASE #. Resolves to true when renamed; alerts and
// resolves to false otherwise, leaving the old case untouched.
async function renameCaseOnServer(oldCaseNumber, newCaseNumber) {
    const oldClean = String(oldCaseNumber || '').replace(/\.json$/i, '');
    // The CASE # is kept in the same URL-safe form the New-case popup uses, so
    // the file name, the bucket and the Saved Cases row all read the same.
    const newClean = String(newCaseNumber || '').replace(/\.json$/i, '').trim().replace(/[^a-zA-Z0-9_-]/g, '_');
    const newBucketId = newClean;
    if (!oldClean || !newClean || isInternalCaseName(newClean)) {
        if (newClean && isInternalCaseName(newClean)) alert(`"${newClean}" is reserved and cannot be used as a case number.`);
        return false;
    }
    if (oldClean === newClean) return true;

    let bundle;
    try {
        bundle = await fetchCaseFromServer(oldClean);
    } catch (e) {
        alert(e.message);
        return false;
    }
    if (!bundle) {
        alert(`The server has no search file for "${oldClean}", so it cannot be renamed. You can still delete it.`);
        return false;
    }

    const wasActive = getActiveCaseNumber() === oldClean;
    // A rename of the open case must carry this device's latest rows.
    if (wasActive) {
        const active = loadBundle();
        if (String(active.fileName || '').replace(/\.json$/i, '') === oldClean) bundle = sanitizeBundle(active);
    }
    bundle.fileName = newClean;
    delete bundle._sectionUpdatedAt;
    addActivityLogEntry('System', `Case # ${oldClean} renamed to ${newClean}`, bundle);
    bundle.lastModified = new Date().toISOString();

    const serverUrl = getSyncServerUrl();
    let resp;
    try {
        resp = await apiFetch(`${serverUrl.replace(/\/$/, '')}/api/v1/${caseNumberToBucket(newBucketId)}/bundle?import=1`, {
            method: 'PUT',
            headers: getAuthHeaders(),
            body: JSON.stringify(bundle)
        });
    } catch (e) {
        alert('Could not reach the server to rename this case. Please try again when online.');
        return false;
    }
    if (!resp.ok) {
        let message = `The server refused the rename (HTTP ${resp.status}).`;
        try {
            const body = await resp.json();
            if (body && (body.message || body.error)) message = body.message || body.error;
        } catch (e) {}
        alert(message);
        return false;
    }
    const result = await resp.json().catch(() => ({}));
    if (result && typeof result.lastModified === 'string' && result.lastModified) {
        bundle.lastModified = result.lastModified;
    }

    if (wasActive) {
        // Switch before the old case is deleted, so the delete below never
        // resets the bucket of the case that is now open.
        await setSyncBucket(newBucketId);
        removeOutboxRecordsForBucket(getSyncBucket());
        setStorageItem(BUNDLE_STORAGE_KEY, JSON.stringify(bundle));
        tagLocalBundleBucket();
        writeOutboxRecord(bundle, {cursor: bundle.lastModified, changes: [], inFlight: null, needsFullUpload: false});
        updateFileNameDisplay();
    }
    await deleteCaseEverywhere(oldClean);
    return true;
}

// Permanently delete a whole case from the database: DELETE /api/v1/:bucket
// removes every row the server holds for (this login, CASE #) - the stored
// search file, the case history entry and every structured-table row - in one
// go. This keys off the CASE # alone, never off a loadable search file, so a
// case that cannot be opened (corrupt, half-written, never downloaded) is
// deleted exactly like any other and, because the server copy is gone, it can
// never come back through a sync.
//
// If the deleted case is the one currently open, the in-memory copy and the
// sync bucket are reset so the app stops showing (and re-pushing) a case that
// no longer exists. Nothing is touched until the server confirms the delete,
// so an offline/refused delete never leaves a half-deleted case. Returns true
// when the case was removed, false when the server refused it (e.g. Super-Admin
// protection) or could not be reached.
async function deleteCaseEverywhere(caseNumber) {
    const clean = String(caseNumber || '').replace(/\.json$/i, '');
    if (!clean) return false;

    const serverUrl = getSyncServerUrl();
    if (!serverUrl || !getUserCredentials()) {
        alert('Log in and connect to the sync server before deleting a case.');
        return false;
    }

    // Build and interpolate the bucket exactly like syncWithServer() does
    // (getSyncBucket()-style) so the DELETE targets the same bucket the data
    // was written under.
    const bucket = caseNumberToBucket(clean);
    try {
        const resp = await apiFetch(`${serverUrl.replace(/\/$/, '')}/api/v1/${bucket}`, {
            method: 'DELETE',
            headers: getAuthHeaders()
        });
        if (!resp.ok) {
            // Surface the server's reason (e.g. Super-Admin protection) and
            // leave the case in place so nothing is half-deleted.
            let message = 'Failed to delete this case on the server. Please try again.';
            try {
                const body = await resp.json();
                if (body && body.message) message = body.message;
            } catch (e) {}
            alert(message);
            return false;
        }
    } catch (e) {
        alert('Could not reach the server to delete this case. Please try again when online.');
        return false;
    }

    // If the deleted case is the one currently open, drop the working copy so
    // nothing below can save it again (a save would queue rows and re-seed the
    // case the server just removed). Rows still queued for the case are
    // forgotten too, so nothing is re-sent for it. Whether a case is "open" is
    // decided by the active CASE #, not by whether its file could be parsed, so
    // a defective open case is reset as well.
    let deletingActive = getActiveCaseNumber() === clean;
    if (!deletingActive) {
        try {
            const active = loadBundle();
            deletingActive = !!active && String(active.fileName || '').replace(/\.json$/i, '') === clean;
        } catch (e) {}
    }
    if (deletingActive) {
        removeStorageItem(BUNDLE_STORAGE_KEY);
        removeStorageItem(BUNDLE_BUCKET_STORAGE_KEY);
    } else if (getActiveCaseNumber()) {
        // The deletion is logged into the activity log of the case that stays open.
        deleteFileFromList(clean);
    }
    removeOutboxRecordsForBucket(bucket);

    // Reset the sync bucket of a deleted active case. Await the setSyncBucket('')
    // write so a caller that reloads cannot abort it, and refresh the file-name
    // display for the current view.
    if (deletingActive) {
        try {
            await setSyncBucket('');
            if (typeof updateFileNameDisplay === 'function') updateFileNameDisplay();
        } catch (e) {}
    }

    return true;
}

function confirmDeleteRow(rowElement, onConfirm) {
  const bundle = loadBundle();
  if (bundle.deleteMode) {
    onConfirm();
    return;
  }

  rowElement.classList.add('delete-highlight');
  
  const onCancel = () => {
    rowElement.classList.remove('delete-highlight');
  };

  const overlay = createPopup("Are you sure you want to delete this row?", rowElement, onCancel);
  const content = overlay.querySelector('.popup-content');
  const btnContainer = overlay.querySelector('.popup-buttons');
  
  // Apply slide-in animation
  content.classList.remove('expanding');
  content.classList.add('slide-in-top');

  const deleteBtn = document.createElement('button');
  deleteBtn.className = 'popup-btn primary';
  deleteBtn.style.background = '#ff4444';
  deleteBtn.style.borderColor = '#ff4444';
  deleteBtn.textContent = 'Delete';
  deleteBtn.onclick = () => {
    overlay.classList.add('fade-out-slow');
    setTimeout(() => {
      onConfirm();
      overlay.remove();
    }, 1000);
  };

  const cancelBtn = document.createElement('button');
  cancelBtn.className = 'popup-btn';
  cancelBtn.textContent = 'Cancel';
  cancelBtn.onclick = () => {
    onCancel();
    closePopup(overlay);
  };

  btnContainer.appendChild(deleteBtn);
  btnContainer.appendChild(cancelBtn);
}

const PERMANENT_PERSONNEL_KEY = 'permanent_personnel_global';

// `bundle` is optional. When a caller already holds the bundle it is about to
// save, it must pass it in: reading/writing through a second loadBundle() would
// otherwise let the caller's older copy overwrite the roles that were just set.
function getPermanentPersonnel(bundle) {
    const source = bundle || loadBundle();
    return source.permanentPersonnel || {};
}

function setPermanentPersonnel(data, bundle) {
    if (bundle) {
        bundle.permanentPersonnel = data;
        return;
    }
    const loaded = loadBundle();
    loaded.permanentPersonnel = data;
    saveBundle(loaded);
}

function syncPersonnelData(fileData, bundle) {
  const global = getPermanentPersonnel(bundle);
  const merged = [];
  const processedNames = new Set();

  // 1. Process data from the file
  fileData.forEach(row => {
    const name = row[0];
    if (!name) {
      merged.push([...row]);
      return;
    }
    processedNames.add(name);
    
    if (global[name]) {
      const mergedRow = [...row];
      // Ensure it has enough columns if it came from an older file
      while (mergedRow.length < 14) mergedRow.push('');
      
      // The row wins over the local global map: the row is what travels between
      // devices, so a role another device just turned on/off must not be
      // reverted by this device's older cached copy.
      mergedRow[3] = row[3] || global[name].gps || '';
      mergedRow[4] = row[4] || global[name].radio || '';
      mergedRow[5] = row[5] || global[name].medic || '';
      merged.push(mergedRow);
    } else {
      global[name] = {
        gps: row[3] || '',
        radio: row[4] || '',
        medic: row[5] || ''
      };
      const mergedRow = [...row];
      while (mergedRow.length < 14) mergedRow.push('');
      merged.push(mergedRow);
    }
  });

  // 2. Add members from global that were NOT in the file
  for (const name in global) {
    if (!processedNames.has(name)) {
      const newRow = Array.from({ length: 14 }, () => '');
      newRow[0] = name;
      newRow[3] = global[name].gps || '';
      newRow[4] = global[name].radio || '';
      newRow[5] = global[name].medic || '';
      newRow[6] = 'false';
      merged.push(newRow);
    }
  }

  setPermanentPersonnel(global, bundle);
  return merged;
}

function splitPersonnelData(mergedData, bundle) {
  const global = getPermanentPersonnel(bundle);
  const filePart = [];

  mergedData.forEach(row => {
    const name = row[0];
    if (!name) {
      filePart.push([...row]);
      return;
    }

    global[name] = {
      gps: row[3] || '',
      radio: row[4] || '',
      medic: row[5] || ''
    };

    // The GPS / Radio / Medic values are ALSO kept in the personnel row itself.
    // They used to be blanked here because they were considered "global only",
    // but the row is what actually reaches the server (one synced row per
    // member), so clearing them meant the three toggles never left the device.
    filePart.push([...row]);
  });

  setPermanentPersonnel(global, bundle);
  return filePart;
}

function loadData() {
  const bundle = loadBundle();
  const key = pageKey();
  if (bundle.pages[key]) {
    if (key === 'page3') return syncPersonnelData(bundle.pages[key], bundle);
    return bundle.pages[key];
  }
  if (isRegionsPage()) return defaultRegionsData();
  if (isSegmentsPage()) return defaultSegmentsData();
  if (isPersonnelPage()) return syncPersonnelData(defaultPersonnelData(), bundle);
  if (isSearchLogPage()) return defaultSearchLogData();
  return defaultData();
}

// Which cells of each table page are described in the activity log when they
// are edited, and how a row is named there. Derived cells (PSR values, the
// Regions consensus) are left out, as are cells whose change is already logged
// by a dedicated handler (personnel team / team lead / status), so nothing is
// recorded twice.
const PAGE_DATA_LOG_INFO = {
  index: {
    type: 'Region',
    keyCols: [0],
    rowName: row => String(row?.[0] || '').trim() || 'unnamed region'
  },
  page2: {
    type: 'Segment',
    keyCols: [0, 1],
    columns: {0: 'Region', 1: 'Segment', 2: 'Area', 3: 'Length', 4: 'Sweep Width', 5: 'Time per Sweep', 8: 'Time per Sweep (manual override)', 9: 'CalTopo link'},
    rowName: row => formatSegmentAssignmentLabel(row?.[0], row?.[1]) || String(row?.[0] || '').trim() || 'unnamed segment'
  },
  page3: {
    type: 'Personnel',
    keyCols: [0],
    columns: {0: 'Name', 3: 'GPS', 4: 'Radio', 5: 'Medic'},
    rowName: row => String(row?.[0] || '').trim() || 'unnamed person'
  },
  page4: {
    type: 'Search Log Entry',
    keyCols: [0],
    columns: {1: 'Date', 2: 'Time', 3: 'Region', 4: 'Segment', 7: 'Team', 8: 'Sweep Width', 9: 'Num of Sweeps'},
    rowName: row => String(row?.[0] || '').trim() || 'unnumbered task'
  }
};

function describeCellChangeForLog(label, oldValue, newValue) {
  const isToggle = v => v === 'true' || v === 'false';
  if (isToggle(newValue) && (isToggle(oldValue) || oldValue === '')) {
    return `${label} turned ${newValue === 'true' ? 'on' : 'off'}`;
  }
  const show = v => (v === '' ? '(blank)' : `"${v}"`);
  if (oldValue === '') return `${label} set to ${show(newValue)}`;
  if (newValue === '') return `${label} cleared (was ${show(oldValue)})`;
  return `${label} changed from ${show(oldValue)} to ${show(newValue)}`;
}

// Records every edited cell of a table page in the activity log by comparing
// the rows about to be saved with the rows that were stored before. Rows are
// matched by position when the table kept its size (a plain cell edit, which
// also covers renames) and by their name/key otherwise (a row was added or
// removed - which the caller logs itself). Cells that are not user-editable
// text are skipped; see PAGE_DATA_LOG_INFO.
function logPageDataChanges(key, before, after, bundle) {
  const info = PAGE_DATA_LOG_INFO[key];
  if (!info) return 0;

  const cell = v => (v === undefined || v === null) ? '' : String(v).trim();
  let beforeRows;
  let afterRows;
  let columnLabel;
  const messages = [];

  if (key === 'index') {
    const beforeHeaders = Array.isArray(before?.headers) ? before.headers : [];
    const afterHeaders = Array.isArray(after?.headers) ? after.headers : [];
    // A voter column was added or removed (logged by the caller): every cell
    // shifted position, so a cell-by-cell comparison would be meaningless.
    if (beforeHeaders.length !== afterHeaders.length && beforeHeaders.length > 0) return 0;
    afterHeaders.forEach((h, c) => {
      const oldName = cell(beforeHeaders[c]);
      const newName = cell(h);
      if (beforeHeaders.length && oldName !== newName) messages.push(`Regions: ${describeCellChangeForLog('voter column name', oldName, newName)}`);
    });
    beforeRows = Array.isArray(before?.rows) ? before.rows : [];
    afterRows = Array.isArray(after?.rows) ? after.rows : [];
    // Only the region name and the voter columns are typed in; the last column
    // (Consensus) is computed from them.
    columnLabel = c => (c === afterHeaders.length - 1 ? null : (cell(afterHeaders[c]) || `Column ${c + 1}`));
  } else {
    beforeRows = Array.isArray(before) ? before : [];
    afterRows = Array.isArray(after) ? after : [];
    columnLabel = c => (info.columns && Object.prototype.hasOwnProperty.call(info.columns, c) ? info.columns[c] : null);
  }

  const diffRows = (oldRow, newRow) => {
    if (!Array.isArray(oldRow) || !Array.isArray(newRow)) return;
    const name = info.rowName(newRow);
    const width = Math.max(oldRow.length, newRow.length);
    for (let c = 0; c < width; c++) {
      const label = columnLabel(c);
      if (!label) continue;
      const oldValue = cell(oldRow[c]);
      const newValue = cell(newRow[c]);
      if (oldValue === newValue) continue;
      messages.push(`${info.type} "${name}": ${describeCellChangeForLog(label, oldValue, newValue)}`);
    }
  };

  if (beforeRows.length === afterRows.length) {
    afterRows.forEach((row, r) => diffRows(beforeRows[r], row));
  } else {
    const rowKey = row => (Array.isArray(row) ? info.keyCols.map(c => cell(row[c]).toLowerCase()).join('|') : '');
    const byKey = new Map();
    beforeRows.forEach(row => {
      const k = rowKey(row);
      if (k.replace(/\|/g, '') && !byKey.has(k)) byKey.set(k, row);
    });
    afterRows.forEach(row => {
      const k = rowKey(row);
      if (byKey.has(k)) diffRows(byKey.get(k), row);
    });
  }

  messages.forEach(message => addActivityLogEntry('System', message, bundle));
  return messages.length;
}

function saveCurrentPageData(data) {
  const bundle = loadBundle();
  const key = pageKey();
  try {
    logPageDataChanges(key, bundle.pages[key], data, bundle);
  } catch (err) {
    console.error('Could not record the table edit in the activity log:', err);
  }
  if (key === 'page3') {
    bundle.pages[key] = splitPersonnelData(data, bundle);
  } else {
    bundle.pages[key] = data;
  }
  saveBundle(bundle);
  // A Search Log edit can change a segment's active/inactive search state (e.g.
  // logging that a team searched or finished a segment). Push the refreshed
  // colors/opacity to SARTopo when the assignment overlay is enabled.
  if (key === 'page4') {
    refreshCalTopoAssignmentOverlayIfEnabled();
  }
  const status = document.getElementById('save-status');
  if (status) {
    const now = new Date();
    status.textContent = `Saved automatically at ${now.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })}`;
  }
}

function updateFileNameDisplay() {
  const brandEl = document.querySelector('.brand');
  if (brandEl) brandEl.textContent = BRAND_NAME;

  const bundle = loadBundle();
  const displayName = getCaseDisplayName(bundle);
  document.querySelectorAll('[data-file-name]').forEach((el) => {
    el.textContent = displayName;
  });

  const creds = getUserCredentials();
  const userName = creds && creds.name ? creds.name : '';
  document.querySelectorAll('[data-username]').forEach((el) => {
    el.textContent = userName;
    const badge = el.closest('[data-user-badge]');
    if (badge) badge.style.display = userName ? '' : 'none';
  });
}

function downloadTextFile(filename, content, mimeType = 'application/json') {
  const blob = new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  setTimeout(() => URL.revokeObjectURL(url), 500);
}

function placeCaretAtEnd(el) {
  const range = document.createRange();
  const sel = window.getSelection();
  range.selectNodeContents(el);
  range.collapse(false);
  sel.removeAllRanges();
  sel.addRange(range);
}

function focusSelector(selector) {
  const next = document.querySelector(selector);
  if (!next) return;
  next.focus();
  placeCaretAtEnd(next);
}

function focusCell(row, col) {
  focusSelector(`.pill-cell[data-row="${row}"][data-col="${col}"]`);
}


let highlightedRowIndex = -1;

function animateNewRow(tr, index) {
  if (index === highlightedRowIndex) {
    tr.classList.add('new-row-highlight');
    // We don't need to remove it here as it's an animation that finishes on its own
    // But we should reset the index for the next table build
    setTimeout(() => {
      highlightedRowIndex = -1;
    }, 100);
  }
}

function animateArrivedRow(tr, teamName) {
  const bundle = loadBundle();
  if (bundle.arrivedTeams && bundle.arrivedTeams.includes(teamName)) {
    tr.classList.add('new-row-highlight');
    // Remove from arrivedTeams after highlighting
    bundle.arrivedTeams = bundle.arrivedTeams.filter(t => t !== teamName);
    saveBundle(bundle);
  }
}

function buildStandardTable() {
  const tableBody = document.getElementById('table-body');
  const clearBtn = document.getElementById('clear-table');
  const data = loadData();

  if (!tableBody) return;
  tableBody.innerHTML = '';

  for (let r = 0; r < data.length; r++) {
    const tr = document.createElement('tr');
    animateNewRow(tr, r);

    for (let c = 0; c < COLS; c++) {
      const td = document.createElement('td');
      td.dataset.label = `Column ${c + 1}`;
      const cellContainer = document.createElement('div');
      cellContainer.className = 'pill-cell-container';

      const cell = document.createElement('div');
      cell.className = 'pill-cell';
      cell.contentEditable = 'true';
      cell.spellcheck = false;
      cell.dataset.row = String(r);
      cell.dataset.col = String(c);
      cell.textContent = data[r]?.[c] ?? '';
      cell.setAttribute('role', 'textbox');
      cell.setAttribute('aria-label', `Row ${r + 1}, Column ${c + 1}`);

      cell.addEventListener('blur', () => {
        const row = Number(cell.dataset.row);
        const col = Number(cell.dataset.col);
        data[row][col] = cell.textContent.trim();
        saveCurrentPageData(data);
      });

      cell.addEventListener('keydown', (event) => {
        const row = Number(cell.dataset.row);
        const col = Number(cell.dataset.col);

        if (event.key === 'Enter') {
          event.preventDefault();
          cell.blur();
          focusCell(Math.min(row + 1, data.length - 1), col);
          return;
        }

        if (event.key === 'Tab') {
          event.preventDefault();
          cell.blur();
          const nextCol = event.shiftKey ? Math.max(col - 1, 0) : Math.min(col + 1, COLS - 1);
          focusCell(row, nextCol);
        }
      });

      cellContainer.appendChild(cell);
      td.appendChild(cellContainer);
      tr.appendChild(td);
    }

    // New Delete Column
    const deleteTd = document.createElement('td');
    deleteTd.dataset.label = 'Delete';
    const deleteContainer = document.createElement('div');
    const delBtn = document.createElement('button');
    delBtn.className = 'row-delete-btn';
    delBtn.textContent = 'Delete';
    delBtn.type = 'button';
    delBtn.onclick = () => {
      confirmDeleteRow(tr, () => {
        const rowContent = (data[r] || []).filter(Boolean).join(', ') || 'empty row';
        data.splice(r, 1);
        logDeletion('row', rowContent);
        if (data.length === 0) data.push(Array.from({ length: COLS }, () => ''));
        saveCurrentPageData(data);
        buildStandardTable();
      });
    };
    deleteContainer.appendChild(delBtn);
    deleteTd.appendChild(deleteContainer);
    tr.appendChild(deleteTd);

    tableBody.appendChild(tr);
  }

  // Add Row button
  const addRowContainer = document.createElement('div');
  addRowContainer.className = 'add-row-container';
  const addRowBtn = document.createElement('button');
  addRowBtn.className = 'add-row-btn';
  addRowBtn.textContent = '+ Add new row';
  addRowBtn.onclick = () => {
    data.push(Array.from({ length: COLS }, () => ''));
    logCreation('row', 'new empty row');
    saveCurrentPageData(data);
    highlightedRowIndex = data.length - 1;
    buildStandardTable();
    focusCell(data.length - 1, 0);
  };
  addRowContainer.appendChild(addRowBtn);

  const existing = document.querySelector('.add-row-container');
  if (existing) existing.remove();
  tableBody.parentElement.after(addRowContainer);

  if (clearBtn) {
    clearBtn.remove();
  }
}

function parseVote(value) {
  const num = Number(String(value).trim());
  return Number.isFinite(num) ? num : null;
}

function parseNumeric(val) {
  if (typeof val === 'number') return val;
  if (!val) return 0;
  // Remove commas and handle units like "ac", "mi", "ft", "hr"
  // parseFloat handles trailing text, but not commas in the middle
  const cleaned = String(val).replace(/,/g, '');
  const num = parseFloat(cleaned);
  return isFinite(num) ? num : 0;
}

function formatUnit(val, unit) {
  if (!val) return '';
  const cleaned = String(val).replace(/,/g, '');
  const num = parseFloat(cleaned);
  if (isNaN(num)) return val;
  return `${num} ${unit}`;
}

function computeConsensus(data, rowIndex) {
  const dynamicCount = data.headers.length - 2;
  if (dynamicCount <= 0) return '';

  let totalNormalized = 0;
  let usedColumns = 0;

  for (let voteCol = 0; voteCol < dynamicCount; voteCol++) {
    let columnSum = 0;
    for (let r = 0; r < data.rows.length; r++) {
      const value = parseVote(data.rows[r][voteCol + 1]);
      if (value !== null) columnSum += value;
    }

    const rowValue = parseVote(data.rows[rowIndex][voteCol + 1]);
    if (rowValue === null || columnSum === 0) continue;

    totalNormalized += rowValue / columnSum;
    usedColumns += 1;
  }

  if (!usedColumns) return '';
  return (totalNormalized / usedColumns).toFixed(4);
}

function updateConsensusCells(data) {
  // Update data in memory first for all rows
  for (let r = 0; r < data.rows.length; r++) {
    data.rows[r][data.headers.length - 1] = computeConsensus(data, r);
  }
  // Then update DOM if present
  document.querySelectorAll('.consensus-cell').forEach((cell) => {
    const row = Number(cell.dataset.row);
    if (data.rows[row]) {
      cell.textContent = data.rows[row][data.headers.length - 1];
    }
  });
}

function saveRegionsAndRefresh(data) {
  updateConsensusCells(data);
  saveCurrentPageData(data);
  recalculateEverything();
}

// Recompute every derived value (consensus, time per sweep, PSRi/PSRc, search
// log PSR before/after). Rendering a page calls this too, so it only saves -
// and therefore only sends rows - when a value actually changed; a plain
// re-render stays silent. Returns the save promise (resolved false when
// nothing changed). `colorSyncDelay` is handed to the CalTopo color push a
// change asks for (0 = the soonest the cooldown allows; by default the push
// waits a moment to fold a burst of edits into one).
function recalculateEverything(options = {}) {
  const {colorSyncDelay} = options;
  const bundle = loadBundle();
  const segmentsData = bundle.pages.page2 || [];
  const searchLogData = bundle.pages.page4 || [];
  const regionsData = bundle.pages.index;
  // Only the pages are recomputed below; snapshot them to see whether anything moved.
  const pagesBefore = JSON.stringify(bundle.pages);

  // 1. Recalculate Regions Consensus
  updateConsensusCells(regionsData);

  // Lost Person Behavior (Incident page): every switched-on category adds its
  // bracket's percentage per mile (as a share of the unadjusted PSRi) to a
  // segment within its distances of the IPP; the additions are summed once
  // (factor = 1 + sum / 100). The factor goes into the initial share, so PSRi,
  // PSRc and the search log's PSR before/after all move together.
  const lpbContext = buildLpbContext(bundle);

  // Search Log "Map Tracking": with the switch on, the miles of imported
  // searcher tracks inside a task's segment stand in for Num of Sweeps x
  // segment length in the coverage term (see calculateSearchCoverage and the
  // Searchers Tracks section).
  const mapTracking = isMapTrackingEnabled(bundle);
  const trackAllocation = mapTracking ? allocateSearcherTracksForBundle(bundle) : null;

  // Helper for share calculation
  const getInitialShare = (region, area) => {
    const regionRowIndex = (regionsData.rows || []).findIndex(r => r[0] === region);
    if (regionRowIndex === -1) return 0;
    const consensus = parseFloat(computeConsensus(regionsData, regionRowIndex)) || 0;
    
    let sumOfAreas = 0;
    segmentsData.forEach(r => {
      if (r[0] === region) {
        sumOfAreas += parseNumeric(r[2]);
      }
    });
    if (sumOfAreas <= 0) return 0;
    return (consensus * area / sumOfAreas);
  };

  const segInfoMap = new Map();

  // 2. Recalculate Segments PSRi and Initialize Shares
  for (let r = 0; r < segmentsData.length; r++) {
    if (segmentsData[r][0] && segmentsData[r][1]) {
       const length = parseNumeric(segmentsData[r][3]);
       const manualTime = parseNumeric(segmentsData[r][8]);
       if (manualTime > 0) {
          segmentsData[r][5] = segmentsData[r][8];
       } else if (length > 0) {
          segmentsData[r][5] = (length / 0.5).toFixed(2) + ' hr';
       } else {
          segmentsData[r][5] = '';
       }
       segmentsData[r][6] = calculatePSR(segmentsData, r, bundle, lpbContext);
       
       const share = getInitialShare(segmentsData[r][0], parseNumeric(segmentsData[r][2])) * getLpbPsrFactor(segmentsData[r], lpbContext);
       segInfoMap.set(`${segmentsData[r][0]}|${segmentsData[r][1]}`, { share });
    }
  }

  // 3. Recalculate Search Log row by row, smallest task # first
  const sortedSearchLog = [...searchLogData].filter(row => row[0]).sort((a, b) => {
    const taskA = parseInt(a[0].replace('#', '')) || 0;
    const taskB = parseInt(b[0].replace('#', '')) || 0;
    return taskA - taskB;
  });

  sortedSearchLog.forEach(logRow => {
    const region = logRow[3];
    const segment = logRow[4];
    const key = `${region}|${segment}`;
    const info = segInfoMap.get(key);
    
    const segRow = segmentsData.find(s => s[0] === region && s[1] === segment);
    if (info && segRow) {
      const area = parseNumeric(segRow[2]);
      const length = parseNumeric(segRow[3]);
      const timePerSweep = parseNumeric(segRow[5]);
      const sweepWidth = parseNumeric(logRow[8]);
      const numSweeps = parseNumeric(logRow[9]);
      const teamInfo = logRow[7] || '';
      const match = teamInfo.match(/\((\d+)\)/);
      const numMembers = match ? parseInt(match[1]) : 0;

      // PSR Before using search sweep
      const psrBefore = (length / timePerSweep * sweepWidth * info.share) / (area / 640);
      logRow[5] = isFinite(psrBefore) ? psrBefore.toFixed(4) : '';

      const z = calculateSearchCoverage({
        area, length, sweepWidth, numSweeps, numMembers,
        trackMiles: mapTracking ? getTaskTrackMiles(trackAllocation, logRow[0]) : null
      });
      if (z > 0) {
        info.share *= Math.exp(-z);
      }

      // PSR After using search sweep
      const psrAfter = (length / timePerSweep * sweepWidth * info.share) / (area / 640);
      logRow[6] = isFinite(psrAfter) ? psrAfter.toFixed(4) : '';
    }
  });

  // 4. Update segment's PSRc with final share using segment's default sweep
  for (let r = 0; r < segmentsData.length; r++) {
    const region = segmentsData[r][0];
    const segment = segmentsData[r][1];
    const info = segInfoMap.get(`${region}|${segment}`);
    if (info) {
      const length = parseNumeric(segmentsData[r][3]);
      const timePerSweep = parseNumeric(segmentsData[r][5]);
      const sweep = parseNumeric(segmentsData[r][4]);
      const area = parseNumeric(segmentsData[r][2]);
      
      const psrc = (length / timePerSweep * sweep * info.share) / (area / 640);
      segmentsData[r][7] = isFinite(psrc) ? psrc.toFixed(4) : '';
    }
  }

  // Map back to original searchLogData
  searchLogData.forEach(row => {
     const sortedRow = sortedSearchLog.find(sr => sr[0] === row[0]);
     if (sortedRow) {
       row[5] = sortedRow[5];
       row[6] = sortedRow[6];
     }
  });

  if (JSON.stringify(bundle.pages) === pagesBefore) return Promise.resolve(false);

  const savePromise = saveBundle(bundle);

  // Segment PSRc values (column 7) were just recomputed. If the CalTopo
  // assignment overlay is on, re-color and re-opacity the shapes on SARTopo so
  // the map always reflects the latest PSRc scale.
  refreshCalTopoAssignmentOverlayIfEnabled(Number.isFinite(colorSyncDelay) ? {delay: colorSyncDelay} : {});
  return savePromise;
}

function buildRegionsTable() {
  const tableHead = document.getElementById('table-head');
  const tableBody = document.getElementById('table-body');
  const tableContainer = document.querySelector('.table-card');
  const clearBtn = document.getElementById('clear-table');
  const addBtn = document.getElementById('add-column');
  const data = loadData();
  const dynamicCount = data.headers.length - 2;

  if (tableContainer) {
    // Keep the normal spreadsheet-style table (with an editable header row) until
    // there are more than 10 columns; beyond that, wrap the cells into the pill grid.
    if (data.headers.length > 10) {
      tableContainer.classList.add('force-mobile-layout');
    } else {
      tableContainer.classList.remove('force-mobile-layout');
    }
    // Also remove horizontal overflow from table-card when in card layout
    if (data.headers.length > 10) {
      tableContainer.style.overflowX = 'hidden';
    } else {
      tableContainer.style.overflowX = '';
    }
  }

  tableHead.innerHTML = '';
  tableBody.innerHTML = '';

  const headerRow = document.createElement('tr');
  for (let c = 0; c < data.headers.length; c++) {
    const th = document.createElement('th');
    const isFixed = c === 0 || c === data.headers.length - 1;

    if (isFixed) {
      if (c === data.headers.length - 1) {
        // Consensus column
        const headerContainer = document.createElement('div');
        headerContainer.className = 'pill-cell-container';

        const plusBtn = document.createElement('button');
        plusBtn.className = 'add-col-btn-inline';
        plusBtn.textContent = '+';
        plusBtn.title = 'Add Voter Column';
        plusBtn.onclick = (e) => {
          e.stopPropagation();
          const insertAt = data.headers.length - 1;
          const newHeaderName = `Voter ${data.headers.length - 1}`;
          data.headers.splice(insertAt, 0, newHeaderName);
          data.rows.forEach(row => row.splice(insertAt, 0, ''));
          if (data.voterVisibility) {
            data.voterVisibility.splice(insertAt - 1, 0, true);
          }
          logCreation('Voter Column', newHeaderName);
          saveCurrentPageData(data);
          buildRegionsTable();
        };

        const consensusLabel = document.createElement('span');
        consensusLabel.textContent = data.headers[c];

        headerContainer.appendChild(plusBtn);
        headerContainer.appendChild(consensusLabel);
        th.appendChild(headerContainer);
      } else {
        th.textContent = data.headers[c];
      }
      th.className = 'fixed-header';
    } else {
      const headerContainer = document.createElement('div');
      headerContainer.className = 'pill-cell-container';

      const headerPill = document.createElement('div');
      headerPill.className = 'pill-cell header-pill';
      headerPill.contentEditable = 'true';
      headerPill.spellcheck = false;
      headerPill.dataset.headerCol = String(c);
      headerPill.textContent = data.headers[c];
      headerPill.setAttribute('role', 'textbox');
      headerPill.setAttribute('aria-label', `Voter header ${c}`);

      headerPill.addEventListener('blur', () => {
        data.headers[c] = headerPill.textContent.trim() || `Voter ${c}`;
        saveRegionsAndRefresh(data);
      });

      headerPill.addEventListener('keydown', (event) => {
        if (event.key === 'Enter') {
          event.preventDefault();
          headerPill.blur();
          focusSelector(`.pill-cell[data-row="0"][data-col="${c}"]`);
          return;
        }

        if (event.key === 'Tab') {
          event.preventDefault();
          headerPill.blur();
          const targetCol = event.shiftKey ? Math.max(c - 1, 1) : Math.min(c + 1, data.headers.length - 2);
          focusSelector(`.header-pill[data-header-col="${targetCol}"]`);
        }
      });

      const delBtn = document.createElement('button');
      delBtn.className = 'col-delete-btn';
      delBtn.innerHTML = '✕';
      delBtn.title = 'Delete Voter Column';
      delBtn.onclick = () => {
        if (data.headers.length <= 3) return; // Keep at least one voter
        const removedHeaderName = data.headers[c];
        data.headers.splice(c, 1);
        data.rows.forEach(row => row.splice(c, 1));
        if (data.voterVisibility) {
          data.voterVisibility.splice(c - 1, 1);
        }
        logDeletion('Voter Column', removedHeaderName);
        saveCurrentPageData(data);
        buildRegionsTable();
      };

      headerContainer.appendChild(headerPill);
      headerContainer.appendChild(delBtn);
      th.appendChild(headerContainer);
    }

    headerRow.appendChild(th);
  }

  // Delete Header
  const deleteTh = document.createElement('th');
  deleteTh.textContent = 'Delete';
  deleteTh.className = 'fixed-header no-print';
  headerRow.appendChild(deleteTh);

  tableHead.appendChild(headerRow);

  for (let r = 0; r < data.rows.length; r++) {
    const tr = document.createElement('tr');
    animateNewRow(tr, r);

    for (let c = 0; c < data.headers.length; c++) {
      const td = document.createElement('td');
      td.dataset.label = data.headers[c];
      td.className = 'regions-td';

      if (c === data.headers.length - 1) {
        const consensus = document.createElement('div');
        consensus.className = 'pill-cell consensus-cell readonly-pill';
        consensus.dataset.row = String(r);
        consensus.textContent = computeConsensus(data, r);
        td.appendChild(consensus);
        tr.appendChild(td);
        continue;
      }

      const cellContainer = document.createElement('div');
      cellContainer.className = 'pill-cell-container';

      const cell = document.createElement('div');
      cell.className = 'pill-cell';
      const isVoterCol = c > 0 && c < data.headers.length - 1;
      if (isVoterCol) {
        cell.classList.add('password-style');
      }
      cell.contentEditable = 'true';
      cell.spellcheck = false;
      cell.dataset.row = String(r);
      cell.dataset.col = String(c);
      cell.textContent = data.rows[r]?.[c] ?? '';
      cell.setAttribute('role', 'textbox');
      cell.setAttribute('aria-label', `Row ${r + 1}, ${data.headers[c]}`);

      cell.addEventListener('blur', () => {
        const row = Number(cell.dataset.row);
        const col = Number(cell.dataset.col);
        data.rows[row][col] = cell.textContent.trim();
        saveRegionsAndRefresh(data);
      });

      cell.addEventListener('keydown', (event) => {
        const row = Number(cell.dataset.row);
        const col = Number(cell.dataset.col);

        if (event.key === 'Enter') {
          event.preventDefault();
          cell.blur();
          focusCell(Math.min(row + 1, data.rows.length - 1), col);
          return;
        }

        if (event.key === 'Tab') {
          event.preventDefault();
          cell.blur();
          const maxEditableCol = data.headers.length - 2;
          const nextCol = event.shiftKey ? Math.max(col - 1, 0) : Math.min(col + 1, maxEditableCol);
          focusCell(row, nextCol);
        }
      });

      cellContainer.appendChild(cell);
      td.appendChild(cellContainer);
      tr.appendChild(td);
    }

    // New Delete Column
    const deleteTd = document.createElement('td');
    deleteTd.dataset.label = 'Delete';
    deleteTd.className = 'regions-td no-print';
    const deleteContainer = document.createElement('div');
    deleteContainer.className = 'pill-cell-container';
    const delBtn = document.createElement('button');
    delBtn.className = 'row-delete-btn';
    delBtn.textContent = 'Delete';
    delBtn.type = 'button';
    delBtn.onclick = () => {
      confirmDeleteRow(tr, () => {
        const regionName = (data.rows[r] && data.rows[r][0]) || 'unnamed region';
        data.rows.splice(r, 1);
        logDeletion('Region', regionName);
        if (data.rows.length === 0) {
          data.rows.push(Array.from({ length: data.headers.length }, () => ''));
        }
        saveCurrentPageData(data);
        buildRegionsTable();
      });
    };
    deleteContainer.appendChild(delBtn);
    deleteTd.appendChild(deleteContainer);
    tr.appendChild(deleteTd);

    tableBody.appendChild(tr);
  }

  // Add Row button
  const addRowContainer = document.createElement('div');
  addRowContainer.className = 'add-row-container';
  const addRowBtn = document.createElement('button');
  addRowBtn.className = 'add-row-btn';
  addRowBtn.textContent = '+ Add new row';
  addRowBtn.onclick = () => {
    data.rows.push(Array.from({ length: data.headers.length }, () => ''));
    logCreation('Region', 'new empty region');
    saveRegionsAndRefresh(data);
    highlightedRowIndex = data.rows.length - 1;
    buildRegionsTable();
    focusCell(data.rows.length - 1, 0);
  };
  addRowContainer.appendChild(addRowBtn);

  const existing = document.querySelector('.add-row-container');
  if (existing) existing.remove();
  tableBody.parentElement.after(addRowContainer);

  updateConsensusCells(data);
  saveCurrentPageData(data);

  addBtn.onclick = () => {
    const insertAt = data.headers.length - 1;
    const newHeaderName = `Voter ${dynamicCount + 1}`;
    data.headers.splice(insertAt, 0, newHeaderName);
    data.rows.forEach((row) => row.splice(insertAt, 0, ''));
    if (data.voterVisibility) {
      data.voterVisibility.push(false);
    } else {
      data.voterVisibility = Array.from({ length: data.headers.length - 2 }, () => false);
    }
    logCreation('Voter Column', newHeaderName);
    saveCurrentPageData(data);
    buildRegionsTable();
  };

  const removeBtn = document.getElementById('remove-voter-columns');
  const removeModal = document.getElementById('remove-voter-columns-modal');
  const closeRemoveModal = document.getElementById('close-remove-modal');
  const confirmRemoveBtn = document.getElementById('confirm-remove-columns');
  const voterListContainer = document.getElementById('voter-columns-list');

  if (removeBtn) {
    removeBtn.onclick = () => {
      voterListContainer.innerHTML = '';
      for (let c = 1; c < data.headers.length - 1; c++) {
        const item = document.createElement('div');
        item.className = 'voter-remove-item';
        
        const label = document.createElement('span');
        label.textContent = data.headers[c];
        
        const toggleContainer = document.createElement('label');
        toggleContainer.className = 'toggle-switch';
        
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.dataset.colIndex = String(c);
        
        const slider = document.createElement('span');
        slider.className = 'slider round';
        
        toggleContainer.appendChild(checkbox);
        toggleContainer.appendChild(slider);
        
        item.appendChild(label);
        item.appendChild(toggleContainer);
        
        item.onclick = (e) => {
          if (e.target !== checkbox && !toggleContainer.contains(e.target)) {
            checkbox.checked = !checkbox.checked;
          }
        };
        
        voterListContainer.appendChild(item);
      }
      removeModal.style.display = 'flex';
    };
  }

  if (closeRemoveModal) {
    closeRemoveModal.onclick = () => {
      removeModal.style.display = 'none';
    };
  }

  if (confirmRemoveBtn) {
    confirmRemoveBtn.onclick = () => {
      const selectedCheckboxes = voterListContainer.querySelectorAll('input[type="checkbox"]:checked');
      if (selectedCheckboxes.length === 0) {
        removeModal.style.display = 'none';
        return;
      }

      const indicesToDelete = Array.from(selectedCheckboxes)
        .map(cb => parseInt(cb.dataset.colIndex))
        .sort((a, b) => b - a);

      indicesToDelete.forEach(idx => {
        data.headers.splice(idx, 1);
        data.rows.forEach(row => row.splice(idx, 1));
        if (data.voterVisibility) {
          data.voterVisibility.splice(idx - 1, 1);
        }
      });

      logDeletion('Voter Columns', `${selectedCheckboxes.length} columns`);
      saveCurrentPageData(data);
      buildRegionsTable();
      removeModal.style.display = 'none';
    };
  }

  if (clearBtn) {
    clearBtn.remove();
  }
}

// `lpbContext` (buildLpbContext) is passed in by recalculateEverything so the
// Lost Person Behavior lookups run once per recalculation, not once per row.
function calculatePSR(data, rowIndex, bundle, lpbContext = null) {
  const row = data[rowIndex];
  const regionName = row[0];
  const area = parseNumeric(row[2]);
  const length = parseNumeric(row[3]);
  const sweep = parseNumeric(row[4]);
  
  // Calculate Time per Sweep as Length / 0.5 if no manual override
  const manualTime = parseNumeric(row[8]);
  const timePerSweep = manualTime > 0 ? manualTime : (length / 0.5);

  if (!regionName || area <= 0 || length <= 0 || sweep <= 0 || timePerSweep <= 0) return '';

  const regionsData = bundle.pages.index;
  const regionRowIndex = (regionsData.rows || []).findIndex(r => r[0] === regionName);
  if (regionRowIndex === -1) return '';

  const consensus = parseFloat(computeConsensus(regionsData, regionRowIndex)) || 0;
  if (consensus <= 0) return '';

  // Sum of Areas for all segments in this region
  let sumOfAreas = 0;
  data.forEach(r => {
    if (r[0] === regionName) {
      sumOfAreas += parseNumeric(r[2]);
    }
  });

  if (sumOfAreas <= 0) return '';

  // Formula: PSR = ((Sweep * Length ) / Time) * (Consensus * (Area / Sum of Areas)) / (Area / 640)
  // The Lost Person Behavior factor (1 + the summed percentage per mile of
  // the categories' brackets / 100, or 1 when the adjustment is off or does
  // not reach this segment) scales the share: PSRi + the categories' additions.
  const lpbFactor = getLpbPsrFactor(row, lpbContext || buildLpbContext(bundle));
  const psr = ((sweep * length ) / timePerSweep) * (consensus * (area / sumOfAreas) * lpbFactor) / (area / 640);

  return isFinite(psr) ? psr.toFixed(4) : '';
}

// updateAllPSRs removed, logic moved to recalculateEverything

// One line for the Segments page's Lost Person Behavior panel saying what the
// PSR values are (or are not) adjusted by right now. With several categories
// on, every applied one is named; one still missing a distance is pointed out.
function describeLpbStatus(context) {
  const lpb = context && context.lpb ? context.lpb : normalizeLostPersonBehavior(null);
  const category = context && context.category ? context.category : null;
  const categoryText = category ? `${category.label} (${context.terrain})` : '';
  const applied = context && Array.isArray(context.categories) && context.categories.length
    ? context.categories.map(entry => `${entry.category.label} (${entry.terrain})`).join(', ')
    : categoryText;
  const incomplete = context && Array.isArray(context.incomplete) ? context.incomplete.map(cat => cat.label) : [];
  if (context && context.active) {
    const ipp = context.ipp || {};
    const pending = incomplete.length ? ` ${incomplete.join(', ')}: enter the four distances on the Incident page to include ${incomplete.length === 1 ? 'it' : 'them'}.` : '';
    return `Applying ${applied} from IPP ${ipp.featureName ? `"${ipp.featureName}"` : `(${Number(ipp.lat).toFixed(5)}, ${Number(ipp.lng).toFixed(5)})`}.${pending}`;
  }
  switch (context && context.reason) {
    case 'disabled': {
      const on = getLpbCategories().filter(cat => lpb.categories[cat.key] && lpb.categories[cat.key].enabled).map(cat => cat.label);
      return on.length
        ? `Off - PSRi values are not adjusted. ${on.join(', ')} and the IPP stay set on the Incident page.`
        : 'Off - PSRi values are not adjusted.';
    }
    case 'no-category':
      return 'No lost person category is switched on (Incident page, Lost Person Behavior).';
    case 'no-distances':
      return `${incomplete.length > 1 ? incomplete.join(', ') : categoryText}: enter the four distances on the Incident page first.`;
    case 'no-ipp':
      return `${applied}: import the IPP marker on the Incident page first.`;
    default:
      return 'Lost Person Behavior is not available on this page.';
  }
}

// Store a change to the Lost Person Behavior section - a category, terrain,
// distance or the IPP on the Incident / Maps page, the switch on the Segments
// page. The section moves the PSRi / PSRc of every segment it reaches, and
// with them the PSRc colors on the CalTopo map, so those are recomputed at
// once instead of on the next visit to the Segments page: the section is
// stored without sending, recalculateEverything saves - so the section, the
// log entry and the recomputed rows travel in one batch - and asks for the
// CalTopo color push straight away (it still runs no sooner than the cooldown
// allows, see refreshCalTopoAssignmentOverlayIfEnabled). When no value moved
// the deferred rows still go out. Returns the flush promise.
function saveLostPersonBehaviorChange(bundle) {
  saveBundle(bundle, true);
  return recalculateEverything({colorSyncDelay: 0})
    .then((flushed) => (flushed ? true : pushBundleDelta(loadBundle())));
}

// The Segments page switch. It only flips psrAdjustmentEnabled in the case;
// the categories, terrains, distances and IPP entered on the Incident page are
// kept, so the adjustment can be lifted and re-applied at will.
function setLpbPsrAdjustmentEnabled(enabled) {
  const bundle = loadBundle();
  const lpb = normalizeLostPersonBehavior(bundle.lostPersonBehavior);
  if (lpb.psrAdjustmentEnabled === !!enabled) return Promise.resolve(false);
  lpb.psrAdjustmentEnabled = !!enabled;
  bundle.lostPersonBehavior = lpb;
  addActivityLogEntry('System', `Lost Person Behavior PSR adjustment switched ${enabled ? 'on' : 'off'} on the Segments page`, bundle);
  return saveLostPersonBehaviorChange(bundle);
}

function bindLpbSegmentsPanel(bundle, context) {
  const toggle = document.getElementById('lpb-toggle');
  const label = document.getElementById('lpb-label');
  if (!toggle && !label) return;
  const lpb = context && context.lpb ? context.lpb : getLostPersonBehavior(bundle);
  if (toggle) {
    toggle.checked = lpb.psrAdjustmentEnabled !== false;
    if (!toggle.dataset.bound) {
      toggle.dataset.bound = 'true';
      toggle.onchange = () => {
        // saveBundle stores the switch at once; the network flush it returns
        // is not waited for, so the table redraws immediately.
        setLpbPsrAdjustmentEnabled(toggle.checked);
        buildSegmentsTable();
      };
    }
  }
  if (label) {
    const status = describeLpbStatus(context);
    label.textContent = status;
    label.classList.toggle('lpb-status-active', !!(context && context.active));
    // In Geek Mode the panel shows only "LPB" next to the switch; the status
    // line stays available as the panel's tooltip.
    const panel = document.getElementById('lpb-panel');
    if (panel) panel.title = status;
  }
}

// One line of the PSRi tooltip per applied category: the bracket the segment
// fell into and the percentage of the PSRi that bracket adds, or why the
// category adds nothing.
function describeLpbContribution(contribution) {
  const name = `${contribution.category.label} (${contribution.terrain})`;
  const bracket = contribution.bracket;
  if (!bracket) return `${name}: beyond its 95% distance, adds nothing.`;
  if (typeof bracket.ratePercentPerMile !== 'number') return `${name}: ${bracket.percent}% bracket, but its distance does not lie beyond the previous bracket's, so it adds nothing.`;
  const span = `${formatLpbMiles(bracket.previousDistance) || '0.0 mi'} to ${formatLpbMiles(bracket.distance)}`;
  return `${name}: ${bracket.percent}% bracket (${bracket.percent - bracket.previousPercent}% over ${span} = ${formatLpbPercent(bracket.ratePercentPerMile)} per mile), adds ${formatLpbPercent(contribution.addedPercent)} of the PSRi.`;
}

// The small tag on the top-right border of a PSRi pill showing what the
// switched-on categories add to the segment ("+13.2%"), with the per-category
// breakdown as the tooltip. Segments the adjustment does not reach (no shape
// on the map, beyond every category's 95 % distance) get the tooltip only.
function appendLpbBracketTag(container, cell, row, context) {
  if (!context || !context.active) return;
  const adjustment = getLpbSegmentAdjustment(row, context);
  if (!adjustment) return;
  if (!adjustment.matched) {
    cell.title = 'Lost Person Behavior: no CalTopo shape was found for this segment, so its PSRi is unchanged.';
    return;
  }
  const miles = Number.isFinite(adjustment.distanceMiles) ? adjustment.distanceMiles.toFixed(1) : '?';
  const contributions = Array.isArray(adjustment.contributions) ? adjustment.contributions : [];
  const breakdown = contributions.map(describeLpbContribution).join('\n');
  if (!(adjustment.addedPercent > 0)) {
    cell.title = `Lost Person Behavior: ${miles} mi from the IPP - nothing is added to the PSRi.\n${breakdown}`;
    return;
  }
  const tag = document.createElement('span');
  tag.className = 'psri-bracket-tag';
  tag.textContent = `+${formatLpbPercent(adjustment.addedPercent)}`;
  tag.title = `Lost Person Behavior: ${miles} mi from the IPP, PSRi + ${formatLpbPercent(adjustment.addedPercent)} of itself (x${adjustment.factor.toFixed(4)}).\n${breakdown}`;
  cell.title = tag.title;
  container.classList.add('has-lpb-tag');
  container.appendChild(tag);
}

function buildSegmentsTable() {
  const tableHead = document.getElementById('table-head');
  const tableBody = document.getElementById('table-body');
  const clearBtn = document.getElementById('clear-table');
  const sortToggle = document.getElementById('sort-toggle');
  const sortLabel = document.getElementById('sort-label');
  
  recalculateEverything();
  let data = loadData();
  const bundle = loadBundle();

  if (sortToggle && !sortToggle.dataset.bound) {
    sortToggle.checked = isSegmentsPsrcSortEnabled();
    sortToggle.dataset.bound = 'true';
  }

  // The Lost Person Behavior panel: its switch applies / lifts the PSR
  // adjustment for the whole case (the Incident page settings stay as they
  // are), and the PSRi pills below get a bracket tag while it is applied.
  const lpbContext = buildLpbContext(bundle);
  bindLpbSegmentsPanel(bundle, lpbContext);

  const isPSRDescending = sortToggle && sortToggle.checked;
  if (sortLabel) {
    sortLabel.textContent = isPSRDescending ? 'Sorted by PSRc (Descending)' : 'Sorted by Region then Segment';
  }

  const sortedData = [...data].sort((a, b) => {
    if (isPSRDescending) {
      const psrA = parseFloat(a[7]) || 0;
      const psrB = parseFloat(b[7]) || 0;
      return psrB - psrA;
    } else {
      // Region then Segment
      const regionA = (a[0] || '').toLowerCase();
      const regionB = (b[0] || '').toLowerCase();
      if (regionA < regionB) return -1;
      if (regionA > regionB) return 1;

      // Same region, check segment (index 1)
      const segA = parseNumeric(a[1]);
      const segB = parseNumeric(b[1]);
      return segA - segB;
    }
  });

  const activeSegments = new Set();
  if (bundle.currentAssignments && bundle.teamStatuses) {
    for (const team in bundle.currentAssignments) {
      const status = bundle.teamStatuses[team] || '';
      const assignment = bundle.currentAssignments[team] || '';
      if (!status.includes('at base') && assignment !== 'Base' && assignment !== 'None' && assignment !== '') {
        const match = assignment.match(/#\d+ (.+) - (.+)/);
        if (match) {
          activeSegments.add(`${match[1]}|${match[2]}`);
        }
      }
    }
  }

  const logSweepsDue = getLogSweepsDue();
  const dueSegments = new Set(logSweepsDue.map(d => `${d.region}|${d.segment}`));

  const regionsData = bundle.pages.index;
  const regionNames = (regionsData.rows || []).map(r => r[0]).filter(name => name && name.trim() !== '');

  const actionsContainer = document.getElementById('segment-header-actions');
  if (actionsContainer) {
      actionsContainer.innerHTML = '';
      const importBtn = document.createElement('button');
      importBtn.className = 'clear-btn';
      importBtn.innerHTML = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="margin-right: 8px; vertical-align: middle;"><path d="M12 3v12"/><path d="m8 11 4 4 4-4"/><path d="M8 5H4a2 2 0 0 0-2 2v10a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-4"/></svg>Import JSON';
      importBtn.onclick = showImportSegmentsPopup;
      actionsContainer.appendChild(importBtn);
  }

  tableHead.innerHTML = '';
  tableBody.innerHTML = '';

  const headers = ['Region', 'Segment', 'Area (acres)', 'Length (mi)', 'Sweep (ft)', 'Time per Sweep (hr)', 'PSRi', 'PSRc', 'CalTopo', 'Delete'];
  const headerRow = document.createElement('tr');
  headers.forEach(h => {
    const th = document.createElement('th');
    th.textContent = h;
    th.className = 'fixed-header';
    headerRow.appendChild(th);
  });
  tableHead.appendChild(headerRow);

  for (let r = 0; r < sortedData.length; r++) {
    const tr = document.createElement('tr');
    animateNewRow(tr, r);
    const segKey = `${sortedData[r][0]}|${sortedData[r][1]}`;
    if (activeSegments.has(segKey)) {
      tr.classList.add('unfinished-row');
    } else if (dueSegments.has(segKey)) {
      tr.classList.add('log-sweeps-due');
    }

    if (newlyImportedSegments.has(segKey)) {
      tr.classList.add('new-import-row');
    }

    const headers = ['Region', 'Segment', 'Area (acres)', 'Length (mi)', 'Sweep (ft)', 'Time per Sweep (hr)', 'PSRi', 'PSRc', 'CalTopo', 'Delete'];
    for (let c = 0; c < 8; c++) {
      const td = document.createElement('td');
      td.dataset.label = headers[c];
      const cellContainer = document.createElement('div');
      cellContainer.className = 'pill-cell-container';

      if (c === 0) {
        // Region Dropdown
        const select = document.createElement('select');
        select.className = 'pill-cell segment-select';
        if (newlyImportedSegments.has(segKey)) select.classList.add('new-import-highlight');
        select.dataset.row = String(r);
        select.dataset.col = String(c);
        select.style.width = '100%';

        const emptyOpt = document.createElement('option');
        emptyOpt.value = '';
        emptyOpt.textContent = '-- Select --';
        select.appendChild(emptyOpt);

        regionNames.forEach(name => {
          const opt = document.createElement('option');
          opt.value = name;
          opt.textContent = name;
          if (sortedData[r][c] === name) opt.selected = true;
          select.appendChild(opt);
        });

        select.onchange = () => {
          const originalRow = sortedData[r];
          originalRow[c] = select.value;
          saveCurrentPageData(data);
          buildSegmentsTable();
        };

        select.addEventListener('keydown', (event) => {
          if (event.key === 'Enter') {
            event.preventDefault();
            focusCell(Math.min(r + 1, sortedData.length - 1), c);
          }
          if (event.key === 'Tab') {
            event.preventDefault();
            const nextCol = event.shiftKey ? Math.max(c - 1, 0) : Math.min(c + 1, 7);
            focusCell(r, nextCol);
          }
        });

        cellContainer.appendChild(select);
      } else if (c === 5) {
        // Time per Sweep (hr) with manual override logic
        if (sortedData[r][8]) {
          const resetBtn = document.createElement('button');
          resetBtn.className = 'reset-pill-btn';
          resetBtn.textContent = '↺';
          resetBtn.title = 'Reset to calculated value';
          resetBtn.onclick = (e) => {
             e.stopPropagation();
             const originalRowIndex = data.indexOf(sortedData[r]);
             data[originalRowIndex][8] = '';
             saveCurrentPageData(data);
             buildSegmentsTable();
          };
          cellContainer.appendChild(resetBtn);
        }

        const cell = document.createElement('div');
        cell.className = 'pill-cell';
        if (newlyImportedSegments.has(segKey)) cell.classList.add('new-import-highlight');
        cell.contentEditable = 'true';
        cell.spellcheck = false;
        cell.dataset.row = String(r);
        cell.dataset.col = String(c);
        cell.textContent = sortedData[r][c] || '';

        cell.addEventListener('blur', () => {
          let val = cell.textContent.trim();
          const originalRowIndex = data.indexOf(sortedData[r]);
          if (val) {
            val = formatUnit(val, 'hr');
            // Check if it's different from the calculated value (length / 0.5)
            const length = parseNumeric(sortedData[r][3]);
            const calc = (length / 0.5).toFixed(2) + ' hr';
            if (val !== calc) {
              data[originalRowIndex][8] = val; // Store manual override
            } else {
              data[originalRowIndex][8] = ''; // Clear override
            }
          } else {
            data[originalRowIndex][8] = '';
          }
          saveCurrentPageData(data);
          buildSegmentsTable();
        });

        cell.addEventListener('keydown', (event) => {
          if (event.key === 'Enter') {
            event.preventDefault();
            focusCell(Math.min(r + 1, sortedData.length - 1), c);
          }
          if (event.key === 'Tab') {
            event.preventDefault();
            const nextCol = event.shiftKey ? Math.max(c - 1, 0) : Math.min(c + 1, 7);
            focusCell(r, nextCol);
          }
        });

        cellContainer.appendChild(cell);
      } else if (c === 6 || c === 7) {
        // PSR Columns (Read-only)
        cellContainer.className = 'pill-cell-container psr-cell-container';

        const cell = document.createElement('div');
        cell.className = 'pill-cell readonly-pill';
        if (newlyImportedSegments.has(segKey)) cell.classList.add('new-import-highlight');
        cell.contentEditable = 'false';
        cell.spellcheck = false;
        cell.dataset.row = String(r);
        cell.dataset.col = String(c);
        cell.textContent = sortedData[r][c] || '';
        
        cell.addEventListener('keydown', (event) => {
          if (event.key === 'Tab') {
            event.preventDefault();
            const nextCol = event.shiftKey ? Math.max(c - 1, 0) : Math.min(c + 1, 7);
            focusCell(r, nextCol);
          }
        });

        cellContainer.appendChild(cell);

        if (c === 6) {
          appendLpbBracketTag(cellContainer, cell, sortedData[r], lpbContext);
        }

        if (c === 7) {
          const sweepsDue = getLogSweepsDue();
          const isDue = sweepsDue.find(d => d.region === sortedData[r][0] && d.segment === sortedData[r][1]);
          
          const actionBtn = document.createElement('button');
          actionBtn.className = 'row-search-btn';
          actionBtn.type = 'button';
          
          if (isDue) {
            actionBtn.textContent = 'log sweeps';
            actionBtn.classList.add('log-sweeps-active');
            actionBtn.onclick = () => showLogSweepsPopup(isDue.taskNum);
          } else {
            actionBtn.textContent = 'search';
            actionBtn.onclick = () => {
              showTeamSelectionPopup((teamName) => {
                // Same assignment process as the Personnel page's "Assign New
                // Task" (Search Log row, team status, activity log entry).
                showMissingStepsPopup(teamName, null, (currentStamp) => {
                  const region = sortedData[r][0] || '';
                  const segment = sortedData[r][1] || '';
                  assignSearchTaskToTeam(teamName, region, segment, currentStamp);
                  navigateToPage('page4.html?scroll=latest');
                });
              }, {
                // "Custom" team: no roster team, no status workflow - the search
                // log row is filled in from the task assignment form instead.
                onCustom: () => {
                  const region = sortedData[r][0] || '';
                  const segment = sortedData[r][1] || '';
                  const taskNumber = createCustomSearchTask(region, segment);
                  navigateToPage(`page5.html?task=${taskNumber}`);
                }
              });
            };
          }
          cellContainer.appendChild(actionBtn);
        }
      } else {
        const cell = document.createElement('div');
        cell.className = 'pill-cell';
        if (newlyImportedSegments.has(segKey)) cell.classList.add('new-import-highlight');
        cell.contentEditable = 'true';
        cell.spellcheck = false;
        cell.dataset.row = String(r);
        cell.dataset.col = String(c);
        cell.textContent = sortedData[r]?.[c] ?? '';

        cell.addEventListener('blur', () => {
          let val = cell.textContent.trim();
          if (val) {
            if (c === 2) val = formatUnit(val, 'ac');
            else if (c === 3) val = formatUnit(val, 'mi');
            else if (c === 4) val = formatUnit(val, 'ft');
            else if (c === 5) val = formatUnit(val, 'hr');
          }
          const originalRow = sortedData[r];
          originalRow[c] = val;
          saveCurrentPageData(data);
          buildSegmentsTable();
        });

        cell.addEventListener('keydown', (event) => {
          const row = Number(cell.dataset.row);
          const col = Number(cell.dataset.col);
          if (event.key === 'Enter') {
            event.preventDefault();
            cell.blur();
            focusCell(Math.min(row + 1, sortedData.length - 1), col);
            return;
          }
          if (event.key === 'Tab') {
            event.preventDefault();
            cell.blur();
            const nextCol = event.shiftKey ? Math.max(col - 1, 0) : Math.min(col + 1, 7);
            focusCell(row, nextCol);
          }
        });

        cellContainer.appendChild(cell);
      }
      td.appendChild(cellContainer);
      tr.appendChild(td);
    }

    const caltopoTd = document.createElement('td');
    caltopoTd.dataset.label = 'CalTopo';
    const caltopoContainer = document.createElement('div');
    caltopoContainer.className = 'pill-cell-container';
    
    const caltopoBtn = document.createElement('button');
    caltopoBtn.className = 'mini-pill';
    const caltopoId = sortedData[r][9];
    caltopoBtn.textContent = caltopoId ? 'Linked.' : 'Link CalTopo';
    caltopoBtn.style.cursor = 'pointer';
    caltopoBtn.style.width = '100%';
    caltopoBtn.style.textAlign = 'center';
    if (caltopoId) {
        caltopoBtn.style.background = 'rgba(64, 192, 87, 0.2)';
        caltopoBtn.style.borderColor = 'rgba(64, 192, 87, 0.4)';
        caltopoBtn.style.color = '#2b8a3e';
        caltopoBtn.style.fontWeight = '600';
        caltopoBtn.title = `Linked to CalTopo ID: ${caltopoId}`;
    }
    
    caltopoBtn.onclick = () => {
        const originalIdx = data.indexOf(sortedData[r]);
        showCalTopoLinkPopup(originalIdx);
    };
    
    caltopoContainer.appendChild(caltopoBtn);
    caltopoTd.appendChild(caltopoContainer);
    tr.appendChild(caltopoTd);

    const deleteTd = document.createElement('td');
    deleteTd.dataset.label = 'Delete';
    const deleteContainer = document.createElement('div');
    deleteContainer.className = 'pill-cell-container';
    const delBtn = document.createElement('button');
    delBtn.className = 'row-delete-btn';
    delBtn.textContent = 'Delete';
    delBtn.type = 'button';
    delBtn.onclick = () => {
      confirmDeleteRow(tr, () => {
        const segName = (sortedData[r] && sortedData[r][1]) || 'unnamed segment';
        const indexInData = data.indexOf(sortedData[r]);
        if (indexInData > -1) {
          data.splice(indexInData, 1);
          logDeletion('Segment', segName);
          if (data.length === 0) data.push(Array.from({ length: 10 }, () => ''));
          saveCurrentPageData(data);
          buildSegmentsTable();
        }
      });
    };
    deleteContainer.appendChild(delBtn);
    deleteTd.appendChild(deleteContainer);
    tr.appendChild(deleteTd);

    tableBody.appendChild(tr);
  }

  const addRowContainer = document.createElement('div');
  addRowContainer.className = 'add-row-container';
  const addRowBtn = document.createElement('button');
  addRowBtn.className = 'add-row-btn';
  addRowBtn.textContent = '+ Add new segment';
  addRowBtn.onclick = () => {
    data.push(Array.from({ length: 10 }, () => ''));
    logCreation('Segment', 'new empty segment');
    saveCurrentPageData(data);
    highlightedRowIndex = data.length - 1;
    buildSegmentsTable();
    focusCell(data.length - 1, 1);
  };
  addRowContainer.appendChild(addRowBtn);
  const existing = document.querySelector('.add-row-container');
  if (existing) existing.remove();
  tableBody.parentElement.after(addRowContainer);

  if (sortToggle) {
    sortToggle.onchange = () => {
      setSegmentsPsrcSortEnabled(sortToggle.checked);
      buildSegmentsTable();
    };
  }

  if (clearBtn) {
    clearBtn.remove();
  }
}

let currentPersonnelSubpage = 'activity';

function buildPersonnelTable() {
  const btnAll = document.getElementById('btn-all-members');
  const btnAct = document.getElementById('btn-activity');
  const btnTeamRep = document.getElementById('btn-team-reports');
  const btnMemRep = document.getElementById('btn-member-reports');

  const logContainer = document.getElementById('activity-log-container');
  const baseContainer = document.getElementById('base-teams-container-header');
  const teamReportsContainer = document.getElementById('team-reports-container');
  const memberReportsContainer = document.getElementById('member-reports-container');
  const searchTeamsContainer = document.getElementById('search-teams-container');
  const controls = document.getElementById('all-members-controls');
  const personnelGrid = document.querySelector('.personnel-grid');

  const subNavBtns = [btnAll, btnAct, btnTeamRep, btnMemRep];
  const containers = [controls, baseContainer, teamReportsContainer, memberReportsContainer, searchTeamsContainer];

    const isSubAllowed = (_sub) => {
      return true;
  };

  if (btnAct) btnAct.style.display = isSubAllowed('activity') ? 'inline-block' : 'none';
  if (btnTeamRep) btnTeamRep.style.display = isSubAllowed('team-reports') ? 'inline-block' : 'none';
  if (btnMemRep) btnMemRep.style.display = isSubAllowed('member-reports') ? 'inline-block' : 'none';
  if (btnAll) btnAll.style.display = isSubAllowed('all-members') ? 'inline-block' : 'none';

  // If current subpage is not allowed, switch to first allowed
  if (!isSubAllowed(currentPersonnelSubpage)) {
      if (isSubAllowed('activity')) currentPersonnelSubpage = 'activity';
      else if (isSubAllowed('all-members')) currentPersonnelSubpage = 'all-members';
      else if (isSubAllowed('team-reports')) currentPersonnelSubpage = 'team-reports';
      else if (isSubAllowed('member-reports')) currentPersonnelSubpage = 'member-reports';
  }

  function hideAll() {
    containers.forEach(c => { if (c) c.style.display = 'none'; });
    subNavBtns.forEach(b => { if (b) b.classList.remove('active'); });
    if (personnelGrid) personnelGrid.classList.remove('all-members-active');
  }

  if (btnAll) {
    btnAll.onclick = () => {
      currentPersonnelSubpage = 'all-members';
      buildPersonnelTable();
    };
  }
  if (btnAct) {
    btnAct.onclick = () => {
      currentPersonnelSubpage = 'activity';
      buildPersonnelTable();
    };
  }
  if (btnTeamRep) {
    btnTeamRep.onclick = () => {
      currentPersonnelSubpage = 'team-reports';
      buildPersonnelTable();
    };
  }
  if (btnMemRep) {
    btnMemRep.onclick = () => {
      currentPersonnelSubpage = 'member-reports';
      buildPersonnelTable();
    };
  }

  const btnPrintTeam = document.getElementById('print-team-reports');
  const btnPrintAllTeam = document.getElementById('print-all-team-reports');
  const btnPrintMem = document.getElementById('print-member-reports');
  const btnPrintAllMem = document.getElementById('print-all-member-reports');

  if (btnPrintTeam) btnPrintTeam.onclick = () => printCurrentReport('team');
  if (btnPrintAllTeam) btnPrintAllTeam.onclick = () => printAllReports('team');
  if (btnPrintMem) btnPrintMem.onclick = () => printCurrentReport('member');
  if (btnPrintAllMem) btnPrintAllMem.onclick = () => printAllReports('member');

  const btnReset = document.getElementById('btn-reset-members');
  const btnMobileStatus = document.getElementById('btn-mobile-status');

  if (btnMobileStatus) {
    btnMobileStatus.onclick = () => {
      navigateToPage('mobile-status.html');
    };
  }

  if (btnReset) {
    btnReset.onclick = () => {
      const popup = createPopup('Delete All Members?');
      const content = popup.querySelector('.popup-content');
      const btnContainer = popup.querySelector('.popup-buttons');
      
      // Semi-transparent red theme
      content.style.background = 'rgba(150, 0, 0, 0.9)';
      content.style.borderColor = '#ff4444';
      content.style.color = '#fff';

      const msg = document.createElement('p');
      msg.textContent = 'This will permanently delete all members from the list. Please type your name to confirm:';
      msg.style.marginBottom = '15px';
      content.insertBefore(msg, btnContainer);

      const confirmInput = document.createElement('input');
      confirmInput.type = 'text';
      confirmInput.placeholder = 'Your Name';
      confirmInput.className = 'cell-edit-input';
      confirmInput.style.width = '100%';
      confirmInput.style.marginBottom = '20px';
      confirmInput.style.background = 'rgba(255, 255, 255, 0.1)';
      confirmInput.style.color = '#fff';
      content.insertBefore(confirmInput, btnContainer);

      const confirmBtn = document.createElement('button');
      confirmBtn.className = 'popup-btn primary';
      confirmBtn.style.background = '#ff4444';
      confirmBtn.textContent = 'Delete All Members';
      confirmBtn.disabled = true;

      confirmInput.oninput = () => {
        confirmBtn.disabled = confirmInput.value.trim() === '';
      };

      confirmBtn.onclick = () => {
        const bundle = loadBundle();
        const allMembersData = bundle.pages.page3 || [];
        const memberNames = allMembersData.map(m => m[0]).filter(n => n);

        // 1. Mark finish all steps for all teams
        const teams = Object.keys(bundle.teamStatuses);
        teams.forEach(team => {
          const currentStatus = bundle.teamStatuses[team] || '';
          if (!currentStatus.startsWith('at base')) {
            const sequence = [
              { id: 'headed to assignment', log: 'Leaving base for assignment' },
              { id: 'searching', log: 'Beginning assignment' },
              { id: 'finished segment', log: 'Finished assignment' },
              { id: 'returning', log: 'Returning to base' },
              { id: 'at base', log: 'Arrived at base' }
            ];
            
            const getIndex = (s) => {
              if (s === 'assigned') return -1;
              if (s === 'headed to assignment') return 0;
              if (s === 'searching') return 1;
              if (s === 'finished segment') return 2;
              if (s === 'returning') return 3;
              if (s && s.startsWith('at base')) return 4;
              return -1;
            };

            const currentIndex = getIndex(currentStatus);
            for (let i = currentIndex + 1; i < sequence.length; i++) {
              const step = sequence[i];
              if (step.id === 'at base') {
                 const now = new Date();
                 const timeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
                 bundle.teamStatuses[team] = `at base (${timeStr})`;
                 bundle.currentAssignments[team] = 'Base';
                 bundle.teamAssignmentTimes[team] = Date.now();
                 if (bundle.parChecks) delete bundle.parChecks[team];
                 if (bundle.teamLeaveTimes) delete bundle.teamLeaveTimes[team];
              } else {
                 bundle.teamStatuses[team] = step.id;
                 if (!bundle.parChecks) bundle.parChecks = {};
                 bundle.parChecks[team] = { lastTime: Date.now() };
                 if (step.id === 'headed to assignment') bundle.teamLeaveTimes[team] = Date.now();
              }
              addActivityLogEntry(team, step.log, bundle);
            }
          }
        });

        // 2. Log deleted members
        if (memberNames.length > 0) {
          addActivityLogEntry('System', 'Deleted all members: ' + memberNames.join(', '), bundle);
        }

        // 3. Clear data
        delete bundle.permanentPersonnel;
        bundle.pages.page3 = [];
        
        saveBundle(bundle);
        closePopup(popup);
        buildPersonnelTable();
      };
      btnContainer.appendChild(confirmBtn);
    };
  }

  const btnCallAll = document.getElementById('btn-call-all-to-base');
  if (btnCallAll) {
    btnCallAll.onclick = callAllTeamsToBase;
  }

  hideAll();

  if (logContainer) logContainer.style.display = 'block';

  if (currentPersonnelSubpage === 'all-members') {
    if (personnelGrid) personnelGrid.classList.add('all-members-active');
    if (controls) controls.style.display = 'flex';
    if (searchTeamsContainer) {
      searchTeamsContainer.style.display = 'block';
      const h2 = searchTeamsContainer.querySelector('h2');
      if (h2) h2.textContent = 'All Members';
    }
    if (btnAll) btnAll.classList.add('active');
    if (btnReset) btnReset.style.display = 'block';
    buildPersonnelAllMembersTable();
  } else if (currentPersonnelSubpage === 'activity') {
    if (searchTeamsContainer) {
      searchTeamsContainer.style.display = 'block';
      const h2 = searchTeamsContainer.querySelector('h2');
      if (h2) h2.textContent = 'Search Teams';
    }
    if (baseContainer) baseContainer.style.display = 'block';
    if (btnAct) btnAct.classList.add('active');
    buildPersonnelActivityTable();
  } else if (currentPersonnelSubpage === 'team-reports') {
    if (teamReportsContainer) teamReportsContainer.style.display = 'block';
    if (btnTeamRep) btnTeamRep.classList.add('active');
    buildTeamReports();
  } else if (currentPersonnelSubpage === 'member-reports') {
    if (memberReportsContainer) memberReportsContainer.style.display = 'block';
    if (btnMemRep) btnMemRep.classList.add('active');
    buildMemberReports();
  }
  updateActivityLogUI();
}

function buildPersonnelAllMembersTable() {
  const tableHead = document.getElementById('table-head');
  const tableBody = document.getElementById('table-body');
  const onSceneToggle = document.getElementById('on-scene-toggle');
  const onSceneLabel = document.getElementById('on-scene-label');
  const sortToggle = document.getElementById('personnel-sort-toggle');
  const sortLabel = document.getElementById('personnel-sort-label');
  const data = loadData();
  // The Status column follows the Incident Times Report (see getMemberIncidentStatus).
  const incidentDays = getIncidentDays(loadBundle());

  // Ensure first row has 'Off Duty' if it's empty
  if (data.length > 0 && !data[0][0] && !data[0][1]) {
    data[0][1] = 'Off Duty';
    saveCurrentPageData(data);
  }

  const filterOnScene = onSceneToggle && onSceneToggle.checked;
  const sortByTeam = sortToggle && sortToggle.checked;

  if (onSceneLabel) onSceneLabel.textContent = filterOnScene ? 'Filter: On Scene' : 'Filter: All Members';
  if (sortLabel) sortLabel.textContent = sortByTeam ? 'Sort: Team then Name' : 'Sort: Name';

  if (onSceneToggle && !onSceneToggle.dataset.listenerAdded) {
    onSceneToggle.addEventListener('change', buildPersonnelTable);
    onSceneToggle.dataset.listenerAdded = 'true';
  }
  if (sortToggle && !sortToggle.dataset.listenerAdded) {
    sortToggle.addEventListener('change', buildPersonnelTable);
    sortToggle.dataset.listenerAdded = 'true';
  }

  tableHead.innerHTML = '';
  tableBody.innerHTML = '';

  const headers = ['Name', 'Team', 'GPS', 'Radio', 'Medic', 'Status', 'Delete'];
  const headerRow = document.createElement('tr');
  headers.forEach(h => {
    const th = document.createElement('th');
    th.textContent = h;
    th.className = 'fixed-header';
    headerRow.appendChild(th);
  });
  tableHead.appendChild(headerRow);

  const teamOptions = ['Alpha', 'Bravo', 'Charlie', 'Delta', 'Echo', 'Foxtrot', 'Golf', 'Hotel', 'India', 'Juliett', 'Kilo', 'Lima', 'Mike', 'November', 'Oscar', 'Papa', 'Quebec', 'Romeo', 'Sierra', 'Tango', 'Uniform', 'Victor', 'Whiskey', 'X-ray', 'Yankee', 'Zulu', 'Command', 'Off Duty', 'Base Support'];
  
  let filteredData = [...data];

  // Collapse duplicate members: files from before the Incident Times Report
  // kept a member's extra incident "sets" as separate personnel rows sharing
  // the same name. The All Members table must show each member only once, so
  // keep only the first row for each non-empty name. Rows with an empty name
  // (e.g. a freshly added blank row) are always kept so they stay editable.
  const seenMemberNames = new Set();
  filteredData = filteredData.filter(row => {
    const name = row && row[0] ? String(row[0]).trim() : '';
    if (!name) return true;
    const key = name.toLowerCase();
    if (seenMemberNames.has(key)) return false;
    seenMemberNames.add(key);
    return true;
  });

  filteredData.sort((a, b) => {
    if (sortByTeam) {
      const teamA = (a[1] || '').toLowerCase();
      const teamB = (b[1] || '').toLowerCase();
      if (teamA < teamB) return -1;
      if (teamA > teamB) return 1;
    }
    const nameA = (a[0] || '').toLowerCase();
    const nameB = (b[0] || '').toLowerCase();
    return nameA.localeCompare(nameB);
  });

  const activeStatuses = ['Enroute', 'On-Scene', 'Hotel', 'Returning Home', 'true'];
  if (filterOnScene) {
    filteredData = filteredData.filter(row => activeStatuses.includes(row[6]));
  }

  if (highlightedRowIndex === -2 && window.lastAddedRow) {
    highlightedRowIndex = filteredData.indexOf(window.lastAddedRow);
    if (highlightedRowIndex === -1) {
      const targetStr = JSON.stringify(window.lastAddedRow);
      highlightedRowIndex = filteredData.findIndex(r => JSON.stringify(r) === targetStr);
    }
    window.lastAddedRow = null;
  }

  for (let r = 0; r < filteredData.length; r++) {
    const tr = document.createElement('tr');
    animateNewRow(tr, r);
    const originalRowIndex = data.indexOf(filteredData[r]);
    
    const rowHeaders = ['Name', 'Team', 'GPS', 'Radio', 'Medic', 'Status'];
    const cellIndices = [0, 1, 3, 4, 5, 6];
    
    for (let i = 0; i < rowHeaders.length; i++) {
      const c = cellIndices[i];
      const td = document.createElement('td');
      td.dataset.label = rowHeaders[i];
      const cellContainer = document.createElement('div');
      cellContainer.className = 'pill-cell-container';

      if (c === 0) {
        const cell = document.createElement('div');
        cell.className = 'mini-pill';
        cell.style.width = '100%';
        cell.style.cursor = 'text';
        cell.contentEditable = 'true';
        cell.spellcheck = false;
        cell.textContent = filteredData[r][c] || '';
        
        cell.addEventListener('blur', () => {
          const newName = cell.textContent.trim();
          if (data[originalRowIndex][c] !== newName) {
            data[originalRowIndex][c] = newName;
            saveCurrentPageData(data);
            if (!window.pendingEmptyCellFocus) {
               buildPersonnelTable();
            }
          }
        });
        cell.addEventListener('keydown', (e) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            const newName = cell.textContent.trim();
            if (data[originalRowIndex][c] !== newName) {
              data[originalRowIndex][c] = newName;
              saveCurrentPageData(data);
            }
            window.pendingEmptyCellFocus = { colLabel: 'Name' };
            buildPersonnelTable();
          }
        });
        cellContainer.appendChild(cell);
      } else if (c === 1) {
        const select = document.createElement('select');
        select.className = 'mini-pill personnel-select';
        select.style.width = '100%';
        select.style.cursor = 'pointer';
        const emptyOpt = document.createElement('option');
        emptyOpt.value = ''; emptyOpt.textContent = '-- Select Team --';
        select.appendChild(emptyOpt);
        teamOptions.forEach(team => {
          const opt = document.createElement('option');
          opt.value = team; opt.textContent = team;
          if (filteredData[r][c] === team) opt.selected = true;
          select.appendChild(opt);
        });
        select.onchange = () => {
          const newTeam = select.value;
          const oldTeam = data[originalRowIndex][c];
          const memberName = data[originalRowIndex][0];
          data[originalRowIndex][c] = newTeam;
          
          // Auto-switch team lead to new team's lead
          const existingTeamMember = data.find(row => row[1] === newTeam && row[2]);
            data[originalRowIndex][2] = existingTeamMember ? existingTeamMember[2] : '';
          
          saveCurrentPageData(data);
          addActivityLogEntry(newTeam || 'Personnel', `${memberName} moved from team ${oldTeam || 'none'} to ${newTeam || 'none'}`);
          buildPersonnelTable();
        };
        cellContainer.appendChild(select);
      } else if (c === 2) {
        const selectLead = document.createElement('select');
        selectLead.className = 'mini-pill personnel-select';
        selectLead.style.width = '100%';
        selectLead.style.cursor = 'pointer';
        const emptyOptLead = document.createElement('option');
        emptyOptLead.value = ''; emptyOptLead.textContent = '-- Select Leader --';
        selectLead.appendChild(emptyOptLead);
        
        const currentTeam = filteredData[r][1];
        const possibleLeads = data.filter(row => row[1] === currentTeam && row[0]);
        
        possibleLeads.forEach(row => {
          const opt = document.createElement('option');
          opt.value = row[0]; opt.textContent = row[0];
          if (filteredData[r][c] === row[0]) opt.selected = true;
          selectLead.appendChild(opt);
        });
        selectLead.onchange = () => {
          const newLead = selectLead.value;
          const targetTeam = data[originalRowIndex][1];
          const oldLead = data[originalRowIndex][c];
          
          // Update everyone on the same team to have this new lead
          data.forEach(row => {
            if (row[1] === targetTeam) {
              row[2] = newLead;
            }
          });
          
          saveCurrentPageData(data);
          addActivityLogEntry(targetTeam || 'Personnel', `Team lead changed from ${oldLead || 'none'} to ${newLead || 'none'}`);
          buildPersonnelTable();
        };
        cellContainer.appendChild(selectLead);
      } else {
        if (c === 6) { // Status column
          // The displayed status must reflect the Incident Times Report rather than
          // the raw stored status field: show the furthest step reached on the
          // member's OLDEST unfinished day (see getMemberIncidentStatus).
          const rawStatus = data[originalRowIndex][c];
          const baseLabel = rawStatus === 'true' ? 'On-Scene' : (rawStatus === 'false' ? 'Off Duty' : (rawStatus || 'Off Duty'));
          const derivedStatus = getMemberIncidentStatus(data[originalRowIndex][0], incidentDays);
          const statusLabel = derivedStatus || baseLabel;
          const statusBtn = document.createElement('button');
          statusBtn.className = 'mini-pill status-pill-btn';
          statusBtn.style.width = '100%';
          statusBtn.style.cursor = 'pointer';
          statusBtn.textContent = statusLabel === 'false' ? 'Off Duty' : statusLabel;
          
          statusBtn.onclick = () => {
            // The member travels in the address, not in browser storage.
            const memberName = data[originalRowIndex][0] || '';
            navigateToPage(`mobile-status.html?member=${encodeURIComponent(memberName)}`);
          };
          cellContainer.appendChild(statusBtn);
        } else { // GPS, Radio, Medic columns
          const checkbox = document.createElement('input');
          checkbox.type = 'checkbox';
          checkbox.className = 'pill-checkbox';
          checkbox.checked = filteredData[r][c] === 'true';
          checkbox.onchange = () => {
            const isChecked = checkbox.checked;
            data[originalRowIndex][c] = isChecked ? 'true' : 'false';
            saveCurrentPageData(data);
          };
          cellContainer.appendChild(checkbox);
        }
      }
      td.appendChild(cellContainer);
      tr.appendChild(td);
    }

    const deleteTd = document.createElement('td');
    deleteTd.dataset.label = 'Delete';
    const deleteBtn = document.createElement('button');
    deleteBtn.className = 'row-delete-btn';
    deleteBtn.textContent = 'Delete';
    deleteBtn.onclick = () => {
      confirmDeleteRow(tr, () => {
        const memberName = (data[originalRowIndex] && data[originalRowIndex][0]) || 'unnamed person';
        
        // Also remove from permanent storage
        if (memberName && memberName !== 'unnamed person') {
          const global = getPermanentPersonnel();
          if (global[memberName]) {
            delete global[memberName];
            setPermanentPersonnel(global);
          }
        }

        data.splice(originalRowIndex, 1);
        logDeletion('Personnel', memberName);
        if (data.length === 0) data.push(Array.from({ length: 14 }, () => ''));
        saveCurrentPageData(data);
        // The person is a user of the login, listed in every case: deleting
        // their row here takes them off the login too, or the row would be
        // back on the next page load (see removeLoginUser).
        if (memberName && memberName !== 'unnamed person') removeLoginUser(memberName);
        buildPersonnelTable();
      });
    };
    deleteTd.appendChild(deleteBtn);
    tr.appendChild(deleteTd);
    tableBody.appendChild(tr);
  }

  const addRowContainer = document.createElement('div');
  addRowContainer.className = 'add-row-container';
  const addRowBtn = document.createElement('button');
  addRowBtn.className = 'add-row-btn';
  addRowBtn.textContent = '+ Add new person';
  addRowBtn.onclick = () => {
    const newRow = Array.from({ length: 14 }, () => '');
    newRow[1] = 'Off Duty';
    newRow[6] = 'Enroute'; // Default to Enroute
    
    data.push(newRow);
    logCreation('Personnel', 'New Person');
    saveCurrentPageData(data);
    
    // Clear filters to ensure new row is visible
    if (onSceneToggle) {
        onSceneToggle.checked = false;
        if (onSceneLabel) onSceneLabel.textContent = 'Filter: All Members';
    }
    
    highlightedRowIndex = -2;
    window.lastAddedRow = newRow;
    buildPersonnelTable();
    
    // Focus the Name cell of the new row and select text
    setTimeout(() => {
      const highlightedRow = tableBody.querySelector('.new-row-highlight');
      if (highlightedRow) {
        const nameCell = highlightedRow.querySelector('.mini-pill[contenteditable="true"]');
        if (nameCell) {
          nameCell.focus();
          const range = document.createRange();
          range.selectNodeContents(nameCell);
          const selection = window.getSelection();
          selection.removeAllRanges();
          selection.addRange(range);
        }
      }
    }, 100);
  };
  addRowContainer.appendChild(addRowBtn);
  const existingAllMem = document.querySelector('.add-row-container');
  if (existingAllMem) existingAllMem.remove();
  tableBody.parentElement.after(addRowContainer);

  if (window.pendingEmptyCellFocus) {
    const colLabel = window.pendingEmptyCellFocus.colLabel;
    window.pendingEmptyCellFocus = null;
    setTimeout(() => {
      const rows = tableBody.querySelectorAll('tr');
      for (const row of rows) {
        const targetCell = row.querySelector(`td[data-label="${colLabel}"] .mini-pill[contenteditable="true"]`);
        if (targetCell && !targetCell.textContent.trim()) {
          targetCell.focus();
          return;
        }
      }
    }, 100);
  }
}

function getLatestPSR(region, segment) {
  const bundle = loadBundle();
  const segData = bundle.pages.page2 || [];
  for (let i = 0; i < segData.length; i++) {
    if (segData[i][0] === region && segData[i][1] === segment) {
      // Index 7 is PSRc. If empty, fallback to index 6 (PSRi)
      return segData[i][7] || segData[i][6] || '';
    }
  }
  return '';
}

// The coverage term of the PSR maths - the exponent a segment's share decays
// by after a search: the sweep width over the searchers' spacing. The spacing
// is the segment's average width (area / 640 / length, in miles) split between
// the sweeps and the team members, in feet:
//   z = sweepWidth / ((area / 640 / length / numSweeps / numMembers) x 5280)
// With the Search Log's Map Tracking switch on, `trackMiles` - the miles of
// imported searcher tracks inside the task's segment - takes the place of the
// whole length x numSweeps x numMembers product (those three only ever
// estimated the miles the team walked; the tracks are those miles), so the
// term reads "tracks" instead of "num of sweeps" and the team count is not
// used:
//   z = sweepWidth / ((area / 640 / trackMiles) x 5280)
// 0 when a value the term needs is missing (the share does not decay). The
// operations of the classic form are kept in their original order so stored
// PSR values do not move by a rounding bit.
function calculateSearchCoverage({area, length, sweepWidth, numSweeps, numMembers, trackMiles = null}) {
  if (!(area > 0) || !(sweepWidth > 0)) return 0;
  let spacingFt;
  if (trackMiles === null || trackMiles === undefined) {
    if (!(length > 0) || !(numSweeps > 0) || !(numMembers > 0)) return 0;
    spacingFt = (area / 640 / length / numSweeps / numMembers) * 5280;
  } else {
    if (!(trackMiles > 0)) return 0;
    spacingFt = (area / 640 / trackMiles) * 5280;
  }
  const z = sweepWidth / spacingFt;
  return Number.isFinite(z) && z > 0 ? z : 0;
}

function calculatePSRAfter(row, bundle, segDataOverride = null) {
  const region = row[3];
  const segment = row[4];
  const teamInfo = row[7] || '';
  const sweepWidth = parseNumeric(row[8]);
  const numSweeps = parseNumeric(row[9]);
  // Map Tracking: the task's track miles stand in for Num of Sweeps x length.
  const mapTracking = isMapTrackingEnabled(bundle);
  const trackMiles = mapTracking ? getTaskTrackMiles(allocateSearcherTracksForBundle(bundle), row[0]) : null;

  if (!region || !segment || sweepWidth <= 0 || (mapTracking ? trackMiles <= 0 : numSweeps <= 0)) return '';

  // Extract team members count from e.g. "Team Alpha (3)" (not used with Map
  // Tracking on - the track miles already are the miles the team walked).
  const match = teamInfo.match(/\((\d+)\)/);
  const numMembers = match ? parseInt(match[1]) : 0;
  if (!mapTracking && numMembers <= 0) return '';

  // Get segment info from Segments page data
  const segData = segDataOverride || bundle.pages.page2 || [];
  const segRow = segData.find(r => r[0] === region && r[1] === segment);
  if (!segRow) return '';

  const area = parseNumeric(segRow[2]);
  const length = parseNumeric(segRow[3]);
  const timePerSweep = parseNumeric(segRow[5]);

  if (area <= 0 || length <= 0 || timePerSweep <= 0) return '';

  // Get Consensus and Sum of Areas from Regions page data
  const regionsData = bundle.pages.index;
  const regionRowIndex = (regionsData.rows || []).findIndex(r => r[0] === region);
  if (regionRowIndex === -1) return '';

  const consensus = parseFloat(computeConsensus(regionsData, regionRowIndex)) || 0;
  if (consensus <= 0) return '';

  let sumOfAreas = 0;
  segData.forEach(r => {
    if (r[0] === region) {
      sumOfAreas += parseNumeric(r[2]);
    }
  });
  if (sumOfAreas <= 0) return '';

  // Formula as requested:
  // PSR = Length / TimePerSweep * SweepWidth * ((Consensus * Area / SumOfAreas) - ((Consensus * Area / SumOfAreas) * (1 - EXP(-(SweepWidth / (Area / 640 / Length / NumOfSweeps / NumTeamMembers) * 5280)))))) / (Area / 640)
  // (with Map Tracking on, Length x NumOfSweeps x NumTeamMembers is the task's track miles - see calculateSearchCoverage)

  const baseValue = (consensus * area / sumOfAreas);
  const z = calculateSearchCoverage({area, length, sweepWidth, numSweeps, numMembers, trackMiles});
  const psrAfter = (length / timePerSweep * sweepWidth * (baseValue - (baseValue * (1 - Math.exp(-z))))) / (area / 640);

  return isFinite(psrAfter) ? psrAfter.toFixed(4) : '';
}

// Progress-bar levels of the current page (for the fill animation). In memory
// only: the values come from the case data, which never stays on the device.
let lastKnownProgress = {};
const updatedTasks = new Set();

function markTaskUpdated(teamName) {
  updatedTasks.add(String(teamName));
  const bundle = loadBundle();
  const assignment = bundle.currentAssignments[teamName] || '';
  const match = assignment.match(/#(\d+)/);
  if (match) {
    updatedTasks.add(String(match[0])); // e.g. "#1"
    updatedTasks.add(String(match[1])); // e.g. "1"
  }
}

function getTaskProgressPercent(status) {
  if (status === 'assigned') return 16.6;
  if (status === 'headed to assignment') return 33.3;
  if (status === 'searching') return 50;
  if (status === 'finished segment') return 66.6;
  if (status === 'returning') return 83.3;
  if (status && status.startsWith('at base')) return 100;
  return 0;
}

function createProgressBar(progress, keyRaw) {
  const key = String(keyRaw);
  const progFill = document.createElement('div');
  progFill.className = 'progress-fill-bg';
  const prev = lastKnownProgress[key] || 0;
  progFill.style.width = prev + '%';
  
  if (updatedTasks.has(key)) {
      progFill.classList.add('animate-progress');
      // Smooth fill from previous level
      setTimeout(() => {
        progFill.style.width = progress + '%';
        if (progress === 100) {
            progFill.classList.add('filling');
            // Wait for fill to finish (0.6s), then turn green, wait 5s, fade out and reset.
            setTimeout(() => {
                progFill.classList.add('completed-green');
                setTimeout(() => {
                    progFill.classList.add('fade-out');
                    setTimeout(() => {
                        progFill.style.width = '0%';
                        progFill.classList.remove('animate-progress', 'filling', 'completed-green', 'fade-out');
                        lastKnownProgress[key] = 0;
                    }, 1000);
                }, 3000);
            }, 600);
        }
      }, 50);
  } else {
      progFill.style.width = progress + '%';
      if (progress === 100) {
          progFill.classList.add('finished');
      }
  }
  
  if (progress < 100) {
      lastKnownProgress[key] = progress;
  }

  return progFill;
}

function isActiveMemberStatus(status) {
  if (!status) return false;
  const s = status.toString();
  const activeStatuses = ['Enroute', 'On-Scene', 'Hotel', 'Returning Home', 'true'];
  return activeStatuses.includes(s);
}

function getTeamMembers(teamName) {
  const bundle = loadBundle();
  const data = bundle.pages.page3 || [];
  return data.filter(row => row[1] === teamName);
}

// Reads the GPS / Radio / Medic toggles of a personnel roster row (page3,
// columns 3/4/5) so the Task Assignment form can pre-fill them.
function getPersonnelRoleFlags(row) {
  return {
    gps: !!row && row[3] === 'true',
    radio: !!row && row[4] === 'true',
    medic: !!row && row[5] === 'true'
  };
}

function buildTaskFormMemberFromRoster(row) {
  return {
    name: row[0],
    leader: row[2] === row[0],
    ...getPersonnelRoleFlags(row),
    rolesLoaded: true
  };
}

// Task forms created before the roster toggles were carried over have every
// role unchecked. Seed those members once from the roster; members that were
// already seeded keep whatever the user set on the form.
function syncTaskFormMemberRolesFromRoster(members, roster) {
  if (!Array.isArray(members)) return false;
  let changed = false;
  members.forEach(m => {
    if (!m || !m.name || m.rolesLoaded) return;
    const row = (roster || []).find(r => r && r[0] === m.name);
    if (!row) return;
    const flags = getPersonnelRoleFlags(row);
    if (!m.gps && flags.gps) { m.gps = true; changed = true; }
    if (!m.radio && flags.radio) { m.radio = true; changed = true; }
    if (!m.medic && flags.medic) { m.medic = true; changed = true; }
    m.rolesLoaded = true;
    changed = true;
  });
  return changed;
}

function isParCheckDue(teamName, bundle) {
  const baseTeamNames = ['Base Support', 'Off Duty', 'Command'];
  if (baseTeamNames.includes(teamName)) return false;
  
  const status = bundle.teamStatuses[teamName] || '';
  if (status.startsWith('at base')) return false;

  const lastPar = bundle.parChecks?.[teamName];
  const leaveTime = bundle.teamLeaveTimes?.[teamName];
  const assignTime = bundle.teamAssignmentTimes?.[teamName];
  
  let startTime = 0;
  if (lastPar) startTime = Math.max(startTime, lastPar.lastTime);
  if (leaveTime) startTime = Math.max(startTime, leaveTime);
  if (assignTime) startTime = Math.max(startTime, assignTime);

  if (startTime > 0) {
    const elapsedMs = Date.now() - startTime;
    const freqMs = (bundle.parCheckFrequency || 20) * 60 * 1000;
    return (freqMs - elapsedMs) <= 0;
  }
  return false;
}

function getSegmentInfo(region, segment) {
  const bundle = loadBundle();
  const segData = bundle.pages.page2 || [];
  const row = segData.find(r => r[0] === region && r[1] === segment);
  if (row) {
    return {
      area: row[2],
      length: row[3],
      sweep: row[4],
      time: row[5],
      psr: row[6]
    };
  }
  return { area: '', length: '', sweep: '', time: '', psr: '' };
}

function getNextTaskNumber() {
  const bundle = loadBundle();
  const searchLog = bundle.pages.page4 || [];
  let max = 0;
  searchLog.forEach(row => {
    if (row[0]) {
      const num = parseInt(row[0].replace('#', ''));
      if (!isNaN(num) && num > max) max = num;
    }
  });
  return max + 1;
}

function addAutoSearchLogEntry(teamName, region, segment) {
  const bundle = loadBundle();
  const logData = bundle.pages.page4 || [];
  const now = new Date();
  const dateStr = `${(now.getMonth() + 1).toString().padStart(2, '0')}-${now.getDate().toString().padStart(2, '0')}-${now.getFullYear()}`;
  const timeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
  
  const psrBefore = getLatestPSR(region, segment);
  const teamMembers = getTeamMembers(teamName);
  const teamPillText = `${teamName} (${teamMembers.length})`;
  const segInfo = getSegmentInfo(region, segment);
  const taskNumber = getNextTaskNumber();

  const newRow = [
    `#${taskNumber}`,
    dateStr,
    timeStr,
    region,
    segment,
    psrBefore,
    '', // PSR After
    teamPillText,
    segInfo.sweep,
    '' // Num of Sweeps
  ];
  
  logData.push(newRow);
  bundle.pages.page4 = logData;
  logCreation('Search Log Entry', '#' + taskNumber, bundle);
  saveBundle(bundle);
  return taskNumber;
}

// Date/time stamp ({date: 'MM-DD-YYYY', time: 'hh:mm', timestampMs}) for "now",
// the same shape showMissingStepsPopup hands to its onComplete callback.
function buildCurrentTimeStamp() {
  const now = new Date();
  return {
    date: `${(now.getMonth() + 1).toString().padStart(2, '0')}-${now.getDate().toString().padStart(2, '0')}-${now.getFullYear()}`,
    time: `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`,
    timestampMs: now.getTime()
  };
}

// Assigns a new task to a roster team. This is the ONE process behind both the
// Personnel page ("Assign New Task") and the Segments page ("search" button),
// so a search shows up identically in the Search Log and the activity log no
// matter where it was started from: a Search Log row is created, the team is
// put on the assignment with status "assigned" and a fresh par-check timer, and
// a single "Assigned to segment: #N Region - Segment" activity log entry is
// written with the timestamp the user confirmed. Returns the task number and
// the full assignment label.
function assignSearchTaskToTeam(teamName, region, segment, currentStamp = null) {
  const stamp = currentStamp || buildCurrentTimeStamp();
  const taskNumber = addAutoSearchLogEntry(teamName, region, segment);
  const fullAssignment = `#${taskNumber} ${formatSegmentAssignmentLabel(region, segment)}`;

  const b = loadBundle();
  if (!b.currentAssignments) b.currentAssignments = {};
  if (!b.teamAssignmentTimes) b.teamAssignmentTimes = {};
  if (!b.teamStatuses) b.teamStatuses = {};
  if (!b.parChecks) b.parChecks = {};
  b.currentAssignments[teamName] = fullAssignment;
  b.teamAssignmentTimes[teamName] = stamp.timestampMs;
  b.teamStatuses[teamName] = 'assigned';
  b.parChecks[teamName] = { lastTime: stamp.timestampMs };
  saveBundle(b);
  markTaskUpdated(teamName);
  addActivityLogEntry(teamName, 'Assigned to segment: ' + fullAssignment, null, null, stamp.date, stamp.time);
  return { taskNumber, fullAssignment };
}

// ---------------------------------------------------------------------------
// Custom (manually entered) searches
//
// A custom search is started from the Segments page like any other search, but
// instead of picking a roster team the user picks "Custom". No team status,
// par-check timer or activity-log workflow is driven for it; everything the
// Search Log needs (personnel count, timestamps, par checks) is typed straight
// into the task's Task Assignment form. The task counts as "still out" until
// that form is marked completed, which is also when its sweep count is asked
// for and when the map stops drawing the segment in the active-search style.
// ---------------------------------------------------------------------------
const CUSTOM_SEARCH_DEFAULT_TEAM_NAME = 'Custom';

function isCustomSearchTaskForm(form) {
  return !!(form && form.customSearch === true);
}

function getCustomSearchTaskForm(bundle, taskNum) {
  const num = String(taskNum || '').replace('#', '');
  const form = bundle?.forms?.[num];
  return isCustomSearchTaskForm(form) ? form : null;
}

// A custom task is in progress until its Task Assignment form is marked finished.
function isCustomSearchTaskInProgress(bundle, taskNum) {
  const form = getCustomSearchTaskForm(bundle, taskNum);
  return !!form && !form.completed;
}

function countCustomSearchTaskPersonnel(form) {
  return (form?.teamMembers || []).filter(m => m && String(m.name || '').trim()).length;
}

function getCustomSearchTaskTeamName(form) {
  const name = String(form?.teamName || '').trim();
  return name || CUSTOM_SEARCH_DEFAULT_TEAM_NAME;
}

// The Search Log "Team" cell ("Name (N)") of a custom task is derived from the
// form: the personnel count is the number of members typed into it.
function buildCustomSearchTeamCell(form) {
  return `${getCustomSearchTaskTeamName(form)} (${countCustomSearchTaskPersonnel(form)})`;
}

function syncCustomSearchTaskLogRow(bundle, taskNum) {
  const form = getCustomSearchTaskForm(bundle, taskNum);
  if (!form) return false;
  const tag = '#' + String(taskNum).replace('#', '');
  const row = (bundle.pages?.page4 || []).find(r => r && r[0] === tag);
  if (!row) return false;
  const cell = buildCustomSearchTeamCell(form);
  if (row[7] === cell) return false;
  row[7] = cell;
  return true;
}

// Search-log task tags ("#N") of custom searches whose form is not finished yet.
function getCustomSearchTasksInProgress(bundle) {
  const forms = bundle?.forms || {};
  return Object.keys(forms)
    .filter(num => isCustomSearchTaskForm(forms[num]) && !forms[num].completed)
    .map(num => '#' + num);
}

// Adds the segments of in-progress custom searches to a set of normalized
// segment names so the map draws them in the active-search style.
function addCustomSearchActiveSegmentNames(bundle, names) {
  const target = names instanceof Set ? names : new Set();
  const inProgress = new Set(getCustomSearchTasksInProgress(bundle));
  if (inProgress.size === 0) return target;
  (bundle?.pages?.page4 || []).forEach(row => {
    if (!row || !inProgress.has(row[0])) return;
    const fullName = formatSegmentAssignmentLabel(row[3], row[4]);
    if (!fullName) return;
    target.add(normalizeSegmentNameForMatch(row[4]));
    target.add(normalizeSegmentNameForMatch(fullName));
  });
  return target;
}

function buildCustomSearchTaskForm(region, segment, dateStamp) {
  return {
    customSearch: true,
    incidentNumber: '',
    opPeriod: '1',
    dateTime: dateStamp,
    lostPersonName: '',
    lostPersonAge: '',
    lostPersonGender: '',
    lostPersonDescription: '',
    lostPersonClothing: '',
    lostPersonPhysical: '',
    onSceneFamily: false,
    onSceneMedia: false,
    briefedBy: '',
    radioNumber: '',
    gpsNumber: '',
    leaveBase: '',
    beginSearch: '',
    completeSearch: '',
    returnBase: '',
    teamType: '',
    teamTypes: { hasty: false, grid: false, area: false, k9: false, atv: false, argo: false, drone: false, boat: false, other: false },
    otherTeamType: '',
    instructions: '',
    segment: formatSegmentAssignmentLabel(region, segment),
    teamName: CUSTOM_SEARCH_DEFAULT_TEAM_NAME,
    teamMembers: [],
    manualParChecks: [],
    parChecksRaw: [],
    statusUpdates: Array.from({length: 8}, () => ({time: '', clue: '', usng: ''}))
  };
}

// Creates the Search Log row plus the Task Assignment form for a custom search
// of `region - segment` and returns the new task number.
function createCustomSearchTask(region, segment) {
  const bundle = loadBundle();
  const logData = bundle.pages.page4 || [];
  const now = new Date();
  const dateStr = `${(now.getMonth() + 1).toString().padStart(2, '0')}-${now.getDate().toString().padStart(2, '0')}-${now.getFullYear()}`;
  const timeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

  const psrBefore = getLatestPSR(region, segment);
  const segInfo = getSegmentInfo(region, segment);
  const taskNumber = getNextTaskNumber();

  const form = buildCustomSearchTaskForm(region, segment, `${dateStr} ${timeStr}`);
  const newRow = [
    `#${taskNumber}`,
    dateStr,
    timeStr,
    region,
    segment,
    psrBefore,
    '', // PSR After
    buildCustomSearchTeamCell(form),
    segInfo.sweep,
    '' // Num of Sweeps
  ];

  logData.push(newRow);
  bundle.pages.page4 = logData;
  if (!bundle.forms) bundle.forms = {};
  bundle.forms[taskNumber] = form;
  logCreation('Search Log Entry', '#' + taskNumber, bundle);
  addActivityLogEntry('System', `Custom search started on #${taskNumber} ${formatSegmentAssignmentLabel(region, segment)} (manual entry)`, bundle);
  saveBundle(bundle);
  return taskNumber;
}

function reassignMember(memberName, targetTeam) {
  const bundle = loadBundle();
  const data = bundle.pages.page3 || [];
  const originalRow = data.find(row => row[0] === memberName);
  
  if (originalRow) {
    const fromTeam = originalRow[1];
    if (fromTeam === targetTeam) return;
    
    originalRow[1] = targetTeam;
    
    // Auto-switch team lead to new team's lead
    const existingTeamMember = data.find(row => row[1] === targetTeam && row[2]);
    originalRow[2] = existingTeamMember ? existingTeamMember[2] : '';
    
    saveBundle(bundle);
    addActivityLogEntry(targetTeam, `${memberName} reassigned from ${fromTeam} to ${targetTeam}`);
    refreshCurrentPageTable();
  }
}

function promoteToTeamLead(memberName, targetTeam) {
  const bundle = loadBundle();
  const data = bundle.pages.page3 || [];
  
  // First ensure member is in the target team
  const originalRow = data.find(row => row[0] === memberName);
  if (!originalRow) return;

  const fromTeam = originalRow[1];
  const oldLeadRow = data.find(row => row[1] === targetTeam && row[2] === row[0]);
  const oldLeadName = oldLeadRow ? oldLeadRow[0] : 'None';

  if (memberName === oldLeadName && fromTeam === targetTeam) return;

  if (fromTeam !== targetTeam) {
    originalRow[1] = targetTeam;
    addActivityLogEntry(targetTeam, `${memberName} reassigned from ${fromTeam} to ${targetTeam}`);
  }

  // Update all team members to the new lead name
  data.forEach(row => {
    if (row[1] === targetTeam) {
      row[2] = memberName;
    }
  });

  saveBundle(bundle);
  addActivityLogEntry(targetTeam, `${memberName} is now Team Lead (previously ${oldLeadName})`);
  refreshCurrentPageTable();
}

function buildPersonnelActivityTable() {
  const tableHead = document.getElementById('table-head');
  const tableBody = document.getElementById('table-body');
  const baseTableHead = document.getElementById('base-table-head');
  const baseTableBody = document.getElementById('base-table-body');
  const baseContainer = document.getElementById('base-teams-container-header');
  const searchTeamsContainer = document.getElementById('search-teams-container');
  
  const bundle = loadBundle();
  const data = bundle.pages.page3 || [];

  tableHead.innerHTML = '';
  tableBody.innerHTML = '';
  if (baseTableHead) baseTableHead.innerHTML = '';
  if (baseTableBody) baseTableBody.innerHTML = '';

  const headers = ['Team / Lead', 'Members', 'Assignment / Status', 'Update / Par Check'];
  const headerRow = document.createElement('tr');
  headers.forEach(h => {
    const th = document.createElement('th');
    th.textContent = h;
    th.className = 'fixed-header';
    headerRow.appendChild(th);
  });
  tableHead.appendChild(headerRow);

  if (baseTableHead) {
    const baseHeaderRow = document.createElement('tr');
    ['Team', 'Members'].forEach(h => {
      const th = document.createElement('th');
      th.textContent = h;
      th.className = 'fixed-header';
      baseHeaderRow.appendChild(th);
    });
    baseTableHead.appendChild(baseHeaderRow);
  }

  const teamsMap = new Map();
  const baseTeamsMap = new Map();
  const baseTeamNames = ['Base Support', 'Off Duty', 'Command'];

  data.forEach((row) => {
    // Show all members that have a name regardless of status
    if (row[0] && row[0].trim() !== '') {
      let teamName = row[1] && row[1].trim() !== '' ? row[1] : 'Off Duty';
      
      if (baseTeamNames.includes(teamName)) {
        if (!baseTeamsMap.has(teamName)) baseTeamsMap.set(teamName, []);
        baseTeamsMap.get(teamName).push(row);
      } else {
        if (!teamsMap.has(teamName)) teamsMap.set(teamName, []);
        teamsMap.get(teamName).push(row);
      }
    }
  });

  if (baseContainer) {
    baseContainer.style.display = 'block';
  }
  if (searchTeamsContainer) {
    searchTeamsContainer.style.display = 'block';
  }

  const sortedBaseTeams = Array.from(baseTeamsMap.keys()).sort();
  sortedBaseTeams.forEach((teamName, idx) => {
    const members = baseTeamsMap.get(teamName);

    const tr = document.createElement('tr');
    animateNewRow(tr, idx);
    animateArrivedRow(tr, teamName);

    const tdTeam = document.createElement('td');
    tdTeam.dataset.label = 'Team';
    const teamPill = document.createElement('div');
    teamPill.className = 'mini-pill readonly-pill';
    teamPill.textContent = teamName;
    tdTeam.appendChild(teamPill);
    tr.appendChild(tdTeam);

    const tdMembers = document.createElement('td');
    tdMembers.dataset.label = 'Members';
    const membersContainer = document.createElement('div');
    membersContainer.className = 'pill-container';
    
    // Drag and drop for container
    membersContainer.ondragover = (e) => {
      e.preventDefault();
      membersContainer.classList.add('drag-over');
    };
    membersContainer.ondragleave = () => {
      membersContainer.classList.remove('drag-over');
    };
    membersContainer.ondrop = (e) => {
      e.preventDefault();
      membersContainer.classList.remove('drag-over');
      const memberName = e.dataTransfer.getData('text/plain');
      reassignMember(memberName, teamName);
    };

    members.forEach(member => {
      const pill = document.createElement('div');
      pill.className = 'mini-pill';
      pill.textContent = member[0];
      pill.onclick = () => showReassignPopup(member, teamName);
      
      // Drag and drop for pill
      pill.draggable = true;
      pill.ondragstart = (e) => {
        e.dataTransfer.setData('text/plain', member[0]);
        pill.classList.add('dragging');
      };
      pill.ondragend = () => {
        pill.classList.remove('dragging');
      };

      membersContainer.appendChild(pill);
    });
    tdMembers.appendChild(membersContainer);
    tr.appendChild(tdMembers);

    if (baseTableBody) baseTableBody.appendChild(tr);
  });

  const sortedTeams = Array.from(teamsMap.keys()).sort();
  sortedTeams.forEach((teamName, idx) => {
    const members = teamsMap.get(teamName);
    const teamLeadRow = members.find(row => row[2] === row[0]) || members[0];
    const teamLead = teamLeadRow ? teamLeadRow[0] : '';

    const tr = document.createElement('tr');
    animateNewRow(tr, idx);
    animateArrivedRow(tr, teamName);

    const tdTeamLead = document.createElement('td');
    tdTeamLead.dataset.label = 'Team / Lead';
    const teamLeadContainer = document.createElement('div');
    teamLeadContainer.className = 'pill-cell-container stacked';

    const teamPill = document.createElement('div');
    teamPill.className = 'mini-pill readonly-pill';
    teamPill.textContent = teamName;
    teamLeadContainer.appendChild(teamPill);

    const teamLeadPill = document.createElement('div');
    teamLeadPill.className = 'mini-pill clickable-pill';
    teamLeadPill.textContent = teamLead || 'No Lead';
    teamLeadPill.onclick = () => {
        if (teamLeadRow) showTeamLeadSwapPopup(teamLeadRow, teamName);
    };

    // Drag and drop for Team Lead pill (drop target)
    teamLeadPill.ondragover = (e) => {
      e.preventDefault();
      teamLeadPill.classList.add('drag-over');
    };
    teamLeadPill.ondragleave = () => {
      teamLeadPill.classList.remove('drag-over');
    };
    teamLeadPill.ondrop = (e) => {
      e.preventDefault();
      teamLeadPill.classList.remove('drag-over');
      const memberName = e.dataTransfer.getData('text/plain');
      promoteToTeamLead(memberName, teamName);
    };

    // Drag for team lead (draggable)
    if (teamLead) {
      teamLeadPill.draggable = true;
      teamLeadPill.ondragstart = (e) => {
        e.dataTransfer.setData('text/plain', teamLead);
        teamLeadPill.classList.add('dragging');
      };
      teamLeadPill.ondragend = () => {
        teamLeadPill.classList.remove('dragging');
      };
    }

    teamLeadContainer.appendChild(teamLeadPill);
    tdTeamLead.appendChild(teamLeadContainer);
    tr.appendChild(tdTeamLead);

    const tdMembers = document.createElement('td');
    tdMembers.dataset.label = 'Members';
    const membersContainer = document.createElement('div');
    membersContainer.className = 'pill-container';

    // Drag and drop for Members container (drop target)
    membersContainer.ondragover = (e) => {
      e.preventDefault();
      membersContainer.classList.add('drag-over');
    };
    membersContainer.ondragleave = () => {
      membersContainer.classList.remove('drag-over');
    };
    membersContainer.ondrop = (e) => {
      e.preventDefault();
      membersContainer.classList.remove('drag-over');
      const memberName = e.dataTransfer.getData('text/plain');
      reassignMember(memberName, teamName);
    };

    members.forEach(member => {
      // Members who are team leads do not need to be in the Members column
      if (member[0] === teamLead) return;

      const pill = document.createElement('div');
      pill.className = 'mini-pill';
      pill.textContent = member[0];
      pill.onclick = () => showReassignPopup(member, teamName);
      
      // Drag for member (draggable)
      pill.draggable = true;
      pill.ondragstart = (e) => {
        e.dataTransfer.setData('text/plain', member[0]);
        pill.classList.add('dragging');
      };
      pill.ondragend = () => {
        pill.classList.remove('dragging');
      };

      membersContainer.appendChild(pill);
    });
    tdMembers.appendChild(membersContainer);
    tr.appendChild(tdMembers);

    const tdAssignStatus = document.createElement('td');
    tdAssignStatus.dataset.label = 'Assignment / Status';
    const assignStatusContainer = document.createElement('div');
    assignStatusContainer.className = 'pill-cell-container stacked';

    const assignmentText = bundle.currentAssignments[teamName] || 'None';
    const assignPill = document.createElement('div');
    assignPill.className = 'mini-pill clickable-pill';
    assignPill.textContent = assignmentText;
    assignPill.onclick = () => showTeamUpdatePopup(teamName);
    assignStatusContainer.appendChild(assignPill);

    const statusPill = document.createElement('div');
    statusPill.className = 'mini-pill clickable-pill';
    const statusText = bundle.teamStatuses[teamName] || '';
    statusPill.textContent = statusText;
    statusPill.onclick = () => showTeamUpdatePopup(teamName);
    
    if (assignmentText !== 'None' && assignmentText !== 'Base' && assignmentText !== '') {
      const progress = getTaskProgressPercent(statusText);
      statusPill.appendChild(createProgressBar(progress, teamName));
    }
    
    assignStatusContainer.appendChild(statusPill);
    tdAssignStatus.appendChild(assignStatusContainer);
    tr.appendChild(tdAssignStatus);

    const tdUpdatePar = document.createElement('td');
    tdUpdatePar.dataset.label = 'Update / Par Check';
    const updateParContainer = document.createElement('div');
    updateParContainer.className = 'pill-cell-container stacked';

    const updatePill = document.createElement('div');
    updatePill.className = 'mini-pill update-pill';
    updatePill.textContent = 'Update';
    updatePill.onclick = () => showTeamUpdatePopup(teamName);
    updateParContainer.appendChild(updatePill);

    const parPill = document.createElement('div');
    parPill.className = 'mini-pill readonly-pill';
    
    const lastPar = bundle.parChecks?.[teamName];
    const leaveTime = bundle.teamLeaveTimes?.[teamName];
    const assignTime = bundle.teamAssignmentTimes?.[teamName];
    
    let startTime = 0;
    if (lastPar) startTime = Math.max(startTime, lastPar.lastTime);
    if (leaveTime) startTime = Math.max(startTime, leaveTime);
    if (assignTime) startTime = Math.max(startTime, assignTime);

    const status = bundle.teamStatuses[teamName] || '';
    if (status.startsWith('at base')) {
      parPill.textContent = ' - ';
    } else if (startTime > 0) {
      const elapsedMs = Date.now() - startTime;
      const freqMs = (bundle.parCheckFrequency || 20) * 60 * 1000;
      const remainingMs = freqMs - elapsedMs;

      if (remainingMs <= 0) {
        parPill.textContent = 'Par Check Due';
        parPill.classList.add('par-check-due');
      } else {
        const remainingMin = Math.ceil(remainingMs / 60000);
        parPill.textContent = `${remainingMin}m`;
      }
    } else {
      parPill.textContent = 'N/A';
    }

    parPill.onclick = () => showParCheckPopup(teamName);
    updateParContainer.appendChild(parPill);
    tdUpdatePar.appendChild(updateParContainer);
    tr.appendChild(tdUpdatePar);

    if (idx < sortedTeams.length - 1) {
      tr.classList.add('team-divider-row');
    }

    tableBody.appendChild(tr);
  });

  updateActivityLogUI();
  const existingAddRow = document.querySelector('.add-row-container');
  if (existingAddRow) existingAddRow.remove();
}

function showReassignPopup(member, currentTeam) {
  const teamOptions = ['Alpha', 'Bravo', 'Charlie', 'Delta', 'Echo', 'Foxtrot', 'Golf', 'Hotel', 'India', 'Juliett', 'Kilo', 'Lima', 'Mike', 'November', 'Oscar', 'Papa', 'Quebec', 'Romeo', 'Sierra', 'Tango', 'Uniform', 'Victor', 'Whiskey', 'X-ray', 'Yankee', 'Zulu', 'Command', 'Off Duty', 'Base Support'];
  const popup = createPopup('Reassign ' + member[0]);
  const btnContainer = popup.querySelector('.popup-buttons');
  btnContainer.style.display = 'flex';
  btnContainer.style.flexWrap = 'wrap';
  btnContainer.style.gap = '10px';

  teamOptions.forEach(team => {
    if (team === currentTeam) return;
    const btn = document.createElement('button');
    btn.className = 'mini-pill';
    btn.textContent = 'Move to ' + team;
    btn.onclick = () => {
      const bundle = loadBundle();
      const data = bundle.pages.page3;
      const originalRow = data.find(row => row[0] === member[0]);
      if (originalRow) {
        originalRow[1] = team;
        
        // Auto-switch team lead to new team's lead
        const existingTeamMember = data.find(row => row[1] === team && row[2]);
        originalRow[2] = existingTeamMember ? existingTeamMember[2] : '';
        
        saveBundle(bundle);
        addActivityLogEntry(team, `${member[0]} reassigned from ${currentTeam} to ${team}`);
        refreshCurrentPageTable();
      }
      closePopup(popup);
    };
    btnContainer.appendChild(btn);
  });

  // Leave Scene button in reassign popup
  const leaveBtn = document.createElement('button');
  leaveBtn.className = 'mini-pill';
  leaveBtn.style.borderColor = 'rgba(255, 69, 58, 0.4)';
  leaveBtn.style.color = '#ff453a';
  leaveBtn.textContent = 'Leave Scene';
  leaveBtn.onclick = () => {
    closePopup(popup);
    promptMemberOffScene(member);
  };
  btnContainer.appendChild(leaveBtn);
}

function showTeamLeadSwapPopup(currentLeadRow, teamName) {
  const bundle = loadBundle();
  const data = bundle.pages.page3 || [];
  const teamMembers = data.filter(row => row[1] === teamName && row[0] !== currentLeadRow[0] && isActiveMemberStatus(row[6]));
  
  const popup = createPopup(`Change Team Lead for ${teamName}`);
  const btnContainer = popup.querySelector('.popup-buttons');
  btnContainer.style.display = 'flex';
  btnContainer.style.flexWrap = 'wrap';
  btnContainer.style.gap = '10px';

  if (teamMembers.length === 0) {
    const msg = document.createElement('div');
    msg.textContent = "No other members in this team to promote.";
    msg.style.marginBottom = "10px";
    btnContainer.appendChild(msg);
  }

  teamMembers.forEach(member => {
    const btn = document.createElement('button');
    btn.className = 'mini-pill';
    btn.textContent = 'Promote ' + member[0];
    btn.onclick = () => {
      const b = loadBundle();
      const d = b.pages.page3;
      const newLeadName = member[0];
      const oldLeadName = currentLeadRow[0];
      
      // Update all team members to the new lead name
      d.forEach(row => {
        if (row[1] === teamName) {
          row[2] = newLeadName;
        }
      });
      
      saveBundle(b);
      addActivityLogEntry(teamName, `${newLeadName} is now Team Lead (previously ${oldLeadName})`);
      closePopup(popup);
      refreshCurrentPageTable();
    };
    btnContainer.appendChild(btn);
  });
}

function getStatusIndex(status) {
    if (status === 'assigned') return -1;
    if (status === 'headed to assignment') return 0;
    if (status === 'searching') return 1;
    if (status === 'finished segment') return 2;
    if (status === 'returning') return 3;
    if (status && (status === 'at base' || status.startsWith('at base'))) return 4;
    return -1;
}

function showTeamUpdatePopup(teamName) {
  const popup = createPopup('Team ' + teamName + ' Update');
  const btnContainer = popup.querySelector('.popup-buttons');

  const bundle = loadBundle();
  const currentStatus = bundle.teamStatuses[teamName] || '';
  const currentIndex = getStatusIndex(currentStatus);

  const updateStatus = (newStatus, logAction) => {
    showMissingStepsPopup(teamName, newStatus, (currentStamp) => {
      markTaskUpdated(teamName);
      const b = loadBundle();
      b.teamStatuses[teamName] = newStatus;
      if (newStatus === 'headed to assignment') {
        b.teamLeaveTimes[teamName] = currentStamp.timestampMs;
      }
      if (!b.parChecks) b.parChecks = {};
      b.parChecks[teamName] = { lastTime: currentStamp.timestampMs };
      saveBundle(b);
      addActivityLogEntry(teamName, logAction, null, null, currentStamp.date, currentStamp.time);
      popup.remove();
      refreshCurrentPageTable();
    });
  };

  const statusActions = [
    { id: 'headed to assignment', label: 'Leave Base', action: () => updateStatus('headed to assignment', 'Leaving base for assignment') },
    { id: 'searching', label: 'Begin Assignment', action: () => updateStatus('searching', 'Beginning assignment') },
    { id: 'finished segment', label: 'Finish Assignment', action: () => updateStatus('finished segment', 'Finished assignment') },
    { id: 'returning', label: 'Return to Base', action: () => updateStatus('returning', 'Returning to base') },
    { id: 'at base', label: 'Arrived at Base', action: () => {
        showMissingStepsPopup(teamName, 'at base', (currentStamp) => {
            markTaskUpdated(teamName);
            const b = loadBundle();
            const timeStr = currentStamp.time;
            b.teamStatuses[teamName] = `at base (${timeStr})`;
            b.currentAssignments[teamName] = 'Base';
            b.teamAssignmentTimes[teamName] = currentStamp.timestampMs;
            
            if (b.parChecks) delete b.parChecks[teamName];
            if (b.teamLeaveTimes) delete b.teamLeaveTimes[teamName];
            if (b.teamAssignmentTimes) delete b.teamAssignmentTimes[teamName];
            
            if (!b.arrivedTeams) b.arrivedTeams = [];
            if (!b.arrivedTeams.includes(teamName)) b.arrivedTeams.push(teamName);
            
            saveBundle(b);
            addActivityLogEntry(teamName, `Arrived at base at ${timeStr}`, null, null, currentStamp.date, currentStamp.time);
            popup.remove();
            refreshCurrentPageTable();
        });
    }}
  ];

  // Assign New Task (Always available)
  const btnNew = document.createElement('button');
  btnNew.className = 'popup-btn';
  btnNew.textContent = 'Assign New Task';
  btnNew.onclick = () => {
    showNewSegmentPopup(teamName, popup);
  };
  btnContainer.appendChild(btnNew);

  // Status Buttons
  statusActions.forEach((step, idx) => {
    const btn = document.createElement('button');
    btn.className = 'popup-btn';
    btn.textContent = step.label;
    if (idx <= currentIndex) {
      btn.style.opacity = '0.4';
      btn.style.pointerEvents = 'none';
    }
    btn.onclick = step.action;
    btnContainer.appendChild(btn);
  });

  // Par Check
  const btnPar = document.createElement('button');
  btnPar.className = 'popup-btn';
  if (isParCheckDue(teamName, bundle)) {
    btnPar.textContent = 'Par Check Due';
    btnPar.classList.add('par-check-due');
  } else {
    btnPar.textContent = 'Par Check';
  }
  btnPar.onclick = () => {
    showParCheckPopup(teamName, popup);
  };
  btnContainer.appendChild(btnPar);
}

function refreshCurrentPageTable() {
  if (isPersonnelPage()) buildPersonnelTable();
  else if (isSearchLogPage()) buildSearchLogTable();
  else if (isSegmentsPage()) buildSegmentsTable();
  else if (isFormsPage()) buildFormsPage();
  else if (isRegionsPage()) buildRegionsTable();
  else if (isHomePage()) buildHomePage();

  // Ensure header status (like par checks) is updated immediately, but avoid infinite loop
  checkParChecksAndNotify(true);
}

function showParCheckPopup(teamName, parentPopup) {
  if (parentPopup) closePopup(parentPopup);
  const popup = createPopup('Par Check - Team ' + teamName, null, () => refreshCurrentPageTable());
  const content = popup.querySelector('.popup-content');
  
  const inputContainer = document.createElement('div');
  inputContainer.className = 'popup-input-container';
  
  const textarea = document.createElement('textarea');
  textarea.className = 'popup-textarea';
  textarea.placeholder = 'Enter par check update...';
  inputContainer.appendChild(textarea);
  
  const updateBtn = document.createElement('button');
  updateBtn.className = 'popup-btn primary';
  updateBtn.textContent = 'Update';
  updateBtn.onclick = () => {
    const bundle = loadBundle();
    const now = new Date();
    const timeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    const fullNote = `[${timeStr}] Par Check: ${textarea.value}`;
    bundle.parChecks[teamName] = {
      lastTime: Date.now(),
      lastNote: textarea.value
    };
    saveBundle(bundle);
    addActivityLogEntry(teamName, fullNote);
    closePopup(popup);
    refreshCurrentPageTable();
  };
  inputContainer.appendChild(updateBtn);
  
  content.appendChild(inputContainer);
}

function showNewSegmentPopup(teamName, parentPopup) {
  if (parentPopup) parentPopup.remove();
  const popup = createPopup('Assign New Task - Team ' + teamName);
  const content = popup.querySelector('.popup-content');
  
  const bundle = loadBundle();
  const segments = (bundle.pages.page2 || []).filter(s => s[0] && s[1]);
  
  // Sort by PSR descending
  segments.sort((a, b) => {
    const psrA = parseFloat(getLatestPSR(a[0], a[1])) || 0;
    const psrB = parseFloat(getLatestPSR(b[0], b[1])) || 0;
    return psrB - psrA;
  });

  if (segments.length === 0) {
    const p = document.createElement('p');
    p.textContent = 'No segments defined.';
    content.appendChild(p);
  } else {
    const select = document.createElement('select');
    select.className = 'popup-select';
    select.style.width = '100%';
    select.style.marginBottom = '15px';
    select.style.padding = '8px';
    
    const defaultOpt = document.createElement('option');
    defaultOpt.value = "";
    defaultOpt.textContent = "Select a segment...";
    select.appendChild(defaultOpt);
    
    segments.forEach(seg => {
      const region = seg[0];
      const segment = seg[1];
      const psr = getLatestPSR(region, segment);
      const val = `${region} - ${segment}`;
      
      const opt = document.createElement('option');
      opt.value = JSON.stringify({region, segment, val});
      opt.textContent = `${segment} (PSRc: ${psr || 'N/A'})`;
      select.appendChild(opt);
    });
    
    content.appendChild(select);
    
    const assignBtn = document.createElement('button');
    assignBtn.className = 'popup-btn primary';
    assignBtn.textContent = 'Assign Selected Task';
    assignBtn.onclick = () => {
      if (!select.value) return;
      
      const {region, segment} = JSON.parse(select.value);
      
      showMissingStepsPopup(teamName, null, (currentStamp) => {
        assignSearchTaskToTeam(teamName, region, segment, currentStamp);
        closePopup(popup);
        refreshCurrentPageTable();
      });
    };
    content.appendChild(assignBtn);
  }
}

function showTeamSelectionPopup(onTeamSelected, options = {}) {
  const bundle = loadBundle();
  const data = bundle.pages.page3 || [];
  const teamsMap = new Map();
  data.forEach(row => {
    if (row[1]) {
      teamsMap.set(row[1], true);
    }
  });
  const sortedTeams = Array.from(teamsMap.keys())
    .filter(team => team !== 'Base Support' && team !== 'Command')
    .sort();

  const popup = createPopup('Select Team for Search');
  const content = popup.querySelector('.popup-content');
  
  const segmentsGrid = document.createElement('div');
  segmentsGrid.className = 'popup-segments-grid';
  
  if (sortedTeams.length === 0 && typeof options.onCustom !== 'function') {
    const p = document.createElement('p');
    p.textContent = 'No teams currently available.';
    segmentsGrid.appendChild(p);
  }

  if (typeof options.onCustom === 'function') {
    const customBtn = document.createElement('button');
    customBtn.className = 'mini-pill';
    customBtn.style.width = '100%';
    customBtn.style.padding = '12px';
    customBtn.style.display = 'flex';
    customBtn.style.flexDirection = 'column';
    customBtn.style.alignItems = 'center';
    customBtn.style.gap = '4px';
    customBtn.style.background = 'rgba(255, 140, 0, 0.15)';
    customBtn.style.borderColor = 'rgba(255, 140, 0, 0.5)';

    const nameDiv = document.createElement('div');
    nameDiv.style.fontWeight = 'bold';
    nameDiv.textContent = 'Custom';
    customBtn.appendChild(nameDiv);

    const pill = document.createElement('div');
    pill.style.fontSize = '0.75rem';
    pill.style.color = '#ff8c00';
    pill.textContent = 'Enter search data manually';
    customBtn.appendChild(pill);

    customBtn.onclick = () => {
      closePopup(popup);
      options.onCustom();
    };
    segmentsGrid.appendChild(customBtn);
  }

  sortedTeams.forEach(team => {
    const status = bundle.teamStatuses[team] || 'unassigned';
    const assignment = bundle.currentAssignments[team] || '';
    
    const btn = document.createElement('button');
    btn.className = 'mini-pill';
    btn.style.width = '100%';
    btn.style.padding = '12px';
    btn.style.display = 'flex';
    btn.style.flexDirection = 'column';
    btn.style.alignItems = 'center';
    btn.style.gap = '4px';
    
    const nameDiv = document.createElement('div');
    nameDiv.style.fontWeight = 'bold';
    nameDiv.textContent = 'Team ' + team;
    btn.appendChild(nameDiv);

    if (status && status.startsWith('at base')) {
      btn.style.background = 'rgba(255, 255, 255, 0.05)';
      const pill = document.createElement('div');
      pill.style.fontSize = '0.75rem';
      pill.style.opacity = '0.7';
      pill.textContent = status;
      btn.appendChild(pill);
    } else {
      btn.style.background = 'rgba(125, 198, 255, 0.15)';
      btn.style.borderColor = 'rgba(125, 198, 255, 0.4)';
      const match = assignment.match(/#\d+/);
      
      const pill = document.createElement('div');
      pill.style.fontSize = '0.75rem';
      pill.style.color = 'var(--accent)';
      
      let displayText = status;
      if (match) {
        displayText += ` (Task ${match[0]})`;
      } else if (assignment) {
        displayText += ` (${assignment})`;
      }
      pill.textContent = displayText;
      btn.appendChild(pill);
    }

    btn.onclick = () => {
      onTeamSelected(team);
      closePopup(popup);
    };
    segmentsGrid.appendChild(btn);
  });
  content.appendChild(segmentsGrid);
}

function showMissingStepsPopup(teamName, targetStatus, onComplete) {
  const bundle = loadBundle();
  const currentStatus = bundle.teamStatuses[teamName] || '';
  
  const sequence = [
    { id: 'headed to assignment', label: 'Leave Base', log: 'Leaving base for assignment' },
    { id: 'searching', label: 'Begin Assignment', log: 'Beginning assignment' },
    { id: 'finished segment', label: 'Finish Assignment', log: 'Finished assignment' },
    { id: 'returning', label: 'Return to Base', log: 'Returning to base' },
    { id: 'at base', label: 'Arrived at Base', log: 'Arrived at base' }
  ];

  const currentIndex = getStatusIndex(currentStatus);
  const targetIndex = getStatusIndex(targetStatus);
  
  let missingSteps = [];
  let currentStep;
  if (targetStatus === null || targetIndex === -1) {
    // Assignment (null target) flow: single synthetic entry, no intermediate steps
    currentStep = { id: '__current__', label: 'Assign Task', log: null };
  } else {
    missingSteps = sequence.slice(currentIndex + 1, targetIndex);
    currentStep = sequence[targetIndex];
  }
  
  const stepsToShow = [...missingSteps, currentStep];
  
  const popup = createPopup('Update Timestamps: ' + teamName);
  const content = popup.querySelector('.popup-content');
  const btnContainer = popup.querySelector('.popup-buttons');
  
  const msg = document.createElement('p');
  msg.textContent = 'Please provide missing step information:';
  msg.style.marginBottom = '15px';
  content.insertBefore(msg, btnContainer);
  
  const list = document.createElement('div');
  list.style.textAlign = 'left';
  list.style.marginBottom = '20px';
  list.style.display = 'flex';
  list.style.flexDirection = 'column';
  list.style.gap = '15px';
  list.style.maxHeight = '300px';
  list.style.overflowY = 'auto';
  list.style.paddingRight = '5px';
  
  const stepData = [];

    stepsToShow.forEach((step, idx) => {
    const isCurrent = (idx === stepsToShow.length - 1);
    const item = document.createElement('div');
    item.style.display = 'flex';
    item.style.alignItems = 'center';
    item.style.justifyContent = 'space-between';
    item.style.gap = '15px';
    
    // Step Pill Button
    const stepPill = document.createElement('div');
    stepPill.className = 'popup-btn';
    stepPill.textContent = step.label;
    stepPill.style.flex = '1';
    stepPill.style.padding = '8px 16px';
    stepPill.style.fontSize = '0.9rem';
    stepPill.style.cursor = 'default';
    stepPill.style.textAlign = 'center';
    item.appendChild(stepPill);

    // Date/Time Stamp
    const now = new Date();
    const initialDate = `${(now.getMonth() + 1).toString().padStart(2, '0')}-${now.getDate().toString().padStart(2, '0')}-${now.getFullYear()}`;
    const initialTime = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    
    const stamp = document.createElement('div');
    stamp.className = 'sub-nav-btn';
    stamp.style.padding = '8px 12px';
    stamp.style.fontSize = '0.85rem';
    stamp.style.whiteSpace = 'nowrap';
    stamp.style.cursor = 'pointer';
    stamp.textContent = `${initialDate} ${initialTime}`;
    
    const currentStepData = { step, date: initialDate, time: initialTime, isCurrent };
    stepData.push(currentStepData);

    stamp.onclick = () => {
        showEditTimePopup(currentStepData, (newData) => {
            stamp.textContent = `${newData.date} ${newData.time}`;
        });
    };

    item.appendChild(stamp);
    list.appendChild(item);
  });
  
  content.insertBefore(list, btnContainer);
  
  const submitBtn = document.createElement('button');
  submitBtn.className = 'popup-btn primary';
  submitBtn.textContent = 'Submit';
  submitBtn.onclick = () => {
    markTaskUpdated(teamName);
    const b = loadBundle();
    let currentStamp = null;
    stepData.forEach(item => {
        const d = item.date;
        const t = item.time;

        if (item.isCurrent) {
            // The current/target step is applied by the caller's onComplete via currentStamp.
            let timestampMs;
            const [mm, dd, yyyy] = (d || '').split('-');
            timestampMs = new Date(`${yyyy}-${mm}-${dd}T${t}:00`).getTime();
            if (isNaN(timestampMs)) timestampMs = Date.now();
            currentStamp = { date: d, time: t, timestampMs };
            return;
        }

        let logText = item.step.log;

        if (item.step.id === 'at base') {
          b.teamStatuses[teamName] = `at base (${t})`;
          b.currentAssignments[teamName] = 'Base';
          b.teamAssignmentTimes[teamName] = Date.now();
        } else {
          b.teamStatuses[teamName] = item.step.id;
          if (item.step.id === 'headed to assignment') {
            b.teamLeaveTimes[teamName] = Date.now();
          }
        }

        if (item.step.id === 'finished segment') {
            const assignment = b.currentAssignments[teamName] || '';
            const match = assignment.match(/#\d+/);
            if (match) {
                const tag = match[0];
                const searchLog = b.pages.page4 || [];
                const logEntry = searchLog.find(r => r[0] === tag);
                if (logEntry) {
                    logEntry[1] = d;
                    logEntry[2] = t;
                }
            }
        }

        addActivityLogEntry(teamName, logText, b, null, d, t);
    });
    if (!currentStamp) {
        const now = new Date();
        const d = `${(now.getMonth() + 1).toString().padStart(2, '0')}-${now.getDate().toString().padStart(2, '0')}-${now.getFullYear()}`;
        const t = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
        currentStamp = { date: d, time: t, timestampMs: Date.now() };
    }
    saveBundle(b);
    closePopup(popup);
    onComplete(currentStamp);
  };
  btnContainer.appendChild(submitBtn);
}

