function importSegmentsAction(segments) {
    beginUserAction();
    const b = loadBundle();
    const segmentRows = ensureSegmentsPageRows(b);

    // Keep all non-blank existing rows
    const nonBlankRows = segmentRows.filter(row => Array.isArray(row) && row.some(c => c !== '' && c !== undefined && c !== null));

    const importedNames = [];
    segments.forEach(seg => {
        const lengthVal = parseFloat(seg.length) || 0;
        const timeVal = lengthVal / 0.5;
        const segName = String(seg.segment || seg.name || '').trim();
        const calTopoId = String(seg.feature?.attributes?.id || seg.caltopoId || '').trim();

        // Check if segment already exists in nonBlankRows
        const existingIdx = nonBlankRows.findIndex(r => {
            const rCalTopoId = String(r[9] || '').trim();
            const rSegName = String(r[1] || '').trim().toLowerCase();
            if (calTopoId && rCalTopoId && calTopoId === rCalTopoId) return true;
            if (segName && rSegName && segName.toLowerCase() === rSegName) return true;
            return false;
        });

        const newRow = [
            seg.region || (existingIdx !== -1 ? nonBlankRows[existingIdx][0] : ''),
            segName || (existingIdx !== -1 ? nonBlankRows[existingIdx][1] : ''),
            seg.area ? (String(seg.area).includes('ac') ? seg.area : seg.area + ' ac') : (existingIdx !== -1 ? nonBlankRows[existingIdx][2] : ''),
            seg.length ? (String(seg.length).includes('mi') ? seg.length : seg.length + ' mi') : (existingIdx !== -1 ? nonBlankRows[existingIdx][3] : ''),
            (seg.sweep || (existingIdx !== -1 ? nonBlankRows[existingIdx][4] : 20)) + (typeof (seg.sweep || '') === 'string' && (seg.sweep || '').includes('ft') ? '' : ' ft'),
            timeVal > 0 ? timeVal.toFixed(2) + ' hr' : (existingIdx !== -1 ? nonBlankRows[existingIdx][5] : ''),
            existingIdx !== -1 ? nonBlankRows[existingIdx][6] : '',
            existingIdx !== -1 ? nonBlankRows[existingIdx][7] : '',
            existingIdx !== -1 ? nonBlankRows[existingIdx][8] : '',
            calTopoId || (existingIdx !== -1 ? nonBlankRows[existingIdx][9] : '')
        ];

        if (existingIdx !== -1) {
            nonBlankRows[existingIdx] = newRow;
        } else {
            nonBlankRows.push(newRow);
        }

        newlyImportedSegments.add(`${newRow[0]}|${newRow[1]}`);
        importedNames.push(newRow[1]);
    });

    const minRows = typeof ROWS !== 'undefined' ? ROWS : 50;
    while (nonBlankRows.length < minRows) {
        nonBlankRows.push(Array.from({ length: 10 }, () => ''));
    }

    b.pages.page2 = nonBlankRows;

    if (importedNames.length > 0) {
        addActivityLogEntry('System', 'Imported segments: ' + importedNames.join(', '), b);
    }

    // Queue the imported rows without sending yet: the recalculation right
    // after fills in their derived cells, and both go out as ONE row batch
    // (rather than an upload per step). The rebuild below is render-only.
    saveBundle(b, true);
    const savePromise = recalculateEverything().then((flushed) => (flushed ? true : pushBundleDelta(loadBundle())));
    if (isSegmentsPage()) buildSegmentsTable();

    setTimeout(() => {
        newlyImportedSegments.clear();
        if (isSegmentsPage()) buildSegmentsTable();
    }, 7000);

    Promise.resolve(savePromise).catch(() => false).finally(() => {
        endUserAction();
    });
    return savePromise;
}

async function showCalTopoLinkPopup(originalIdx) {
    const bundle = loadBundle();
    const map = bundle.maps?.[0];
    if (!map || !map.id) {
        alert('Please add a CalTopo map first on the Maps page.');
        return;
    }

    let features = map.features || [];
    if (features.length === 0) {
        const confirmFetch = confirm('No CalTopo features loaded. Fetch them now?');
        if (confirmFetch) {
            try {
                const fetchBtn = document.getElementById('fetch-shapes-btn');
                if (fetchBtn) fetchBtn.click(); // If on maps page
                else await caltopo_request(null, {silent: false});
                
                const updatedBundle = loadBundle();
                features = updatedBundle.maps?.[0]?.features || [];
                if (features.length === 0) {
                    alert('Still no features found after fetch.');
                    return;
                }
            } catch (err) {
                alert('Error fetching shapes: ' + err.message);
                return;
            }
        } else {
            return;
        }
    }

    const assignments = features.filter(f => getCalTopoFeatureTypeKey(f) === 'assignment');
    if (assignments.length === 0) {
        alert('No assignment shapes (polygons) found on this map.');
        return;
    }

    const popup = createPopup('Link Segment to CalTopo', null);
    const content = popup.querySelector('.popup-content');
    
    content.innerHTML = `
        <p style="margin-bottom: 15px; opacity: 0.8;">Select a CalTopo assignment to link with this segment. This ID will be used for color updates.</p>
        <div style="max-height: 400px; overflow-y: auto; background: rgba(0,0,0,0.1); border-radius: 12px; border: 1px solid var(--line);">
            <table class="grid-table" style="width: 100%; border-collapse: collapse;">
                <thead>
                    <tr>
                        <th style="padding: 12px; text-align: left; background: var(--header-bg); position: sticky; top: 0;">Name</th>
                        <th style="padding: 12px; text-align: left; background: var(--header-bg); position: sticky; top: 0;">ID</th>
                        <th style="padding: 12px; text-align: center; background: var(--header-bg); position: sticky; top: 0;">Action</th>
                    </tr>
                </thead>
                <tbody id="caltopo-link-list"></tbody>
            </table>
        </div>
    `;
    
    const tbody = content.querySelector('#caltopo-link-list');
    assignments.forEach(feat => {
        const tr = document.createElement('tr');
        const attrs = feat.attributes || {};
        const name = attrs.name || 'Unnamed Graphic';
        const id = attrs.id;
        
        tr.innerHTML = `
            <td style="padding: 12px; border-bottom: 1px solid var(--line);">${name}</td>
            <td style="padding: 12px; border-bottom: 1px solid var(--line); font-family: monospace; font-size: 0.8rem; color: var(--muted);">${id}</td>
            <td style="padding: 12px; border-bottom: 1px solid var(--line); text-align: center;">
                <button class="mini-pill select-link" style="cursor: pointer; padding: 6px 12px;">Link</button>
            </td>
        `;
        
        tr.querySelector('.select-link').onclick = () => {
            const bundleToUpdate = loadBundle();
            const data = bundleToUpdate.pages.page2;
            if (data && data[originalIdx]) {
                const previousId = String(data[originalIdx][9] || '').trim();
                const segmentLabel = formatSegmentAssignmentLabel(data[originalIdx][0], data[originalIdx][1]) || 'unnamed segment';
                data[originalIdx][9] = id;
                addActivityLogEntry('System', `Linked segment "${segmentLabel}" to CalTopo feature "${name}" (${id})${previousId && previousId !== String(id) ? ` - was linked to ${previousId}` : ''}`, bundleToUpdate);
                saveBundle(bundleToUpdate);
                popup.remove();
                buildSegmentsTable();
            }
        };
        
        tbody.appendChild(tr);
    });
}

function showImportSegmentsPopup() {
  const bundle = loadBundle();
  const uploads = bundle.uploads || [];
  const jsonFiles = uploads.filter(f => f.name.toLowerCase().endsWith('.json'));

  if (jsonFiles.length === 0) {
    alert("No JSON files found in uploads. Please upload JSON files on the Uploads page first.");
    return;
  }

  const popup = createPopup('Import Segments from JSON', null);
  const content = popup.querySelector('.popup-content');
  const btnContainer = popup.querySelector('.popup-buttons');

  content.style.display = 'flex';
  content.style.flexDirection = 'column';
  content.style.maxHeight = '90vh';

  const bodyContainer = document.createElement('div');
  bodyContainer.style.flex = '1';
  bodyContainer.style.display = 'flex';
  bodyContainer.style.flexDirection = 'column';
  bodyContainer.style.overflow = 'hidden';
  content.insertBefore(bodyContainer, btnContainer);

  function renderFileSelection() {
    bodyContainer.innerHTML = '<p style="margin-bottom: 15px; opacity: 0.8; flex-shrink: 0;">Select one or more JSON files to import as segments:</p>';
    const list = document.createElement('div');
    list.style.display = 'flex';
    list.style.flexDirection = 'column';
    list.style.gap = '10px';
    list.style.flex = '1';
    list.style.overflowY = 'auto';
    list.style.paddingRight = '5px';

    jsonFiles.forEach((file, index) => {
      const label = document.createElement('label');
      label.className = 'pill-cell-container clickable-pill';
      label.style.display = 'flex';
      label.style.alignItems = 'center';
      label.style.gap = '15px';
      label.style.padding = '12px 20px';
      label.style.background = 'rgba(255,255,255,0.03)';
      label.style.border = '1px solid var(--pill-border)';
      label.style.borderRadius = '999px';
      label.style.cursor = 'pointer';

      const chk = document.createElement('input');
      chk.type = 'checkbox';
      chk.className = 'pill-checkbox';
      chk.dataset.index = index;
      
      const info = document.createElement('div');
      info.style.flex = '1';
      info.innerHTML = `<div style="font-weight:700;">${file.name}</div><div style="font-size:0.8rem; opacity:0.6;">${(file.size / 1024).toFixed(2)} KB</div>`;
      
      label.appendChild(chk);
      label.appendChild(info);
      list.appendChild(label);
    });

    bodyContainer.appendChild(list);

    btnContainer.innerHTML = '';
    btnContainer.style.display = 'flex';
    btnContainer.style.flexDirection = 'row';
    btnContainer.style.justifyContent = 'flex-end';
    btnContainer.style.marginTop = '20px';
    btnContainer.style.flexShrink = '0';
    btnContainer.style.gap = '12px';

    const cancelBtn = document.createElement('button');
    cancelBtn.className = 'popup-btn';
    cancelBtn.style.flex = '1';
    cancelBtn.textContent = 'Cancel';
    cancelBtn.onclick = () => closePopup(popup);
    btnContainer.appendChild(cancelBtn);

    const nextBtn = document.createElement('button');
    nextBtn.className = 'popup-btn primary';
    nextBtn.style.flex = '1';
    nextBtn.textContent = 'Preview Import';
    nextBtn.onclick = () => {
      const selectedIndices = Array.from(bodyContainer.querySelectorAll('.pill-checkbox:checked')).map(cb => parseInt(cb.dataset.index));
      if (selectedIndices.length === 0) {
        alert("Please select at least one file.");
        return;
      }
      processFiles(selectedIndices.map(i => jsonFiles[i]));
    };
    btnContainer.appendChild(nextBtn);
  }

  function processFiles(files) {
    const segmentsToImport = [];

    const findProp = (item, keys) => {
      const p = item.properties || item.attributes || item.fields || {};
      for (const k of keys) {
        const found = Object.keys(p).find(x => x.toLowerCase() === k.toLowerCase());
        if (found && p[found] !== undefined && p[found] !== null && p[found] !== '') return { value: p[found], key: found };
        const foundTop = Object.keys(item).find(x => x.toLowerCase() === k.toLowerCase());
        if (foundTop && item[foundTop] !== undefined && item[foundTop] !== null && item[foundTop] !== '') return { value: item[foundTop], key: foundTop };
      }
      return null;
    };

    const calculateGeometryLocal = (item) => {
        return calculateGeometry(item);
    };

    const areaKeys = ['acres', 'area', 'size', 'sqmi', 'sq_mi', 'shape_area', 'st_area', 'hectares', 'ha', 'gis_acres', 'acres_total', 'sqft', 'sq_ft', 'sqkm', 'sq_km', 'total_acres'];
    const lengthKeys = ['length', 'len', 'leng', 'shape_leng', 'distance', 'mi', 'miles', 'shape_length', 'st_length', 'dist', 'width', 'height', 'ft', 'feet', 'km', 'meters', 'm', 'shape_len'];

    files.forEach(file => {
      let jsonText = '';
      try {
        if (file.content.startsWith('data:')) {
          const base64 = file.content.split(',')[1];
          const binString = atob(base64);
          const bytes = Uint8Array.from(binString, c => c.charCodeAt(0));
          jsonText = new TextDecoder().decode(bytes);
        } else {
          jsonText = file.content;
        }
      } catch (e) {
        console.error("Failed to decode file", file.name, e);
        return;
      }

      let data;
      try {
        data = JSON.parse(jsonText);
      } catch (e) {
        console.error("Failed to parse JSON", file.name, e);
        return;
      }

      let items = [];
      if (Array.isArray(data)) {
        items = data;
      } else if (data.features && Array.isArray(data.features)) {
        items = data.features;
      } else {
        items = [data];
      }

      items.forEach((item, idx) => {
        let name = file.name.replace(/\.json$/i, '');
        if (items.length > 1) {
            const innerNameRes = findProp(item, ['name', 'segment', 'label', 'title']);
            if (innerNameRes) {
                name = String(innerNameRes.value);
            } else {
                name += ` - ${idx + 1}`;
            }
        }
        
        const areaRes = findProp(item, areaKeys);
        const lengthRes = findProp(item, lengthKeys);
        
        let areaDefaultUnit = 'ac';
        if (areaRes) {
          const lk = areaRes.key.toLowerCase().replace(/[^a-z0-9]/g, '');
          if (lk.includes('sqmi')) areaDefaultUnit = 'sqmi';
          else if (lk.includes('ha') || lk.includes('hectare')) areaDefaultUnit = 'ha';
          else if (lk.includes('sqkm')) areaDefaultUnit = 'sqkm';
          else if (lk.includes('sqm') || lk.includes('starea') || lk.includes('shapearea')) areaDefaultUnit = 'sqm';
          else if (lk.includes('sqft')) areaDefaultUnit = 'sqft';
        }

        let lengthDefaultUnit = 'mi';
        if (lengthRes) {
          const lk = lengthRes.key.toLowerCase().replace(/[^a-z0-9]/g, '');
          if (lk.includes('km')) lengthDefaultUnit = 'km';
          else if (lk.includes('ft') || lk.includes('feet')) lengthDefaultUnit = 'ft';
          else if (lk.includes('mi') && !lk.includes('sqmi')) lengthDefaultUnit = 'mi';
          else if (lk.includes('m') && !lk.includes('mi')) lengthDefaultUnit = 'm';
          else if (lk.includes('stlength') || lk.includes('shapelength') || lk.includes('shapeleng') || lk.includes('perimeter')) lengthDefaultUnit = 'm';
        }
        
        let area = areaRes ? parseWithUnits(String(areaRes.value), areaDefaultUnit) : 0;
        let lengthVal = lengthRes ? parseWithUnits(String(lengthRes.value), lengthDefaultUnit) : 0;
        
        // If still 0, try geometry calculation
        if (area === 0 || lengthVal === 0) {
            const geomRes = calculateGeometryLocal(item);
            if (area === 0 && geomRes.area > 0) area = geomRes.area;
            if (lengthVal === 0 && geomRes.length > 0) lengthVal = geomRes.length;
        }

        // Fallback for length if not found but width/height exist
        if (lengthVal === 0) {
          const w = findProp(item, ['width']);
          const h = findProp(item, ['height']);
          if (w || h) {
             const wv = w ? parseWithUnits(String(w.value), 'mi') : 0;
             const hv = h ? parseWithUnits(String(h.value), 'mi') : 0;
             lengthVal = Math.max(wv, hv);
          }
        }
        
        segmentsToImport.push({
          region: '',
          segment: name,
          area: area > 0 ? area.toFixed(2) : '',
          length: lengthVal > 0 ? lengthVal.toFixed(2) : '',
          sweep: 20
        });
      });
    });

      closePopup(popup);
      showSegmentsImportPreviewPopup(segmentsToImport, {
          title: 'Import Segments from JSON',
          onBack: showImportSegmentsPopup
      });
  }

  function parseWithUnits(valStr, defaultUnit) {
    if (!valStr) return 0;
    // Clean string for parsing numeric value: handle commas as thousand separators
    const cleanStr = String(valStr).replace(/,/g, '');
    const val = parseFloat(cleanStr);
    if (isNaN(val)) return 0;

    const lower = String(valStr).toLowerCase().replace(/[^a-z0-9]/g, '');
    
    // String contains units - they override defaultUnit
    if (lower.includes('sqkm') || lower.includes('squarekilometer')) return val * 247.105;
    if (lower.includes('sqm') || lower.includes('m2') || lower.includes('squaremeter')) return val * 0.000247105;
    if (lower.includes('ha') || lower.includes('hectare')) return val * 2.47105;
    if (lower.includes('sqft') || lower.includes('ft2') || lower.includes('squarefeet')) return val / 43560;
    if (lower.includes('sqmi') || lower.includes('squaremiles')) return val * 640;
    if (lower.includes('acres') || (lower.includes('ac') && !lower.includes('active'))) {
        if (!lower.includes('sqm') && !lower.includes('ha') && !lower.includes('sqft') && !lower.includes('sqmi')) {
            return val;
        }
    }

    if (lower.includes('km') || lower.includes('kilometers')) return val * 0.621371;
    if (lower.includes('ft') || lower.includes('feet')) return val / 5280;
    if (lower.includes('meters') || (lower.includes('m') && !lower.includes('mi') && !lower.includes('km'))) return val * 0.000621371;

    // No units in string, use defaultUnit
    if (defaultUnit === 'sqkm') return val * 247.105;
    if (defaultUnit === 'sqm') return val * 0.000247105;
    if (defaultUnit === 'ha') return val * 2.47105;
    if (defaultUnit === 'sqft') return val / 43560;
    if (defaultUnit === 'sqmi') return val * 640;
    if (defaultUnit === 'km') return val * 0.621371;
    if (defaultUnit === 'm') return val * 0.000621371;
    if (defaultUnit === 'ft') return val / 5280;
    
    return val;
  }

  renderFileSelection();
}

function showCalTopoShapesPopup(features) {
    const popup = createPopup('Import Shapes from CalTopo', null);
  const content = popup.querySelector('.popup-content');
  const btnContainer = popup.querySelector('.popup-buttons');

  content.style.display = 'flex';
  content.style.flexDirection = 'column';
  content.style.maxHeight = '90vh';
  content.style.width = '90vw';
  content.style.maxWidth = '1100px';

  const bodyContainer = document.createElement('div');
  bodyContainer.style.flex = '1';
  bodyContainer.style.display = 'flex';
  bodyContainer.style.flexDirection = 'column';
  bodyContainer.style.overflow = 'hidden';
  content.insertBefore(bodyContainer, btnContainer);

    const bundle = loadBundle();
    // Shapes are listed A-Z. `featureIndex` keeps each one tied to its position
    // in `features`, so the selection survives sorting, searching and filtering.
    const segmentsToPreview = sortMapFeaturesByName(features).map(feature => {
        const item = buildCalTopoSegmentImportItem(feature);
        item.featureIndex = features.indexOf(feature);
        item.imported = isMapFeatureAccountedFor(feature, bundle);
        item.unwanted = !item.imported && isMapFeatureUnwanted(feature, bundle);
        return item;
    });
    const isNewShape = seg => !seg.imported && !seg.unwanted;
    const countByType = typeKey => segmentsToPreview.filter(seg => seg.typeKey === typeKey).length;
    const newCount = () => segmentsToPreview.filter(isNewShape).length;

    let activeFilter = 'all';
    let onlyNew = false;
    let searchQuery = '';
    // Shapes that are already segments or were marked unwanted start unchecked,
    // so a quick "Submit Import" only brings in what is actually new.
    const selectionState = new Map(segmentsToPreview.map(seg => [seg.featureIndex, isNewShape(seg)]));
    const selectedCount = () => segmentsToPreview.filter(seg => selectionState.get(seg.featureIndex) !== false).length;

    bodyContainer.innerHTML = `
      <p style="margin-bottom: 15px; opacity: 0.8; flex-shrink: 0;">Select the shapes you want to import, then click <strong>Submit Import</strong>: <strong>Assignments</strong> go to the Segments page (through the same import preview), <strong>tracks and lines</strong> to the Searchers Tracks table on the Search Log page; markers and plain shapes cannot be imported. Shapes left out of an import are remembered as <strong>unwanted</strong>, so <strong>Only new</strong> hides them the next time you fetch.</p>
      <div style="display: flex; flex-wrap: wrap; gap: 12px; margin-bottom: 12px; align-items: center;">
        <input type="search" id="caltopo-shape-search" class="pill-input" placeholder="Search by segment name..." autocomplete="off" style="flex: 1; min-width: 200px; min-height: 40px;">
        <label style="display: inline-flex; align-items: center; gap: 10px; color: var(--muted); font-size: 0.92rem; cursor: pointer; white-space: nowrap;">
          <span class="toggle-switch" style="transform: scale(0.9);">
            <input type="checkbox" id="caltopo-only-new-toggle">
            <span class="slider"></span>
          </span>
          <span>Only new (<span id="caltopo-only-new-count">${newCount()}</span>)</span>
        </label>
      </div>
      <div id="caltopo-filter-row" style="display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 12px; align-items: center;"></div>
      <div style="margin-bottom: 10px; display: flex; align-items: center; gap: 10px;">
          <input type="checkbox" id="check-all-shapes" style="width: 18px; height: 18px; cursor: pointer;">
          <label for="check-all-shapes" style="cursor: pointer; font-weight: bold;">Check / Uncheck Visible</label>
      </div>
    `;

    const tableWrap = document.createElement('div');
    tableWrap.style.overflowX = 'auto';
    tableWrap.style.flex = '1';
    tableWrap.style.overflowY = 'auto';
    tableWrap.style.background = 'rgba(0,0,0,0.1)';
    tableWrap.style.borderRadius = '12px';
    bodyContainer.appendChild(tableWrap);

    const searchInput = bodyContainer.querySelector('#caltopo-shape-search');
    const onlyNewToggle = bodyContainer.querySelector('#caltopo-only-new-toggle');
    const filterRow = bodyContainer.querySelector('#caltopo-filter-row');
    const checkAll = bodyContainer.querySelector('#check-all-shapes');
    const onlyNewCountEl = bodyContainer.querySelector('#caltopo-only-new-count');
    let submitBtn = null;

    const getVisibleSegments = () => {
        let visible = getFilteredSegmentImports(segmentsToPreview, activeFilter);
        if (onlyNew) visible = visible.filter(isNewShape);
        if (searchQuery.trim()) {
            const keep = new Set(filterMapFeaturesByName(visible.map(seg => seg.feature), searchQuery));
            visible = visible.filter(seg => keep.has(seg.feature));
        }
        return visible;
    };

    const updateSubmitLabel = () => {
        if (submitBtn) submitBtn.textContent = `Submit Import (${selectedCount()})`;
    };

    const renderFilters = () => {
        filterRow.innerHTML = `
        <span style="opacity: 0.8; font-size: 0.95rem;">Filter:</span>
        <button type="button" class="mini-pill caltopo-filter-btn ${activeFilter === 'all' ? 'active' : ''}" data-filter="all">All (${segmentsToPreview.length})</button>
        <button type="button" class="mini-pill caltopo-filter-btn ${activeFilter === 'marker' ? 'active' : ''}" data-filter="marker">Markers (${countByType('marker')})</button>
        <button type="button" class="mini-pill caltopo-filter-btn ${activeFilter === 'assignment' ? 'active' : ''}" data-filter="assignment">Assignments (${countByType('assignment')})</button>
        <button type="button" class="mini-pill caltopo-filter-btn ${activeFilter === 'route' ? 'active' : ''}" data-filter="route">Tracks / Lines (${countByType('route')})</button>
        <span class="caltopo-showing" style="margin-left: auto; opacity: 0.7; font-size: 0.85rem;"></span>
      `;
        filterRow.querySelectorAll('.caltopo-filter-btn').forEach(btn => {
            btn.onclick = () => {
                activeFilter = btn.dataset.filter || 'all';
                renderFilters();
                renderTable();
            };
        });
    };

    const renderTable = () => {
        const visibleSegments = getVisibleSegments();
        const selectedVisibleCount = visibleSegments.filter(seg => selectionState.get(seg.featureIndex) !== false).length;
        checkAll.checked = visibleSegments.length > 0 && selectedVisibleCount === visibleSegments.length;
        if (onlyNewCountEl) onlyNewCountEl.textContent = newCount();
        const showing = filterRow.querySelector('.caltopo-showing');
        if (showing) showing.textContent = `Showing ${visibleSegments.length} of ${segmentsToPreview.length}`;

        tableWrap.innerHTML = '';
        const table = document.createElement('table');
        table.className = 'grid-table';
        table.style.width = '100%';

        const thead = document.createElement('thead');
        thead.innerHTML = `
      <tr>
          <th style="width: 40px; text-align: center; padding: 12px;"></th>
          <th style="padding: 12px;">Name</th>
          <th style="padding: 12px;">Type</th>
          <th style="padding: 12px;">Status</th>
          <th style="padding: 12px;">Max Dim (mi)</th>
          <th style="padding: 12px;">Area (acres)</th>
          <th style="padding: 12px;">W x H (mi)</th>
      </tr>
    `;
        table.appendChild(thead);

        const tbody = document.createElement('tbody');
        if (visibleSegments.length === 0) {
            const emptyText = segmentsToPreview.length === 0
                ? 'No shapes were fetched from the map.'
                : (onlyNew && !searchQuery.trim() && activeFilter === 'all'
                    ? 'Every fetched shape is already imported or marked unwanted.'
                    : 'No shapes match the current search / filter.');
            tbody.innerHTML = `<tr><td colspan="7" style="text-align:center; padding: 28px; color: var(--muted);">${emptyText}</td></tr>`;
        } else {
            visibleSegments.forEach(seg => {
                const tr = document.createElement('tr');
                const status = seg.imported
                    ? '<span class="mini-pill" style="padding: 4px 10px; font-size: 0.75rem; background: rgba(64, 192, 87, 0.12); border-color: rgba(64, 192, 87, 0.35);">Imported</span>'
                    : (seg.unwanted
                        ? '<span style="display: inline-flex; align-items: center; gap: 6px;"><span class="mini-pill" style="padding: 4px 10px; font-size: 0.75rem; opacity: 0.7;">Unwanted</span><button type="button" class="mini-pill restore-shape" style="padding: 4px 10px; font-size: 0.75rem; cursor: pointer;" title="Remove from the unwanted list">Restore</button></span>'
                        : '<span class="mini-pill" style="padding: 4px 10px; font-size: 0.75rem; background: rgba(var(--accent-rgb), 0.12); border-color: rgba(var(--accent-rgb), 0.35);">New</span>');
                tr.innerHTML = `
          <td style="text-align: center;"><input type="checkbox" class="shape-checkbox" data-index="${seg.featureIndex}" ${selectionState.get(seg.featureIndex) !== false ? 'checked' : ''} style="width: 18px; height: 18px; cursor: pointer;"></td>
          <td><div class="pill-cell readonly-pill" style="padding: 8px 12px;">${seg.segment}</div></td>
          <td><div class="pill-cell readonly-pill" style="padding: 8px 12px;">${seg.typeLabel}</div></td>
          <td style="padding: 8px 12px;">${status}</td>
          <td><div class="pill-cell readonly-pill" style="padding: 8px 12px;">${seg.length || '0.00'} mi</div></td>
          <td><div class="pill-cell readonly-pill" style="padding: 8px 12px;">${seg.area || '0.00'} ac</div></td>
          <td><div class="pill-cell readonly-pill" style="padding: 8px 12px; font-size: 0.8rem;">${seg.width} x ${seg.height}</div></td>
        `;
                const cb = tr.querySelector('.shape-checkbox');
                cb.onchange = () => {
                    selectionState.set(seg.featureIndex, cb.checked);
                    const stillVisible = getVisibleSegments();
                    checkAll.checked = stillVisible.length > 0 && stillVisible.every(s => selectionState.get(s.featureIndex) !== false);
                    updateSubmitLabel();
                };
                const restoreBtn = tr.querySelector('.restore-shape');
                if (restoreBtn) {
                    restoreBtn.onclick = () => {
                        unmarkMapFeaturesUnwanted([seg.feature]);
                        seg.unwanted = false;
                        selectionState.set(seg.featureIndex, true);
                        renderTable();
                        if (isMapsPage()) renderUnaccountedFeaturesPanel();
                    };
                }
                tbody.appendChild(tr);
            });
        }

        table.appendChild(tbody);
        tableWrap.appendChild(table);
        updateSubmitLabel();
    };

    checkAll.onchange = () => {
        getVisibleSegments().forEach(seg => selectionState.set(seg.featureIndex, checkAll.checked));
        renderTable();
    };
    searchInput.oninput = () => {
        searchQuery = searchInput.value || '';
        renderTable();
    };
    onlyNewToggle.onchange = () => {
        onlyNew = onlyNewToggle.checked;
        renderTable();
    };

  btnContainer.innerHTML = '';
  btnContainer.style.display = 'flex';
  btnContainer.style.gap = '12px';
  btnContainer.style.marginTop = '20px';

  const cancelBtn = document.createElement('button');
  cancelBtn.className = 'popup-btn';
  cancelBtn.style.flex = '1';
  cancelBtn.textContent = 'Cancel';
  cancelBtn.onclick = () => closePopup(popup);
  btnContainer.appendChild(cancelBtn);

  submitBtn = document.createElement('button');
  submitBtn.className = 'popup-btn primary';
  submitBtn.style.flex = '1';
  submitBtn.textContent = 'Submit Import';
  submitBtn.onclick = () => {
      const selected = segmentsToPreview.filter(seg => selectionState.get(seg.featureIndex) !== false);
      if (selected.length === 0) {
          alert('No shapes selected.');
          return;
      }

      // Each selected shape goes where its type belongs: Assignments to the
      // Segments page (through the import preview), lines to the Searchers
      // Tracks table; anything else cannot be imported and is left alone
      // (neither imported nor marked unwanted - the user did want it).
      const groups = groupMapFeaturesByImportTarget(selected.map(seg => seg.feature));
      const segmentItems = selected.filter(seg => groups.segment.includes(seg.feature));
      const trackFeatures = groups.track;
      const notImportable = groups.other;
      const commit = (importedSegmentItems) => {
          if (trackFeatures.length) {
              importSearcherTracks(trackFeatures, {quiet: true});
              showToast(`Imported ${trackFeatures.length} searcher track${trackFeatures.length === 1 ? '' : 's'}: ${trackFeatures.map(getMapFeatureDisplayName).join(', ')} (Search Log page, Searchers Tracks).`, 'Import Complete');
          }
          if (notImportable.length) {
              showToast(`${notImportable.length} shape${notImportable.length === 1 ? '' : 's'} cannot be imported (only Assignments become segments and only tracks / lines become searcher tracks): ${notImportable.map(getMapFeatureDisplayName).join(', ')}.`, 'Not Imported');
          }
          finishCalTopoFeatureImport(features, [...(importedSegmentItems || []), ...trackFeatures.map(feature => ({feature}))], {keep: notImportable});
      };

      closePopup(popup);
      if (!segmentItems.length) {
          commit([]);
          return;
      }
      showSegmentsImportPreviewPopup(segmentItems, {
          title: 'Import Segments from CalTopo',
          description: `Review the selected CalTopo assignments before importing them into Segments.${trackFeatures.length ? ` The ${trackFeatures.length} selected track${trackFeatures.length === 1 ? '' : 's'} / line${trackFeatures.length === 1 ? '' : 's'} will be imported into the Searchers Tracks table at the same time.` : ''} Fetched shapes that are not imported will be marked unwanted so they stop showing up as new.`,
          onBack: () => showCalTopoShapesPopup(features),
          onImported: imported => commit(imported)
      });
  };
  btnContainer.appendChild(submitBtn);

    renderFilters();
    renderTable();
}

// After an import that started from a list of fetched CalTopo shapes: every
// shape in `features` that was NOT imported (and is not a segment or a
// searcher track already) goes on the hidden unwanted list, so it stops
// clogging the "only new" and unaccounted views. `options.keep` lists shapes
// to leave alone (selected but not importable). Returns how many shapes were
// newly marked.
function finishCalTopoFeatureImport(features, importedItems, options = {}) {
    const importedKeys = new Set((Array.isArray(importedItems) ? importedItems : [])
        .map(item => item && item.feature ? getMapFeatureIdentityKey(item.feature) : '')
        .filter(Boolean));
    (Array.isArray(options.keep) ? options.keep : []).forEach(feature => importedKeys.add(getMapFeatureIdentityKey(feature)));
    const leftOut = (Array.isArray(features) ? features : []).filter(feature => !importedKeys.has(getMapFeatureIdentityKey(feature)));
    // markMapFeaturesUnwanted records the marked shapes in the activity log.
    const marked = markMapFeaturesUnwanted(leftOut);
    if (marked > 0) {
        showToast(`${marked} shape${marked === 1 ? '' : 's'} not imported ${marked === 1 ? 'was' : 'were'} marked unwanted.`, 'Import Complete');
    }
    if (isMapsPage()) {
        renderUnaccountedFeaturesPanel();
        if (typeof renderFeaturesList === 'function') renderFeaturesList();
    }
    refreshUnaccountedMapFeatureNotifications();
    return marked;
}

function importCalTopoSegments(selected) {
    importSegmentsAction(selected.map(seg => ({
        region: seg.region || '',
        segment: seg.segment || seg.name || 'Unnamed Graphic',
        area: seg.area || '',
        length: seg.length || '',
        sweep: seg.sweep || 20
    })));
}

async function caltopo_api_call(method, endpoint, payload = null, domain = null, options = {}) {
  const { silent = false } = (typeof options === 'object' && options !== null) ? options : {};
  try {
    return await _execute_caltopo_api_call(method, endpoint, payload, domain);
  } catch (error) {
    console.error('CalTopo API Call Error:', error);
    if (!silent) {
      if (error.message.includes('Unexpected token')) {
         alert('CalTopo API Call Error: The server returned an invalid response (not JSON). This usually happens when the sync server is down or its address (login popup > Set Server) is wrong.');
      } else {
         alert('CalTopo API Call Error: ' + error.message);
      }
    }
    return null;
  }
}

async function _execute_caltopo_api_call(method, endpoint, payload, domain) {
  const proxyUrl = getCalTopoProxy();
  if (!proxyUrl) {
    alert('No sync server is configured, so CalTopo cannot be reached. Log out and use "Set Server" on the login popup.');
    return null;
  }

  const normalizedDomain = normalizeCalTopoDomain(domain);
  const requestBody = { method, endpoint, payload, domain: normalizedDomain };

  // Ensure we call /api/call - normalizeCalTopoProxyUrl always ends in /api/proxy or is a .php file
  let proxyCallUrl = normalizeCalTopoProxyUrl(proxyUrl);
  if (proxyCallUrl.includes('.php')) {
      proxyCallUrl = appendUrlQueryParam(proxyCallUrl, 'api_call', '1');
  } else {
      proxyCallUrl = proxyCallUrl.replace(/\/api\/proxy\/?$/i, '/api/call').replace(/\/fetch-map\/?$/i, '/api/call');
  }
  
  const response = await fetch(proxyCallUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(requestBody)
  });
  
  const contentType = response.headers.get('content-type');
  if (contentType && contentType.includes('application/json')) {
    const data = await response.json();
    if (!response.ok) {
      if (data.proxyDiagnostics) {
        console.group('CalTopo Proxy Diagnostics');
        console.error('Method:', data.proxyDiagnostics.method);
        console.error('Endpoint:', data.proxyDiagnostics.endpoint);
        console.error('Expires:', data.proxyDiagnostics.expires);
        console.error('Payload Size:', data.proxyDiagnostics.payloadSize);
        console.error('Message signed by proxy:', data.proxyDiagnostics.messageToSign);
        console.groupEnd();
      }
      
      let errorMsg = data.message || data.error || `Server Error ${response.status}`;
      if (data.targetUrl) {
        errorMsg += `\n(Attempted: ${data.targetUrl})`;
      }
      
      // Specific help for 403 / "write rights" errors
      if (response.status === 403 || errorMsg.toLowerCase().includes('write rights')) {
         errorMsg = "CalTopo Permission Error: " + errorMsg + "\n\n" +
                    "This usually means your CalTopo Service Account (Credential ID) has 'READ' access but needs 'UPDATE' or 'MANAGE' access to create maps. " +
                    "Also, ensure your Team ID is correct for the domain you selected (CalTopo vs SARTopo).";
      }
      
      throw new Error(errorMsg);
    }
    return data;
  } else {
    const text = await response.text();
    if (!response.ok) {
      if (response.status === 404) {
        const lowerText = text.toLowerCase();
        if (lowerText.includes("lost") || text.includes("404image.png") || lowerText.includes("not found")) {
           throw new Error(`The CalTopo endpoint '${endpoint}' was not found. This might be because the Team ID is incorrect or the domain '${normalizedDomain}' is wrong for this account.`);
        }
        throw new Error(`Endpoint not found (404) at '${proxyCallUrl}'. Your proxy server might be out of date. Please ensure you have the latest sync-server.js running.`);
      }
      
      // Extract title from HTML if possible
      let displayError = text.substring(0, 150);
      const titleMatch = text.match(/<title>(.*?)<\/title>/i);
      if (titleMatch && titleMatch[1]) {
         displayError = titleMatch[1];
      } else {
         const h2Match = text.match(/<h2>(.*?)<\/h2>/i);
         if (h2Match && h2Match[1]) displayError = h2Match[1];
      }
      
      throw new Error(`Server Error ${response.status}: ${displayError}`);
    }
    // If it's 200 OK but not JSON, still a problem for this API
    throw new Error(`Expected JSON response but got ${contentType || 'text'}.`);
  }
}

async function handleCreateMap() {
  const teamIdInput = document.getElementById('create-team-id');
  const titleInput = document.getElementById('create-map-title');
  const domainInput = document.getElementById('create-map-domain');
  const statusDiv = document.getElementById('create-map-status');
  const submitBtn = document.getElementById('submit-create-map');

  if (!teamIdInput || !titleInput || !statusDiv || !submitBtn || !domainInput) return;

  const teamId = teamIdInput.value.trim();
  const title = titleInput.value.trim();
  const domain = normalizeCalTopoDomain(domainInput.value);

  if (!teamId) {
    alert('Please enter a Team ID.');
    return;
  }
  if (!title) {
    alert('Please enter a Map Title.');
    return;
  }

  submitBtn.disabled = true;
  submitBtn.textContent = 'Creating...';
  statusDiv.style.display = 'block';
  statusDiv.style.color = 'var(--accent)';
  statusDiv.textContent = 'Sending request to CalTopo...';

  const payload = {
    properties: {
      title: title
    }
  };

  const endpoint = `/api/v1/acct/${teamId}/CollaborativeMap`;
  const result = await caltopo_api_call('POST', endpoint, payload, domain);

  if (result && result.id) {
    statusDiv.style.color = '#40c057';
    statusDiv.innerHTML = `Success! Map created with ID: <strong>${result.id}</strong><br>Adding to your maps list...`;
    
    // Add to local bundle
    const bundle = loadBundle();
    if (!bundle.maps) bundle.maps = [];
    // Check if it already exists (unlikely for a new map but good practice)
    if (!bundle.maps.find(m => m.id === result.id)) {
        bundle.maps.unshift({
          id: result.id,
          name: title,
          domain: domain,
          teamId: teamId
        });
        addActivityLogEntry('System', `Created CalTopo map "${title}" (${domain}/m/${result.id}) for team ${teamId}`, bundle);
        saveBundle(bundle);
    }
    
    // Switch to Map tab after a delay
    setTimeout(() => {
      const newUrl = window.location.pathname + '?tab=map';
      window.history.replaceState(null, '', newUrl);
      buildMapsPage();
    }, 2000);
  } else {
    submitBtn.disabled = false;
    submitBtn.textContent = 'Create Map';
    statusDiv.style.color = '#ff6b6b';
    statusDiv.textContent = 'Failed to create map. Check console for details.';
  }
}

async function verifyCalTopoAccount() {
  const teamIdInput = document.getElementById('create-team-id');
  const domainInput = document.getElementById('create-map-domain');
  const resultSmall = document.getElementById('team-verify-result');
  const verifyBtn = document.getElementById('verify-team-btn');

  if (!teamIdInput || !domainInput || !resultSmall || !verifyBtn) return;

  const teamId = teamIdInput.value.trim();
  const domain = normalizeCalTopoDomain(domainInput.value);

  if (!teamId) {
    alert('Please enter a Team ID first.');
    return;
  }

  verifyBtn.disabled = true;
  verifyBtn.textContent = '...';
  resultSmall.textContent = 'Verifying...';
  resultSmall.style.color = 'var(--muted)';

  const endpoint = `/api/v1/acct/${teamId}/CollaborativeMap`;
  const result = await caltopo_api_call('GET', endpoint, null, domain);
  
  verifyBtn.disabled = false;
  verifyBtn.textContent = 'Verify';
  
  if (result && (Array.isArray(result) || result.features || result.id || (typeof result === 'object' && Object.keys(result).length > 0))) {
      resultSmall.textContent = `✓ Connected! Account access verified.`;
      resultSmall.style.color = '#40c057';
  } else {
      resultSmall.textContent = '✗ Failed to connect. Check Team ID and Domain.';
      resultSmall.style.color = '#ff6b6b';
  }
}

// Fetch the active map's shapes through the proxy and store them on the map.
// Options:
//   silent - do not open the "Import Shapes" popup afterwards.
//   quiet  - background use (the 5-minute unaccounted check): no alerts at all,
//            problems are only logged. Implies silent.
// Resolves to the fetched feature list, or null when nothing was fetched.
async function caltopo_request(btn = null, options = {}) {
    const {quiet = false} = options;
    const silent = options.silent === true || quiet;
    const report = message => {
        if (quiet) {
            console.warn(message);
        } else {
            alert(message);
        }
    };
  const bundle = loadBundle();
  const map = bundle.maps ? bundle.maps[0] : null;
  if (!map || !map.id) return null;

  const activeMapId = map.id;
  const activeMapDomain = normalizeCalTopoDomain(map.domain);
  let fetchedFeatures = null;

  if (btn) {
    btn.disabled = true;
    btn.dataset.originalText = btn.textContent;
    btn.textContent = 'Fetching...';
  }

  try {
    const proxyUrl = getCalTopoProxy();
    if (!proxyUrl) {
      report('No sync server is configured, so CalTopo cannot be reached. Log out and use "Set Server" on the login popup.');
      return null;
    }

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 20000);
    const requestBody = { mapId: activeMapId, domain: activeMapDomain };

    const finalProxyUrl = normalizeCalTopoProxyUrl(proxyUrl);
    const buster = finalProxyUrl.includes('?') ? `&_=${Date.now()}` : `?_=${Date.now()}`;
    const proxyResp = await fetch(finalProxyUrl + buster, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(requestBody),
      signal: controller.signal
    });
    clearTimeout(timeoutId);

    if (proxyResp.ok) {
      const data = await proxyResp.json();
      console.log('CalTopo Proxy Data:', data);
      
      const features = (data.features || []).filter(f => {
        const props = f.properties || f;
        const hasGeom = !!(f.geometry || f.vertices || f.position || props.geometry || props.vertices || props.position || f.pts || f.coords || f.coordinates || props.pts || props.coords || props.coordinates);
        const rawType = (f.geometry?.type || f.type || props.class || props.type || '').toString().toLowerCase();
        
        console.log(`Checking feature: ${rawType}, hasGeom: ${hasGeom}`, f);
        
        // Very lenient check - if it has geometry/vertices, we probably want it
        // We only exclude things that are clearly not shapes (like Folders, though Folders don't have geometry)
        const allowedTypes = [
          'polygon', 'multipolygon', 'linestring', 'multilinestring', 'point', 'multipoint',
          'shape', 'assignment', 'track', 'route', 'marker', 'clue', 'area', 'line', 'sector', 'buffer', 'graphic', 'feature'
        ];
        
        const isAllowed = allowedTypes.some(t => rawType.includes(t)) || rawType === 'feature' || rawType === 'graphic' || rawType === '';
        return hasGeom && isAllowed;
      }).map((f, idx) => {
        const props = f.properties || f;
        const geom = cloneIfValidGeoJsonGeometry(f.geometry) || cloneIfValidGeoJsonGeometry(props.geometry);
        const objectId = idx + 1;
        const resolvedFeatureId = resolveCalTopoFeatureId(f, props, '');

        let name = props.label || props.title || props.name || props.text;
        
        // Robust naming for Assignments or unnamed features
        if (props.class === 'Assignment' || props.type === 'Assignment' || props.assignment) {
            const a = (typeof props.assignment === 'object') ? props.assignment : props;
            const num = a.number || '';
            const label = a.label || props.title || props.label || '';
            if (num && label) name = `${num} ${label}`;
            else if (num) name = num;
            else if (label) name = label;
        }
        
        if (!name) name = f.id ? `Feature ${f.id}` : `Unnamed Graphic ${objectId}`;

        const feature = {
          geometry: geom,
          attributes: {
            ...props,
            ObjectID: objectId,
            name: name,
            id: resolvedFeatureId || `gfx-${objectId}`
          }
        };

        // Cleanup: remove redundant nested objects
        delete feature.attributes.geometry;
        delete feature.attributes.properties;
        
        return feature;
      });

      if (features.length === 0) {
        console.warn('CalTopo Proxy Data received but no features filtered:', data);
        const rawCount = (data.state && data.state.features) ? data.state.features.length : 0;
        report(`No compatible shapes found on this map. (Total objects from proxy: ${rawCount}). Check your service account permissions or object types (polygon, line, marker, assignment).`);
      } else {
        fetchedFeatures = features;
        const b = loadBundle();
        if (b.maps && b.maps[0]) {
          b.maps[0].features = features;
          // A fetch the user asked for is recorded; silent fetches (the 5-minute
          // background check, the overlay loading missing shapes) are not, so
          // they cannot flood the log.
          if (!silent) {
            addActivityLogEntry('System', `Fetched ${features.length} shape${features.length === 1 ? '' : 's'} from CalTopo map ${b.maps[0].name ? `"${b.maps[0].name}" ` : ''}(${activeMapId})`, b);
          }
          // Feature types switched off below the map are marked unwanted
          // straight away, so they never show up as new.
          applyMapFeatureTypeFilters(b);
          saveBundle(b);
        }
        
        if (isMapsPage()) {
          const urlParams = new URLSearchParams(window.location.search);
          const activeTab = urlParams.get('tab') || 'map';
          // Shapes are known now: the color-sync countdown can show itself.
          renderCalTopoColorSyncCountdown();
          renderUnaccountedFeaturesPanel();
          if (activeTab === 'features') {
            renderFeaturesList();
          } else if (activeTab === 'arcgis') {
            renderArcGISMap();
          } else if (!silent) {
            showCalTopoShapesPopup(features);
          }
        }
      }
    } else {
      const errData = await proxyResp.json().catch(() => ({}));
      const errMsg = errData.message || errData.error || proxyResp.statusText;
      report(`Proxy Error: ${errMsg}`);
    }
  } catch (err) {
    console.error(err);
    report(`Could not fetch shapes: ${err.message}`);
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.textContent = btn.dataset.originalText || 'Fetch Shapes';
    }
  }
  return fetchedFeatures;
}

let arcgisView = null;

function renderArcGISMap() {
  const mapDiv = document.getElementById('arcgis-map-div');
  if (!mapDiv) return;
  
  const refreshBtn = document.getElementById('refresh-arcgis-btn');
    const psrcToggle = document.getElementById('maps-psrc-overlay-toggle');
  if (refreshBtn && !refreshBtn.onclick) {
    refreshBtn.onclick = () => caltopo_request(refreshBtn);
  }
    if (psrcToggle && !psrcToggle.dataset.bound) {
        psrcToggle.checked = isMapPsrcOverlayEnabled();
        psrcToggle.onchange = () => {
            setMapPsrcOverlayEnabled(psrcToggle.checked);
            renderArcGISMap();
        };
        psrcToggle.dataset.bound = 'true';
    }

  const bundle = loadBundle();
  const currentMap = bundle.maps ? bundle.maps[0] : null;
  const features = currentMap ? (currentMap.features || []) : [];
    const segmentRows = ensureSegmentsPageRows(bundle);
    const segmentDisplaySettings = getSegmentDisplaySettings(bundle);
    const psrcLookup = buildSegmentPsrcLookup(segmentRows, segmentDisplaySettings);
    const activeSearchNames = buildActiveSearchSegmentNameSet(bundle, segmentRows);
    const usePsrcOverlay = isMapPsrcOverlayEnabled();

  if (typeof require === 'undefined') {
    mapDiv.innerHTML = '<p style="padding: 20px;">ArcGIS API not loaded yet. Please check your internet connection.</p>';
    return;
  }

  require([
    "esri/Map",
    "esri/views/MapView",
    "esri/Graphic",
    "esri/layers/GraphicsLayer"
  ], function(Map, MapView, Graphic, GraphicsLayer) {
    
    if (!arcgisView) {
      const map = new Map({
        basemap: "topo-vector"
      });

      arcgisView = new MapView({
        container: mapDiv,
        map: map,
        zoom: 4,
        center: [-98, 39]
      });
    } else {
      // Re-attach to the new DOM element created by buildMapsPage()
      arcgisView.container = mapDiv;
    }

    const map = arcgisView.map;
    let graphicsLayer = map.layers.find(l => l.id === "caltopo-features");
    if (!graphicsLayer) {
      graphicsLayer = new GraphicsLayer({ id: "caltopo-features" });
      map.add(graphicsLayer);
    } else {
      graphicsLayer.removeAll();
    }

    if (features.length === 0) return;

    const arcgisGraphics = features.map(f => {
      const geom = f.geometry || {};
      const attrs = f.attributes || {};
      
      let arcgisGeom = null;
      const vertices = geom.vertices || attrs.vertices || geom.pts || attrs.pts || geom.coords || attrs.coords || geom.coordinates || attrs.coordinates;
      const position = geom.position || attrs.position || (geom.type === 'Point' ? geom.coordinates : null);

      if (geom.type === 'Point' || position) {
        const pos = position || geom.coordinates;
        if (pos && Array.isArray(pos)) {
          arcgisGeom = {
            type: "point",
            longitude: pos[0],
            latitude: pos[1]
          };
        }
      } else if (vertices && Array.isArray(vertices)) {
        const isClosed = geom.closed === true || attrs.closed === true || (attrs.class === 'Assignment' && attrs.closed !== false) || geom.type === 'Polygon';
        if (isClosed) {
          // ArcGIS rings expect array of rings, each ring is array of points
          // If vertices is [ [lon,lat], [lon,lat] ], then [vertices] is one ring
          const rings = (Array.isArray(vertices[0]) && Array.isArray(vertices[0][0])) ? vertices : [vertices];
          arcgisGeom = {
            type: "polygon",
            rings: rings
          };
        } else {
          const paths = (Array.isArray(vertices[0]) && Array.isArray(vertices[0][0])) ? vertices : [vertices];
          arcgisGeom = {
            type: "polyline",
            paths: paths
          };
        }
      }

      if (!arcgisGeom) return null;

        const overlayColor = usePsrcOverlay ? getFeaturePsrcColor(f, psrcLookup, segmentDisplaySettings) : null;
        const isActiveSearch = isFeatureActivelyBeingSearched(f, activeSearchNames);
        // For segments that are NOT actively being searched the border/outline opacity
        // stays CONSTANT so that only the fill communicates status. Actively-searched
        // segments instead use the fill color/opacity, border color/opacity and border
        // thickness configured on the Settings page.
        // `strokeOpacity` drives line/marker features (which have no fill), where the
        // stroke is the primary visual; `borderOpacity` is used for area outlines.
        const strokeOpacity = resolveDisplayedSegmentOpacity(isActiveSearch, segmentDisplaySettings, overlayColor ? 1 : 0.2);
        const borderOpacity = resolveDisplayedSegmentBorderOpacity(isActiveSearch, segmentDisplaySettings, overlayColor ? 1 : 0.2);
        const fillOpacity = resolveDisplayedSegmentOpacity(isActiveSearch, segmentDisplaySettings, overlayColor ? 0.42 : 0.4);
        const baseRgb = overlayColor ? overlayColor.rgb : [64, 192, 87];
        const fillRgb = resolveDisplayedSegmentRgb(isActiveSearch, segmentDisplaySettings, baseRgb, 'fill');
        const borderRgb = resolveDisplayedSegmentRgb(isActiveSearch, segmentDisplaySettings, baseRgb, 'border');
        const overlayRgb = [...borderRgb, strokeOpacity];
        const overlayBorderRgb = [...borderRgb, borderOpacity];
        const overlayFillRgb = [...fillRgb, fillOpacity];
        const areaBorderWidth = resolveDisplayedSegmentBorderWidth(isActiveSearch, segmentDisplaySettings, overlayColor ? 3 : 2);
        const lineWidth = resolveDisplayedSegmentBorderWidth(isActiveSearch, segmentDisplaySettings, overlayColor ? 4 : 3);

      let symbol = {
        type: "simple-fill",
          color: overlayFillRgb,
          outline: {color: overlayBorderRgb, width: areaBorderWidth}
      };

      if (arcgisGeom.type === 'polyline') {
        symbol = {
          type: "simple-line",
            color: overlayRgb,
            width: lineWidth
        };
      } else if (arcgisGeom.type === 'point') {
        symbol = {
          type: "simple-marker",
            color: overlayRgb,
            size: overlayColor ? 10 : 8,
            outline: {color: [255, 255, 255, strokeOpacity], width: 1}
        };
      }

      return new Graphic({
        geometry: arcgisGeom,
        attributes: attrs,
        symbol: symbol,
        popupTemplate: {
          title: "{name}",
          content: [{
            type: "fields",
            fieldInfos: [
              { fieldName: "ObjectID", label: "ID" },
              { fieldName: "id", label: "CalTopo ID" },
              { fieldName: "class", label: "Class" }
            ]
          }]
        }
      });
    }).filter(g => g !== null);

    graphicsLayer.addMany(arcgisGraphics);

    if (arcgisGraphics.length > 0) {
      arcgisView.when(() => {
        arcgisView.goTo(arcgisGraphics).catch(() => {});
      });
    }
  });
}

function renderFeaturesList() {
  const tbody = document.getElementById('features-list-body');
  if (!tbody) return;
  
  const bundle = loadBundle();
  const currentMap = bundle.maps ? bundle.maps[0] : null;
  const features = currentMap ? currentMap.features : [];
    const segmentNames = buildSegmentNameSet(ensureSegmentsPageRows(bundle));

  if (!features || features.length === 0) {
    tbody.innerHTML = '<tr><td colspan="4" style="text-align: center; padding: 40px; color: var(--muted);">No features loaded. Use "Fetch Shapes" to load features from the active map.</td></tr>';
    return;
  }

  tbody.innerHTML = '';
  sortMapFeaturesByName(features).forEach(f => {
    const tr = document.createElement('tr');
    const attrs = f.attributes || {};
    const name = attrs.name || 'Unnamed Graphic';
    const type = (f.geometry?.type || attrs.class || attrs.type || (attrs.vertices ? 'Shape' : 'Graphic'));
    const objectId = attrs.ObjectID || 'N/A';
      // Where this shape goes: an Assignment to the Segments page, a line to
      // the Searchers Tracks table, anything else nowhere.
      const importTarget = getMapFeatureImportTarget(f);
      const existingSegment = importTarget === 'segment' && (segmentNames.has(normalizeSegmentNameForMatch(name)) || isMapFeatureImportedAsSegment(f, bundle));
      const existingTrack = importTarget === 'track' && isMapFeatureImportedAsTrack(f, bundle);
      const importLabel = importTarget === 'track'
          ? (existingTrack ? 'Re-measure track' : 'Import as track')
          : (importTarget === 'segment' ? (existingSegment ? 'Reimport' : 'Import') : 'Not importable');
      const importTitle = importTarget === 'track'
          ? `${existingTrack ? 'Re-measure this line in' : 'Import this line into'} the Searchers Tracks table (Search Log page)`
          : (importTarget === 'segment' ? `${existingSegment ? 'Reimport' : 'Import'} this assignment as a segment` : 'Only Assignments (segments) and tracks / lines (searcher tracks) can be imported');

    tr.innerHTML = `
      <td><div class="pill-cell readonly-pill" style="padding: 8px 12px; font-family: monospace; font-size: 0.8rem;">${objectId}</div></td>
      <td><div class="pill-cell readonly-pill" style="padding: 8px 12px;">${name}</div></td>
      <td><div class="pill-cell readonly-pill" style="padding: 8px 12px;">${type}</div></td>
      <td style="padding: 8px 12px;">
        <div style="display: flex; gap: 6px; flex-wrap: wrap;">
          <button class="mini-pill import-feat" ${importTarget ? '' : 'disabled'} title="${importTitle}" style="background: rgba(64, 192, 87, 0.1); border-color: rgba(64, 192, 87, 0.3); padding: 5px 10px; font-size: 0.8rem; cursor: ${importTarget ? 'pointer' : 'not-allowed'};${importTarget ? '' : ' opacity: 0.5;'}">${importLabel}</button>
        </div>
      </td>
    `;

    tr.querySelector('.import-feat').onclick = () => {
        if (importTarget === 'track') {
            importSearcherTracks([f]);
            renderFeaturesList();
            if (isMapsPage()) renderUnaccountedFeaturesPanel();
            refreshUnaccountedMapFeatureNotifications();
            return;
        }
        if (importTarget !== 'segment') return;
        showSegmentsImportPreviewPopup([buildCalTopoSegmentImportItem(f)], {
            title: 'Import Segments from CalTopo',
            description: `Review the selected CalTopo assignment before ${existingSegment ? 'reimporting' : 'importing'} "${name}" into Segments.`
        });
    };

    tbody.appendChild(tr);
  });
}

function buildUserAccountPage() {
    const container = document.getElementById('user-account-container');
    const tabContainer = document.getElementById('user-tabs');
    if (!container) return;

    const bundle = loadBundle();
    const urlParams = new URLSearchParams(window.location.search);
    const userPin = urlParams.get('userPin');
    const tab = urlParams.get('tab') || 'account';
    const currentUser = getCurrentUser();

    if (tabContainer) {
        if (isUserAdmin(currentUser)) {
            tabContainer.style.display = 'flex';
            const tabAccount = document.getElementById('tab-account');
            const tabManage = document.getElementById('tab-manage');
            
            tabAccount.classList.toggle('active', tab === 'account');
            tabManage.classList.toggle('active', tab === 'manage');

            tabAccount.onclick = () => {
                const newUrl = window.location.pathname + '?tab=account';
                window.history.replaceState(null, '', newUrl);
                buildUserAccountPage();
            };
            tabManage.onclick = () => {
                const newUrl = window.location.pathname + '?tab=manage';
                window.history.replaceState(null, '', newUrl);
                buildUserAccountPage();
            };
        } else {
            tabContainer.style.display = 'none';
        }
    }

    if (tab === 'manage' && isUserAdmin(currentUser)) {
        renderUserManagement(container, bundle);
        return;
    }
    
    let userToEdit;
    if (userPin && isUserAdmin(currentUser)) {
        userToEdit = (bundle.accounts || []).find(a => a.pin === userPin);
    } else {
        userToEdit = (bundle.accounts || []).find(a => a.pin === (currentUser ? currentUser.pin : ''));
    }

    if (!userToEdit) {
        // The Anonymous stand-in has no account of its own to edit.
        const message = (!userPin && isAnonymousUser(currentUser))
            ? `This device is working as "${ANONYMOUS_USER_NAME}", which has no profile. Pick yourself from the team to edit your account.`
            : 'User not found.';
        container.innerHTML = `
            <div style="text-align: center; padding: 40px; color: white;">
                <p style="font-size: 1.2rem; margin-bottom: 20px;">${message}</p>
                <button id="switch-user-btn" class="mini-pill" style="padding: 12px 20px; font-size: 1rem; background: rgba(235, 87, 87, 0.1); border-color: rgba(235, 87, 87, 0.4);">Switch User</button>
                <button id="logout-btn" class="mini-pill" style="padding: 12px 20px; font-size: 1rem; margin-left: 10px; background: rgba(235, 87, 87, 0.1); border-color: rgba(235, 87, 87, 0.4);">Log Out</button>
            </div>
        `;
        const switchBtn = document.getElementById('switch-user-btn');
        if (switchBtn) {
            switchBtn.onclick = () => requestUserSwitch();
        }
        const logoutBtnAnon = document.getElementById('logout-btn');
        if (logoutBtnAnon) {
            logoutBtnAnon.onclick = () => {
                setCurrentUser(null);
                window.location.href = 'index.html';
            };
        }
        return;
    }

    container.innerHTML = `
        <div class="profile-form" style="max-width: 800px; margin: 0 auto; background: rgba(0,0,0,0.2); padding: 30px; border-radius: 32px; border: 1px solid rgba(255,255,255,0.1);">
            <div class="form-group small">
                <label style="display: block; margin-bottom: 8px; color: var(--text); font-weight: bold;">Username</label>
                <input type="text" id="user-username" class="pill-input" value="${userToEdit.username || ''}" style="width: 100%; box-sizing: border-box;">
            </div>
            <div class="form-group small">
                <label style="display: block; margin-bottom: 8px; color: var(--text); font-weight: bold;">User PIN</label>
                <input type="password" id="user-pin" class="pill-input" value="${userToEdit.pin || ''}" style="width: 100%; box-sizing: border-box;">
            </div>
            <div class="form-group small">
                <label style="display: block; margin-bottom: 8px; color: var(--text); font-weight: bold;">Handle</label>
                <input type="text" id="user-handle" class="pill-input" value="${userToEdit.handle || ''}" style="width: 100%; box-sizing: border-box;">
            </div>
            <div class="form-group large">
                <label style="display: block; margin-bottom: 8px; color: var(--text); font-weight: bold;">Theme Preference</label>
                <div style="display: flex; gap: 10px;">
                    <button id="theme-dark-btn" class="mini-pill ${userToEdit.theme !== 'light' ? 'active' : ''}" style="flex: 1;">Dark Mode</button>
                    <button id="theme-light-btn" class="mini-pill ${userToEdit.theme === 'light' ? 'active' : ''}" style="flex: 1;">Light Mode</button>
                </div>
            </div>
            <div class="form-group large">
                <label style="display: block; margin-bottom: 12px; color: var(--text); font-weight: bold;">Highlight Color</label>
                <div id="color-selection" style="display: flex; flex-wrap: wrap; gap: 12px; justify-content: center;">
                    <!-- Color buttons will be here -->
                </div>
            </div>
            <div class="tool-actions" style="margin-top: 20px; justify-content: center; grid-column: span 6;">
                <button id="save-user-btn" class="update-pill" style="padding: 12px 40px; font-size: 1rem;">Update Account</button>
                <button id="switch-user-btn" class="mini-pill" style="padding: 12px 20px; font-size: 1rem; margin-left: 10px; background: rgba(235, 87, 87, 0.1); border-color: rgba(235, 87, 87, 0.4);">Switch User</button>
                <button id="logout-btn" class="mini-pill" style="padding: 12px 20px; font-size: 1rem; margin-left: 10px; background: rgba(235, 87, 87, 0.1); border-color: rgba(235, 87, 87, 0.4);">Log Out</button>
            </div>
        </div>
    `;


    const colors = ['none', 'orange', 'yellow', 'red', 'blue', 'green', 'purple', 'brown', 'black', 'white', 'grey', 'maroon'];
    const colorContainer = document.getElementById('color-selection');
    colors.forEach(c => {
        const btn = document.createElement('button');
        btn.className = 'pill-cell-btn';
        btn.style.width = '36px';
        btn.style.height = '36px';
        btn.style.borderRadius = '50%';
        btn.style.padding = '0';
        btn.style.cursor = 'pointer';
        btn.style.transition = 'transform 0.2s ease';
        
        const updateUI = () => {
            // Unselect all
            Array.from(colorContainer.children).forEach(b => {
                b.style.border = '1px solid rgba(255,255,255,0.3)';
                b.style.transform = 'scale(1)';
            });
            // Select this one
            btn.style.border = '3px solid white';
            btn.style.transform = 'scale(1.2)';
        };

        if (userToEdit.color === c) {
            btn.style.border = '3px solid white';
            btn.style.transform = 'scale(1.2)';
        } else {
            btn.style.border = '1px solid rgba(255,255,255,0.3)';
        }
        
        if (c === 'none') {
            btn.style.background = 'transparent';
            btn.innerHTML = '<span style="color: white; font-size: 20px;">×</span>';
        } else {
            btn.style.background = HIGHLIGHT_COLORS[c];
        }

        btn.onclick = () => {
            userToEdit.color = c;
            updateUI();
        };
        colorContainer.appendChild(btn);
    });

    const darkBtn = document.getElementById('theme-dark-btn');
    const lightBtn = document.getElementById('theme-light-btn');
    if (darkBtn && lightBtn) {
        darkBtn.onclick = () => {
            userToEdit.theme = 'dark';
            darkBtn.classList.add('active');
            lightBtn.classList.remove('active');
            applyTheme(bundle);
        };
        lightBtn.onclick = () => {
            userToEdit.theme = 'light';
            lightBtn.classList.add('active');
            darkBtn.classList.remove('active');
            applyTheme(bundle);
        };
    }

    const switchBtn = document.getElementById('switch-user-btn');
    if (switchBtn) {
        switchBtn.onclick = () => requestUserSwitch();
    }

    const logoutBtn = document.getElementById('logout-btn');
    if (logoutBtn) {
        logoutBtn.onclick = () => {
            setCurrentUser(null);
            window.location.href = 'index.html';
        };
    }

    document.getElementById('save-user-btn').onclick = () => {
        const newUsername = document.getElementById('user-username').value;
        const newPin = document.getElementById('user-pin').value;
        const newHandle = document.getElementById('user-handle').value;
        
        if (!newUsername || !newPin) {
            alert('Username and PIN are required.');
            return;
        }

        const oldPin = userToEdit.pin;
        const oldHandle = userToEdit.handle;
        const oldFullName = (userToEdit.username || '').trim();

        const idx = (bundle.accounts || []).findIndex(a => a.pin === oldPin);

        // A renamed user is a new name on the login's list; the old one is retired.
        noteLoginUserRename(oldFullName, newUsername);
        userToEdit.username = newUsername;
        userToEdit.pin = newPin;
        userToEdit.handle = newHandle;
        
        // Sync name change to Personnel list (page3)
        if (bundle.pages && bundle.pages.page3) {
            const newName = newHandle || (newUsername || '').trim();
            bundle.pages.page3.forEach(row => {
                const rowName = (row[0] || '').trim();
                const rowPin = (row[8] || '').trim();
                if ((rowPin && rowPin === oldPin) || rowName === oldHandle || rowName === oldFullName) {
                    row[0] = newName;
                    row[8] = newPin;
                }
            });
        }
        
        if (idx >= 0) {
            bundle.accounts[idx] = userToEdit;
        } else {
            bundle.accounts.push(userToEdit);
        }
        
        saveBundle(bundle);
        
        // If we edited our own account, update the session
        if (oldPin === currentUser.pin) {
            setCurrentUser(userToEdit);
        }

        // Immediately apply the selected theme and highlight-accent preference
        applyTheme(bundle);
        applyAccentColor(bundle);

        // If PIN changed and we are Admin editing another user, update the URL to prevent duplicate saves
        if (userPin && userPin !== newPin) {
            const newUrl = window.location.pathname + '?userPin=' + newPin;
            window.history.replaceState(null, '', newUrl);
        }
        
        const status = document.getElementById('save-status');
        if (status) {
            status.textContent = 'Account updated successfully!';
            status.style.color = '#4caf50';
            setTimeout(() => status.textContent = 'Ready.', 3000);
        }
        updateHeaderProfile();
    };
}

function renderUserManagement(container, bundle) {
    container.innerHTML = `
        <div class="table-card" style="max-width: 1200px; margin: 0 auto; background: rgba(0,0,0,0.2); border-radius: 15px; border: 1px solid rgba(255,255,255,0.1); overflow-x: auto;">
            <div style="padding: 20px; background: rgba(0,0,0,0.2); border-bottom: 1px solid rgba(255,255,255,0.1); color: var(--muted); font-size: 0.9rem; text-align: center;">
                These users belong to the login "${(getUserCredentials() || {}).name || ''}" and are the same in every Case #: their name, PIN, highlight color and theme travel with the login, while their team and status are kept per case on the Personnel page. A name typed on the Personnel page becomes a user; "Remove" takes a user off the login (out of every case).
            </div>
            <table class="grid-table" style="width: 100%; border-collapse: collapse; min-width: 600px;">
                <thead>
                    <tr style="background: rgba(255,255,255,0.05);">
                        <th style="padding: 15px; text-align: left; color: var(--accent); width: 45%;">User Name</th>
                        <th style="padding: 15px; text-align: center; color: var(--accent); width: 15%;">File Manager</th>
                        <th style="padding: 15px; text-align: center; color: var(--accent); width: 15%;">PIN</th>
                        <th style="padding: 15px; text-align: center; color: var(--accent); width: 25%;">Actions</th>
                    </tr>
                </thead>
                <tbody id="user-management-body"></tbody>
            </table>
        </div>
        <div style="text-align: center; margin-top: 30px; display: flex; gap: 10px; justify-content: center; flex-wrap: wrap;">
            <button id="add-user-btn-mgmt" class="mini-pill" style="padding: 12px 20px; font-size: 1rem;">+ Add User</button>
            <button id="switch-user-btn-mgmt" class="mini-pill" style="padding: 12px 20px; font-size: 1rem; background: rgba(235, 87, 87, 0.1); border-color: rgba(235, 87, 87, 0.4);">Switch User</button>
        </div>
    `;

    const switchBtnMgmt = document.getElementById('switch-user-btn-mgmt');
    if (switchBtnMgmt) {
        switchBtnMgmt.onclick = () => requestUserSwitch();
    }
    // A new user gets a name (and a Personnel row in this case); the save hook
    // then puts them on the login's list for every case.
    const addBtnMgmt = document.getElementById('add-user-btn-mgmt');
    if (addBtnMgmt) {
        addBtnMgmt.onclick = () => showEditAccountPopup(null, -1, () => buildUserAccountPage());
    }

    const tbody = document.getElementById('user-management-body');
    (bundle.accounts || []).forEach(acc => {
        const tr = document.createElement('tr');
        tr.style.borderBottom = '1px solid rgba(255,255,255,0.05)';
        
        const tdName = document.createElement('td');
        tdName.style.padding = '12px 15px';
        const nameBtn = document.createElement('button');
        nameBtn.className = 'mini-pill';
        nameBtn.style.fontWeight = 'bold';
        nameBtn.style.whiteSpace = 'normal';
        nameBtn.style.textAlign = 'left';
        nameBtn.style.wordBreak = 'break-word';
        nameBtn.textContent = `${getAccountName(acc)} (@${acc.handle || 'no-handle'})`;
        if (acc.color && acc.color !== 'none') {
            nameBtn.classList.add(`profile-highlight-${acc.color}`);
        }
        nameBtn.onclick = () => {
            const newUrl = window.location.pathname + '?tab=account&userPin=' + acc.pin;
            window.history.replaceState(null, '', newUrl);
            buildUserAccountPage();
        };
        tdName.appendChild(nameBtn);
        tr.appendChild(tdName);
        
        const tdFileManager = document.createElement('td');
        tdFileManager.style.padding = '12px 15px';
        tdFileManager.style.textAlign = 'center';
        const chk = document.createElement('input');
        chk.type = 'checkbox';
        chk.className = 'pill-checkbox';
        chk.checked = !!acc.isFileManager;
        chk.onchange = () => {
            acc.isFileManager = chk.checked;
            saveBundle(bundle);
        };
        tdFileManager.appendChild(chk);
        tr.appendChild(tdFileManager);

        const tdPin = document.createElement('td');
        tdPin.style.padding = '12px 15px';
        tdPin.style.textAlign = 'center';
        const pinInput = document.createElement('input');
        pinInput.type = 'password';
        pinInput.className = 'pill-input';
        pinInput.style.width = '80px';
        pinInput.style.textAlign = 'center';
        pinInput.value = acc.pin;
        pinInput.onchange = () => {
            const oldPin = acc.pin;
            acc.pin = pinInput.value;
            // Sync to personnel
            if (bundle.pages && bundle.pages.page3) {
                bundle.pages.page3.forEach(row => {
                    if (row[8] === oldPin) row[8] = acc.pin;
                });
            }
            saveBundle(bundle);
        };
        tdPin.appendChild(pinInput);
        tr.appendChild(tdPin);
        
        const tdActions = document.createElement('td');
        tdActions.style.padding = '12px 15px';
        tdActions.style.textAlign = 'center';
        
        if (isLoginUserCandidate(acc)) {
            // Off the login: flagged as removed in the login's list, dropped
            // from this case now and from every other case when it is opened.
            const removeBtn = document.createElement('button');
            removeBtn.className = 'mini-pill';
            removeBtn.style.color = 'var(--accent)';
            removeBtn.textContent = 'Remove';
            removeBtn.title = 'Remove this user from the login (every Case #)';
            removeBtn.onclick = () => {
                const b = loadBundle();
                const doRemove = () => {
                    removeLoginUser(acc.username);
                    logDeletion('User', acc.username);
                    buildUserAccountPage();
                };
                if (b.deleteMode || confirm(`Remove ${acc.username || 'this user'} from the login? They disappear from every Case #.`)) {
                    doRemove();
                }
            };
            tdActions.appendChild(removeBtn);
        } else {
            const span = document.createElement('span');
            span.textContent = 'Built-in';
            span.style.color = 'var(--muted)';
            span.style.fontSize = '0.8rem';
            span.style.display = 'block';
            span.style.lineHeight = '1.2';
            tdActions.appendChild(span);
        }

        tr.appendChild(tdActions);
        
        tbody.appendChild(tr);
    });
}

function buildUserManagementPage() {
    navigateToPage('page8.html?tab=manage');
}

// The Maps page's map + Lost Person Behavior row (.map-lpb-row) spans the
// whole screen, not just <main>'s 1200px. The stylesheet sizes it from
// --sar-viewport-width on <html>: the document's width without the vertical
// scrollbar (documentElement.clientWidth). Its fallback, plain 100vw, counts
// the scrollbar on Windows and would leave a horizontal scrollbar behind.
// Kept current by a ResizeObserver on <html> (it also fires when the
// scrollbar appears or goes, which a window resize event does not), else on
// resize; bound once per page load.
let _viewportWidthVariableBound = false;
function syncViewportWidthVariable() {
    const root = document.documentElement;
    if (!root || !root.style || typeof root.style.setProperty !== 'function') return;
    const width = Number(root.clientWidth);
    if (Number.isFinite(width) && width > 0) root.style.setProperty('--sar-viewport-width', `${width}px`);
    if (_viewportWidthVariableBound) return;
    _viewportWidthVariableBound = true;
    try {
        if (typeof ResizeObserver === 'function') {
            new ResizeObserver(() => syncViewportWidthVariable()).observe(root);
        } else {
            window.addEventListener('resize', () => syncViewportWidthVariable());
        }
    } catch (e) {
        // Without either the stylesheet's 100vw fallback still applies.
    }
}

// ---------------------------------------------------------------------------
// Maps page "Proxy Status" indicator.
// ---------------------------------------------------------------------------
// The CalTopo proxy is the sync server (getCalTopoProxy()), so its health is
// GET <server>/api/health: an answer means the server is up, and its
// `caltopoSigningConfigured` flag says whether it can sign Team API requests
// (without that, every "Fetch Shapes" fails with "Proxy Not Configured").
// When the address cannot be tested at all - no answer came back, or the
// browser would not send the request - the dot says "Unproven Connection"
// rather than pronouncing the proxy down: the shapes may well still fetch.
// The last answer is remembered (see MAPS_PROXY_STATUS_RECHECK_INTERVAL_MS)
// so the frequent page rebuilds neither hammer the server nor flicker the dot
// back to "Checking..."; a probe already running is shared rather than doubled.
const MAPS_PROXY_STATUS_COLORS = {
    ok: '#40c057',
    warn: '#f59f00',
    error: '#fa5252',
    unproven: '#868e96',
    checking: '#ccc',
    none: '#ccc'
};
const MAPS_PROXY_STATUS_UNPROVEN_TEXT = 'Unproven Connection';
let _mapsProxyStatus = null;
let _mapsProxyStatusInFlight = null;

function paintMapsProxyStatus(status) {
    if (typeof document === 'undefined' || !status) return;
    const dot = document.getElementById('maps-proxy-status-dot');
    const text = document.getElementById('maps-proxy-status-text');
    if (dot && dot.style) dot.style.background = MAPS_PROXY_STATUS_COLORS[status.state] || MAPS_PROXY_STATUS_COLORS.checking;
    if (text) {
        text.textContent = status.text || '';
        text.title = status.detail || '';
    }
}

// One GET /api/health of the proxy's server, reduced to {state, text, detail}.
async function probeMapsProxyStatus(proxyUrl) {
    const healthUrl = getCalTopoProxyHealthUrl(proxyUrl);
    if (!healthUrl) {
        return {state: 'none', text: 'No proxy', detail: 'No sync server is set: log out and use "Set Server" on the login popup.'};
    }
    if (isBlockedMixedContentUrl(healthUrl)) {
        return {state: 'unproven', text: MAPS_PROXY_STATUS_UNPROVEN_TEXT, detail: `${proxyUrl} could not be tested: this page is served over HTTPS and cannot call an http:// server.`};
    }
    try {
        const resp = await fetchWithTimeout(appendUrlQueryParam(healthUrl, '_', String(Date.now())), {method: 'GET', cache: 'no-store'}, MAPS_PROXY_STATUS_TIMEOUT_MS);
        let body = {};
        try {
            body = await resp.json();
        } catch (e) {
            body = {};
        }
        if (!body || typeof body !== 'object') body = {};
        if (!resp.ok) {
            return {state: 'error', text: `Error (HTTP ${resp.status})`, detail: body.message || body.error || `${healthUrl} answered HTTP ${resp.status}`};
        }
        if (body.caltopoSigningConfigured === false) {
            return {state: 'warn', text: 'Server up, CalTopo credentials missing', detail: body.message || 'The sync server answers but has no CalTopo credentials, so it cannot sign Team API requests.'};
        }
        return {state: 'ok', text: 'Connected', detail: `${proxyUrl} - ${body.message || `answered HTTP ${resp.status}`}`};
    } catch (e) {
        return {state: 'unproven', text: MAPS_PROXY_STATUS_UNPROVEN_TEXT, detail: `${proxyUrl} could not be tested: ${describeConnectionError(e)}`};
    }
}

// Paints the remembered answer (or "Checking...") into the Maps page's dot and
// asks the server again when it is stale, `force`d, or for another address.
function refreshMapsProxyStatus({force = false} = {}) {
    const proxyUrl = getCalTopoProxy();
    const cached = _mapsProxyStatus && _mapsProxyStatus.proxyUrl === proxyUrl ? _mapsProxyStatus : null;
    if (cached && !force && (Date.now() - cached.checkedAt) < MAPS_PROXY_STATUS_RECHECK_INTERVAL_MS) {
        paintMapsProxyStatus(cached);
        return Promise.resolve(cached);
    }
    if (_mapsProxyStatusInFlight && _mapsProxyStatusInFlight.proxyUrl === proxyUrl && !force) {
        paintMapsProxyStatus(cached || {state: 'checking', text: 'Checking...', detail: proxyUrl});
        return _mapsProxyStatusInFlight.promise;
    }
    paintMapsProxyStatus({state: 'checking', text: 'Checking...', detail: proxyUrl});
    const inFlight = {proxyUrl, promise: null};
    inFlight.promise = probeMapsProxyStatus(proxyUrl).then((result) => {
        const status = {...result, proxyUrl, checkedAt: Date.now()};
        _mapsProxyStatus = status;
        if (_mapsProxyStatusInFlight === inFlight) _mapsProxyStatusInFlight = null;
        // Only paint while this address is still the one the page shows.
        if (getCalTopoProxy() === proxyUrl) paintMapsProxyStatus(status);
        return status;
    });
    _mapsProxyStatusInFlight = inFlight;
    return inFlight.promise;
}

